internal readonly record struct TransactionSnapshot(
    EmbeddedDatabase.SchemaCatalog Catalog,
    long Version,
    PragmaHeaderMetadata PragmaHeader);

public class EmbeddedSqlException : Exception
{
    public EmbeddedSqlException(string message) : base(message)
    {
    }

    public EmbeddedSqlException(string message, int sqliteErrorCode) : base(message)
    {
        SqliteErrorCode = sqliteErrorCode;
    }

    internal EmbeddedSqlException(string message, InsertConflictAlgorithm conflictAlgorithm) : base(message)
    {
        ConflictAlgorithm = conflictAlgorithm;
    }

    internal EmbeddedSqlException(
        string message,
        InsertConflictAlgorithm? conflictAlgorithm,
        bool constraintViolation = true) : base(message)
    {
        ConflictAlgorithm = conflictAlgorithm ?? InsertConflictAlgorithm.Abort;
    }

    internal EmbeddedSqlException(
        string message,
        int sqliteErrorCode,
        InsertConflictAlgorithm? conflictAlgorithm) : base(message)
    {
        SqliteErrorCode = sqliteErrorCode;
        ConflictAlgorithm = conflictAlgorithm;
    }

    public EmbeddedSqlException(string message, Exception innerException) : base(message, innerException)
    {
    }

    /// <summary>
    /// Optional SQLite result code (e.g. 19 CONSTRAINT) when raised from Halt / HaltIfNull.
    /// </summary>
    public int? SqliteErrorCode { get; }

    internal InsertConflictAlgorithm? ConflictAlgorithm { get; }
}

internal readonly record struct PragmaHeaderMetadata(
    int SchemaVersion,
    int UserVersion,
    int ApplicationId);

internal enum ManagedSchemaObjectKind
{
    Table,
    View,
    Trigger,
    Index,
}

internal readonly record struct FileCatalogVersion(
    uint ChangeCounter,
    uint SchemaCookie,
    uint DatabaseSizeInPages,
    uint FreelistPageCount,
    int UserVersion,
    int ApplicationId,
    int PageSize,
    SqliteTextEncoding TextEncoding)
{
    public static FileCatalogVersion FromHeader(SqliteDatabaseHeader header)
        => new(
            header.ChangeCounter,
            header.SchemaCookie,
            header.DatabaseSizeInPages,
            header.FreelistPageCount,
            header.UserVersion,
            header.ApplicationId,
            header.PageSize,
            header.TextEncoding);
}

internal sealed class EmbeddedConflictRollbackException : EmbeddedSqlException
{
    public EmbeddedConflictRollbackException(EmbeddedSqlException conflict, long? lastInsertRowId = null)
        : base(conflict.Message, conflict)
    {
        LastInsertRowId = lastInsertRowId;
    }

    public long? LastInsertRowId { get; }
}

/// <summary>
/// Signals that a write found its catalog snapshot stale (SQLite's
/// <c>SQLITE_BUSY_SNAPSHOT</c>). Carries the public busy message so it is safe
/// to surface unhandled, while internal catch sites recognize it by type and
/// reload the catalog or retry the statement instead.
/// </summary>
/// <summary>
/// Raised when a managed write discovers the durable file catalog moved past
/// this connection's snapshot. This is the managed engine's
/// <c>SQLITE_BUSY_SNAPSHOT</c>: a busy failure (surfaced as error 5,
/// "database is locked") whose transaction must roll back, while autocommit
/// statements and BEGIN may re-read the catalog and retry.
/// </summary>
internal sealed class EmbeddedCatalogSnapshotStaleException : EmbeddedBusyException
{
    public EmbeddedCatalogSnapshotStaleException()
        : base("database is locked")
    {
    }
}

internal class EmbeddedConflictFailException : EmbeddedSqlException
{
    public EmbeddedConflictFailException(EmbeddedSqlException conflict, long lastInsertRowId)
        : base(conflict.Message, conflict)
    {
        LastInsertRowId = lastInsertRowId;
    }

    public long LastInsertRowId { get; }
}

internal sealed class EmbeddedUpsertConflictFailException : EmbeddedConflictFailException
{
    public EmbeddedUpsertConflictFailException(EmbeddedSqlException conflict, long lastInsertRowId)
        : base(conflict, lastInsertRowId)
    {
    }
}

internal sealed class TriggerIgnoreException : Exception;

internal sealed class EmbeddedStatementAbortException : EmbeddedSqlException
{
    public EmbeddedStatementAbortException(EmbeddedSqlException conflict, long lastInsertRowId)
        : base(conflict.Message, conflict)
    {
        LastInsertRowId = lastInsertRowId;
    }

    public long LastInsertRowId { get; }
}

internal sealed class EmbeddedStatementFailureException : Exception
{
    public EmbeddedStatementFailureException(Exception failure, long lastInsertRowId)
        : base(failure.Message, failure)
    {
        Failure = failure;
        LastInsertRowId = lastInsertRowId;
    }

    public Exception Failure { get; }

    public long LastInsertRowId { get; }
}

internal sealed class EmbeddedTriggerRaiseException : EmbeddedSqlException
{
    public EmbeddedTriggerRaiseException(string message, InsertConflictAlgorithm algorithm)
        : base(message, algorithm)
    {
        Algorithm = algorithm;
    }

    public InsertConflictAlgorithm Algorithm { get; }
}

internal sealed class EmbeddedTriggerDepthException : EmbeddedSqlException
{
    public EmbeddedTriggerDepthException(long lastInsertRowId, bool preserveChanges = false)
        : base("too many levels of trigger recursion")
    {
        LastInsertRowId = lastInsertRowId;
        PreserveChanges = preserveChanges;
    }

    public EmbeddedTriggerDepthException(
        EmbeddedTriggerDepthException exception,
        long lastInsertRowId,
        bool? preserveChanges = null)
        : base(exception.Message, exception)
    {
        LastInsertRowId = lastInsertRowId;
        PreserveChanges = preserveChanges ?? exception.PreserveChanges;
    }

    public long LastInsertRowId { get; }

    public bool PreserveChanges { get; }
}

/// <summary>
/// Reports that a catalog mutation reached its durable WAL commit marker, but
/// subsequent checkpoint maintenance failed. Retrying the mutation would apply
/// it twice; dispose and reopen before attempting another write.
/// </summary>
public sealed class EmbeddedPostCommitMaintenanceException : EmbeddedSqlException
{
    public EmbeddedPostCommitMaintenanceException(Exception maintenanceFailure)
        : base(
            "The managed database mutation committed successfully, but post-commit checkpoint maintenance failed. "
            + "Do not retry the mutation; dispose and reopen the database before another write.",
            maintenanceFailure)
    {
        MaintenanceFailure = maintenanceFailure;
    }

    /// <summary>The maintenance failure that occurred after the durable commit.</summary>
    public Exception MaintenanceFailure { get; }
}

