    [ThreadStatic]
    private static RecursiveTriggerCallbackDispatcher? s_recursiveTriggerCallbackDispatcher;
    private static readonly AsyncLocal<EmbeddedDatabase?> RecursiveTriggerCallbackDatabase = new();
    internal const string SqliteSequenceTableName = "sqlite_sequence";
    internal const string SqliteStat1TableName = "sqlite_stat1";
    internal const string SqliteStat4TableName = "sqlite_stat4";
    private const string TursoSequenceBackingTablePrefix = "__turso_internal_seq_";
    private const string TursoAutoIncrementSequencePrefix = "__turso_internal_autoincrement_";
    private static readonly ConditionalWeakTable<IFileSystem, FileCatalogWriteLockScope> FileCatalogWriteLocks = new();
    private static readonly ConditionalWeakTable<IFileSystem, FileCatalogWriterRegistry> FileCatalogWriterRegistries = new();
    private readonly object _gate = new();
    private Dictionary<string, EmbeddedTable> _tables = new(StringComparer.OrdinalIgnoreCase);
    private Dictionary<string, ViewDefinition> _views = new(StringComparer.OrdinalIgnoreCase);
    private Dictionary<string, TriggerDefinition> _triggers = new(StringComparer.OrdinalIgnoreCase);
    private Dictionary<string, VirtualTableDefinition> _virtualTables = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<(string Name, int Arity), Func<IReadOnlyList<SqlValue>, SqlValue>> _scalarFunctions = new();
    private readonly Dictionary<(string Name, int Arity), ManagedAggregateFunction> _aggregateFunctions = new();
    private readonly Dictionary<string, Func<string, string, int>> _collations = new(StringComparer.OrdinalIgnoreCase);
    /// <summary>
    /// In-memory-only "is this custom/overridden-collation index currently safe for
    /// planning/writes" cache, keyed by index name, holding the file store's committed
    /// generation at the time the index was last proven consistent with the active collation
    /// callback plus that proof's outcome. Never persisted — usability is tracked purely in
    /// memory (architecture item 4). Cleared whenever the collation registry or the attached
    /// file store changes; see <see cref="RefreshCollationResolverBinding"/>. A cache miss (or
    /// a stale generation) lazily re-derives the answer via
    /// <see cref="EmbeddedFileStore.RevalidateIndexOrderAndContent"/> instead of trusting a
    /// possibly outdated result, so REINDEX, a callback replacement, or an ordinary commit
    /// that happens to touch the index all naturally invalidate it without any explicit
    /// "mark clean" hook.
    /// </summary>
    private readonly Dictionary<string, (long Generation, long RegistryVersion, bool Clean)> _customCollationIndexClean = new(StringComparer.OrdinalIgnoreCase);
    /// <summary>
    /// Monotonically increasing version bumped by <see cref="RefreshCollationResolverBinding"/>
    /// (i.e. every registration, replacement, or unregistration of a collation callback).
    /// <see cref="IsCustomCollationIndexPlanReady"/> captures this alongside the file store's
    /// committed generation before revalidating an index, and only trusts/publishes the result
    /// if both are still unchanged afterward — guarding against a reentrant or concurrent
    /// callback replacement racing the very validation it is supposed to gate.
    /// </summary>
    private long _collationRegistryVersion;
    /// <summary>
    /// Every built-in collation name (BINARY/NOCASE/RTRIM) that has ever been registered as a
    /// custom override on this connection, even if it has since been unregistered. Never
    /// cleared. Without this, <see cref="IsCustomCollationIndexPlanReady"/> could not tell "this
    /// name was never overridden, so any durable index using it was always built under pure
    /// built-in semantics" (safe to skip revalidation) apart from "this name's override was just
    /// unregistered, so a durable index using it may still be physically ordered/uniqued the way
    /// the removed callback saw the world, not the way the just-restored built-in comparer does"
    /// (unsafe to skip — must revalidate against the restored built-in semantics before being
    /// trusted again).
    /// </summary>
    private readonly HashSet<string> _everOverriddenBuiltInCollations = new(StringComparer.OrdinalIgnoreCase);
    private bool _hasScalarFunctions;
    private bool _hasCustomCollations;
    /// <summary>
    /// Fallback collation lookup consulted only when this instance's own <see cref="_collations"/>
    /// registry has no entry for a requested name. Unset on every ordinary connection; wired up
    /// exclusively by <see cref="EmbeddedFileStore"/> on its private
    /// <c>_indexExpressionEvaluator</c> — a throwaway <see cref="EmbeddedDatabase"/> constructed
    /// solely to evaluate partial-index predicates and index expressions, which therefore never
    /// receives an application's <see cref="RegisterCollation"/> calls directly. Routing it through
    /// <see cref="EmbeddedFileStore.SetCollationResolver"/> gives that evaluator visibility into
    /// whichever custom collations are actually active on the owning connection, through the same
    /// safe callback wrapper (<see cref="InvokeManagedCallback{T}"/>) real value comparisons use,
    /// so a partial predicate or expression-index key containing a custom COLLATE evaluates
    /// correctly instead of always failing "no such collation sequence". A missing callback still
    /// fails closed, but only lazily — the first time <see cref="Compare"/> or
    /// <see cref="ValidateCollation"/> actually needs that specific name, never eagerly.
    /// </summary>
    private Func<string, Func<string, string, int>?>? _externalCollationResolver;
    private EmbeddedFileStore? _fileStore;
    private readonly string _databasePath = string.Empty;
    private readonly IFileSystem? _fileSystem;
    private readonly AsyncFifoGate? _fileCatalogWriteLock;
    private readonly bool _readOnly;
    private readonly bool _foreignReadOnly;
    private SqlitePagerViewToken _foreignViewToken;
    private SqlitePagerViewToken _ownedViewToken;
    private FileCatalogVersion _fileCatalogVersion;
    private long _ownedCommittedGeneration;
    private PragmaHeaderMetadata _inMemoryPragmaHeader;
    private long _version;
    private int _activeTransactions;
    private int _activeStatementReaders;
    private readonly object _lockingModeGate = new();
    private int _exclusiveLockingConnections;
    private readonly Dictionary<BlobMutationIdentity, int> _activeBlobMutations = new();
    private readonly Dictionary<BlobMutationIdentity, long> _blobMutationGenerations = new();
    private long _nextBlobMutationGeneration;

    // Managed in-memory page model backing PRAGMA page_count / page_size /
    // max_page_count on databases that have no file store. The memory database
    // starts with zero pages (matching SQLite's empty pager) and materializes
    // pages the way the pager would: the first header write creates the header
    // page, and each table or index adds one page.
    internal bool _inMemoryInitialized;
    internal int? _inMemoryPageSize;
    private uint _maxPageCount = 4294967294;
    private readonly EmbeddedTransactionLock _transactionLock;
    /// <summary>
    /// Opt-in Turso MVCC store. When non-null, <c>PRAGMA journal_mode</c> reports
    /// <c>mvcc</c> and <c>BEGIN CONCURRENT</c> is accepted.
    /// </summary>
    private MvStore? _mvStore;

    public EmbeddedDatabase()
    {
        _transactionLock = new EmbeddedTransactionLock();
    }

    private EmbeddedDatabase(
        EmbeddedFileStore fileStore,
        EmbeddedFileCatalog catalog,
        string databasePath,
        IFileSystem fileSystem,
        FileCatalogVersion fileCatalogVersion,
        AsyncFifoGate fileCatalogWriteLock,
        bool readOnly,
        bool foreignReadOnly = false)
    {
        _fileStore = fileStore;
        _databasePath = databasePath;
        _fileSystem = fileSystem;
        _fileCatalogVersion = fileCatalogVersion;
        _fileCatalogWriteLock = fileCatalogWriteLock;
        _readOnly = readOnly;
        _foreignReadOnly = foreignReadOnly;
        _foreignViewToken = foreignReadOnly
            ? fileStore.CaptureCommittedViewToken()
            : default;
        _ownedCommittedGeneration = fileStore.CommittedViewGeneration;
        // Owned connections also pin a durable view token so peer engines that
        // commit without going through the process-local lock manager (stock
        // SQLite / Turso on the same WAL) still invalidate the heap catalog.
        _ownedViewToken = foreignReadOnly
            ? default
            : fileStore.CaptureCommittedViewToken();
        _tables = catalog.Tables;
        _views = catalog.Views;
        _triggers = catalog.Triggers;
        _virtualTables = catalog.VirtualTables;
        _transactionLock = EmbeddedTransactionLockRegistry.Get(fileSystem, databasePath);
    }

    /// <summary>
    /// Opens (or creates) a file-backed managed database that persists its schema
    /// and table data as real SQLite pages. See <c>AhtolaBindings.OpenManagedDatabase</c>
    /// for the exact set of supported schema and data and the documented gaps.
    /// </summary>
    public static EmbeddedDatabase OpenFile(
        string path,
        IFileSystem? fileSystem = null,
        bool readOnly = false,
            bool foreignReadOnly = false,
            int? initialPageSize = null)
    {
        ArgumentException.ThrowIfNullOrEmpty(path);
        if (foreignReadOnly && !readOnly)
            throw new ArgumentException("A foreign open is always read-only.", nameof(foreignReadOnly));
        var effectiveFileSystem = fileSystem ?? PhysicalFileSystem.Instance;
        var fileCatalogWriteLock = GetFileCatalogWriteLock(effectiveFileSystem, path);
        using (fileCatalogWriteLock.Enter(Timeout.InfiniteTimeSpan))
        {
            using var catalogWriteLease = readOnly
                ? null
                : EnterPhysicalFileCatalogWriteLock(effectiveFileSystem, path);
            var store = EmbeddedFileStore.Open(
                path,
                effectiveFileSystem,
                out var catalog,
                readOnly: readOnly,
                initialPageSize: initialPageSize,
                foreignReadOnly: foreignReadOnly);
            EmbeddedDatabase? database = null;
            try
            {
                // The store now owns the physical database before this second pager
                // reads the durable version, so no foreign client can race catalog load.
                // A foreign read-only open holds no ownership, but the version read
                // is a self-contained snapshot and only feeds catalog-cache reuse.
                var catalogVersion = ReadFileCatalogVersion(effectiveFileSystem, path, foreignReadOnly);
                database = new EmbeddedDatabase(
                    store,
                    catalog,
                    path,
                    effectiveFileSystem,
                    catalogVersion,
                    fileCatalogWriteLock,
                    readOnly,
                    foreignReadOnly);
                // Cold-open restore: header version 255 means MVCC was last active.
                if (!readOnly && store.JournalMode == SqliteJournalMode.Mvcc)
                    database.AttachMvStoreFromDurableLog();
                return database;
            }
            catch
            {
                if (database is not null)
                    database.Dispose();
                else
                {
                    DisconnectVirtualTables(catalog.VirtualTables.Values);
                    store.Dispose();
                }
                throw;
            }
        }
    }

    /// <summary>Releases the backing file store, if any.</summary>
    public void Dispose()
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        lock (_gate)
        {
            DisconnectVirtualTables(_virtualTables.Values);
            _virtualTables.Clear();

            if (_mvStore is not null && _fileSystem is not null && !string.IsNullOrEmpty(_databasePath))
            {
                var last = EmbeddedMvStoreRegistry.Release(_fileSystem, _databasePath);
                last?.LogicalLog?.Dispose();
                _mvStore = null;
            }

            _fileStore?.Dispose();
        }
    }

    internal bool IsFileBacked => _fileStore is not null;

    internal bool SetConnectionExclusiveLockingMode(bool exclusive, TimeSpan busyTimeout)
    {
        lock (_lockingModeGate)
        {
            if (_fileStore is null)
                return exclusive;
            if (_readOnly)
                return false;

            if (exclusive)
            {
                if (_exclusiveLockingConnections != 0)
                {
                    _exclusiveLockingConnections++;
                    return true;
                }

                if (!_fileStore.SetExclusiveLockingMode(exclusive: true, busyTimeout))
                    return false;
                _exclusiveLockingConnections = 1;
                return true;
            }

            if (_exclusiveLockingConnections == 0)
                return false;
            if (_exclusiveLockingConnections == 1)
            {
                _ = _fileStore.SetExclusiveLockingMode(exclusive: false, busyTimeout);
                _exclusiveLockingConnections = 0;
                return false;
            }

            _exclusiveLockingConnections--;
            return false;
        }
    }

    /// <summary>
    /// How long autocommit statements on this database wait out a conflicting
    /// writer and retry against a stale catalog snapshot before surfacing busy.
    /// The owning connection sets this from its command timeout; zero fails
    /// fast, matching SQLite's default <c>busy_timeout</c>.
    /// </summary>
    internal TimeSpan BusyTimeout { get; set; }

    /// <summary>Re-reads the committed catalog after a stale-snapshot signal. Throws busy when the version cannot settle.</summary>
    /// <param name="forceReload">
    /// When true, reopen the store even if <see cref="FileCatalogVersion"/> matches.
    /// Peer engines (stock SQLite) can grow the WAL without a change we already
    /// folded into the header cookie comparison, so durable view-token mismatches
    /// must force adoption.
    /// </param>
    internal void ReloadFileCatalogAfterStale(bool forceReload = false)
    {
        lock (_gate)
        {
            if (_fileStore is null || _fileSystem is null || _fileCatalogWriteLock is null)
                throw new InvalidOperationException("The managed file catalog persistence state is not initialized.");

            using (_fileCatalogWriteLock.Enter(Timeout.InfiniteTimeSpan))
            {
                // A commit landing mid-reload fails the race check; spin until the
                // reload observes a settled version. Bounded so a commit storm
                // degrades to the public busy error instead of hanging.
                for (var attempt = 0; attempt < 1000; attempt++)
                {
                    if (TryReloadFileCatalogIfChanged(forceReload))
                        return;
                    Thread.Sleep(1);
                }

                throw new EmbeddedCatalogSnapshotStaleException();
            }
        }
    }

    /// <summary>
    /// The write reservation shared by every managed connection open on this
    /// database, modeling SQLite's RESERVED and EXCLUSIVE locks.
    /// </summary>
    internal EmbeddedTransactionLock TransactionLock => _transactionLock;

    /// <summary>
    /// Whether an EXCLUSIVE transaction also excludes readers. SQLite only does
    /// that under a rollback journal; in WAL and MVCC modes EXCLUSIVE behaves as
    /// IMMEDIATE because readers never contend with the writer.
    /// </summary>
    internal bool ExclusiveTransactionsExcludeReaders
    {
        get
        {
            var mode = GetJournalMode();
            return mode is not (SqliteJournalMode.Wal or SqliteJournalMode.Mvcc);
        }
    }

    /// <summary>Whether Turso MVCC mode is enabled on this database.</summary>
    internal bool IsMvccEnabled
    {
        get { lock (_gate) return _mvStore is not null; }
    }

    /// <summary>The per-database MVCC store, or null when classic mode is active.</summary>
    internal MvStore? MvStore
    {
        get { lock (_gate) return _mvStore; }
    }

    internal bool IsReadOnly => _readOnly;

    internal string DatabasePath => _databasePath;

    internal uint MaxPageCount
    {
        get => _maxPageCount;
        set => _maxPageCount = value;
    }

    internal IFileSystem FileSystem
        => _fileSystem ?? throw new InvalidOperationException("The managed database is not file-backed.");

    internal static StringComparer PhysicalPathComparer { get; } =
        OperatingSystem.IsWindows() || OperatingSystem.IsMacOS()
            ? StringComparer.OrdinalIgnoreCase
            : StringComparer.Ordinal;

    internal bool ReferencesSameDatabase(EmbeddedDatabase other)
    {
        ArgumentNullException.ThrowIfNull(other);
        if (ReferenceEquals(this, other))
            return true;
        if (!IsFileBacked || !other.IsFileBacked || _fileSystem is null || other._fileSystem is null)
            return false;

        var fileSystem = AhtolaEncryptionFileSystem.Unwrap(_fileSystem);
        var otherFileSystem = AhtolaEncryptionFileSystem.Unwrap(other._fileSystem);
        if (fileSystem is PhysicalFileSystem && otherFileSystem is PhysicalFileSystem)
        {
            return PhysicalPathComparer.Equals(
                Path.GetFullPath(_databasePath),
                Path.GetFullPath(other._databasePath));
        }

        return ReferenceEquals(fileSystem, otherFileSystem)
               && string.Equals(_databasePath, other._databasePath, StringComparison.Ordinal);
    }

    internal bool ReferencesStoragePath(string path, IFileSystem fileSystem)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);
        ArgumentNullException.ThrowIfNull(fileSystem);
        if (!IsFileBacked || _fileSystem is null)
            return false;

        var ownFileSystem = AhtolaEncryptionFileSystem.Unwrap(_fileSystem);
        var candidateFileSystem = AhtolaEncryptionFileSystem.Unwrap(fileSystem);
        if (ownFileSystem is PhysicalFileSystem && candidateFileSystem is PhysicalFileSystem)
        {
            var candidate = Path.GetFullPath(path);
            return new[] { string.Empty, "-wal", "-journal", "-shm" }.Any(suffix =>
                PhysicalPathComparer.Equals(Path.GetFullPath(_databasePath + suffix), candidate));
        }

        return ReferenceEquals(ownFileSystem, candidateFileSystem)
               && new[] { string.Empty, "-wal", "-journal", "-shm" }.Any(suffix =>
                   string.Equals(_databasePath + suffix, path, StringComparison.Ordinal));
    }

