public sealed partial class EmbeddedConnection : IDisposable
{
    private const int MaximumAttachedDatabases = 10;
    private const char UnqualifiedSchemaMarker = '\0';
    private const string PersistentTriggerColumnSchemaMarker = "\u0001persistent-trigger-columns";

    [field: ThreadStatic]
    internal static Action? AfterMvccBeginBeforeCatalogSnapshotForTesting { get; set; }

    private readonly EmbeddedDatabase _database;
    private EmbeddedDatabase _tempDatabase;
    private readonly Dictionary<string, AttachedDatabase> _attachedDatabases = new(StringComparer.OrdinalIgnoreCase);
    private readonly object _statementReaderGate = new();
    private readonly HashSet<ConnectionStatementReaderLease> _statementReaders = [];
    private Dictionary<EmbeddedDatabase, TransactionDatabaseState>? _transactionDatabases;
    private EmbeddedDatabase? _transactionWriteDatabase;
    private EmbeddedDatabase? _transactionMutationDatabase;
    private EmbeddedDatabase? _autocommitWriteReservation;
    private IDisposable? _autocommitMvccWriteAdmission;
    private readonly List<EmbeddedDatabase> _writeReservations = [];
    private readonly Dictionary<EmbeddedDatabase, IDisposable> _classicMvccWriteAdmissions = [];
    private bool _transactionOpenedBySavepoint;
    /// <summary>When set, the open SQL transaction is a Turso <c>BEGIN CONCURRENT</c> MVCC tx.</summary>
    private bool _transactionIsConcurrent;
    private readonly Dictionary<EmbeddedDatabase, MvccTxId> _mvccTransactions = [];
    private long _nextMvccStatementSavepoint;
    private readonly List<SavepointEntry> _savepoints = [];
    private long _lastInsertRowId;
    private bool _queryOnly;
    private bool _foreignKeys;
    private bool _deferForeignKeys;
    private bool _recursiveTriggers;
    private readonly Dictionary<EmbeddedDatabase, long> _cacheSizes = [];
    private readonly Dictionary<EmbeddedDatabase, bool> _cacheSpills = [];
    private int _tempStore;
    private bool _ignoreCheckConstraints;
    private readonly Dictionary<EmbeddedDatabase, SqliteSynchronousMode> _synchronousModes = [];
    private readonly Dictionary<EmbeddedDatabase, string> _lockingModes = [];
    private bool _dataSyncRetry;
    private bool _fullColumnNames;
    private bool _shortColumnNames = true;
    private long _mvccCheckpointThreshold = DefaultMvccCheckpointThreshold;
    private long _mvccGcThreshold = DefaultMvccGcThreshold;
    private bool _requireWhere;
    private bool _tempInitialized;
    private readonly Dictionary<EmbeddedDatabase, int> _pendingPageSizes = [];
    private readonly ManagedConnectionHooks _hooks = new();
    private ChangeDataCaptureSession? _changeDataCapture;
    private bool _suppressUpdateHook;
    private bool _insideHookCallback;
    private bool _disposed;
    private TimeSpan _busyTimeout = TimeSpan.Zero;

    /// <summary>
    /// How long contended transaction-lock acquisitions wait for a competing
    /// connection to release before reporting busy, mirroring
    /// <c>sqlite3_busy_timeout</c> per connection. The default of zero preserves
    /// SQLite's fail-fast default.
    /// </summary>
    internal TimeSpan BusyTimeout
    {
        get => _busyTimeout;
        set
        {
            _busyTimeout = value;
            _database.BusyTimeout = value;
            foreach (var attachment in _attachedDatabases.Values)
                attachment.Database.BusyTimeout = value;
        }
    }

    /// <summary>
    /// Fails this connection's lock acquisitions immediately instead of parking the
    /// calling thread until its busy timeout expires.
    /// </summary>
    /// <remarks>
    /// The asynchronous statement seam pairs this with
    /// <see cref="AcquireAutocommitWriteReservationAsync"/> and
    /// <see cref="WaitForBusyRetryAsync"/>: drain contention on the managed lock's
    /// asynchronous signal, then run the statement so no <see cref="Monitor"/> wait
    /// or <see cref="Thread.Sleep(int)"/> inside it can block. Only this
    /// connection's budget changes; the owning <see cref="EmbeddedDatabase"/> keeps
    /// its own, so a peer connection's retry budget is untouched and the engine's
    /// stale-catalog statement restart still converges. Saving and restoring makes
    /// nesting safe when a SQL callback steps another statement here.
    /// </remarks>
    internal FailFastBusyScope EnterFailFastBusyScope() => new(this);

    internal readonly struct FailFastBusyScope : IDisposable
    {
        private readonly EmbeddedConnection _connection;
        private readonly TimeSpan _restore;

        internal FailFastBusyScope(EmbeddedConnection connection)
        {
            _connection = connection;
            _restore = connection._busyTimeout;
            if (_restore != TimeSpan.Zero)
                connection._busyTimeout = TimeSpan.Zero;
        }

        public void Dispose()
        {
            // A PRAGMA busy_timeout executed inside the scope is the caller's new
            // intent; never clobber it with the value this scope displaced.
            if (_restore != TimeSpan.Zero && _connection._busyTimeout == TimeSpan.Zero)
                _connection._busyTimeout = _restore;
        }
    }

    /// <summary>
    /// Asynchronously takes the write reservation an autocommit mutation would
    /// otherwise block on, returning <see langword="null"/> when the statement does
    /// not need one.
    /// </summary>
    /// <remarks>
    /// Draining the contention here rather than retrying the whole statement keeps
    /// the barging shape SQLite has between autocommit writers — the reservation is
    /// held across the statement instead of being re-raced on every attempt — while
    /// the acquisition itself suspends rather than sleeping a thread. The engine's
    /// own <c>EnterAutocommit</c> then finds the reservation re-entrant and never
    /// waits. The lease is taken per attempt so a failed attempt cannot pin a
    /// database another connection needs to make progress.
    /// </remarks>
    internal async ValueTask<IDisposable?> AcquireAutocommitWriteReservationAsync(
        ParsedStatement statement,
        TimeSpan busyTimeout,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(statement);
        cancellationToken.ThrowIfCancellationRequested();
        if (_transactionDatabases is not null
            || _database.IsReadOnly
            || !StatementMayMutate(_database, statement))
        {
            return null;
        }

        await _database.TransactionLock
            .EnterAutocommitAsync(this, busyTimeout, cancellationToken)
            .ConfigureAwait(false);
        return new AutocommitWriteReservation(this, _database);
    }

    private sealed class AutocommitWriteReservation(
        EmbeddedConnection owner,
        EmbeddedDatabase database) : IDisposable
    {
        private EmbeddedDatabase? _database = database;

        public void Dispose()
        {
            var released = Interlocked.Exchange(ref _database, null);
            released?.TransactionLock.Exit(owner);
        }
    }

    /// <summary>
    /// Asynchronously waits out whatever made this connection's last attempt busy,
    /// returning <see langword="false"/> once the busy budget is spent.
    /// </summary>
    internal async ValueTask<bool> WaitForBusyRetryAsync(
        long deadline,
        CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        if (!EmbeddedDatabase.HasBusyBudgetRemaining(deadline))
            return false;

        try
        {
            foreach (var database in EnumerateReachableDatabases())
            {
                await database
                    .WaitForBusyRetryAsync(this, deadline, cancellationToken)
                    .ConfigureAwait(false);
            }
        }
        catch (EmbeddedBusyException)
        {
            // The wait itself ran out of budget; the caller reports the original
            // busy failure rather than this one.
            return false;
        }

        // The reservation can be retaken between that signal and this retry, so
        // yield for SQLite's shortest busy delay rather than spinning — the same
        // one-millisecond poll the synchronous autocommit contender uses.
        var delay = SqliteBusyBackoff.DelayForAttempt(
            attempt: 0,
            TimeSpan.Zero,
            EmbeddedDatabase.RemainingBusyBudget(deadline));
        if (delay > TimeSpan.Zero)
            await Task.Delay(delay, cancellationToken).ConfigureAwait(false);

        return EmbeddedDatabase.HasBusyBudgetRemaining(deadline);
    }

    private IEnumerable<EmbeddedDatabase> EnumerateReachableDatabases()
    {
        yield return _database;
        foreach (var attachment in _attachedDatabases.Values)
            yield return attachment.Database;
    }

    private VdbeExecutionOptions CreateVdbeExecutionOptions(EmbeddedDatabase database)
    {
        ArgumentNullException.ThrowIfNull(database);
        var cacheSize = _cacheSizes.GetValueOrDefault(database, -2000);
        Int128 bytes = cacheSize < 0
            ? (Int128)(cacheSize == long.MinValue ? long.MaxValue : -cacheSize) * 1024
            : (Int128)cacheSize * database.GetPageSize();
        var budget = bytes <= 0
            ? 1L
            : bytes >= long.MaxValue
                ? long.MaxValue
                : (long)bytes;

        if (_tempStore == 2)
        {
            return new VdbeExecutionOptions(
                new InMemoryFileSystem(),
                budget,
                temporaryDirectory: "ahtola-memory-execution",
                allowTemporaryFileSpill: false);
        }

        return new VdbeExecutionOptions(
            PhysicalFileSystem.Instance,
            budget,
            temporaryDirectory: Path.GetTempPath());
    }

    /// <summary>
    /// Tracks one outer statement's use of connection-private temp triggers. Temp triggers live in
    /// a separate in-memory database, so firing one for a main-schema table means handing it to the
    /// main database, and a body statement may target yet another schema. Those cross-schema writes
    /// run against a working copy of the target catalog that is published only after the statement
    /// that fired the trigger succeeds, mirroring how a local statement is rolled back on failure.
    /// </summary>
    private sealed class TempTriggerSession(EmbeddedConnection connection, EmbeddedDatabase executing)
    {
        private readonly Dictionary<ParsedStatement, RoutedStatement> _routes =
            new(ReferenceEqualityComparer.Instance);
        private readonly Dictionary<EmbeddedDatabase, ForeignWrite> _foreignWrites = [];

        private sealed class ForeignWrite(EmbeddedDatabase.SchemaCatalog catalog)
        {
            public EmbeddedDatabase.SchemaCatalog Catalog { get; } = catalog;

            public bool Changed { get; set; }

            public bool ForceFullCatalogRewrite { get; set; }
        }

        public bool IsForeign(ParsedStatement statement)
        {
            var route = Resolve(statement);
            return route.ExternalTables is not null || !ReferenceEquals(route.Database, executing);
        }

        public ParsedStatement Localize(ParsedStatement statement) => Resolve(statement).Statement;

        public ExecutionResult ExecuteForeign(
            ParsedStatement statement,
            EmbeddedDatabase.QueryContext outer)
        {
            var route = Resolve(statement);
            if (ReferenceEquals(route.Database, executing))
            {
                return route.Database.ExecuteTriggerBodyStatement(
                    route.Statement,
                    new EmbeddedDatabase.SchemaCatalog(
                        outer.Tables,
                        new Dictionary<string, ViewDefinition>(
                            outer.Views ?? new Dictionary<string, ViewDefinition>(StringComparer.OrdinalIgnoreCase),
                            StringComparer.OrdinalIgnoreCase),
                        new Dictionary<string, TriggerDefinition>(
                            outer.Triggers ?? new Dictionary<string, TriggerDefinition>(StringComparer.OrdinalIgnoreCase),
                            StringComparer.OrdinalIgnoreCase)),
                    outer,
                    connection.CreateTriggerBodyHooks(route.Database, outer.Hooks),
                    route.ExternalTables);
            }

            if (!_foreignWrites.TryGetValue(route.Database, out var write))
            {
                var transaction = connection.GetTransactionState(route.Database);
                write = new ForeignWrite((transaction?.Catalog ?? route.Database.LiveCatalog).Clone());
                _foreignWrites.Add(route.Database, write);
            }

            var result = route.Database.ExecuteTriggerBodyStatement(
                route.Statement,
                write.Catalog,
                outer,
                connection.CreateTriggerBodyHooks(route.Database, outer.Hooks),
                route.ExternalTables);

            write.Changed |= result.Changed;
            write.ForceFullCatalogRewrite |= result.ForceFullCatalogRewrite;
            return result;
        }

        public void Commit()
        {
            foreach (var pair in _foreignWrites.ToArray())
            {
                if (!pair.Value.Changed)
                {
                    pair.Value.Catalog.DisconnectOwnedVirtualTables();
                    _foreignWrites.Remove(pair.Key);
                    continue;
                }

                if (connection.GetTransactionState(pair.Key) is { } transaction)
                {
                    var previous = transaction.Catalog;
                    transaction.Catalog = pair.Value.Catalog;
                    previous.DisconnectOwnedVirtualTables(transaction.VirtualTableTransaction);
                    transaction.HasChanges = true;
                    // Publishing a replaced trigger-body catalog is not a targeted index
                    // rebuild: an earlier REINDEX in this same transaction must not cause
                    // commit to skip persisting this catalog swap.
                    transaction.HasNonTargetedIndexRebuildChange = true;
                    transaction.ForceFullCatalogRewrite |= pair.Value.ForceFullCatalogRewrite;
                    if (!ReferenceEquals(pair.Key, connection._tempDatabase))
                        connection._transactionWriteDatabase = pair.Key;
                }
                else
                {
                    pair.Key.PublishTriggerBodyCatalog(
                        pair.Value.Catalog,
                        pair.Value.ForceFullCatalogRewrite,
                        connection.GetSynchronousMode(pair.Key));
                }
                if (ReferenceEquals(pair.Key, connection._tempDatabase))
                    connection._tempInitialized = true;
                _foreignWrites.Remove(pair.Key);
            }
        }

        public void Abandon()
        {
            foreach (var write in _foreignWrites.Values)
                write.Catalog.DisconnectOwnedVirtualTables();
            _foreignWrites.Clear();
        }

        private RoutedStatement Resolve(ParsedStatement statement)
        {
            if (_routes.TryGetValue(statement, out var route))
                return route;

            route = connection.TryRouteTempTriggerInsertReadingForeignSchema(
                statement,
                GetCurrentCatalog,
                out var crossSchemaRoute)
                    ? crossSchemaRoute
                    : connection.RouteStatement(statement);
            _routes.Add(statement, route);
            return route;
        }

        private EmbeddedDatabase.SchemaCatalog GetCurrentCatalog(EmbeddedDatabase database)
        {
            if (_foreignWrites.TryGetValue(database, out var write))
                return write.Catalog;

            return connection.GetTransactionState(database)?.Catalog ?? database.LiveCatalog;
        }
    }

    // Temp triggers that watch a table owned by the executing database have to be handed over
    // explicitly: they are stored in the connection-private temp database so that they stay
    // invisible to other connections and never reach the persistent schema.
    private EmbeddedDatabase.TempTriggerBridge? CreateTempTriggerBridge(
        EmbeddedDatabase executing,
        out TempTriggerSession? session)
    {
        var transactionState = GetTransactionState(_tempDatabase);
        var isTempDatabase = ReferenceEquals(executing, _tempDatabase);

        // Statements that touch neither the temp database nor a temp trigger are the common case,
        // so bail out before snapshotting the temp catalog.
        if (!isTempDatabase
            && (transactionState is { } pending ? pending.Catalog.Triggers.Count == 0 : !_tempDatabase.HasTriggers))
        {
            session = null;
            return null;
        }

        var triggers = transactionState is { } state
            ? state.Catalog.Triggers.Values.ToArray()
            : _tempDatabase.SnapshotTriggers();
        var overlay = triggers
            .Where(trigger => trigger.TargetSchema is { } schema
                && ReferenceEquals(FindSchemaDatabase(schema), executing))
            .ToArray();

        // The temp database also needs the bridge without an overlay: its own triggers may name
        // their schema explicitly, and only the connection can resolve those names.
        if (overlay.Length == 0 && !isTempDatabase)
        {
            session = null;
            return null;
        }

        var scope = new TempTriggerSession(this, executing);
        session = scope;
        return new EmbeddedDatabase.TempTriggerBridge(
            overlay,
            scope.IsForeign,
            scope.Localize,
            scope.ExecuteForeign);
    }

    private EmbeddedDatabase? FindSchemaDatabase(string schema)
    {
        if (schema.Equals("temp", StringComparison.OrdinalIgnoreCase))
            return _tempDatabase;
        if (schema.Equals("main", StringComparison.OrdinalIgnoreCase))
            return _database;

        return _attachedDatabases.TryGetValue(schema, out var attachment) ? attachment.Database : null;
    }

    private string? GetSchemaName(EmbeddedDatabase database)
    {
        if (ReferenceEquals(database, _tempDatabase))
            return "temp";
        if (ReferenceEquals(database, _database))
            return "main";

        foreach (var pair in _attachedDatabases)
        {
            if (ReferenceEquals(pair.Value.Database, database))
                return pair.Key;
        }

        return null;
    }

    // SQLite drops the triggers that watch a dropped table or view, including temp triggers that
    // reach across schemas. Those live in the temp catalog, so prune them here.
    private void RemoveTempTriggersForDroppedObject(RoutedStatement routed)
    {
        var droppedName = routed.Statement switch
        {
            DropTableStatement drop => drop.Name,
            DropViewStatement drop => drop.Name,
            _ => null,
        };
        if (droppedName is null || GetSchemaName(routed.Database) is not { } schema)
            return;
        if (ReferenceEquals(routed.Database, _tempDatabase))
            return;

        if (GetTransactionState(_tempDatabase) is { } state)
        {
            if (EmbeddedDatabase.RemoveForeignTargetTriggers(state.Catalog, schema, droppedName))
            {
                // Pruning a dangling temp trigger is a catalog mutation, not a targeted index
                // rebuild: an earlier REINDEX in this same transaction must not cause commit
                // to skip persisting this removal.
                state.HasChanges = true;
                state.HasNonTargetedIndexRebuildChange = true;
            }

            return;
        }

        if (EmbeddedDatabase.RemoveForeignTargetTriggers(_tempDatabase.LiveCatalog, schema, droppedName))
            _tempDatabase.MarkSchemaMutated();
    }

    private sealed record PendingTempTriggerCatalogRewrite(EmbeddedDatabase.SchemaCatalog Catalog);

    // Temp triggers are connection-private, so the altered database cannot rewrite their stored
    // definitions itself. Prepare their catalog replacement before the primary ALTER succeeds,
    // then publish it with the same transaction lifetime as the table rename.
    private PendingTempTriggerCatalogRewrite? PrepareTempTriggerTableRename(
        RoutedStatement routed,
        CancellationToken cancellationToken)
    {
        if (ReferenceEquals(routed.Database, _tempDatabase)
            && routed.Statement is AlterTableRenameStatement)
        {
            ValidateTempTableOwnedTriggers(cancellationToken);
        }

        if (!ReferenceEquals(routed.Database, _database)
            || routed.Statement is not AlterTableRenameStatement rename)
        {
            return null;
        }

        var sourceCatalog = GetTransactionState(_tempDatabase)?.Catalog ?? _tempDatabase.LiveCatalog;
        if (sourceCatalog.Triggers.Count == 0)
            return null;

        var candidateCatalog = sourceCatalog.Clone();
        try
        {
            var includeUnqualifiedReferences = !sourceCatalog.Tables.ContainsKey(rename.TableName);
            var changed = false;
            foreach (var trigger in sourceCatalog.Triggers.Values)
            {
                var rewritten = AlterTableSqlRewriter.RenameTableReferences(
                    trigger.Sql,
                    rename.TableName,
                    rename.NewName,
                    targetSchema: "main",
                    includeUnqualifiedReferences);
                if (rewritten is null || string.Equals(rewritten, trigger.Sql, StringComparison.Ordinal))
                    continue;

                var parsed = (CreateTriggerStatement)SqlParser.Parse(rewritten, SqlParameterMap.Parse(rewritten));
                var watchesRenamedMainTable = trigger.TargetSchema?.Equals(
                    "main",
                    StringComparison.OrdinalIgnoreCase) == true
                    && string.Equals(trigger.TableName, rename.TableName, StringComparison.OrdinalIgnoreCase);
                candidateCatalog.Triggers[trigger.Name] = trigger with
                {
                    TableName = watchesRenamedMainTable ? rename.NewName : trigger.TableName,
                    UpdateOfColumns = parsed.UpdateOfColumns,
                    When = parsed.When,
                    Body = parsed.Body,
                    Sql = parsed.Sql,
                };
                changed = true;
            }

            if (changed)
                return new PendingTempTriggerCatalogRewrite(candidateCatalog);

            candidateCatalog.DisconnectOwnedVirtualTables();
            return null;
        }
        catch
        {
            candidateCatalog.DisconnectOwnedVirtualTables();
            throw;
        }
    }

    private void ValidateTempTableOwnedTriggers(CancellationToken cancellationToken)
    {
        var tempCatalog = GetTransactionState(_tempDatabase)?.Catalog ?? _tempDatabase.LiveCatalog;
        var mainCatalog = GetTransactionState(_database)?.Catalog ?? _database.LiveCatalog;
        var tables = new Dictionary<string, EmbeddedTable>(mainCatalog.Tables, StringComparer.OrdinalIgnoreCase);
        foreach (var table in tempCatalog.Tables)
            tables[table.Key] = table.Value;

        var views = new Dictionary<string, ViewDefinition>(mainCatalog.Views, StringComparer.OrdinalIgnoreCase);
        foreach (var view in tempCatalog.Views)
            views[view.Key] = view.Value;

        var context = new EmbeddedDatabase.QueryContext(
            tables,
            new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
            views,
            tempCatalog.Triggers,
            SchemaValidation: true);
        foreach (var trigger in tempCatalog.Triggers.Values)
        {
            // Explicitly qualified body statements are routed by the connection at execution time.
            // This combined-catalog preflight only models temp-first unqualified resolution.
            if (trigger.TargetSchema is not null
                || trigger.Body.Any(ContainsSchemaQualification))
            {
                continue;
            }

            try
            {
                _tempDatabase.ValidateTriggerSchema(trigger, context, cancellationToken);
            }
            catch (EmbeddedSqlException exception)
            {
                throw new EmbeddedSqlException($"error in trigger {trigger.Name}: {exception.Message}", exception);
            }
        }
    }

    private PendingTempTriggerCatalogRewrite? PrepareTempTriggerColumnRename(
        RoutedStatement routed,
        CancellationToken cancellationToken)
    {
        if (routed.Statement is not AlterTableRenameColumnStatement rename)
        {
            return null;
        }

        if (ReferenceEquals(routed.Database, _tempDatabase))
        {
            ValidateTempTableOwnedTriggersAfterColumnRename(rename, cancellationToken);
            return null;
        }

        if (GetSchemaName(routed.Database) is not { } alteredSchema)
            return null;

        var tempCatalog = GetTransactionState(_tempDatabase)?.Catalog ?? _tempDatabase.LiveCatalog;
        if (tempCatalog.Triggers.Count == 0)
            return null;

        var primaryCatalog = GetTransactionState(routed.Database)?.Catalog ?? routed.Database.LiveCatalog;
        if (!primaryCatalog.Tables.TryGetValue(rename.TableName, out var renamedTable))
            return null;

        var oldName = renamedTable.Columns[renamedTable.GetColumnIndex(rename.ColumnName)];
        var primarySchema = EmbeddedDatabase.CreateRenameColumnSchema(
            primaryCatalog.Tables,
            primaryCatalog.Views,
            renamedTable.Name,
            renamedTable.Columns.ToArray());
        var rewriteSchema = CreateTempTriggerRenameColumnSchema(primarySchema, tempCatalog, alteredSchema);
        var candidateCatalog = tempCatalog.Clone();
        try
        {
            var changed = false;
            foreach (var trigger in tempCatalog.Triggers.Values)
            {
                string? rewritten;
                try
                {
                    rewritten = RenameColumnRewriter.RewriteSchemaObject(
                        trigger.Sql,
                        oldName,
                        rename.NewName,
                        rename.QuoteNewName,
                        rewriteSchema);
                }
                catch (RenameColumnRewriteException exception)
                {
                    throw new EmbeddedSqlException(
                        $"error in trigger {trigger.Name} after rename: {exception.Message}",
                        exception);
                }

                if (rewritten is null)
                    continue;

                var parsed = (CreateTriggerStatement)SqlParser.Parse(rewritten, SqlParameterMap.Parse(rewritten));
                candidateCatalog.Triggers[trigger.Name] = trigger with
                {
                    UpdateOfColumns = parsed.UpdateOfColumns,
                    When = parsed.When,
                    Body = parsed.Body,
                    Sql = parsed.Sql,
                };
                changed = true;
            }

            if (alteredSchema.Equals("main", StringComparison.OrdinalIgnoreCase))
            {
                ValidateTempTriggersAfterMainColumnRename(
                    rename,
                    renamedTable,
                    primaryCatalog,
                    tempCatalog,
                    candidateCatalog,
                    cancellationToken);
            }
            if (changed)
                return new PendingTempTriggerCatalogRewrite(candidateCatalog);

            candidateCatalog.DisconnectOwnedVirtualTables();
            return null;
        }
        catch
        {
            candidateCatalog.DisconnectOwnedVirtualTables();
            throw;
        }
    }

    private void ValidateTempTriggersAfterMainColumnRename(
        AlterTableRenameColumnStatement rename,
        EmbeddedTable originalTable,
        EmbeddedDatabase.SchemaCatalog primaryCatalog,
        EmbeddedDatabase.SchemaCatalog tempCatalog,
        EmbeddedDatabase.SchemaCatalog candidateTempCatalog,
        CancellationToken cancellationToken)
    {
        var candidatePrimaryTables = new Dictionary<string, EmbeddedTable>(
            primaryCatalog.Tables,
            StringComparer.OrdinalIgnoreCase)
        {
            [rename.TableName] = originalTable.CreateWithRenamedColumn(
                rename.ColumnName,
                rename.NewName,
                rename.QuoteNewName,
                cancellationToken),
        };
        var tables = new Dictionary<string, EmbeddedTable>(
            candidatePrimaryTables,
            StringComparer.OrdinalIgnoreCase);
        foreach (var table in candidateTempCatalog.Tables)
            tables[table.Key] = table.Value;

        var views = new Dictionary<string, ViewDefinition>(primaryCatalog.Views, StringComparer.OrdinalIgnoreCase);
        foreach (var view in candidateTempCatalog.Views)
            views[view.Key] = view.Value;

        var context = new EmbeddedDatabase.QueryContext(
            tables,
            new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
            views,
            candidateTempCatalog.Triggers,
            SchemaValidation: true);
        foreach (var trigger in candidateTempCatalog.Triggers.Values)
        {
            // Explicitly qualified body statements are routed by the connection at execution time.
            // This combined-catalog candidate check only models unqualified temp-first resolution.
            if (trigger.TargetSchema is not null
                || trigger.Body.Any(ContainsSchemaQualification))
            {
                continue;
            }

            try
            {
                _tempDatabase.ValidateTriggerSchema(trigger, context, cancellationToken);
            }
            catch (EmbeddedSqlException exception)
            {
                throw new EmbeddedSqlException(
                    $"error in trigger {trigger.Name} after rename: {exception.Message}",
                    exception);
            }
        }
    }

    private void ValidateTempTriggersAfterDropColumn(
        RoutedStatement routed,
        CancellationToken cancellationToken)
    {
        if (routed.Statement is not AlterTableDropColumnStatement drop
            || (!ReferenceEquals(routed.Database, _database)
                && !ReferenceEquals(routed.Database, _tempDatabase)))
        {
            return;
        }

        var ownedMainCatalog = GetTransactionState(_database) is null
            ? _database.SnapshotCatalog()
            : null;
        var ownedTempCatalog = GetTransactionState(_tempDatabase) is null
            ? _tempDatabase.SnapshotCatalog()
            : null;
        var mainCatalog = GetTransactionState(_database)?.Catalog ?? ownedMainCatalog!;
        var tempCatalog = GetTransactionState(_tempDatabase)?.Catalog ?? ownedTempCatalog!;
        try
        {
            var alteredCatalog = ReferenceEquals(routed.Database, _database) ? mainCatalog : tempCatalog;
            if (tempCatalog.Triggers.Count == 0
                || !alteredCatalog.Tables.TryGetValue(drop.TableName, out var originalTable))
            {
                return;
            }

            var replacement = originalTable.CreateWithoutColumn(drop.ColumnName, cancellationToken);
            var candidateMainTables = new Dictionary<string, EmbeddedTable>(mainCatalog.Tables, StringComparer.OrdinalIgnoreCase);
            var candidateTempTables = new Dictionary<string, EmbeddedTable>(tempCatalog.Tables, StringComparer.OrdinalIgnoreCase);
            (ReferenceEquals(routed.Database, _database) ? candidateMainTables : candidateTempTables)[drop.TableName] = replacement;

            var currentContext = CreateTempFirstValidationContext(
                mainCatalog.Tables,
                mainCatalog.Views,
                tempCatalog.Tables,
                tempCatalog.Views,
                tempCatalog.Triggers);
            var candidateContext = CreateTempFirstValidationContext(
                candidateMainTables,
                mainCatalog.Views,
                candidateTempTables,
                tempCatalog.Views,
                tempCatalog.Triggers);
            foreach (var trigger in tempCatalog.Triggers.Values)
            {
                // Explicitly qualified body statements are routed by the connection at execution time.
                // This preflight only models unqualified temp-first resolution.
                if (trigger.TargetSchema is not null
                    || trigger.Body.Any(ContainsSchemaQualification))
                {
                    continue;
                }

                try
                {
                    _tempDatabase.ValidateTriggerSchema(trigger, currentContext, cancellationToken);
                }
                catch (EmbeddedSqlException exception)
                {
                    throw new EmbeddedSqlException($"error in trigger {trigger.Name}: {exception.Message}", exception);
                }

                try
                {
                    _tempDatabase.ValidateTriggerSchema(trigger, candidateContext, cancellationToken);
                }
                catch (EmbeddedSqlException exception)
                {
                    throw new EmbeddedSqlException(
                        $"error in trigger {trigger.Name} after drop column: {exception.Message}",
                        exception);
                }
            }
        }
        finally
        {
            ownedMainCatalog?.DisconnectOwnedVirtualTables();
            ownedTempCatalog?.DisconnectOwnedVirtualTables();
        }
    }

    private static EmbeddedDatabase.QueryContext CreateTempFirstValidationContext(
        IReadOnlyDictionary<string, EmbeddedTable> mainTables,
        IReadOnlyDictionary<string, ViewDefinition> mainViews,
        IReadOnlyDictionary<string, EmbeddedTable> tempTables,
        IReadOnlyDictionary<string, ViewDefinition> tempViews,
        IReadOnlyDictionary<string, TriggerDefinition> tempTriggers)
    {
        var tables = new Dictionary<string, EmbeddedTable>(mainTables, StringComparer.OrdinalIgnoreCase);
        foreach (var table in tempTables)
            tables[table.Key] = table.Value;

        var views = new Dictionary<string, ViewDefinition>(mainViews, StringComparer.OrdinalIgnoreCase);
        foreach (var view in tempViews)
            views[view.Key] = view.Value;

        return new EmbeddedDatabase.QueryContext(
            tables,
            new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
            views,
            tempTriggers,
            SchemaValidation: true);
    }

    private void ValidateTempTableOwnedTriggersAfterColumnRename(
        AlterTableRenameColumnStatement rename,
        CancellationToken cancellationToken)
    {
        var tempCatalog = GetTransactionState(_tempDatabase)?.Catalog ?? _tempDatabase.LiveCatalog;
        if (!tempCatalog.Tables.TryGetValue(rename.TableName, out var originalTable))
            return;

        var columnIndex = Array.FindIndex(
            originalTable.Columns,
            column => column.Equals(rename.ColumnName, StringComparison.OrdinalIgnoreCase));
        if (columnIndex < 0)
            return;

        var oldName = originalTable.Columns[columnIndex];
        var candidateTables = new Dictionary<string, EmbeddedTable>(tempCatalog.Tables, StringComparer.OrdinalIgnoreCase)
        {
            [rename.TableName] = originalTable.CreateWithRenamedColumn(
                rename.ColumnName,
                rename.NewName,
                rename.QuoteNewName,
                cancellationToken),
        };
        var rewriteSchema = EmbeddedDatabase.CreateRenameColumnSchema(
            candidateTables,
            tempCatalog.Views,
            originalTable.Name,
            originalTable.Columns);
        var candidateContext = new EmbeddedDatabase.QueryContext(
            candidateTables,
            new Dictionary<string, SourceData>(StringComparer.OrdinalIgnoreCase),
            tempCatalog.Views,
            tempCatalog.Triggers,
            SchemaValidation: true);
        foreach (var trigger in tempCatalog.Triggers.Values)
        {
            // Explicitly qualified body statements are routed by the connection at execution time.
            // This candidate check only models temp-local, unqualified trigger bodies.
            if (trigger.TargetSchema is not null
                || trigger.Body.Any(ContainsSchemaQualification))
            {
                continue;
            }

            string? rewritten;
            try
            {
                rewritten = RenameColumnRewriter.RewriteSchemaObject(
                    trigger.Sql,
                    oldName,
                    rename.NewName,
                    rename.QuoteNewName,
                    rewriteSchema);
            }
            catch (RenameColumnRewriteException exception)
            {
                throw new EmbeddedSqlException(
                    $"error in trigger {trigger.Name} after rename: {exception.Message}",
                    exception);
            }

            if (rewritten is null)
                continue;

            var parsed = (CreateTriggerStatement)SqlParser.Parse(rewritten, SqlParameterMap.Parse(rewritten));
            var candidate = trigger with
            {
                UpdateOfColumns = parsed.UpdateOfColumns,
                When = parsed.When,
                Body = parsed.Body,
                Sql = parsed.Sql,
            };
            try
            {
                _tempDatabase.ValidateTriggerSchema(
                    candidate,
                    candidateContext,
                    cancellationToken,
                    pseudoRowTable: string.Equals(
                        trigger.TableName,
                        rename.TableName,
                        StringComparison.OrdinalIgnoreCase)
                        ? originalTable
                        : null);
            }
            catch (EmbeddedSqlException exception)
            {
                throw new EmbeddedSqlException(
                    $"error in trigger {trigger.Name} after rename: {exception.Message}",
                    exception);
            }
        }
    }

    private static RenameColumnSchema CreateTempTriggerRenameColumnSchema(
        RenameColumnSchema primarySchema,
        EmbeddedDatabase.SchemaCatalog tempCatalog,
        string primarySchemaName)
    {
        return new RenameColumnSchema(ResolveColumns, IsRenameTarget);

        IReadOnlyList<string>? ResolveColumns(string name)
        {
            if (ManagedSchemaName.TrySplit(name, out var schema, out var localName))
            {
                return schema.Equals("temp", StringComparison.OrdinalIgnoreCase)
                    ? ResolveTempColumns(localName)
                    : schema.Equals(primarySchemaName, StringComparison.OrdinalIgnoreCase)
                        ? primarySchema.ResolveColumns(name)
                        : null;
            }

            return ResolveTempColumns(name) ?? primarySchema.ResolveColumns(name);
        }

        bool IsRenameTarget(string name)
        {
            if (ManagedSchemaName.TrySplit(name, out var schema, out _))
                return schema.Equals(primarySchemaName, StringComparison.OrdinalIgnoreCase)
                    && primarySchema.IsRenameTarget(name);

            return ResolveTempColumns(name) is null && primarySchema.IsRenameTarget(name);
        }

        IReadOnlyList<string>? ResolveTempColumns(string name)
        {
            if (tempCatalog.Tables.TryGetValue(name, out var table))
                return table.Columns;

            return tempCatalog.Views.TryGetValue(name, out var view) ? view.Columns : null;
        }
    }

    private void PublishTempTriggerCatalogRewrite(PendingTempTriggerCatalogRewrite pending)
    {
        if (GetTransactionState(_tempDatabase) is { } state)
        {
            var previous = state.Catalog;
            state.Catalog = pending.Catalog;
            previous.DisconnectOwnedVirtualTables(state.VirtualTableTransaction);
            state.HasChanges = true;
            // Rewriting the temp trigger catalog for a rename is not a targeted index
            // rebuild: an earlier REINDEX in this same transaction must not cause commit
            // to skip persisting this rewrite.
            state.HasNonTargetedIndexRebuildChange = true;
            state.PragmaHeader = state.PragmaHeader with
            {
                SchemaVersion = unchecked(state.PragmaHeader.SchemaVersion + 1),
            };
        }
        else
        {
            _tempDatabase.PublishTriggerBodyCatalog(pending.Catalog, forceFullRewrite: false);
        }

        _tempInitialized = true;
    }

    private sealed class AttachedDatabase : IDisposable
    {
        public AttachedDatabase(
            string path,
            string pathIdentity,
            EmbeddedDatabase database,
            int sequence,
            IDisposable? ownedFileSystem)
        {
            Path = path;
            PathIdentity = pathIdentity;
            Database = database;
            Sequence = sequence;
            OwnedFileSystem = ownedFileSystem;
        }

        public string Path { get; }
        public string PathIdentity { get; }
        public EmbeddedDatabase Database { get; }
        public int Sequence { get; }
        private IDisposable? OwnedFileSystem { get; }

        public void Dispose()
        {
            try
            {
                Database.Dispose();
            }
            finally
            {
                OwnedFileSystem?.Dispose();
            }
        }
    }

    private sealed class ConnectionStatementReaderLease(
        EmbeddedConnection owner,
        IDisposable[] databaseLeases) : IDisposable
    {
        private EmbeddedConnection? _owner = owner;
        private IDisposable[]? _databaseLeases = databaseLeases;

        public void Dispose()
        {
            var currentOwner = Interlocked.Exchange(ref _owner, null);
            var leases = Interlocked.Exchange(ref _databaseLeases, null);
            if (currentOwner is not null && leases is not null)
                currentOwner.ReleaseStatementReader(this, leases);
        }

        internal void ReleaseFromOwner()
        {
            _ = Interlocked.Exchange(ref _owner, null);
            var leases = Interlocked.Exchange(ref _databaseLeases, null);
            DisposeDatabaseLeases(leases);
        }
    }

    private sealed class TransactionDatabaseState(
        EmbeddedDatabase.SchemaCatalog catalog,
        long version,
        PragmaHeaderMetadata pragmaHeader)
    {
        public EmbeddedDatabase.SchemaCatalog Catalog { get; set; } = catalog;
        public long Version { get; } = version;
        public PragmaHeaderMetadata PragmaHeader { get; set; } = pragmaHeader;
        public bool HasChanges { get; set; }
        public bool HasSnapshotPragmaHeader { get; set; }
        public bool HasSchemaChanges { get; set; }
        public bool ForceFullCatalogRewrite { get; set; }

        /// <summary>
        /// Index names a REINDEX statement anywhere in this transaction (or an enclosing
        /// savepoint) targeted for an in-place rebuild, unioned across every such statement.
        /// Deliberately just names, never the <see cref="EmbeddedTable"/>/<see
        /// cref="EmbeddedIndex"/> objects a statement's <c>ExecutionResult</c> captured at the
        /// time it ran: a later statement in the same transaction can still mutate that same
        /// table, which would leave a captured object stale. Resolving these names against the
        /// transaction's actual final catalog at commit (see the <c>CommitTransaction</c>
        /// overload below) means intervening DML can never be rebuilt from stale data, and an
        /// intervening schema/index change that drops or redefines the target is caught by
        /// <c>EmbeddedFileStore.HasCurrentSchemaShape</c>'s existing schema-signature check,
        /// which safely widens to the unconditional full-catalog rewrite
        /// <see cref="ForceFullCatalogRewrite"/> already guarantees for any REINDEX.
        /// </summary>
        public HashSet<string> TargetedIndexRebuildNames { get; } = new(StringComparer.OrdinalIgnoreCase);

        /// <summary>
        /// Set whenever this transaction changed anything other than the ordinary index trees
        /// named by <see cref="TargetedIndexRebuildNames"/> -- any INSERT/UPDATE/DELETE, pragma
        /// header write, schema change, CDC record, virtual-table mutation, bare/collation
        /// REINDEX, or a REINDEX that rebuilt a method index. A targeted, in-place index rebuild
        /// (<c>EmbeddedFileStore.TryPersistTargetedIndexRebuild</c>) only ever rewrites the named
        /// index trees themselves; it never re-derives or rewrites any table's row storage. If
        /// commit only checked <see cref="TargetedIndexRebuildNames"/> for emptiness it would
        /// silently drop every other durable change the moment a targeted REINDEX shares a
        /// transaction with them -- the in-memory catalog would look correct until the store is
        /// reopened, at which point the un-persisted DML/schema/CDC/virtual-table changes are
        /// simply gone. Commit must therefore widen to the full-catalog rewrite (which
        /// <see cref="ForceFullCatalogRewrite"/> already guarantees runs for any REINDEX) whenever
        /// this is true, by treating <see cref="TargetedIndexRebuildNames"/> as empty.
        /// </summary>
        public bool HasNonTargetedIndexRebuildChange { get; set; }
        public HashSet<EmbeddedDatabase.ForeignKeyViolation> PendingDeferredViolations { get; } = [];
        public EmbeddedDatabase.ManagedVirtualTableTransaction VirtualTableTransaction { get; } = new();

        /// <summary>
        /// The durable pager read snapshot pinned at BEGIN for a file-backed transaction, coupled
        /// to <see cref="Catalog"/>/<see cref="Version"/> at the same locked point in time. Also
        /// populated for a concurrent (MVCC) transaction — a durable index accessor opened
        /// against this snapshot merges lazily with visible <c>MvStore</c> effects instead of
        /// materializing the base index (see <c>TryOpenConcurrentMvccIndexAccessor</c>). Null for
        /// an in-memory/temp database. Disposed centrally in ResetTransactionState.
        /// </summary>
        public EmbeddedFileReadSnapshot? PinnedSnapshot { get; set; }

        /// <summary>
        /// Per-table mutation bookkeeping fed by every DML path a classic (non-MVCC) transaction
        /// executes, so a durable index seek against <see cref="PinnedSnapshot"/> can merge in
        /// read-your-writes without materializing the whole index. Always null for a concurrent
        /// (MVCC) transaction — that transaction's own writes live in the attached <c>MvStore</c>
        /// instead and are merged in via <c>ConcurrentMvStore</c>/<c>ConcurrentMvccTxId</c>.
        /// </summary>
        public TransactionMutationOverlay? Overlay { get; set; }
    }


    private readonly record struct RoutedStatement(
        EmbeddedDatabase Database,
        ParsedStatement Statement,
        bool IsAttached,
        EmbeddedDatabase.SchemaCatalog? ReadCatalog = null,
        IReadOnlyDictionary<string, EmbeddedTable>? ExternalTables = null);

    internal EmbeddedConnection(EmbeddedDatabase database)
    {
        _database = database;
        _tempDatabase = new EmbeddedDatabase();
        _database.CopyFunctionAndCollationRegistriesTo(_tempDatabase);
    }

    internal bool HasActiveTransaction => _transactionDatabases is not null;

    internal IDisposable OpenStatementReaderLease()
    {
        ThrowIfDisposed();
        var databases = new[] { _database }
            .Concat(_attachedDatabases.Values.Select(attachment => attachment.Database))
            .Distinct()
            .ToArray();
        var databaseLeases = new List<IDisposable>(databases.Length);
        try
        {
            foreach (var database in databases)
                databaseLeases.Add(database.OpenStatementReaderLease());

            var lease = new ConnectionStatementReaderLease(this, databaseLeases.ToArray());
            lock (_statementReaderGate)
            {
                ThrowIfDisposed();
                if (!_statementReaders.Add(lease))
                    throw new InvalidOperationException("Managed statement reader lease is already registered.");
            }

            return lease;
        }
        catch
        {
            DisposeDatabaseLeases(databaseLeases);
            throw;
        }
    }

    internal EmbeddedConnection OpenDatabaseConnection(string databaseName)
        => ResolveDatabase(databaseName).Connect();

    internal (EmbeddedConnection Connection, EmbeddedDatabase? Owner) OpenSnapshotConnection(
        string databaseName)
    {
        var database = ResolveDatabase(databaseName);
        if (!database.IsFileBacked)
            return (database.Connect(), null);

        var snapshot = EmbeddedDatabase.OpenFile(
            database.DatabasePath,
            database.FileSystem,
            readOnly: true);
        try
        {
            database.CopyFunctionAndCollationRegistriesTo(snapshot);
            return (snapshot.Connect(), snapshot);
        }
        catch
        {
            snapshot.Dispose();
            throw;
        }
    }

    internal bool ReferencesSameDatabase(
        string databaseName,
        EmbeddedConnection other,
        string otherDatabaseName)
    {
        ArgumentNullException.ThrowIfNull(other);
        return ResolveDatabase(databaseName).ReferencesSameDatabase(other.ResolveDatabase(otherDatabaseName));
    }

    internal bool CannotProveDistinctSnapshotFiles(
        string databaseName,
        EmbeddedConnection other,
        string otherDatabaseName)
    {
        ArgumentNullException.ThrowIfNull(other);
        var database = ResolveDatabase(databaseName);
        var otherDatabase = other.ResolveDatabase(otherDatabaseName);
        if (!database.IsFileBacked || !otherDatabase.IsFileBacked)
            return false;

        var storageKind = GetSnapshotStorageKind(database.FileSystem);
        var otherStorageKind = GetSnapshotStorageKind(otherDatabase.FileSystem);
        if (storageKind != SnapshotStorageKind.Unknown
            && otherStorageKind != SnapshotStorageKind.Unknown)
        {
            return false;
        }

        var fileSystem = AhtolaEncryptionFileSystem.Unwrap(database.FileSystem);
        var otherFileSystem = AhtolaEncryptionFileSystem.Unwrap(otherDatabase.FileSystem);
        return !CanProveDistinctSnapshotFiles(
            fileSystem,
            database.DatabasePath,
            otherFileSystem,
            otherDatabase.DatabasePath);
    }

    private static bool CanProveDistinctSnapshotFiles(
        IFileSystem fileSystem,
        string path,
        IFileSystem otherFileSystem,
        string otherPath)
        => fileSystem is ISnapshotFileIdentity identity
               && identity.CanProveDistinctFile(path, otherFileSystem, otherPath)
           || otherFileSystem is ISnapshotFileIdentity otherIdentity
               && otherIdentity.CanProveDistinctFile(otherPath, fileSystem, path);

    private static SnapshotStorageKind GetSnapshotStorageKind(IFileSystem fileSystem)
        => AhtolaEncryptionFileSystem.Unwrap(fileSystem) switch
        {
            PhysicalFileSystem => SnapshotStorageKind.Physical,
            InMemoryFileSystem => SnapshotStorageKind.InMemory,
            _ => SnapshotStorageKind.Unknown,
        };

    private enum SnapshotStorageKind
    {
        Physical,
        InMemory,
        Unknown,
    }

    public EmbeddedStatement Prepare(string sql)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ThrowIfDisposed();
        ThrowIfInsideHookCallback();
        var parameterMap = SqlParameterMap.Parse(sql);
        var statement = SqlParser.Parse(sql, parameterMap);
        if (_hooks.Authorizer is not null)
            statement = Authorize(statement);

        return new EmbeddedStatement(this, statement, parameterMap, sql);
    }

    /// <summary>
    /// The callbacks registered on this connection. Mutating the returned instance takes effect
    /// on the next prepared statement or execution, mirroring SQLite's hook registration APIs.
    /// </summary>
    public ManagedConnectionHooks Hooks => _hooks;

    private ParsedStatement Authorize(ParsedStatement statement)
    {
        var authorizer = _hooks.Authorizer!;
        var catalog = _transactionDatabases is not null
            && _transactionDatabases.TryGetValue(_database, out var transactionState)
            ? transactionState.Catalog
            : _database.CreateAuthorizationCatalog();
        var tempCatalog = _tempDatabase.CreateAuthorizationCatalog();
        return SqlAuthorization.Apply(
            statement,
            catalog,
            tempCatalog,
            context => InvokeHook(() => authorizer(context)));
    }

    /// <summary>
    /// Builds the per-execution hook payload for a routed statement. Returning <c>null</c> when
    /// nothing is registered keeps the uninstrumented execution path byte-for-byte unchanged.
    /// </summary>
    private ManagedStatementHooks? CreateStatementHooks(EmbeddedDatabase database, bool includeCommitGate)
    {
        var updateHook = _hooks.UpdateHook;
        var detailedUpdateHook = _hooks.DetailedUpdateHook;
        var commitHook = includeCommitGate ? _hooks.CommitHook : null;
        var progressHandler = _hooks.ProgressHandler;
        var progressInterval = _hooks.ProgressInterval;
        if (updateHook is null
            && detailedUpdateHook is null
            && commitHook is null
            && (progressHandler is null || progressInterval <= 0))
            return null;

        var schema = ResolveSchemaName(database);
        return new ManagedStatementHooks
        {
            RowChanged = (updateHook is null && detailedUpdateHook is null) || _suppressUpdateHook
                ? null
                : (operation, table, rowId, before, after) =>
                {
                    if (updateHook is not null)
                        InvokeHook(() => updateHook(new SqliteRowChange(operation, schema, table, rowId)));
                    if (detailedUpdateHook is not null)
                    {
                        InvokeHook(() => detailedUpdateHook(new ManagedSqliteRowChange(
                            operation,
                            schema,
                            table,
                            rowId,
                            before?.ToArray(),
                            after?.ToArray())));
                    }
                },
            CommitGate = commitHook is null ? null : () => InvokeHook(commitHook),
            Progress = progressHandler is null || progressInterval <= 0
                ? null
                : new ManagedProgressCounter(progressInterval, () => InvokeHook(progressHandler)),
        };
    }

    /// <summary>
    /// Builds the hooks for a temp trigger body statement that runs against <paramref name="target"/>
    /// while a different database executes the firing statement. The update hook has to report the
    /// schema that actually changed, so it is rebuilt for the target rather than forwarded; the
    /// commit gate is dropped because a nested body must not re-arm the outer statement's gate; and
    /// the outer progress counter is reused so its step interval keeps counting across the hop and
    /// can still interrupt the statement.
    /// </summary>
    private ManagedStatementHooks? CreateTriggerBodyHooks(
        EmbeddedDatabase target,
        ManagedStatementHooks? outerHooks)
    {
        var targetHooks = CreateStatementHooks(target, includeCommitGate: false);
        if (outerHooks?.Progress is not { } progress)
            return targetHooks;

        return targetHooks is null
            ? new ManagedStatementHooks { Progress = progress }
            : new ManagedStatementHooks { RowChanged = targetHooks.RowChanged, Progress = progress };
    }

    private string ResolveSchemaName(EmbeddedDatabase database)
    {
        if (ReferenceEquals(database, _tempDatabase))
            return "temp";

        foreach (var attachment in _attachedDatabases)
        {
            if (ReferenceEquals(attachment.Value.Database, database))
                return attachment.Key;
        }

        return "main";
    }

    private void FireRollbackHook()
    {
        if (_hooks.RollbackHook is { } rollbackHook)
            InvokeHook(rollbackHook);
    }

    internal void FireTraceHook(string sql)
    {
        if (_hooks.Trace is { } trace)
            InvokeHook(() => trace(sql));
    }

    /// <summary>
    /// Runs a user callback with reentrancy tracking. The managed engine cannot execute a
    /// statement while a mutation is in flight, so a hook that calls back into its own
    /// connection fails loudly instead of corrupting the working catalog.
    /// </summary>
    private void InvokeHook(Action callback)
    {
        if (_insideHookCallback)
            ThrowHookReentry();

        _insideHookCallback = true;
        try
        {
            callback();
        }
        finally
        {
            _insideHookCallback = false;
        }
    }

    private T InvokeHook<T>(Func<T> callback)
    {
        if (_insideHookCallback)
            ThrowHookReentry();

        _insideHookCallback = true;
        try
        {
            return callback();
        }
        finally
        {
            _insideHookCallback = false;
        }
    }

    internal void ThrowIfInsideHookCallback()
    {
        if (_insideHookCallback)
            ThrowHookReentry();
    }

    private static void ThrowHookReentry()
        => throw new EmbeddedSqlException(
            "Managed connections do not support reentrant use of the connection from a hook callback.");

    public IReadOnlyList<EmbeddedStatement> PrepareScript(string sql)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ThrowIfDisposed();
        return SqlScript.Split(sql).Select(Prepare).ToArray();
    }

    public void ResetForPooling()
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ThrowIfDisposed();
        ReleaseAllStatementReaders();
        ResetTransactionState();
        _lastInsertRowId = 0;
        _queryOnly = false;
        BusyTimeout = TimeSpan.Zero;
        _foreignKeys = false;
        _deferForeignKeys = false;
        _recursiveTriggers = false;
        _tempStore = 0;
        _ignoreCheckConstraints = false;
        _requireWhere = false;
        _cacheSizes.Clear();
        _cacheSpills.Clear();
        _synchronousModes.Clear();
        ReleaseExclusiveLockingModes();
        _dataSyncRetry = false;
        _fullColumnNames = false;
        _shortColumnNames = true;
        _mvccCheckpointThreshold = DefaultMvccCheckpointThreshold;
        _mvccGcThreshold = DefaultMvccGcThreshold;
        _tempInitialized = false;
        _pendingPageSizes.Clear();
        _changeDataCapture = null;
        _suppressUpdateHook = false;
        _hooks.UpdateHook = null;
        _hooks.CommitHook = null;
        _hooks.RollbackHook = null;
        _hooks.Authorizer = null;
        _hooks.Trace = null;
        _hooks.ProgressHandler = null;
        _hooks.ProgressInterval = 0;
        foreach (var attachment in _attachedDatabases.Values)
            attachment.Dispose();
        _attachedDatabases.Clear();
        ResetTemporaryDatabase();
        _database.RefreshFileCatalogForPooling();
    }

    public void RegisterScalarFunction(string name, int arity, Func<IReadOnlyList<SqlValue>, SqlValue> function)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ThrowIfDisposed();
        _database.RegisterScalarFunction(name, arity, function);
        _tempDatabase.RegisterScalarFunction(name, arity, function);
        foreach (var attachment in _attachedDatabases.Values)
            attachment.Database.RegisterScalarFunction(name, arity, function);
    }

