    internal IDisposable OpenBlobMutationLease(string databaseName, string tableName, long rowId)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ThrowIfDisposed();
        return ResolveBlobDatabase(databaseName).OpenBlobMutationLease(tableName, rowId);
    }

    internal long GetBlobMutationGeneration(string databaseName, string tableName, long rowId)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ThrowIfDisposed();
        return ResolveBlobDatabase(databaseName).GetBlobMutationGeneration(tableName, rowId);
    }

    internal bool HasUpdateTrigger(string databaseName, string tableName)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ThrowIfDisposed();
        var database = ResolveBlobDatabase(databaseName);
        var catalog = GetTransactionState(database)?.Catalog;
        return catalog is null
            ? database.HasUpdateTrigger(tableName)
            : catalog.Triggers.Values.Any(trigger =>
                trigger.Event == TriggerEvent.Update
                && string.Equals(trigger.TableName, tableName, StringComparison.OrdinalIgnoreCase));
    }

    internal bool HasAttachedDatabases => _attachedDatabases.Count != 0;

    public void Dispose()
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ReleaseAllStatementReaders();
        ResetTransactionState();
        ReleaseExclusiveLockingModes();
        foreach (var attachment in _attachedDatabases.Values)
            attachment.Dispose();
        _attachedDatabases.Clear();
        _tempDatabase.Dispose();
        _disposed = true;
    }

    private void ReleaseStatementReader(
        ConnectionStatementReaderLease lease,
        IDisposable[] databaseLeases)
    {
        lock (_statementReaderGate)
            _statementReaders.Remove(lease);
        DisposeDatabaseLeases(databaseLeases);
    }

    private void ReleaseAllStatementReaders()
    {
        ConnectionStatementReaderLease[] readers;
        lock (_statementReaderGate)
        {
            readers = _statementReaders.ToArray();
            _statementReaders.Clear();
        }

        foreach (var reader in readers)
            reader.ReleaseFromOwner();
    }

    private static void DisposeDatabaseLeases(IEnumerable<IDisposable>? leases)
    {
        if (leases is null)
            return;
        foreach (var lease in leases.Reverse())
            lease.Dispose();
    }

    private void ResetTemporaryDatabase()
    {
        _cacheSizes.Remove(_tempDatabase);
        _cacheSpills.Remove(_tempDatabase);
        _synchronousModes.Remove(_tempDatabase);
        ReleaseExclusiveLockingMode(_tempDatabase);
        _tempDatabase.Dispose();
        _tempDatabase = new EmbeddedDatabase();
        _database.CopyFunctionAndCollationRegistriesTo(_tempDatabase);
    }

    internal ExecutionResult Execute(
        ParsedStatement statement,
        SqlValue[] parameters,
        CancellationToken cancellationToken = default)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        ThrowIfDisposed();
        ThrowIfInsideHookCallback();
        cancellationToken.ThrowIfCancellationRequested();
        ThrowIfRequireWhereViolated(statement);
        if (_transactionMutationDatabase is not null && StatementMayMutate(_database, statement))
        {
            throw new EmbeddedSqlException(
                "Managed connections do not support reentrant writes from SQL callbacks.");
        }
        if (_transactionMutationDatabase is not null
            && statement is BeginStatement
                or CommitStatement
                or RollbackStatement
                or SavepointStatement
                or ReleaseSavepointStatement
                or RollbackToSavepointStatement
                or AttachDatabaseStatement
                or DetachDatabaseStatement)
        {
            throw new EmbeddedSqlException(
                "Managed SQL callbacks cannot change transaction or attachment state during a write.");
        }
        if (_transactionIsConcurrent
            && _transactionDatabases is not null
            && EmbeddedDatabase.MayChangeSchema(statement))
        {
            BeginConcurrentSchemaChange();
        }

        if (_transactionDatabases is null)
        {
            _database.RefreshForeignCatalogForStatementIfNeeded();
            _database.RefreshOwnedCatalogForStatementIfNeeded();
        }

        switch (statement)
        {
            case BeginStatement begin:
                if (_transactionDatabases is not null)
                    throw new EmbeddedSqlException("cannot start a transaction within a transaction");
                BeginTransaction(openedBySavepoint: false, begin.Mode);
                return ExecutionResult.Empty;
            case CommitStatement:
                if (_transactionDatabases is null)
                    throw new EmbeddedSqlException("cannot commit - no transaction is active");

                CommitTransaction();
                return ExecutionResult.Empty;
            case RollbackStatement:
                if (_transactionDatabases is null)
                    throw new EmbeddedSqlException("cannot rollback - no transaction is active");

                ResetTransactionState();
                FireRollbackHook();
                return ExecutionResult.Empty;
            case SavepointStatement savepoint:
                CreateSavepoint(savepoint.Name);
                return ExecutionResult.Empty;
            case ReleaseSavepointStatement release:
                ReleaseSavepoint(release.Name);
                return ExecutionResult.Empty;
            case RollbackToSavepointStatement rollbackTo:
                RollbackToSavepoint(rollbackTo.Name);
                return ExecutionResult.Empty;
            case AttachDatabaseStatement attach:
                return ExecuteWithMutationReservation(
                    _database,
                    () => ExecuteAttach(attach, parameters));
            case DetachDatabaseStatement detach:
                return ExecuteDetach(detach);
            case ReindexStatement reindex when IsMultiDatabaseReindex(reindex):
                return ExecuteMultiDatabaseReindex(reindex, cancellationToken);
            case OptimizeIndexStatement { IndexName: null } optimize:
                return ExecuteMultiDatabaseOptimize(optimize, cancellationToken);
            case PragmaDatabaseListStatement databaseList:
                ValidatePragmaSchema(databaseList.Schema);
                return ExecutePragmaDatabaseList();
            case PragmaTableListStatement { Schema: null } tableList:
                return ExecutePragmaTableList(schema: null, tableList.Filter);
            case PragmaEncodingStatement encoding:
                return ExecutePragmaEncoding(encoding);
            case PragmaPageCountStatement pageCount:
                return ExecutePragmaPageCount(pageCount);
            case PragmaFreelistCountStatement freelistCount:
                return ExecutePragmaFreelistCount(freelistCount);
            case PragmaQueryOnlyStatement queryOnly:
                return ExecutePragmaQueryOnly(queryOnly);
            case PragmaForeignKeysStatement foreignKeys:
                return ExecutePragmaForeignKeys(foreignKeys);
            case PragmaDeferForeignKeysStatement deferForeignKeys:
                return ExecutePragmaDeferForeignKeys(deferForeignKeys);
            case PragmaRecursiveTriggersStatement recursiveTriggers:
                return ExecutePragmaRecursiveTriggers(recursiveTriggers);
            case PragmaCaptureDataChangesConnectionStatement captureDataChanges:
                return ExecutePragmaCaptureDataChangesConnection(captureDataChanges);
            case PragmaHeaderIntegerStatement headerInteger:
                return ExecutePragmaHeaderInteger(headerInteger, cancellationToken);
            case PragmaJournalModeStatement journalMode:
                return ExecutePragmaJournalMode(journalMode);
            case PragmaPageSizeStatement pageSize:
                return ExecutePragmaPageSize(pageSize);
            case PragmaCacheSizeStatement cacheSize:
                return ExecutePragmaCacheSize(cacheSize);
            case PragmaCacheSpillStatement cacheSpill:
                return ExecutePragmaCacheSpill(cacheSpill);
            case PragmaMaxPageCountStatement maxPageCount:
                return ExecutePragmaMaxPageCount(maxPageCount);
            case PragmaIgnoreCheckConstraintsStatement ignoreCheckConstraints:
                return ExecutePragmaIgnoreCheckConstraints(ignoreCheckConstraints);
            case PragmaRequireWhereStatement requireWhere:
                return ExecutePragmaRequireWhere(requireWhere);
            case PragmaTempStoreStatement tempStore:
                return ExecutePragmaTempStore(tempStore);
            case PragmaWalCheckpointStatement walCheckpoint:
                return ExecutePragmaWalCheckpoint(walCheckpoint);
            case PragmaBusyTimeoutStatement busyTimeout:
                return ExecutePragmaBusyTimeout(busyTimeout);
            case PragmaSynchronousStatement synchronous:
                return ExecutePragmaSynchronous(synchronous);
            case PragmaLockingModeStatement lockingMode:
                return ExecutePragmaLockingMode(lockingMode);
            case PragmaAutoVacuumStatement autoVacuum:
                return ExecutePragmaAutoVacuum(autoVacuum);
            case PragmaDataSyncRetryStatement dataSyncRetry:
                return ExecutePragmaDataSyncRetry(dataSyncRetry);
            case PragmaFullColumnNamesStatement fullColumnNames:
                return ExecutePragmaFullColumnNames(fullColumnNames);
            case PragmaShortColumnNamesStatement shortColumnNames:
                return ExecutePragmaShortColumnNames(shortColumnNames);
            case PragmaMvccCheckpointThresholdStatement mvccCheckpointThreshold:
                return ExecutePragmaMvccCheckpointThreshold(mvccCheckpointThreshold);
            case PragmaMvccGcThresholdStatement mvccGcThreshold:
                return ExecutePragmaMvccGcThreshold(mvccGcThreshold);
            case PragmaListTypesStatement listTypes:
                return ExecutePragmaListTypes(listTypes);
            case PragmaFunctionListStatement functionList:
                return ExecutePragmaFunctionList(functionList);
            case PragmaModuleListStatement moduleList:
                return ExecutePragmaModuleList(moduleList);
            case PragmaNoOpStatement:
                // SQLite silently ignores unrecognized pragmas (Turso falls through its
                // translate switch without emitting anything).
                return ExecutionResult.Empty;
            case VacuumStatement vacuum:
                return ExecuteVacuum(vacuum, parameters);
            case CreateTableAsSelectStatement createTableAs:
                if (_queryOnly)
                    throw new EmbeddedSqlException("attempt to write a readonly database");
                return ExecuteCreateTableAs(createTableAs, parameters, cancellationToken);
            default:
                var routed = RouteStatement(statement);
                var routedMayMutate = StatementMayMutate(routed.Database, routed.Statement);
                if (_queryOnly && routedMayMutate)
                    throw new EmbeddedSqlException("attempt to write a readonly database");
                var vdbeExecutionOptions = CreateVdbeExecutionOptions(routed.Database);
                // A reader-excluding EXCLUSIVE transaction on another connection blocks
                // this statement outright, which is what SQLite's EXCLUSIVE lock does
                // under a rollback journal.
                routed.Database.TransactionLock.ThrowIfReadBlocked(this, BusyTimeout);
                TransactionDatabaseState? transactionState = null;
                EmbeddedDatabase.SchemaCatalog? statementCatalog = null;
                // Mirrors statementCatalog: captured before a mutating statement runs so every
                // failure path that discards the cloned catalog also discards this statement's
                // overlay writes (QueryContext.ReportRowChange mutates the overlay in place, with
                // no clone-on-write of its own), and left alone on every path that keeps the
                // catalog (success, and SQLite's ON CONFLICT FAIL / trigger-depth PreserveChanges
                // semantics, which likewise keep the statement's partial catalog changes).
                TransactionMutationOverlayCheckpoint? statementOverlayCheckpoint = null;
                int? virtualTableTransactionCheckpoint = null;
                var retainVirtualTableParticipation = false;
                HashSet<EmbeddedDatabase.ForeignKeyViolation>? deferredBefore = null;
                var tempTriggers = CreateTempTriggerBridge(routed.Database, out var tempTriggerSession);
                var changeDataCapture = _changeDataCapture;
                changeDataCapture?.BeginStatement(routed.Statement);
                var changeDataCaptureSnapshot = changeDataCapture?.Snapshot();
                var pendingTempTriggerRewrite = PrepareTempTriggerTableRename(routed, cancellationToken)
                    ?? PrepareTempTriggerColumnRename(routed, cancellationToken);
                var pendingTempTriggerPublished = false;
                ValidateTempTriggersAfterDropColumn(routed, cancellationToken);
                MvStore? concurrentStore = null;
                MvccTxId? concurrentTxId = null;
                string? mvccStatementSavepoint = null;
                try
                {
                    ExecutionResult result;
                    transactionState = GetTransactionState(routed.Database);
                    if (transactionState is not null && routedMayMutate)
                    {
                        virtualTableTransactionCheckpoint =
                            transactionState.VirtualTableTransaction.CreateCheckpoint();
                    }
                    if (transactionState is not null
                        && _foreignKeys
                        && routedMayMutate)
                    {
                        deferredBefore = routed.Database.CollectForeignKeyViolations(
                            transactionState.Catalog.Tables,
                            includeImmediate: _deferForeignKeys);
                    }
                    var mutationReserved = ReserveTransactionMutation(routed.Database, routed.Statement);
                    TryGetConcurrentMvccScope(routed.Database, out concurrentStore, out concurrentTxId);
                    if (routedMayMutate
                        && concurrentStore is not null
                        && concurrentTxId is not null)
                    {
                        mvccStatementSavepoint = BeginConcurrentStatementSavepoint(
                            concurrentStore,
                            concurrentTxId.Value);
                    }
                    try
                    {
                        if (routed.ReadCatalog is not null)
                        {
                            result = routed.Database.Execute(
                                routed.Statement,
                                parameters,
                                routed.ReadCatalog,
                                _lastInsertRowId,
                                _foreignKeys,
                                _recursiveTriggers,
                                _deferForeignKeys,
                                inTransaction: _transactionDatabases is not null,
                                cancellationToken,
                                compilationEnabled: false,
                                tempTriggers,
                                CreateStatementHooks(routed.Database, includeCommitGate: false),
                                ignoreCheckConstraints: _ignoreCheckConstraints,
                                executeTableList: ExecutePragmaTableList,
                                concurrentMvStore: concurrentStore,
                                concurrentMvccTxId: concurrentTxId,
                                changeDataCapture: changeDataCapture,
                                vdbeExecutionOptions: vdbeExecutionOptions,
                                virtualTableTransaction: transactionState?.VirtualTableTransaction);
                        }
                        else if (transactionState is null)
                        {
                            try
                            {
                                result = routed.Database.Execute(
                                    routed.Statement,
                                    parameters,
                                    _lastInsertRowId,
                                    _foreignKeys,
                                    _recursiveTriggers,
                                    _deferForeignKeys,
                                    inTransaction: false,
                                    cancellationToken,
                                    compilationEnabled: !routed.IsAttached
                                        && !ReferenceEquals(routed.Database, _tempDatabase),
                                    tempTriggers,
                                    CreateStatementHooks(routed.Database, includeCommitGate: true),
                                    ignoreCheckConstraints: _ignoreCheckConstraints,
                                    executeTableList: ExecutePragmaTableList,
                                    externalTables: routed.ExternalTables,
                                    changeDataCapture: changeDataCapture,
                                    vdbeExecutionOptions: vdbeExecutionOptions,
                                    synchronousMode: GetSynchronousMode(routed.Database));
                            }
                            catch (Exception failure)
                                when (failure is not EmbeddedConflictFailException
                                    && routedMayMutate)
                            {
                                // SQLite rolls back the implicit transaction wrapping a failed
                                // autocommit mutation and notifies the rollback hook. ON CONFLICT
                                // FAIL is excluded because the rows written before the failure are
                                // still committed.
                                FireRollbackHook();
                                throw;
                            }
                        }
                        else
                        {
                            statementCatalog = routedMayMutate
                                ? transactionState.Catalog.Clone()
                                : transactionState.Catalog;
                            statementOverlayCheckpoint = routedMayMutate
                                ? transactionState.Overlay?.CreateCheckpoint()
                                : null;
                            result = routed.Database.Execute(
                                routed.Statement,
                                parameters,
                                statementCatalog,
                                _lastInsertRowId,
                                _foreignKeys,
                                _recursiveTriggers,
                                _deferForeignKeys,
                                inTransaction: true,
                                cancellationToken,
                                compilationEnabled: !routed.IsAttached
                                    && !ReferenceEquals(routed.Database, _tempDatabase),
                                tempTriggers,
                                CreateStatementHooks(routed.Database, includeCommitGate: false),
                                ignoreCheckConstraints: _ignoreCheckConstraints,
                                executeTableList: ExecutePragmaTableList,
                                externalTables: routed.ExternalTables,
                                concurrentMvStore: concurrentStore,
                                concurrentMvccTxId: concurrentTxId,
                                changeDataCapture: changeDataCapture,
                                vdbeExecutionOptions: vdbeExecutionOptions,
                                virtualTableTransaction: transactionState.VirtualTableTransaction,
                                transactionOverlay: transactionState.Overlay,
                                transactionPinnedSnapshot: transactionState.HasSchemaChanges
                                    ? null
                                    : transactionState.PinnedSnapshot);
                            if (routedMayMutate)
                                cancellationToken.ThrowIfCancellationRequested();
                            // The catalog overload used for transactional statements does not
                            // record change counters itself, so mirror the autocommit path here:
                            // changes()/total_changes() must observe in-transaction writes.
                            routed.Database.RecordChangeCounters(
                                routed.Statement,
                                result,
                                statementCatalog?.Views ?? transactionState.Catalog.Views);
                        }
                    }
                    finally
                    {
                        if (mutationReserved)
                            ReleaseTransactionMutation(routed.Database);
                    }
                    if (result.Changed)
                        RemoveTempTriggersForDroppedObject(routed);
                    if (transactionState is not null)
                    {
                        if (result.Changed)
                        {
                            UpdatePendingDeferredForeignKeys(
                                routed.Database,
                                transactionState,
                                statementCatalog
                                    ?? throw new InvalidOperationException(
                                        "A transactional mutation lost its statement catalog."),
                                deferredBefore);
                            var previousCatalog = transactionState.Catalog;
                            transactionState.Catalog = statementCatalog
                                ?? throw new InvalidOperationException(
                                    "A transactional mutation lost its statement catalog.");
                            previousCatalog.DisconnectOwnedVirtualTables(
                                transactionState.VirtualTableTransaction);
                            retainVirtualTableParticipation = true;
                            transactionState.HasChanges = true;
                            transactionState.ForceFullCatalogRewrite |= result.ForceFullCatalogRewrite;
                            if (result.TargetedIndexRebuild is { Count: > 0 } targetedThisStatement)
                            {
                                foreach (var target in targetedThisStatement)
                                    transactionState.TargetedIndexRebuildNames.Add(target.Index.Name);
                            }
                            else
                            {
                                // Anything that changed but was not itself a pure, in-place
                                // targeted index rebuild -- DML, schema/pragma changes, a
                                // bare/collation REINDEX, or a REINDEX that rebuilt a method
                                // index -- must widen commit off the targeted-rebuild-only
                                // persistence path (see HasNonTargetedIndexRebuildChange).
                                transactionState.HasNonTargetedIndexRebuildChange = true;
                            }
                            if (!ReferenceEquals(routed.Database, _tempDatabase))
                                _transactionWriteDatabase = routed.Database;
                            if (EmbeddedDatabase.MayChangeSchema(routed.Statement))
                            {
                                transactionState.PragmaHeader = transactionState.PragmaHeader with
                                {
                                    SchemaVersion = unchecked(transactionState.PragmaHeader.SchemaVersion + 1),
                                };
                                transactionState.HasSchemaChanges = true;
                            }

                            RecordConcurrentMvccMutation(
                                routed.Database,
                                routed.Statement,
                                statementCatalog,
                                result);
                        }
                    }

                    // last_insert_rowid() tracks the most recent successful INSERT on this
                    // connection; UPDATE/DELETE and zero-row inserts leave it unchanged.
                    if (result.LastInsertRowId is { } insertedRowId)
                        _lastInsertRowId = insertedRowId;

                    if (ReferenceEquals(routed.Database, _tempDatabase))
                        _tempInitialized = true;

                    if (result.Changed && pendingTempTriggerRewrite is not null)
                    {
                        PublishTempTriggerCatalogRewrite(pendingTempTriggerRewrite);
                        pendingTempTriggerPublished = true;
                    }

                    ReleaseConcurrentStatementSavepoint(
                        concurrentStore,
                        concurrentTxId,
                        mvccStatementSavepoint);
                    tempTriggerSession?.Commit();
                    return result;
                }
                catch (EmbeddedConflictRollbackException exception)
                {
                    if (changeDataCaptureSnapshot is { } snapshot)
                        changeDataCapture?.Restore(snapshot);
                    if (exception.LastInsertRowId is { } rolledBackInsertRowId)
                        _lastInsertRowId = rolledBackInsertRowId;
                    if (_transactionDatabases is not null)
                    {
                        ResetTransactionState();
                        FireRollbackHook();
                    }

                    throw new EmbeddedSqlException(exception.Message, exception.InnerException ?? exception);
                }
                catch (EmbeddedStatementAbortException exception)
                {
                    if (changeDataCaptureSnapshot is { } snapshot)
                        changeDataCapture?.Restore(snapshot);
                    _lastInsertRowId = exception.LastInsertRowId;
                    RollbackConcurrentStatementSavepoint(
                        concurrentStore,
                        concurrentTxId,
                        mvccStatementSavepoint);
                    // The statement's cloned catalog is discarded (never written back), so its
                    // overlay writes must be discarded too.
                    if (statementOverlayCheckpoint is not null)
                        transactionState?.Overlay?.RestoreCheckpoint(statementOverlayCheckpoint);
                    ReleaseConcurrentSchemaGateIfUnused();
                    throw new EmbeddedSqlException(exception.Message, exception.InnerException ?? exception);
                }
                catch (EmbeddedStatementFailureException exception)
                {
                    if (changeDataCaptureSnapshot is { } snapshot)
                        changeDataCapture?.Restore(snapshot);
                    _lastInsertRowId = exception.LastInsertRowId;
                    RollbackConcurrentStatementSavepoint(
                        concurrentStore,
                        concurrentTxId,
                        mvccStatementSavepoint);
                    // The statement's cloned catalog is discarded (never written back), so its
                    // overlay writes must be discarded too.
                    if (statementOverlayCheckpoint is not null)
                        transactionState?.Overlay?.RestoreCheckpoint(statementOverlayCheckpoint);
                    ReleaseConcurrentSchemaGateIfUnused();
                    ExceptionDispatchInfo.Capture(exception.Failure).Throw();
                    throw new InvalidOperationException("ExceptionDispatchInfo.Throw unexpectedly returned.");
                }
                catch (EmbeddedConflictFailException exception)
                {
                    _lastInsertRowId = exception.LastInsertRowId;
                    if (transactionState is not null)
                    {
                        UpdatePendingDeferredForeignKeys(
                            routed.Database,
                            transactionState,
                            statementCatalog
                                ?? throw new InvalidOperationException(
                                    "A partial transactional mutation lost its statement catalog."),
                            deferredBefore);
                        var previousCatalog = transactionState.Catalog;
                        transactionState.Catalog = statementCatalog
                            ?? throw new InvalidOperationException("A partial transactional mutation lost its statement catalog.");
                        previousCatalog.DisconnectOwnedVirtualTables(
                            transactionState.VirtualTableTransaction);
                        retainVirtualTableParticipation = true;
                        transactionState.HasChanges = true;
                        // A conflict-fail rollback still preserves earlier statements' partial
                        // row changes in this transaction: that is table DML, never a targeted
                        // index rebuild, so an earlier REINDEX in this transaction must not
                        // cause commit to silently omit it (see HasNonTargetedIndexRebuildChange).
                        transactionState.HasNonTargetedIndexRebuildChange = true;
                        if (!ReferenceEquals(routed.Database, _tempDatabase))
                            _transactionWriteDatabase = routed.Database;
                    }
                    if (ReferenceEquals(routed.Database, _tempDatabase))
                        _tempInitialized = true;

                    tempTriggerSession?.Commit();
                    ReleaseConcurrentStatementSavepoint(
                        concurrentStore,
                        concurrentTxId,
                        mvccStatementSavepoint);
                    ReleaseConcurrentSchemaGateIfUnused();
                    throw new EmbeddedSqlException(exception.Message, exception.InnerException ?? exception);
                }
                catch (EmbeddedTriggerDepthException exception)
                {
                    _lastInsertRowId = exception.LastInsertRowId;
                    if (transactionState is not null && exception.PreserveChanges)
                    {
                        UpdatePendingDeferredForeignKeys(
                            routed.Database,
                            transactionState,
                            statementCatalog
                                ?? throw new InvalidOperationException(
                                    "A partial recursive trigger mutation lost its statement catalog."),
                            deferredBefore);
                        var previousCatalog = transactionState.Catalog;
                        transactionState.Catalog = statementCatalog
                            ?? throw new InvalidOperationException(
                                "A partial recursive trigger mutation lost its statement catalog.");
                        previousCatalog.DisconnectOwnedVirtualTables(
                            transactionState.VirtualTableTransaction);
                        retainVirtualTableParticipation = true;
                        transactionState.HasChanges = true;
                        // Preserving the partial recursive-trigger mutation is table DML, never
                        // a targeted index rebuild: an earlier REINDEX in this same transaction
                        // must not cause commit to silently omit it.
                        transactionState.HasNonTargetedIndexRebuildChange = true;
                        if (!ReferenceEquals(routed.Database, _tempDatabase))
                            _transactionWriteDatabase = routed.Database;
                        tempTriggerSession?.Commit();
                    }
                    if (ReferenceEquals(routed.Database, _tempDatabase))
                        _tempInitialized = true;

                    if (!exception.PreserveChanges)
                    {
                        if (changeDataCaptureSnapshot is { } snapshot)
                            changeDataCapture?.Restore(snapshot);
                        RollbackConcurrentStatementSavepoint(
                            concurrentStore,
                            concurrentTxId,
                            mvccStatementSavepoint);
                        // The catalog is discarded (never written back) when a recursive-trigger
                        // abort does not preserve changes, so the overlay must discard this
                        // statement's writes too.
                        if (statementOverlayCheckpoint is not null)
                            transactionState?.Overlay?.RestoreCheckpoint(statementOverlayCheckpoint);
                    }
                    else
                    {
                        ReleaseConcurrentStatementSavepoint(
                            concurrentStore,
                            concurrentTxId,
                            mvccStatementSavepoint);
                    }
                    ReleaseConcurrentSchemaGateIfUnused();
                    throw new EmbeddedSqlException(exception.Message, exception.InnerException ?? exception);
                }
                catch (OperationCanceledException)
                {
                    if (changeDataCaptureSnapshot is { } snapshot)
                        changeDataCapture?.Restore(snapshot);
                    RollbackConcurrentStatementSavepoint(
                        concurrentStore,
                        concurrentTxId,
                        mvccStatementSavepoint);
                    if (transactionState is not null && routedMayMutate)
                    {
                        ResetTransactionState();
                        FireRollbackHook();
                    }
                    ReleaseConcurrentSchemaGateIfUnused();
                    throw;
                }
                catch
                {
                    if (changeDataCaptureSnapshot is { } snapshot)
                        changeDataCapture?.Restore(snapshot);
                    RollbackConcurrentStatementSavepoint(
                        concurrentStore,
                        concurrentTxId,
                        mvccStatementSavepoint);
                    // Any other statement failure discards the cloned catalog (never written
                    // back), so the overlay must discard this statement's writes too.
                    if (statementOverlayCheckpoint is not null)
                        transactionState?.Overlay?.RestoreCheckpoint(statementOverlayCheckpoint);
                    ReleaseConcurrentSchemaGateIfUnused();
                    throw;
                }
                finally
                {
                    tempTriggerSession?.Abandon();
                    if (!retainVirtualTableParticipation
                        && virtualTableTransactionCheckpoint is { } checkpoint
                        && transactionState is not null)
                    {
                        transactionState.VirtualTableTransaction.RollbackTo(checkpoint);
                    }
                    if (statementCatalog is not null
                        && !ReferenceEquals(transactionState?.Catalog, statementCatalog))
                    {
                        statementCatalog.DisconnectOwnedVirtualTables();
                    }
                    if (!pendingTempTriggerPublished)
                        pendingTempTriggerRewrite?.Catalog.DisconnectOwnedVirtualTables();
                }
        }
    }

    private void UpdatePendingDeferredForeignKeys(
        EmbeddedDatabase database,
        TransactionDatabaseState state,
        EmbeddedDatabase.SchemaCatalog updatedCatalog,
        HashSet<EmbeddedDatabase.ForeignKeyViolation>? before)
    {
        if (!_foreignKeys || before is null)
            return;

        var after = database.CollectForeignKeyViolations(
            updatedCatalog.Tables,
            includeImmediate: _deferForeignKeys);
        foreach (var resolved in before.Except(after))
            state.PendingDeferredViolations.Remove(resolved);
        foreach (var introduced in after.Except(before))
            state.PendingDeferredViolations.Add(introduced);
    }

    private ExecutionResult ExecuteAttach(AttachDatabaseStatement statement, SqlValue[] parameters)
    {
        EnsureAutocommitAttachmentLifecycle();
        var pathValue = _database.EvaluateConstant(statement.Path, parameters, _lastInsertRowId);
        var requestedPath = EmbeddedDatabase.ToSqlText(pathValue);
        var (path, uriReadOnly) = ResolveAttachmentPath(requestedPath);

        if (statement.Alias.Equals("main", StringComparison.OrdinalIgnoreCase)
            || statement.Alias.Equals("temp", StringComparison.OrdinalIgnoreCase))
        {
            throw new EmbeddedSqlException($"cannot attach database as {statement.Alias}");
        }

        if (_attachedDatabases.ContainsKey(statement.Alias))
            throw new EmbeddedSqlException($"database {statement.Alias} is already in use");
        if (_attachedDatabases.Count >= MaximumAttachedDatabases)
            throw new EmbeddedSqlException($"too many attached databases - maximum {MaximumAttachedDatabases}");

        if (path.Equals(":memory:", StringComparison.OrdinalIgnoreCase))
        {
            if (uriReadOnly)
                throw new EmbeddedSqlException("Managed ATTACH cannot open an in-memory database read-only.");
            if (statement.Key is not null)
                throw new EmbeddedSqlException("Managed ATTACH KEY is not supported for in-memory attachments.");

            var sequence = GetNextAttachedDatabaseSequence();
            var inMemoryAttached = new EmbeddedDatabase();
            try
            {
                // Fresh in-memory attach inherits main page size (and MVCC when enabled).
                inMemoryAttached._inMemoryPageSize = _database.GetPageSize();
                _database.CopyFunctionAndCollationRegistriesTo(inMemoryAttached);
                inMemoryAttached.BusyTimeout = BusyTimeout;
                if (_database.IsMvccEnabled)
                    _ = inMemoryAttached.EnableMvccMode();
                _attachedDatabases.Add(
                    statement.Alias,
                    new AttachedDatabase(
                        string.Empty,
                        $"\0memory:{sequence}",
                        inMemoryAttached,
                        sequence,
                        ownedFileSystem: null));
            }
            catch
            {
                inMemoryAttached.Dispose();
                throw;
            }

            return ExecutionResult.Empty;
        }

        if (!_database.IsFileBacked)
        {
            throw new EmbeddedSqlException(
                "Managed ATTACH requires a file-backed managed primary database so attachments share its file system.");
        }
        if (string.IsNullOrWhiteSpace(path))
            throw new EmbeddedSqlException("Managed ATTACH supports only non-empty file paths.");

        var pathIdentity = GetAttachmentPathIdentity(path);
        var pathComparer = GetAttachmentPathComparer();
        if (pathComparer.Equals(pathIdentity, GetAttachmentPathIdentity(_database.DatabasePath)))
            throw new EmbeddedSqlException("database file is already open as main");
        if (_attachedDatabases.Values.Any(attachment =>
        pathComparer.Equals(attachment.PathIdentity, pathIdentity)))
        {
            throw new EmbeddedSqlException("database file is already attached");
        }

        var readOnly = _database.IsReadOnly || uriReadOnly;
        IFileSystem attachmentFileSystem = _database.FileSystem;
        AhtolaEncryptionFileSystem? ownedFileSystem = null;
        if (statement.Key is not null)
        {
            if (_database.FileSystem is not AhtolaEncryptionFileSystem encryptedFileSystem)
            {
                throw new EmbeddedSqlException(
                    "Managed ATTACH KEY overrides require an encrypted primary database to select the attachment cipher.");
            }

            var keyValue = _database.EvaluateConstant(statement.Key, parameters, _lastInsertRowId);
            var key = EmbeddedDatabase.ToSqlText(keyValue);
            AhtolaEncryptionOptions encryption;
            try
            {
                encryption = AhtolaEncryptionOptions.FromHex(encryptedFileSystem.Encryption.Cipher, key);
            }
            catch (ArgumentException exception)
            {
                throw new EmbeddedSqlException(
                    "Managed ATTACH KEY must be a hexadecimal key for the primary database cipher.",
                    exception);
            }
            using (encryption)
            {
                ownedFileSystem = new AhtolaEncryptionFileSystem(
                    AhtolaEncryptionFileSystem.Unwrap(_database.FileSystem),
                    encryption);
            }
            attachmentFileSystem = ownedFileSystem;
        }

        var isFreshAttach = !attachmentFileSystem.FileExists(path);
        EmbeddedDatabase? attached = null;
        try
        {
            // Fresh files inherit main page size (Turso apply_page_layout_to_fresh_attach_db).
            attached = EmbeddedDatabase.OpenFile(
                path,
                attachmentFileSystem,
                readOnly,
                initialPageSize: isFreshAttach ? _database.GetPageSize() : null);
            _database.CopyFunctionAndCollationRegistriesTo(attached);
            attached.BusyTimeout = BusyTimeout;

            if (isFreshAttach)
            {
                if (_database.IsMvccEnabled && !readOnly)
                    _ = attached.EnableMvccMode();
            }
            else
            {
                RejectInitializedAttachMismatches(statement.Alias, attached);
            }

            _attachedDatabases.Add(
                statement.Alias,
                new AttachedDatabase(path, pathIdentity, attached, GetNextAttachedDatabaseSequence(), ownedFileSystem));
        }
        catch
        {
            attached?.Dispose();
            ownedFileSystem?.Dispose();
            throw;
        }

        return ExecutionResult.Empty;
    }

    /// <summary>
    /// Turso <c>reject_initialized_attach_mismatches</c>: initialized attachments must
    /// share the main database page size and MVCC/WAL journal mode family.
    /// </summary>
    private void RejectInitializedAttachMismatches(string alias, EmbeddedDatabase attached)
    {
        _database.EnsureMvccAttachedIfDurable();
        attached.EnsureMvccAttachedIfDurable();

        var mainMvcc = _database.IsMvccEnabled;
        var attachedMvcc = attached.IsMvccEnabled;
        if (mainMvcc != attachedMvcc)
        {
            var mainMode = mainMvcc ? "MVCC" : "WAL";
            var attachedMode = attachedMvcc ? "MVCC" : "WAL";
            throw new EmbeddedSqlException(
                $"cannot attach database '{alias}': main database uses {mainMode} journal mode "
                + $"but attached database uses {attachedMode}. Both must use the same journal mode.");
        }

        var mainPageSize = _database.GetPageSize();
        var attachedPageSize = attached.GetPageSize();
        if (mainPageSize != attachedPageSize)
        {
            throw new EmbeddedSqlException(
                $"cannot attach database '{alias}': page size mismatch "
                + $"(main={mainPageSize}, attached={attachedPageSize})");
        }
    }

    internal void ApplySnapshotPragmaHeader(int schemaVersion, int userVersion, int applicationId)
    {
        var state = GetTransactionState(_database);
        if (state is null)
            throw new InvalidOperationException("Snapshot PRAGMA metadata requires an active transaction.");

        if (_transactionWriteDatabase is not null
            && !ReferenceEquals(_transactionWriteDatabase, _database))
        {
            throw new InvalidOperationException(
                "Snapshot PRAGMA metadata cannot cross the managed transaction write boundary.");
        }

        _transactionWriteDatabase = _database;
        state.PragmaHeader = new PragmaHeaderMetadata(schemaVersion, userVersion, applicationId);
        state.HasChanges = true;
        // A pragma header write is never a targeted index rebuild: an earlier REINDEX in this
        // same transaction must not cause commit to skip persisting this header change.
        state.HasNonTargetedIndexRebuildChange = true;
        state.HasSnapshotPragmaHeader = true;
    }

    private EmbeddedDatabase ResolveDatabase(string databaseName)
    {
        ArgumentNullException.ThrowIfNull(databaseName);
        if (databaseName.Equals("temp", StringComparison.OrdinalIgnoreCase))
        {
            throw new EmbeddedSqlException(
                "Managed backup excludes the connection-private temporary database.");
        }
        if (databaseName.Equals("main", StringComparison.OrdinalIgnoreCase))
            return _database;
        if (_attachedDatabases.TryGetValue(databaseName, out var attachment))
            return attachment.Database;

        throw new EmbeddedSqlException($"no such database: {databaseName}");
    }

    private EmbeddedDatabase ResolveSchemaDatabase(string schema)
    {
        if (schema.Equals("temp", StringComparison.OrdinalIgnoreCase))
        {
            _tempInitialized = true;
            return _tempDatabase;
        }
        if (schema.Equals("main", StringComparison.OrdinalIgnoreCase))
            return _database;
        if (_attachedDatabases.TryGetValue(schema, out var attachment))
            return attachment.Database;

        throw new EmbeddedSqlException($"no such database: {schema}");
    }

    private EmbeddedDatabase ResolvePragmaDatabase(string? schema)
        => schema is null ? _database : ResolveSchemaDatabase(schema);

    private void ValidatePragmaSchema(string? schema)
    {
        if (schema is not null)
            _ = ResolveSchemaDatabase(schema);
    }

    private ExecutionResult ExecuteDetach(DetachDatabaseStatement statement)
    {
        if (_transactionDatabases is not null)
            throw new EmbeddedSqlException($"database {statement.Alias} is locked");
        if (!_attachedDatabases.TryGetValue(statement.Alias, out var attachment))
            throw new EmbeddedSqlException($"no such database: {statement.Alias}");
        if (attachment.Database.HasOpenBlobHandles)
            throw new EmbeddedSqlException("database is locked");

        _attachedDatabases.Remove(statement.Alias);
        _pendingPageSizes.Remove(attachment.Database);
        _cacheSizes.Remove(attachment.Database);
        _cacheSpills.Remove(attachment.Database);
        _synchronousModes.Remove(attachment.Database);
        ReleaseExclusiveLockingMode(attachment.Database);
        attachment.Dispose();
        return ExecutionResult.Empty;
    }

    private int GetNextAttachedDatabaseSequence()
    {
        var used = _attachedDatabases.Values.Select(attachment => attachment.Sequence).ToHashSet();
        for (var sequence = 2; sequence < MaximumAttachedDatabases + 2; sequence++)
        {
            if (!used.Contains(sequence))
                return sequence;
        }

        throw new InvalidOperationException("No managed ATTACH sequence is available below the enforced limit.");
    }

    private ExecutionResult ExecutePragmaDatabaseList()
    {
        var rows = new List<SqlValue[]>
        {
            new[] { SqlValue.Integer(0), SqlValue.Text("main"), SqlValue.Text(_database.DatabasePath) },
        };
        if (_tempInitialized)
            rows.Add([SqlValue.Integer(1), SqlValue.Text("temp"), SqlValue.Text(string.Empty)]);

        foreach (var pair in _attachedDatabases.OrderBy(pair => pair.Value.Sequence))
        {
            var alias = pair.Key;
            var attachment = pair.Value;
            rows.Add(
            new[]
            {
                SqlValue.Integer(attachment.Sequence),
                SqlValue.Text(alias),
                SqlValue.Text(attachment.Path),
            });
        }

        return new ExecutionResult(["seq", "name", "file"], rows.ToArray(), 0);
    }

    private ExecutionResult ExecutePragmaEncoding(PragmaEncodingStatement statement)
    {
        var database = ResolvePragmaDatabase(statement.Schema);
        var encoding = ReferenceEquals(database, _tempDatabase)
            ? _database.GetTextEncoding()
            : database.GetTextEncoding();
        return new ExecutionResult(
            ["encoding"],
            [[SqlValue.Text(EmbeddedDatabase.FormatPragmaEncoding(encoding))]],
            0);
    }

    private ExecutionResult ExecutePragmaPageCount(PragmaPageCountStatement statement)
    {
        var database = ResolvePragmaDatabase(statement.Schema);
        return new ExecutionResult(["page_count"], [[SqlValue.Integer(database.GetPageCount())]], 0);
    }

    private ExecutionResult ExecutePragmaFreelistCount(PragmaFreelistCountStatement statement)
    {
        var database = ResolvePragmaDatabase(statement.Schema);
        return new ExecutionResult(["freelist_count"], [[SqlValue.Integer(database.GetFreelistCount())]], 0);
    }

    private ExecutionResult ExecutePragmaTableList(string? schema, string? filter)
    {
        var rows = new List<SqlValue[]>();
        if (schema is not null)
        {
            AddPragmaTableListRows(rows, ResolveSchemaDatabase(schema), schema, filter);
            return new ExecutionResult(
                ["schema", "name", "type", "ncol", "wr", "strict"],
                rows,
                0);
        }

        AddPragmaTableListRows(rows, _database, "main", filter);
        AddPragmaTableListRows(rows, _tempDatabase, "temp", filter);
        foreach (var pair in _attachedDatabases.OrderBy(pair => pair.Value.Sequence))
            AddPragmaTableListRows(rows, pair.Value.Database, pair.Key, filter);

        return new ExecutionResult(
            ["schema", "name", "type", "ncol", "wr", "strict"],
            rows,
            0);
    }

    private void AddPragmaTableListRows(
        ICollection<SqlValue[]> rows,
        EmbeddedDatabase database,
        string schema,
        string? filter)
    {
        var statement = new PragmaTableListStatement(schema, filter);
        var transactionState = GetTransactionState(database);
        var result = transactionState is null
            ? database.Execute(
                statement,
                new SqlValue[1],
                synchronousMode: GetSynchronousMode(database))
            : database.Execute(statement, new SqlValue[1], transactionState.Catalog);
        foreach (var row in result.Rows)
            rows.Add(row);
    }

    private ExecutionResult ExecuteCreateTableAs(
        CreateTableAsSelectStatement statement,
        SqlValue[] parameters,
        CancellationToken cancellationToken)
    {
        var (targetSchema, targetName) = ResolveCreateTableTarget(statement);
        var targetDatabase = ResolveSchemaDatabase(targetSchema);
        ReserveWriteAccess(targetDatabase);
        if (CurrentCatalogContains(targetDatabase, targetName, ManagedSchemaObjectKind.Table))
        {
            if (statement.IfNotExists)
                return ExecutionResult.Empty;

            throw new EmbeddedSqlException($"table {targetName} already exists");
        }
        if (CurrentCatalogContains(targetDatabase, targetName, ManagedSchemaObjectKind.View))
            throw new EmbeddedSqlException($"there is already a view named {targetName}");
        if (CurrentCatalogContains(targetDatabase, targetName, ManagedSchemaObjectKind.Trigger))
            throw new EmbeddedSqlException($"there is already a trigger named {targetName}");
        if (CurrentCatalogContains(targetDatabase, targetName, ManagedSchemaObjectKind.Index))
            throw new EmbeddedSqlException($"there is already an index named {targetName}");

        var source = RouteQuery(statement.Query);
        var sourceQuery = source.Statement as QueryStatement
            ?? throw new InvalidOperationException("CREATE TABLE AS SELECT routing did not return a query.");
        var sourceState = GetTransactionState(source.Database);
        var sourceCatalog = source.ReadCatalog ?? sourceState?.Catalog;
        var vdbeExecutionOptions = CreateVdbeExecutionOptions(source.Database);
        var materialization = sourceCatalog is null
            ? source.Database.MaterializeCreateTableAs(
                sourceQuery,
                parameters,
                _lastInsertRowId,
                _foreignKeys,
                _recursiveTriggers,
                cancellationToken,
                vdbeExecutionOptions,
                ExecutePragmaTableList,
                source.ExternalTables)
            : source.Database.MaterializeCreateTableAs(
                sourceQuery,
                parameters,
                sourceCatalog,
                _lastInsertRowId,
                _foreignKeys,
                _recursiveTriggers,
                cancellationToken,
                vdbeExecutionOptions,
                ExecutePragmaTableList,
                source.ExternalTables);
        cancellationToken.ThrowIfCancellationRequested();
        if (ReferenceEquals(source.Database, _tempDatabase))
            _tempInitialized = true;

        var materialized = new CreateTableStatement(
            ManagedSchemaName.Create(targetSchema, targetName),
            materialization.Columns,
            statement.IfNotExists,
            Strict: false,
            InitialRows: materialization.Rows);
        return Execute(materialized, parameters, cancellationToken);
    }

    private (string Schema, string Name) ResolveCreateTableTarget(CreateTableAsSelectStatement statement)
    {
        if (ManagedSchemaName.TrySplit(statement.Name, out var schema, out var name))
        {
            if (statement.Temporary && !schema.Equals("temp", StringComparison.OrdinalIgnoreCase))
                throw new EmbeddedSqlException("temporary table name must be unqualified");

            _ = ResolveSchemaDatabase(schema);
            return (schema, name);
        }

        return (statement.Temporary ? "temp" : "main", statement.Name);
    }

    private bool CurrentCatalogContains(
        EmbeddedDatabase database,
        string objectName,
        ManagedSchemaObjectKind kind)
    {
        var state = GetTransactionState(database);
        return state is null
            ? database.ContainsSchemaObject(objectName, kind)
            : CatalogContainsSchemaObject(state.Catalog, objectName, kind);
    }

    private RoutedStatement RouteStatement(ParsedStatement statement)
    {
        return statement switch
        {
            CreateTableStatement create => RouteNamedStatement(create.Name, name => create with { Name = name }),
            CreateVirtualTableStatement createVirtual => RouteNamedStatement(
                createVirtual.Name,
                name => createVirtual with { Name = name }),
            CreateTriggerStatement createTrigger => RouteCreateTrigger(createTrigger),
            CreateViewStatement createView => RouteCreateView(createView),
            DropTableStatement drop => RouteExistingNamedStatement(
                drop.Name,
                ManagedSchemaObjectKind.Table,
                name => drop with { Name = name }),
            CreateIndexStatement createIndex => RouteCreateIndex(createIndex),
            DropIndexStatement dropIndex => RouteExistingNamedStatement(
                dropIndex.Name,
                ManagedSchemaObjectKind.Index,
                name => dropIndex with { Name = name }),
            DropViewStatement dropView => RouteExistingNamedStatement(
                dropView.Name,
                ManagedSchemaObjectKind.View,
                name => dropView with { Name = name }),
            DropTriggerStatement dropTrigger => RouteExistingNamedStatement(
                dropTrigger.Name,
                ManagedSchemaObjectKind.Trigger,
                name => dropTrigger with { Name = name }),
            AlterTableAddColumnStatement addColumn => RouteExistingNamedStatement(
                addColumn.TableName,
                ManagedSchemaObjectKind.Table,
                name => addColumn with { TableName = name }),
            AlterTableRenameStatement rename => RouteExistingNamedStatement(
                rename.TableName,
                ManagedSchemaObjectKind.Table,
                name => rename with { TableName = name }),
            AlterTableRenameColumnStatement renameColumn => RouteExistingNamedStatement(
                renameColumn.TableName,
                ManagedSchemaObjectKind.Table,
                name => renameColumn with { TableName = name }),
            AlterTableAlterColumnStatement alterColumn => RouteExistingNamedStatement(
                alterColumn.TableName,
                ManagedSchemaObjectKind.Table,
                name => alterColumn with { TableName = name }),
            AlterTableDropColumnStatement dropColumn => RouteExistingNamedStatement(
                dropColumn.TableName,
                ManagedSchemaObjectKind.Table,
                name => dropColumn with { TableName = name }),
            PragmaTableInfoStatement tableInfo => RoutePragmaTableMetadataStatement(
                tableInfo.TableName,
                name => tableInfo with { TableName = name }),
            PragmaTableXInfoStatement tableXInfo => RoutePragmaTableMetadataStatement(
                tableXInfo.TableName,
                name => tableXInfo with { TableName = name }),
            PragmaIndexListStatement indexList => RouteExistingNamedStatement(
                indexList.TableName,
                ManagedSchemaObjectKind.Table,
                name => indexList with { TableName = name }),
            PragmaIndexInfoStatement indexInfo => RouteExistingIndexMetadataStatement(
                indexInfo.IndexName,
                name => indexInfo with { IndexName = name }),
            PragmaIndexXInfoStatement indexXInfo => RouteExistingIndexMetadataStatement(
                indexXInfo.IndexName,
                name => indexXInfo with { IndexName = name }),
            PragmaForeignKeyListStatement { TableName: { } tableName } foreignKeyList => RouteExistingNamedStatement(
                tableName,
                ManagedSchemaObjectKind.Table,
                name => foreignKeyList with { TableName = name }),
            PragmaForeignKeyCheckStatement { TableName: { } tableName } foreignKeyCheck
                => RouteExistingNamedStatement(
                    tableName,
                    ManagedSchemaObjectKind.Table,
                    name => foreignKeyCheck with { TableName = name, Schema = null }),
            PragmaForeignKeyCheckStatement { TableName: null, Schema: { } foreignKeySchema } foreignKeyCheck
                => RouteSchema(
                    foreignKeySchema,
                    string.Empty,
                    _ => foreignKeyCheck with { Schema = null }),
            PragmaIntegrityCheckStatement { TableName: { } integrityTable } integrityCheck
                => RouteExistingNamedStatement(
                    integrityCheck.Schema is null
                        ? integrityTable
                        : ManagedSchemaName.Create(integrityCheck.Schema, integrityTable),
                    ManagedSchemaObjectKind.Table,
                    name => integrityCheck with { TableName = name, Schema = null }),
            PragmaIntegrityCheckStatement { TableName: null, Schema: { } integritySchema } integrityCheck
                => RouteSchema(
                    integritySchema,
                    string.Empty,
                    _ => integrityCheck with { Schema = null }),
            PragmaTableListStatement { Schema: { } schema } tableList
                => RouteSchema(schema, string.Empty, _ => tableList),
            AnalyzeStatement analyze => RouteAnalyze(analyze),
            ReindexStatement reindex => RouteReindex(reindex),
            OptimizeIndexStatement optimize => RouteOptimizeIndex(optimize),
            WithDmlStatement with => RouteDataStatement(with),
            InsertStatement insert => RouteDataStatement(insert),
            UpdateStatement update => RouteDataStatement(update),
            DeleteStatement delete => RouteDataStatement(delete),
            QueryStatement query when StatementMayMutate(_database, query) => RouteDataStatement(query),
            QueryStatement query => RouteQuery(query),
            ExplainStatement explain => RouteExplain(
                            explain.Inner,
                            rewritten => new ExplainStatement(rewritten)),
            ExplainQueryPlanStatement explainQueryPlan => RouteExplain(
                explainQueryPlan.Inner,
                rewritten => new ExplainQueryPlanStatement(rewritten)),
            _ when ContainsSchemaQualification(statement)
                => throw new EmbeddedSqlException("This schema-qualified statement is not supported by managed ATTACH."),
            _ => new RoutedStatement(_database, statement, IsAttached: false),
        };
    }

    private RoutedStatement RouteExplain(
        ParsedStatement inner,
        Func<ParsedStatement, ParsedStatement> wrap)
    {
        var routed = inner switch
        {
            QueryStatement query => RouteQuery(query),
            WithDmlStatement or InsertStatement or UpdateStatement or DeleteStatement
                => RouteDataStatement(inner),
            _ => new RoutedStatement(_database, inner, IsAttached: false),
        };
        return routed with { Statement = wrap(routed.Statement) };
    }

    private static bool ContainsAttachedSchemaQualification(ParsedStatement statement)
    {
        var schemas = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var commonTableExpressions = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (statement is QueryStatement query)
            CollectQuerySchemas(query, schemas, commonTableExpressions);
        else if (statement is WithDmlStatement or InsertStatement or UpdateStatement or DeleteStatement)
            CollectStatementSchemas(statement, schemas, commonTableExpressions);
        else
            return false;
        return schemas.Any(schema =>
            schema.Length != 0
            && schema[0] != UnqualifiedSchemaMarker
            && !schema.Equals("main", StringComparison.OrdinalIgnoreCase)
            && !schema.Equals("temp", StringComparison.OrdinalIgnoreCase));
    }

    private RoutedStatement RouteAnalyze(AnalyzeStatement statement)
    {
        if (statement.Target is null)
            return new RoutedStatement(_database, statement, IsAttached: false);

        if (ManagedSchemaName.TrySplit(statement.Target, out var schema, out var localName))
            return RouteSchema(schema, localName, target => statement with { Target = target });

        if (statement.Target.Equals("temp", StringComparison.OrdinalIgnoreCase))
        {
            return new RoutedStatement(
                _tempDatabase,
                statement with { Target = "main" },
                IsAttached: false);
        }

        if (_attachedDatabases.TryGetValue(statement.Target, out var attachment))
        {
            return new RoutedStatement(
                attachment.Database,
                statement with { Target = "main" },
                IsAttached: true);
        }

        return new RoutedStatement(_database, statement, IsAttached: false);
    }

    private RoutedStatement RouteReindex(ReindexStatement statement)
    {
        // Bare REINDEX and collation REINDEX walk every schema (temp/main/attached),
        // matching Turso collect_all_reindex_targets / collect_reindex_targets_by_collation.
        // Multi-database execution is handled before single-DB routing when needed.
        if (statement.Target is null)
            return new RoutedStatement(_database, statement, IsAttached: false);

        if (ManagedSchemaName.TrySplit(statement.Target, out var schema, out var localName))
            return RouteSchema(schema, localName, name => statement with { Target = name });

        if (HasCollationAnywhere(statement.Target))
        {
            return new RoutedStatement(
                _database,
                statement with { TargetKind = ReindexTargetKind.Collation },
                IsAttached: false);
        }

        schema = ResolveExistingReindexTargetSchema(statement.Target);
        if (schema is null)
            throw new EmbeddedSqlException("unable to identify the object to be reindexed");

        return RouteSchema(schema, statement.Target, name => statement with { Target = name });
    }

    private RoutedStatement RouteOptimizeIndex(OptimizeIndexStatement statement)
    {
        if (statement.IndexName is null)
            return new RoutedStatement(_database, statement, IsAttached: false);
        if (ManagedSchemaName.TrySplit(statement.IndexName, out var schema, out var localName))
            return RouteSchema(schema, localName, name => statement with { IndexName = name });

        schema = FindExistingObjectSchema(statement.IndexName, ManagedSchemaObjectKind.Index);
        return schema is null
            ? new RoutedStatement(_database, statement, IsAttached: false)
            : RouteSchema(schema, statement.IndexName, name => statement with { IndexName = name });
    }

    private bool HasCollationAnywhere(string name)
    {
        if (_database.HasCollation(name) || _tempDatabase.HasCollation(name))
            return true;
        foreach (var attachment in _attachedDatabases.Values)
        {
            if (attachment.Database.HasCollation(name))
                return true;
        }

        return false;
    }

    /// <summary>
    /// Bare REINDEX and collation REINDEX always fan out across schemas so indexes
    /// on temp/main/attached stay consistent (Turso collect_all_reindex_targets).
    /// </summary>
    private bool IsMultiDatabaseReindex(ReindexStatement statement)
    {
        if (statement.Target is null)
            return true;
        if (ManagedSchemaName.TrySplit(statement.Target, out _, out _))
            return false;
        return HasCollationAnywhere(statement.Target);
    }

    private ExecutionResult ExecuteMultiDatabaseReindex(
            ReindexStatement statement,
            CancellationToken cancellationToken)
    {
        // Turso blocks REINDEX entirely under MVCC mode.
        _database.EnsureMvccAttachedIfDurable();
        if (_database.IsMvccEnabled)
            throw new EmbeddedSqlException("REINDEX is not supported in MVCC mode");
        if (_queryOnly)
            throw new EmbeddedSqlException("attempt to write a readonly database");

        var local = statement.Target is null
            ? statement
            : statement with { TargetKind = ReindexTargetKind.Collation };

        var changed = false;
        var forceRewrite = false;
        foreach (var database in EnumerateReindexDatabases())
        {
            cancellationToken.ThrowIfCancellationRequested();
            database.TransactionLock.ThrowIfReadBlocked(this, BusyTimeout);
            var mutationReserved = ReserveTransactionMutation(database, local);
            try
            {
                var state = GetTransactionState(database);
                ExecutionResult result;
                if (state is null)
                {
                    result = database.Execute(
                        local,
                        Array.Empty<SqlValue>(),
                        _lastInsertRowId,
                        _foreignKeys,
                        _recursiveTriggers,
                        _deferForeignKeys,
                        inTransaction: false,
                        cancellationToken,
                        synchronousMode: GetSynchronousMode(database));
                }
                else
                {
                    EmbeddedDatabase.SchemaCatalog? catalog = state.Catalog.Clone();
                    try
                    {
                        result = database.Execute(
                            local,
                            Array.Empty<SqlValue>(),
                            catalog,
                            _lastInsertRowId,
                            _foreignKeys,
                            _recursiveTriggers,
                            _deferForeignKeys,
                            inTransaction: true,
                            cancellationToken);
                        if (result.Changed || result.ForceFullCatalogRewrite)
                        {
                            var previous = state.Catalog;
                            state.Catalog = catalog;
                            previous.DisconnectOwnedVirtualTables(state.VirtualTableTransaction);
                            catalog = null;
                            state.HasChanges = true;
                            state.ForceFullCatalogRewrite |= result.ForceFullCatalogRewrite;
                            if (result.TargetedIndexRebuild is { Count: > 0 } targetedThisDatabase)
                            {
                                foreach (var target in targetedThisDatabase)
                                    state.TargetedIndexRebuildNames.Add(target.Index.Name);
                            }
                            else
                            {
                                // A bare/collation REINDEX that fanned out to this database, or one
                                // that rebuilt a method index, is not a pure targeted rebuild -- see
                                // HasNonTargetedIndexRebuildChange.
                                state.HasNonTargetedIndexRebuildChange = true;
                            }
                            if (!ReferenceEquals(database, _tempDatabase))
                                _transactionWriteDatabase = database;
                        }

                        database.RecordChangeCounters(local, result);
                    }
                    finally
                    {
                        catalog?.DisconnectOwnedVirtualTables();
                    }
                }

                changed |= result.Changed;
                forceRewrite |= result.ForceFullCatalogRewrite;
            }
            finally
            {
                if (mutationReserved)
                    ReleaseTransactionMutation(database);
            }
        }

        return new ExecutionResult([], [], 0, changed, forceRewrite);
    }

    private ExecutionResult ExecuteMultiDatabaseOptimize(
        OptimizeIndexStatement statement,
        CancellationToken cancellationToken)
    {
        if (_queryOnly)
            throw new EmbeddedSqlException("attempt to write a readonly database");

        var changed = false;
        foreach (var database in EnumerateReindexDatabases())
        {
            cancellationToken.ThrowIfCancellationRequested();
            database.TransactionLock.ThrowIfReadBlocked(this, BusyTimeout);
            var mutationReserved = ReserveTransactionMutation(database, statement);
            try
            {
                var state = GetTransactionState(database);
                ExecutionResult result;
                if (state is null)
                {
                    result = database.Execute(
                        statement,
                        Array.Empty<SqlValue>(),
                        _lastInsertRowId,
                        _foreignKeys,
                        _recursiveTriggers,
                        _deferForeignKeys,
                        inTransaction: false,
                        cancellationToken,
                        synchronousMode: GetSynchronousMode(database));
                }
                else
                {
                    EmbeddedDatabase.SchemaCatalog? catalog = state.Catalog.Clone();
                    try
                    {
                        result = database.Execute(
                            statement,
                            Array.Empty<SqlValue>(),
                            catalog,
                            _lastInsertRowId,
                            _foreignKeys,
                            _recursiveTriggers,
                            _deferForeignKeys,
                            inTransaction: true,
                            cancellationToken);
                        if (result.Changed)
                        {
                            var previous = state.Catalog;
                            state.Catalog = catalog;
                            previous.DisconnectOwnedVirtualTables(state.VirtualTableTransaction);
                            catalog = null;
                            state.HasChanges = true;
                            // PRAGMA optimize never reports a TargetedIndexRebuild (only the
                            // REINDEX statement path populates that): any change here is a full
                            // schema/index rebuild, so an earlier REINDEX in this same
                            // transaction must not cause commit to skip persisting it.
                            state.HasNonTargetedIndexRebuildChange = true;
                            if (!ReferenceEquals(database, _tempDatabase))
                                _transactionWriteDatabase = database;
                        }

                        database.RecordChangeCounters(statement, result);
                    }
                    finally
                    {
                        catalog?.DisconnectOwnedVirtualTables();
                    }
                }

                changed |= result.Changed;
            }
            finally
            {
                if (mutationReserved)
                    ReleaseTransactionMutation(database);
            }
        }

        return new ExecutionResult([], [], 0, changed);
    }

    private IEnumerable<EmbeddedDatabase> EnumerateReindexDatabases()
    {
        // Turso order: temp, main, then attachments by attach sequence.
        if (_tempInitialized)
            yield return _tempDatabase;
        yield return _database;
        foreach (var attachment in _attachedDatabases.OrderBy(pair => pair.Value.Sequence))
            yield return attachment.Value.Database;
    }

    private RoutedStatement RouteExistingIndexMetadataStatement(
string objectName,
Func<string, ParsedStatement> rewrite)
    {
        if (ManagedSchemaName.TrySplit(objectName, out var schema, out var localName))
            return RouteSchema(schema, localName, rewrite);

        schema = FindExistingObjectSchema(objectName, ManagedSchemaObjectKind.Index)
            ?? FindExistingObjectSchema(objectName, ManagedSchemaObjectKind.Table)
            ?? "main";
        return RouteSchema(schema, objectName, rewrite);
    }

    // Mirrors SQLite's REINDEX resolution order: tables across all databases
    // (temp, main, attached), then views, then indexes.
    private string? ResolveExistingReindexTargetSchema(string target)
        => FindExistingObjectSchema(target, ManagedSchemaObjectKind.Table)
            ?? FindExistingObjectSchema(target, ManagedSchemaObjectKind.View)
            ?? FindExistingObjectSchema(target, ManagedSchemaObjectKind.Index);

    private RoutedStatement RouteNamedStatement(string objectName, Func<string, ParsedStatement> rewrite)
    {
        if (!ManagedSchemaName.TrySplit(objectName, out var schema, out var localName))
            return new RoutedStatement(_database, rewrite(objectName), IsAttached: false);

        return RouteSchema(schema, localName, rewrite);
    }

    private RoutedStatement RouteExistingNamedStatement(
        string objectName,
        ManagedSchemaObjectKind kind,
        Func<string, ParsedStatement> rewrite)
    {
        if (ManagedSchemaName.TrySplit(objectName, out var schema, out var localName))
            return RouteSchema(schema, localName, rewrite);

        schema = ResolveExistingObjectSchema(objectName, kind);
        return RouteSchema(schema, objectName, rewrite);
    }

    private RoutedStatement RoutePragmaTableMetadataStatement(
        string objectName,
        Func<string, ParsedStatement> rewrite)
    {
        if (ManagedSchemaName.TrySplit(objectName, out var schema, out var localName)
            && IsTemporarySchemaTable(localName)
            && !schema.Equals("temp", StringComparison.OrdinalIgnoreCase))
        {
            return RouteSchema(schema, localName, _ => rewrite(objectName));
        }

        return RouteExistingNamedStatement(
            objectName,
            ManagedSchemaObjectKind.Table,
            rewrite);
    }

    private string ResolveExistingObjectSchema(string objectName, ManagedSchemaObjectKind kind)
        => FindExistingObjectSchema(objectName, kind) ?? "main";

    private string? FindExistingObjectSchema(string objectName, ManagedSchemaObjectKind kind)
    {
        if (GetTransactionState(_tempDatabase) is { } tempState
            ? CatalogContainsSchemaObject(tempState.Catalog, objectName, kind)
            : _tempDatabase.ContainsSchemaObject(objectName, kind))
        {
            return "temp";
        }

        if (GetTransactionState(_database) is { } mainState
            ? CatalogContainsSchemaObject(mainState.Catalog, objectName, kind)
            : _database.ContainsSchemaObject(objectName, kind))
        {
            return "main";
        }

        foreach (var pair in _attachedDatabases.OrderBy(pair => pair.Value.Sequence))
        {
            var database = pair.Value.Database;
            if (GetTransactionState(database) is { } state
                ? CatalogContainsSchemaObject(state.Catalog, objectName, kind)
                : database.ContainsSchemaObject(objectName, kind))
            {
                return pair.Key;
            }
        }

        return null;
    }

    private static bool CatalogContainsSchemaObject(
        EmbeddedDatabase.SchemaCatalog catalog,
        string objectName,
        ManagedSchemaObjectKind kind)
        => kind switch
        {
            ManagedSchemaObjectKind.Table => catalog.Tables.ContainsKey(objectName)
                || catalog.VirtualTables.ContainsKey(objectName),
            ManagedSchemaObjectKind.View => catalog.Views.ContainsKey(objectName),
            ManagedSchemaObjectKind.Trigger => catalog.Triggers.ContainsKey(objectName),
            ManagedSchemaObjectKind.Index => catalog.Tables.Values.Any(table =>
                table.Indexes.Any(index =>
                    string.Equals(index.Name, objectName, StringComparison.OrdinalIgnoreCase))
                || string.Equals(
                    table.WithoutRowidPrimaryKeyIndexName,
                    objectName,
                    StringComparison.OrdinalIgnoreCase)),
            _ => throw new InvalidOperationException($"Unknown managed schema object kind {kind}."),
        };

    private RoutedStatement RouteCreateIndex(CreateIndexStatement statement)
    {
        var hasIndexSchema = ManagedSchemaName.TrySplit(statement.Name, out var indexSchema, out var indexName);
        var hasTableSchema = ManagedSchemaName.TrySplit(statement.TableName, out var tableSchema, out var tableName);
        if (!hasIndexSchema && !hasTableSchema)
        {
            var schema = CurrentCatalogContains(
                _tempDatabase,
                statement.TableName,
                ManagedSchemaObjectKind.Table)
                ? "temp"
                : "main";
            return RouteSchema(schema, statement.TableName, localTableName => statement with
            {
                TableName = localTableName,
            });
        }
        if (hasIndexSchema)
        {
            if (hasTableSchema && !string.Equals(indexSchema, tableSchema, StringComparison.OrdinalIgnoreCase))
                throw new EmbeddedSqlException("CREATE INDEX cannot span managed database schemas.");

            return RouteSchema(
                indexSchema,
                hasTableSchema ? tableName : statement.TableName,
                localTableName => statement with
                {
                    Name = indexName,
                    TableName = localTableName,
                });
        }

        if (!tableSchema.Equals("main", StringComparison.OrdinalIgnoreCase))
        {
            throw new EmbeddedSqlException(
                "CREATE INDEX on an attached table must qualify the index name with the attached schema.");
        }

        return RouteSchema(
            tableSchema,
            tableName,
            localTableName => statement with
            {
                Name = statement.Name,
                TableName = localTableName,
            });
    }

    private RoutedStatement RouteCreateTrigger(CreateTriggerStatement statement)
    {
        var hasTriggerSchema = ManagedSchemaName.TrySplit(
            statement.Name,
            out var triggerSchema,
            out var triggerName);
        var hasTargetSchema = ManagedSchemaName.TrySplit(
            statement.TableName,
            out var targetSchema,
            out var targetName);
        var localTargetName = hasTargetSchema ? targetName : statement.TableName;

        // SQLite resolves an unqualified trigger target temp-first and stores the trigger in the
        // schema that owns that object, so a trigger on a temp table is implicitly temporary.
        var resolvedTargetSchema = hasTargetSchema
            ? targetSchema
            : FindExistingObjectSchema(statement.TableName, ManagedSchemaObjectKind.Table)
                ?? FindExistingObjectSchema(statement.TableName, ManagedSchemaObjectKind.View)
                ?? "main";
        var homeSchema = statement.Temporary
            ? "temp"
            : hasTriggerSchema
                ? triggerSchema
                : resolvedTargetSchema;
        var temporary = homeSchema.Equals("temp", StringComparison.OrdinalIgnoreCase);
        var targetIsForeign = !homeSchema.Equals(resolvedTargetSchema, StringComparison.OrdinalIgnoreCase);
        if (targetIsForeign && !temporary)
            throw new EmbeddedSqlException("CREATE TRIGGER cannot span managed database schemas.");

        // A persistent trigger body only ever runs inside its own database. SQLite/Turso allow
        // explicit references to that same schema, while qualified mutation targets remain
        // invalid in trigger bodies. A temp trigger body is dispatched by this connection, so it
        // may name objects in other schemas.
        var foreignSchema = temporary
            ? null
            : FindPersistentTriggerForeignSchema(statement, homeSchema);
        if (foreignSchema is not null)
        {
            throw new EmbeddedSqlException(
                $"trigger {triggerName} cannot reference objects in database {foreignSchema}");
        }
        if (!temporary && statement.Body.Any(HasQualifiedTriggerMutationTarget))
        {
            throw new EmbeddedSqlException(
                "Managed persistent trigger bodies cannot reference another database schema.");
        }

        return RouteSchema(
            homeSchema,
            localTargetName,
            local => statement with
            {
                Name = hasTriggerSchema ? triggerName : statement.Name,
                TableName = local,
                Temporary = temporary,
                TargetSchema = targetIsForeign ? resolvedTargetSchema : null,
                When = temporary || statement.When is null
                    ? statement.When
                    : RewriteExpressionSchema(
                        ExpressionContainsSchemaQualification(statement.When)
                            ? RewriteExpressionSchema(
                                statement.When,
                                homeSchema,
                                new HashSet<string>(StringComparer.OrdinalIgnoreCase))
                            : statement.When,
                        PersistentTriggerColumnSchemaMarker,
                        new HashSet<string>(StringComparer.OrdinalIgnoreCase)),
                Body = temporary
                    ? statement.Body
                    : statement.Body.Select(body =>
                    {
                        var rewritten = ContainsSchemaQualification(body)
                            ? RewriteStatementSchema(body, homeSchema)
                            : body;
                        return RewriteStatementSchema(rewritten, PersistentTriggerColumnSchemaMarker);
                    }).ToArray(),
                // SQLite stores the ON-clause target qualifier verbatim and drops only the
                // trigger's own-name qualifier; the parser's stored text already matches that.
                Sql = statement.Sql,
            });
    }

    private static string? FindPersistentTriggerForeignSchema(
        CreateTriggerStatement statement,
        string homeSchema)
    {
        var schemas = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var commonTableExpressions = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        CollectExpressionSchemas(statement.When, schemas, commonTableExpressions);
        foreach (var bodyStatement in statement.Body)
        {
            if (bodyStatement is QueryStatement query)
                CollectQuerySchemas(query, schemas, commonTableExpressions);
            else
                CollectStatementSchemas(bodyStatement, schemas, commonTableExpressions);
        }

        return schemas.FirstOrDefault(schema => schema.Length != 0
            && schema[0] != UnqualifiedSchemaMarker
            && !schema.Equals(homeSchema, StringComparison.OrdinalIgnoreCase));
    }

    private static bool HasQualifiedTriggerMutationTarget(ParsedStatement statement)
    {
        return statement switch
        {
            InsertStatement insert => ManagedSchemaName.TrySplit(insert.TableName, out _, out _),
            UpdateStatement update => ManagedSchemaName.TrySplit(update.TableName, out _, out _),
            DeleteStatement delete => ManagedSchemaName.TrySplit(delete.TableName, out _, out _),
            WithDmlStatement with => HasQualifiedTriggerMutationTarget(with.Dml),
            _ => false,
        };
    }

    private RoutedStatement RouteCreateView(CreateViewStatement statement)
    {
        var hasViewSchema = ManagedSchemaName.TrySplit(statement.Name, out var viewSchema, out var viewName);
        var homeSchema = statement.Temporary
            ? "temp"
            : hasViewSchema
                ? viewSchema
                : "main";
        if (!statement.Temporary
            && homeSchema.Equals("main", StringComparison.OrdinalIgnoreCase)
            && ContainsSchemaQualification(statement))
        {
            throw new EmbeddedSqlException(
                "A view in the main schema cannot reference objects in an attached database.");
        }
        if (!statement.Temporary
            && !homeSchema.Equals("main", StringComparison.OrdinalIgnoreCase)
            && ContainsSchemaQualification(statement.Query))
        {
            throw new EmbeddedSqlException("This schema-qualified statement is not supported by managed ATTACH.");
        }

        // A temp view is stored in the connection-private temp database, and the managed engine
        // evaluates a view inside the database that owns it, so a body reaching another schema has
        // to be rejected outright instead of failing later with a confusing "no such table".
        if (statement.Temporary)
        {
            var schemas = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            CollectQuerySchemas(statement.Query, schemas, new HashSet<string>(StringComparer.OrdinalIgnoreCase));
            if (schemas.Select(ResolveCollectedSchema)
                .Any(schema => !schema.Equals("temp", StringComparison.OrdinalIgnoreCase)))
            {
                throw new EmbeddedSqlException(
                    "Managed temporary views can only reference objects in the temp schema.");
            }
        }

        return RouteSchema(
            homeSchema,
            hasViewSchema ? viewName : statement.Name,
            local => statement with
            {
                Name = local,
                // The parser already strips the view's own-name schema qualifier from
                // statement.Sql; no further removal is needed here (and counting it again could
                // over-consume a body identifier spelled like the schema name).
                Sql = statement.Sql,
            });
    }

    private static int CopyQuotedToken(
        string sql,
        int start,
        char terminator,
        char escape,
        StringBuilder output)
    {
        var index = start + 1;
        while (index < sql.Length)
        {
            if (sql[index] != terminator)
            {
                index++;
                continue;
            }
            if (index + 1 < sql.Length && sql[index + 1] == escape)
            {
                index += 2;
                continue;
            }

            index++;
            break;
        }

        output.Append(sql, start, index - start);
        return index;
    }

    private static bool TryReadSqlIdentifier(
        string sql,
        int start,
        out int end,
        out string identifier)
    {
        end = start;
        identifier = string.Empty;
        if (start >= sql.Length)
            return false;

        var quote = sql[start];
        if (quote is '"' or '`' or '[')
        {
            var terminator = quote == '[' ? ']' : quote;
            var decoded = new StringBuilder();
            var index = start + 1;
            while (index < sql.Length)
            {
                if (sql[index] != terminator)
                {
                    decoded.Append(sql[index++]);
                    continue;
                }
                if (index + 1 < sql.Length && sql[index + 1] == terminator)
                {
                    decoded.Append(terminator);
                    index += 2;
                    continue;
                }

                end = index + 1;
                identifier = decoded.ToString();
                return true;
            }

            end = sql.Length;
            identifier = decoded.ToString();
            return true;
        }

        if (!(char.IsLetter(sql[start]) || sql[start] == '_'))
            return false;
        end = start + 1;
        while (end < sql.Length
               && (char.IsLetterOrDigit(sql[end]) || sql[end] is '_' or '$'))
        {
            end++;
        }

        identifier = sql[start..end];
        return true;
    }

    private RoutedStatement RouteQuery(QueryStatement query)
    {
        var schemas = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        CollectQuerySchemas(query, schemas, new HashSet<string>(StringComparer.OrdinalIgnoreCase));
        return RouteForSchemas(query, schemas);
    }

    private RoutedStatement RouteDataStatement(ParsedStatement statement)
    {
        var schemas = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        CollectStatementSchemas(statement, schemas, new HashSet<string>(StringComparer.OrdinalIgnoreCase));
        var resolvedSchemas = schemas
            .Select(ResolveCollectedSchema)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        return TryRouteAttachedUpdateReadingMain(statement, resolvedSchemas, out var routed)
            ? routed
            : RouteForSchemas(statement, schemas);
    }

    // Turso acquires the independent read and write databases needed by a temp trigger subprogram
    // before entering it. This narrow route keeps one foreign schema read-only while the trigger
    // body mutates exactly one non-temp target catalog.
    private bool TryRouteTempTriggerInsertReadingForeignSchema(
        ParsedStatement statement,
        Func<EmbeddedDatabase, EmbeddedDatabase.SchemaCatalog> getCatalog,
        out RoutedStatement routed)
    {
        routed = default;
        if (statement is not InsertStatement { Source: { } source, Returning: null, Upsert: null } insert
            || insert.Rows.Count != 0)
        {
            return false;
        }

        var sourceSchemas = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        CollectQuerySchemas(source, sourceSchemas, new HashSet<string>(StringComparer.OrdinalIgnoreCase));
        var resolvedSourceSchemas = sourceSchemas
            .Select(ResolveCollectedSchema)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        if (resolvedSourceSchemas.Count != 1)
            return false;

        var sourceSchema = resolvedSourceSchemas.Single();
        var targetSchema = ManagedSchemaName.TrySplit(insert.TableName, out var qualifiedTargetSchema, out var targetTableName)
            ? qualifiedTargetSchema
            : ResolveCollectedSchema(UnqualifiedSchemaMarker + insert.TableName);
        if (!ManagedSchemaName.TrySplit(insert.TableName, out _, out targetTableName))
            targetTableName = insert.TableName;

        if (sourceSchema.Equals("temp", StringComparison.OrdinalIgnoreCase)
            || targetSchema.Equals("temp", StringComparison.OrdinalIgnoreCase)
            || sourceSchema.Equals(targetSchema, StringComparison.OrdinalIgnoreCase)
            || FindSchemaDatabase(sourceSchema) is not { } sourceDatabase
            || FindSchemaDatabase(targetSchema) is not { } targetDatabase)
        {
            return false;
        }

        var sourceCatalog = getCatalog(sourceDatabase);
        var targetCatalog = getCatalog(targetDatabase);
        var sourceTables = CloneExternalTables(sourceCatalog);
        var externalTables = new Dictionary<string, EmbeddedTable>(StringComparer.OrdinalIgnoreCase);
        var sourceNames = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var pair in sourceTables)
        {
            var sourceName = targetCatalog.Tables.ContainsKey(pair.Key)
                ? "\u0001" + sourceSchema + ":" + pair.Key
                : pair.Key;
            externalTables.Add(sourceName, pair.Value);
            sourceNames.Add(MainTempSourceKey(sourceSchema, pair.Key), sourceName);
        }

        routed = new RoutedStatement(
            targetDatabase,
            insert with
            {
                TableName = targetTableName,
                Source = RewriteMainTempReadQuery(
                    source,
                    sourceNames,
                    new HashSet<string>(StringComparer.OrdinalIgnoreCase)),
            },
            IsAttached: !ReferenceEquals(targetDatabase, _database),
            ExternalTables: externalTables);
        return true;
    }

    // Turso plans an UPDATE target and every table read with independent database IDs. Keep the
    // first managed cross-database write equally narrow: one attached UPDATE may read main only
    // through its predicate, while writes still target exactly one attached catalog.
    private bool TryRouteAttachedUpdateReadingMain(
        ParsedStatement statement,
        IReadOnlySet<string> resolvedSchemas,
        out RoutedStatement routed)
    {
        routed = default;
        if (statement is not UpdateStatement update
            || update.From is not null
            || update.Returning is not null
            || update.EffectiveOrderBy.Count != 0
            || update.Limit is not null
            || update.Offset is not null
            || update.IndexDirective is not null
            || resolvedSchemas.Count != 2
            || !resolvedSchemas.Contains("main")
            || !ManagedSchemaName.TrySplit(update.TableName, out var targetSchema, out var targetTableName)
            || targetSchema.Equals("main", StringComparison.OrdinalIgnoreCase)
            || targetSchema.Equals("temp", StringComparison.OrdinalIgnoreCase)
            || !resolvedSchemas.Contains(targetSchema)
            || !_attachedDatabases.TryGetValue(targetSchema, out var attachment))
        {
            return false;
        }

        var targetCatalog = GetTransactionState(attachment.Database)?.Catalog ?? attachment.Database.LiveCatalog;
        var mainCatalog = GetTransactionState(_database)?.Catalog ?? _database.LiveCatalog;
        if (targetCatalog.Tables.Keys.Any(mainCatalog.Tables.ContainsKey))
            return false;

        routed = new RoutedStatement(
            attachment.Database,
            update with { TableName = targetTableName },
            IsAttached: true,
            ExternalTables: CloneExternalTables(mainCatalog));
        return true;
    }

    private static Dictionary<string, EmbeddedTable> CloneExternalTables(
        EmbeddedDatabase.SchemaCatalog catalog)
        => catalog.Tables.ToDictionary(
            static entry => entry.Key,
            static entry => entry.Value.Clone(),
            StringComparer.OrdinalIgnoreCase);

    private RoutedStatement RouteForSchemas(ParsedStatement statement, HashSet<string> schemas)
    {
        var resolvedSchemas = schemas
            .Select(ResolveCollectedSchema)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        if (resolvedSchemas.Count == 0)
            return new RoutedStatement(_database, statement, IsAttached: false);
        if (statement is QueryStatement query
            && !StatementMayMutate(_database, statement)
            && !StatementMayMutate(_tempDatabase, statement)
            && resolvedSchemas.Count == 2
            && resolvedSchemas.Contains("main")
            && resolvedSchemas.Contains("temp"))
        {
            return RouteMainTempReadQuery(query);
        }
        if (resolvedSchemas.Count != 1)
        {
            throw new EmbeddedSqlException(
                "Cross-database statements are not supported by managed ATTACH; every persistent table reference must resolve to one database.");
        }

        var schema = resolvedSchemas.Single();
        var rewritten = RewriteStatementSchema(statement, schema);
        if (schema.Equals("main", StringComparison.OrdinalIgnoreCase))
            return new RoutedStatement(_database, rewritten, IsAttached: false);
        if (schema.Equals("temp", StringComparison.OrdinalIgnoreCase))
            return new RoutedStatement(_tempDatabase, rewritten, IsAttached: false);
        if (!_attachedDatabases.TryGetValue(schema, out var attachment))
            throw new EmbeddedSqlException($"no such database: {schema}");

        return new RoutedStatement(attachment.Database, rewritten, IsAttached: true);
    }

    // Temp is connection-private, so a read-only catalog can safely combine its current snapshot with main.
    // Attached databases deliberately remain outside this route because they have independent lock lifecycles.
    private RoutedStatement RouteMainTempReadQuery(QueryStatement query)
    {
        var mainCatalog = GetTransactionState(_database)?.Catalog ?? _database.LiveCatalog;
        var tempCatalog = GetTransactionState(_tempDatabase)?.Catalog ?? _tempDatabase.LiveCatalog;
        var mainTableNames = new HashSet<string>(mainCatalog.Tables.Keys, StringComparer.OrdinalIgnoreCase);
        var tempTableNames = new HashSet<string>(tempCatalog.Tables.Keys, StringComparer.OrdinalIgnoreCase);
        var tables = new Dictionary<string, EmbeddedTable>(StringComparer.OrdinalIgnoreCase);
        var sourceNames = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

        AddTables("main", mainCatalog, tempTableNames);
        AddTables("temp", tempCatalog, mainTableNames);

        return new RoutedStatement(
            _database,
            RewriteMainTempReadQuery(query, sourceNames, new HashSet<string>(StringComparer.OrdinalIgnoreCase)),
            IsAttached: false,
            new EmbeddedDatabase.SchemaCatalog(
                tables,
                new Dictionary<string, ViewDefinition>(StringComparer.OrdinalIgnoreCase),
                new Dictionary<string, TriggerDefinition>(StringComparer.OrdinalIgnoreCase)));

        void AddTables(
            string schema,
            EmbeddedDatabase.SchemaCatalog catalog,
            HashSet<string> otherTableNames)
        {
            foreach (var pair in catalog.Tables)
            {
                var sourceName = otherTableNames.Contains(pair.Key)
                    ? "\u0001" + schema + ":" + pair.Key
                    : pair.Key;
                tables.Add(sourceName, pair.Value);
                sourceNames.Add(MainTempSourceKey(schema, pair.Key), sourceName);
            }
        }
    }

    private QueryStatement RewriteMainTempReadQuery(
        QueryStatement query,
        IReadOnlyDictionary<string, string> sourceNames,
        HashSet<string> commonTableExpressions)
    {
        return query switch
        {
            SelectStatement select => select with
            {
                Projections = select.Projections.Select(projection => projection with
                {
                    Expression = RewriteMainTempReadExpression(
                        projection.Expression,
                        sourceNames,
                        commonTableExpressions)!,
                }).ToArray(),
                Source = RewriteMainTempReadSource(select.Source, sourceNames, commonTableExpressions),
                Where = RewriteMainTempReadExpression(select.Where, sourceNames, commonTableExpressions),
                GroupBy = select.GroupBy.Select(expression =>
                    RewriteMainTempReadExpression(expression, sourceNames, commonTableExpressions)!).ToArray(),
                Having = RewriteMainTempReadExpression(select.Having, sourceNames, commonTableExpressions),
                NamedWindows = select.NamedWindows.Select(window => window with
                {
                    Specification = RewriteMainTempReadWindow(
                        window.Specification,
                        sourceNames,
                        commonTableExpressions)!,
                }).ToArray(),
                OrderBy = RewriteMainTempReadOrderBy(select.OrderBy, sourceNames, commonTableExpressions),
                Limit = RewriteMainTempReadExpression(select.Limit, sourceNames, commonTableExpressions),
                Offset = RewriteMainTempReadExpression(select.Offset, sourceNames, commonTableExpressions),
            },
            ValuesClause values => values with
            {
                Rows = values.Rows.Select(row => row.Select(expression =>
                    RewriteMainTempReadExpression(expression, sourceNames, commonTableExpressions)!).ToArray()).ToArray(),
            },
            CompoundSelectStatement compound => compound with
            {
                Terms = compound.Terms.Select(term =>
                    RewriteMainTempReadQuery(term, sourceNames, commonTableExpressions)).ToArray(),
                OrderBy = RewriteMainTempReadOrderBy(compound.OrderBy, sourceNames, commonTableExpressions),
                Limit = RewriteMainTempReadExpression(compound.Limit, sourceNames, commonTableExpressions),
                Offset = RewriteMainTempReadExpression(compound.Offset, sourceNames, commonTableExpressions),
            },
            WithSelectStatement with => RewriteMainTempReadWithSelect(with, sourceNames, commonTableExpressions),
            _ => throw new InvalidOperationException($"Cannot rewrite query {query.GetType().Name}."),
        };
    }

    private WithSelectStatement RewriteMainTempReadWithSelect(
        WithSelectStatement statement,
        IReadOnlyDictionary<string, string> sourceNames,
        HashSet<string> commonTableExpressions)
    {
        var names = new HashSet<string>(commonTableExpressions, StringComparer.OrdinalIgnoreCase);
        var rewrittenCommonTableExpressions = new List<CommonTableExpression>();
        foreach (var commonTableExpression in statement.CommonTableExpressions)
        {
            names.Add(commonTableExpression.Name);
            rewrittenCommonTableExpressions.Add(commonTableExpression with
            {
                Query = RewriteMainTempReadQuery(commonTableExpression.Query, sourceNames, names),
            });
        }

        return statement with
        {
            CommonTableExpressions = rewrittenCommonTableExpressions,
            Query = RewriteMainTempReadQuery(statement.Query, sourceNames, names),
        };
    }

    private TableSource? RewriteMainTempReadSource(
        TableSource? source,
        IReadOnlyDictionary<string, string> sourceNames,
        HashSet<string> commonTableExpressions)
    {
        return source switch
        {
            null => null,
            NamedTableSource named when !named.IsSchemaQualified
                && commonTableExpressions.Contains(named.Name) => named,
            NamedTableSource named => RewriteMainTempReadNamedSource(named, sourceNames),
            DerivedTableSource derived => derived with
            {
                Query = RewriteMainTempReadQuery(derived.Query, sourceNames, commonTableExpressions),
            },
            JoinTableSource join => join with
            {
                Left = RewriteMainTempReadSource(join.Left, sourceNames, commonTableExpressions)!,
                Right = RewriteMainTempReadSource(join.Right, sourceNames, commonTableExpressions)!,
                Condition = RewriteMainTempReadExpression(
                    join.Condition,
                    sourceNames,
                    commonTableExpressions),
            },
            TableValuedFunctionSource function => function with
            {
                Arguments = [.. function.Arguments.Select(argument =>
                    RewriteMainTempReadExpression(argument, sourceNames, commonTableExpressions)!)],
            },
            _ => throw new InvalidOperationException($"Cannot rewrite source {source.GetType().Name}."),
        };
    }

    private NamedTableSource RewriteMainTempReadNamedSource(
        NamedTableSource source,
        IReadOnlyDictionary<string, string> sourceNames)
    {
        var sourceName = source.Name;
        var schema = ManagedSchemaName.TrySplit(sourceName, out var qualifiedSchema, out var localName)
            ? qualifiedSchema
            : ResolveCollectedSchema(UnqualifiedSchemaMarker + sourceName);
        if (!ManagedSchemaName.TrySplit(sourceName, out _, out localName))
            localName = sourceName;

        return sourceNames.TryGetValue(MainTempSourceKey(schema, localName), out var rewritten)
            ? source with { Name = rewritten, IsSchemaQualified = false }
            : source;
    }

    private IReadOnlyList<OrderByTerm> RewriteMainTempReadOrderBy(
        IReadOnlyList<OrderByTerm> orderBy,
        IReadOnlyDictionary<string, string> sourceNames,
        HashSet<string> commonTableExpressions)
        => orderBy.Select(term => term with
        {
            Expression = RewriteMainTempReadExpression(term.Expression, sourceNames, commonTableExpressions)!,
        }).ToArray();

    private Expression? RewriteMainTempReadExpression(
        Expression? expression,
        IReadOnlyDictionary<string, string> sourceNames,
        HashSet<string> commonTableExpressions)
    {
        return expression switch
        {
            null => null,
            ColumnExpression column when column.Schema is { } schema
                && column.Qualifier is { } qualifier
                && sourceNames.TryGetValue(MainTempSourceKey(schema, qualifier), out var sourceName)
                => column with
                {
                    Name = sourceName + "." + column.UnqualifiedName,
                    Qualifier = sourceName,
                    Schema = null,
                },
            ScalarSubqueryExpression scalarSubquery => scalarSubquery with
            {
                Query = RewriteMainTempReadQuery(
                    scalarSubquery.Query,
                    sourceNames,
                    commonTableExpressions),
            },
            ExistsExpression exists => exists with
            {
                Query = RewriteMainTempReadQuery(exists.Query, sourceNames, commonTableExpressions),
            },
            InSubqueryExpression inSubquery => inSubquery with
            {
                Value = RewriteMainTempReadExpression(
                    inSubquery.Value,
                    sourceNames,
                    commonTableExpressions)!,
                Query = RewriteMainTempReadQuery(inSubquery.Query, sourceNames, commonTableExpressions),
            },
            FunctionExpression function => function with
            {
                Arguments = function.Arguments.Select(argument =>
                    RewriteMainTempReadExpression(argument, sourceNames, commonTableExpressions)!).ToArray(),
                Filter = RewriteMainTempReadExpression(function.Filter, sourceNames, commonTableExpressions),
                Window = RewriteMainTempReadWindow(function.Window, sourceNames, commonTableExpressions),
                AggregateOrderBy = function.AggregateOrderBy is null
                    ? null
                    : RewriteMainTempReadOrderBy(
                        function.AggregateOrderBy,
                        sourceNames,
                        commonTableExpressions),
                OrderedSetOrderBy = function.OrderedSetOrderBy is null
                    ? null
                    : function.OrderedSetOrderBy with
                    {
                        Expression = RewriteMainTempReadExpression(
                            function.OrderedSetOrderBy.Expression,
                            sourceNames,
                            commonTableExpressions)!,
                    },
            },
            RowValueExpression rowValue => rowValue with
            {
                Values = rowValue.Values.Select(value =>
                    RewriteMainTempReadExpression(value, sourceNames, commonTableExpressions)!).ToArray(),
            },
            CollationExpression collation => collation with
            {
                Expression = RewriteMainTempReadExpression(
                    collation.Expression,
                    sourceNames,
                    commonTableExpressions)!,
            },
            CastExpression cast => cast with
            {
                Expression = RewriteMainTempReadExpression(cast.Expression, sourceNames, commonTableExpressions)!,
            },
            CaseExpression @case => @case with
            {
                Operand = RewriteMainTempReadExpression(@case.Operand, sourceNames, commonTableExpressions),
                Clauses = @case.Clauses.Select(clause => clause with
                {
                    When = RewriteMainTempReadExpression(clause.When, sourceNames, commonTableExpressions)!,
                    Then = RewriteMainTempReadExpression(clause.Then, sourceNames, commonTableExpressions)!,
                }).ToArray(),
                Else = RewriteMainTempReadExpression(@case.Else, sourceNames, commonTableExpressions),
            },
            LikeExpression like => like with
            {
                Value = RewriteMainTempReadExpression(like.Value, sourceNames, commonTableExpressions)!,
                Pattern = RewriteMainTempReadExpression(like.Pattern, sourceNames, commonTableExpressions)!,
                Escape = RewriteMainTempReadExpression(like.Escape, sourceNames, commonTableExpressions),
            },
            GlobExpression glob => glob with
            {
                Value = RewriteMainTempReadExpression(glob.Value, sourceNames, commonTableExpressions)!,
                Pattern = RewriteMainTempReadExpression(glob.Pattern, sourceNames, commonTableExpressions)!,
            },
            InExpression @in => @in with
            {
                Value = RewriteMainTempReadExpression(@in.Value, sourceNames, commonTableExpressions)!,
                Values = @in.Values.Select(value =>
                    RewriteMainTempReadExpression(value, sourceNames, commonTableExpressions)!).ToArray(),
            },
            BetweenExpression between => between with
            {
                Value = RewriteMainTempReadExpression(between.Value, sourceNames, commonTableExpressions)!,
                Lower = RewriteMainTempReadExpression(between.Lower, sourceNames, commonTableExpressions)!,
                Upper = RewriteMainTempReadExpression(between.Upper, sourceNames, commonTableExpressions)!,
            },
            UnaryExpression unary => unary with
            {
                Operand = RewriteMainTempReadExpression(unary.Operand, sourceNames, commonTableExpressions)!,
            },
            BinaryExpression binary => binary with
            {
                Left = RewriteMainTempReadExpression(binary.Left, sourceNames, commonTableExpressions)!,
                Right = RewriteMainTempReadExpression(binary.Right, sourceNames, commonTableExpressions)!,
            },
            _ => expression,
        };
    }

    private WindowSpecification? RewriteMainTempReadWindow(
        WindowSpecification? window,
        IReadOnlyDictionary<string, string> sourceNames,
        HashSet<string> commonTableExpressions)
    {
        if (window is null)
            return null;

        return window with
        {
            PartitionBy = window.PartitionBy.Select(expression =>
                RewriteMainTempReadExpression(expression, sourceNames, commonTableExpressions)!).ToArray(),
            OrderBy = RewriteMainTempReadOrderBy(window.OrderBy, sourceNames, commonTableExpressions),
            Frame = window.Frame is null
                ? null
                : window.Frame with
                {
                    Start = window.Frame.Start with
                    {
                        Offset = RewriteMainTempReadExpression(
                            window.Frame.Start.Offset,
                            sourceNames,
                            commonTableExpressions),
                    },
                    End = window.Frame.End with
                    {
                        Offset = RewriteMainTempReadExpression(
                            window.Frame.End.Offset,
                            sourceNames,
                            commonTableExpressions),
                    },
                },
        };
    }

    private static string MainTempSourceKey(string schema, string name)
        => schema + "\u0001" + name;

    private string ResolveCollectedSchema(string schema)
    {
        if (schema.Length == 0 || schema[0] != UnqualifiedSchemaMarker)
            return schema;

        var objectName = schema[1..];
        if (IsTemporarySchemaTable(objectName))
            return "temp";
        if (GetTransactionState(_tempDatabase) is { } tempState
            ? tempState.Catalog.Tables.ContainsKey(objectName) || tempState.Catalog.Views.ContainsKey(objectName)
            : _tempDatabase.ContainsTableOrView(objectName))
        {
            return "temp";
        }
        if (GetTransactionState(_database) is { } mainState
            ? mainState.Catalog.Tables.ContainsKey(objectName) || mainState.Catalog.Views.ContainsKey(objectName)
            : _database.ContainsTableOrView(objectName))
        {
            return "main";
        }

        foreach (var pair in _attachedDatabases.OrderBy(pair => pair.Value.Sequence))
        {
            var attachment = pair.Value;
            if (GetTransactionState(attachment.Database) is { } state
                ? state.Catalog.Tables.ContainsKey(objectName) || state.Catalog.Views.ContainsKey(objectName)
                : attachment.Database.ContainsTableOrView(objectName))
            {
                return pair.Key;
            }
        }

        return "main";
    }

    private static bool IsTemporarySchemaTable(string name)
        => name.Equals("sqlite_temp_master", StringComparison.OrdinalIgnoreCase)
            || name.Equals("sqlite_temp_schema", StringComparison.OrdinalIgnoreCase);

    private static void CollectStatementSchemas(
        ParsedStatement statement,
        ISet<string> schemas,
        HashSet<string> commonTableExpressions)
    {
        switch (statement)
        {
            case InsertStatement insert:
                AddPersistentObjectSchema(insert.TableName, schemas);
                foreach (var expression in insert.Rows.SelectMany(row => row))
                    CollectExpressionSchemas(expression, schemas, commonTableExpressions);
                if (insert.Source is not null)
                    CollectQuerySchemas(insert.Source, schemas, commonTableExpressions);
                foreach (var upsert in insert.Upsert?.Clauses() ?? [])
                {
                    foreach (var target in upsert.Target)
                        CollectExpressionSchemas(target.Expression, schemas, commonTableExpressions);
                    CollectExpressionSchemas(upsert.TargetWhere, schemas, commonTableExpressions);
                    if (upsert.Action is DoUpdateUpsertAction update)
                    {
                        foreach (var assignment in update.Assignments)
                            CollectExpressionSchemas(assignment.Value, schemas, commonTableExpressions);
                        CollectExpressionSchemas(update.Where, schemas, commonTableExpressions);
                    }
                }
                CollectProjectionSchemas(insert.Returning, schemas, commonTableExpressions);
                break;
            case UpdateStatement update:
                AddPersistentObjectSchema(update.TableName, schemas);
                foreach (var assignment in update.Assignments)
                    CollectExpressionSchemas(assignment.Value, schemas, commonTableExpressions);
                CollectSourceSchemas(update.From, schemas, commonTableExpressions);
                CollectExpressionSchemas(update.Where, schemas, commonTableExpressions);
                foreach (var orderBy in update.EffectiveOrderBy)
                    CollectExpressionSchemas(orderBy.Expression, schemas, commonTableExpressions);
                CollectExpressionSchemas(update.Limit, schemas, commonTableExpressions);
                CollectExpressionSchemas(update.Offset, schemas, commonTableExpressions);
                CollectProjectionSchemas(update.Returning, schemas, commonTableExpressions);
                break;
            case DeleteStatement delete:
                AddPersistentObjectSchema(delete.TableName, schemas);
                CollectExpressionSchemas(delete.Where, schemas, commonTableExpressions);
                foreach (var orderBy in delete.EffectiveOrderBy)
                    CollectExpressionSchemas(orderBy.Expression, schemas, commonTableExpressions);
                CollectExpressionSchemas(delete.Limit, schemas, commonTableExpressions);
                CollectExpressionSchemas(delete.Offset, schemas, commonTableExpressions);
                CollectProjectionSchemas(delete.Returning, schemas, commonTableExpressions);
                break;
            case WithDmlStatement with:
                var names = new HashSet<string>(commonTableExpressions, StringComparer.OrdinalIgnoreCase);
                foreach (var commonTableExpression in with.CommonTableExpressions)
                {
                    names.Add(commonTableExpression.Name);
                    CollectStatementSchemas(commonTableExpression.Body, schemas, names);
                }
                CollectStatementSchemas(with.Dml, schemas, names);
                break;
            case QueryStatement query:
                CollectQuerySchemas(query, schemas, commonTableExpressions);
                break;
            default:
                throw new InvalidOperationException($"Cannot route data statement {statement.GetType().Name}.");
        }
    }

    private static void CollectQuerySchemas(
        QueryStatement query,
        ISet<string> schemas,
        HashSet<string> commonTableExpressions)
    {
        switch (query)
        {
            case SelectStatement select:
                CollectSourceSchemas(select.Source, schemas, commonTableExpressions);
                CollectProjectionSchemas(select.Projections, schemas, commonTableExpressions);
                CollectExpressionSchemas(select.Where, schemas, commonTableExpressions);
                foreach (var expression in select.GroupBy)
                    CollectExpressionSchemas(expression, schemas, commonTableExpressions);
                CollectExpressionSchemas(select.Having, schemas, commonTableExpressions);
                foreach (var window in select.NamedWindows)
                    CollectWindowSchemas(window.Specification, schemas, commonTableExpressions);
                foreach (var orderBy in select.OrderBy)
                    CollectExpressionSchemas(orderBy.Expression, schemas, commonTableExpressions);
                CollectExpressionSchemas(select.Limit, schemas, commonTableExpressions);
                CollectExpressionSchemas(select.Offset, schemas, commonTableExpressions);
                break;
            case ValuesClause values:
                foreach (var expression in values.Rows.SelectMany(row => row))
                    CollectExpressionSchemas(expression, schemas, commonTableExpressions);
                break;
            case CompoundSelectStatement compound:
                foreach (var term in compound.Terms)
                    CollectQuerySchemas(term, schemas, commonTableExpressions);
                foreach (var orderBy in compound.OrderBy)
                    CollectExpressionSchemas(orderBy.Expression, schemas, commonTableExpressions);
                CollectExpressionSchemas(compound.Limit, schemas, commonTableExpressions);
                CollectExpressionSchemas(compound.Offset, schemas, commonTableExpressions);
                break;
            case WithSelectStatement with:
                var names = new HashSet<string>(commonTableExpressions, StringComparer.OrdinalIgnoreCase);
                foreach (var commonTableExpression in with.CommonTableExpressions)
                {
                    names.Add(commonTableExpression.Name);
                    CollectStatementSchemas(commonTableExpression.Body, schemas, names);
                }
                CollectQuerySchemas(with.Query, schemas, names);
                break;
            default:
                throw new InvalidOperationException($"Cannot route query {query.GetType().Name}.");
        }
    }

    private static void CollectSourceSchemas(
        TableSource? source,
        ISet<string> schemas,
        HashSet<string> commonTableExpressions)
    {
        switch (source)
        {
            case null:
                break;
            case NamedTableSource named:
                if (ManagedSchemaName.TrySplit(named.Name, out var schema, out _))
                    schemas.Add(schema);
                else if (named.IsSchemaQualified || !commonTableExpressions.Contains(named.Name))
                    schemas.Add(UnqualifiedSchemaMarker + named.Name);
                break;
            case DerivedTableSource derived:
                CollectQuerySchemas(derived.Query, schemas, commonTableExpressions);
                break;
            case JoinTableSource join:
                CollectSourceSchemas(join.Left, schemas, commonTableExpressions);
                CollectSourceSchemas(join.Right, schemas, commonTableExpressions);
                CollectExpressionSchemas(join.Condition, schemas, commonTableExpressions);
                break;
            case TableValuedFunctionSource function:
                CollectTableValuedFunctionSchemas(function, schemas, commonTableExpressions);
                break;
        }
    }

    /// <summary>
    /// Routes a <c>pragma_*</c> call to the schema that owns the object it names, so
    /// <c>pragma_table_info('t')</c> reports the temp shadow when one exists, exactly as the
    /// <c>PRAGMA table_info(t)</c> statement form does.
    /// </summary>
    private static void CollectTableValuedFunctionSchemas(
        TableValuedFunctionSource function,
        ISet<string> schemas,
        HashSet<string> commonTableExpressions)
    {
        foreach (var argument in function.Arguments)
            CollectExpressionSchemas(argument, schemas, commonTableExpressions);

        if (function.Schema is { } explicitSchema)
        {
            schemas.Add(explicitSchema);
            return;
        }

        if (!TableValuedFunctionRegistry.TryResolve(function.Name, out var module))
            return;

        if (module.SchemaNameArgumentIndex is { } schemaIndex
            && schemaIndex < function.Arguments.Count
            && function.Arguments[schemaIndex] is LiteralExpression { Value.Kind: SqlValueKind.Text } schemaLiteral)
        {
            schemas.Add(schemaLiteral.Value.AsText());
            return;
        }

        if (module.SchemaObjectArgumentIndex is not { } argumentIndex
            || argumentIndex >= function.Arguments.Count
            || function.Arguments[argumentIndex] is not LiteralExpression { Value.Kind: SqlValueKind.Text } literal)
        {
            return;
        }

        schemas.Add(UnqualifiedSchemaMarker + literal.Value.AsText());
    }

    private static void CollectProjectionSchemas(
        IReadOnlyList<Projection>? projections,
        ISet<string> schemas,
        HashSet<string> commonTableExpressions)
    {
        if (projections is null)
            return;
        foreach (var projection in projections)
            CollectExpressionSchemas(projection.Expression, schemas, commonTableExpressions);
    }

    private static void CollectExpressionSchemas(
        Expression? expression,
        ISet<string> schemas,
        HashSet<string> commonTableExpressions)
    {
        switch (expression)
        {
            case null:
            case LiteralExpression:
            case ParameterExpression:
            case ColumnExpression:
            case StarExpression:
            case QualifiedStarExpression:
            case CurrentTimeExpression:
            case RaiseExpression:
                return;
            case ScalarSubqueryExpression scalarSubquery:
                CollectQuerySchemas(scalarSubquery.Query, schemas, commonTableExpressions);
                return;
            case ExistsExpression exists:
                CollectQuerySchemas(exists.Query, schemas, commonTableExpressions);
                return;
            case InSubqueryExpression inSubquery:
                CollectExpressionSchemas(inSubquery.Value, schemas, commonTableExpressions);
                CollectQuerySchemas(inSubquery.Query, schemas, commonTableExpressions);
                return;
            case RowValueExpression rowValue:
                foreach (var value in rowValue.Values)
                    CollectExpressionSchemas(value, schemas, commonTableExpressions);
                return;
            case FunctionExpression function:
                foreach (var argument in function.Arguments)
                    CollectExpressionSchemas(argument, schemas, commonTableExpressions);
                CollectExpressionSchemas(function.Filter, schemas, commonTableExpressions);
                foreach (var orderBy in function.AggregateOrderBy ?? [])
                    CollectExpressionSchemas(orderBy.Expression, schemas, commonTableExpressions);
                CollectWindowSchemas(function.Window, schemas, commonTableExpressions);
                return;
            case CollationExpression collation:
                CollectExpressionSchemas(collation.Expression, schemas, commonTableExpressions);
                return;
            case CastExpression cast:
                CollectExpressionSchemas(cast.Expression, schemas, commonTableExpressions);
                return;
            case CaseExpression @case:
                CollectExpressionSchemas(@case.Operand, schemas, commonTableExpressions);
                foreach (var clause in @case.Clauses)
                {
                    CollectExpressionSchemas(clause.When, schemas, commonTableExpressions);
                    CollectExpressionSchemas(clause.Then, schemas, commonTableExpressions);
                }
                CollectExpressionSchemas(@case.Else, schemas, commonTableExpressions);
                return;
            case LikeExpression like:
                CollectExpressionSchemas(like.Value, schemas, commonTableExpressions);
                CollectExpressionSchemas(like.Pattern, schemas, commonTableExpressions);
                CollectExpressionSchemas(like.Escape, schemas, commonTableExpressions);
                return;
            case GlobExpression glob:
                CollectExpressionSchemas(glob.Value, schemas, commonTableExpressions);
                CollectExpressionSchemas(glob.Pattern, schemas, commonTableExpressions);
                return;
            case InExpression @in:
                CollectExpressionSchemas(@in.Value, schemas, commonTableExpressions);
                foreach (var value in @in.Values)
                    CollectExpressionSchemas(value, schemas, commonTableExpressions);
                return;
            case BetweenExpression between:
                CollectExpressionSchemas(between.Value, schemas, commonTableExpressions);
                CollectExpressionSchemas(between.Lower, schemas, commonTableExpressions);
                CollectExpressionSchemas(between.Upper, schemas, commonTableExpressions);
                return;
            case UnaryExpression unary:
                CollectExpressionSchemas(unary.Operand, schemas, commonTableExpressions);
                return;
            case BinaryExpression binary:
                CollectExpressionSchemas(binary.Left, schemas, commonTableExpressions);
                CollectExpressionSchemas(binary.Right, schemas, commonTableExpressions);
                return;
            default:
                throw new InvalidOperationException($"Cannot route expression {expression.GetType().Name}.");
        }
    }

    private static void CollectWindowSchemas(
        WindowSpecification? window,
        ISet<string> schemas,
        HashSet<string> commonTableExpressions)
    {
        if (window is null)
            return;
        foreach (var expression in window.PartitionBy)
            CollectExpressionSchemas(expression, schemas, commonTableExpressions);
        foreach (var orderBy in window.OrderBy)
            CollectExpressionSchemas(orderBy.Expression, schemas, commonTableExpressions);
        CollectExpressionSchemas(window.Frame?.Start.Offset, schemas, commonTableExpressions);
        CollectExpressionSchemas(window.Frame?.End.Offset, schemas, commonTableExpressions);
    }

    private static void AddPersistentObjectSchema(string name, ISet<string> schemas)
    {
        schemas.Add(
            ManagedSchemaName.TrySplit(name, out var schema, out _)
                ? schema
                : UnqualifiedSchemaMarker + name);
    }

    private static ParsedStatement RewriteStatementSchema(ParsedStatement statement, string schema)
    {
        return RewriteStatementSchema(
            statement,
            schema,
            new HashSet<string>(StringComparer.OrdinalIgnoreCase));
    }

    private static ParsedStatement RewriteStatementSchema(
        ParsedStatement statement,
        string schema,
        HashSet<string> commonTableExpressions)
    {
        return statement switch
        {
            InsertStatement insert => insert with
            {
                TableName = RewritePersistentObjectName(insert.TableName, schema),
                Rows = insert.Rows.Select(row => row.Select(expression =>
                    RewriteExpressionSchema(expression, schema, commonTableExpressions)).ToArray()).ToArray(),
                Source = insert.Source is null
                    ? null
                    : RewriteQuerySchema(insert.Source, schema, commonTableExpressions),
                Returning = RewriteProjections(insert.Returning, schema, commonTableExpressions),
                Upsert = RewriteUpsertSchema(insert.Upsert, schema, commonTableExpressions),
            },
            UpdateStatement update => update with
            {
                TableName = RewritePersistentObjectName(update.TableName, schema),
                Assignments = RewriteAssignments(update.Assignments, schema, commonTableExpressions),
                From = RewriteSourceSchema(update.From, schema, commonTableExpressions),
                Where = RewriteNullableExpression(update.Where, schema, commonTableExpressions),
                OrderBy = RewriteOrderBy(update.EffectiveOrderBy, schema, commonTableExpressions),
                Limit = RewriteNullableExpression(update.Limit, schema, commonTableExpressions),
                Offset = RewriteNullableExpression(update.Offset, schema, commonTableExpressions),
                Returning = RewriteProjections(update.Returning, schema, commonTableExpressions),
            },
            DeleteStatement delete => delete with
            {
                TableName = RewritePersistentObjectName(delete.TableName, schema),
                Where = RewriteNullableExpression(delete.Where, schema, commonTableExpressions),
                OrderBy = RewriteOrderBy(delete.EffectiveOrderBy, schema, commonTableExpressions),
                Limit = RewriteNullableExpression(delete.Limit, schema, commonTableExpressions),
                Offset = RewriteNullableExpression(delete.Offset, schema, commonTableExpressions),
                Returning = RewriteProjections(delete.Returning, schema, commonTableExpressions),
            },
            WithDmlStatement with => RewriteWithDmlSchema(with, schema, commonTableExpressions),
            QueryStatement query => RewriteQuerySchema(query, schema, commonTableExpressions),
            _ => statement,
        };
    }

    private static IReadOnlyList<ColumnAssignment> RewriteAssignments(
        IReadOnlyList<ColumnAssignment> assignments,
        string schema,
        HashSet<string> commonTableExpressions)
    {
        var rewrittenValues = new Dictionary<Expression, Expression>(ReferenceEqualityComparer.Instance);
        var rewritten = new ColumnAssignment[assignments.Count];
        for (var index = 0; index < assignments.Count; index++)
        {
            var assignment = assignments[index];
            if (!rewrittenValues.TryGetValue(assignment.Value, out var value))
            {
                value = RewriteExpressionSchema(assignment.Value, schema, commonTableExpressions);
                rewrittenValues.Add(assignment.Value, value);
            }

            rewritten[index] = assignment with { Value = value };
        }

        return rewritten;
    }

    private static WithDmlStatement RewriteWithDmlSchema(
        WithDmlStatement statement,
        string schema,
        HashSet<string> commonTableExpressions)
    {
        var names = new HashSet<string>(commonTableExpressions, StringComparer.OrdinalIgnoreCase);
        var rewritten = new List<CommonTableExpression>();
        foreach (var commonTableExpression in statement.CommonTableExpressions)
        {
            names.Add(commonTableExpression.Name);
            rewritten.Add(RewriteCommonTableExpressionSchema(commonTableExpression, schema, names));
        }

        return statement with
        {
            CommonTableExpressions = rewritten,
            Dml = RewriteStatementSchema(statement.Dml, schema, names),
        };
    }

    private static UpsertClause? RewriteUpsertSchema(
        UpsertClause? upsert,
        string schema,
        HashSet<string> commonTableExpressions)
    {
        if (upsert is null)
            return null;

        var targets = upsert.Target.Select(target => target with
        {
            Expression = RewriteNullableExpression(
                target.Expression,
                schema,
                commonTableExpressions),
        }).ToArray();
        var action = upsert.Action is DoUpdateUpsertAction update
            ? update with
            {
                Assignments = RewriteAssignments(
                    update.Assignments,
                    schema,
                    commonTableExpressions),
                Where = RewriteNullableExpression(update.Where, schema, commonTableExpressions),
            }
            : upsert.Action;
        return upsert with
        {
            Target = targets,
            TargetWhere = RewriteNullableExpression(
                upsert.TargetWhere,
                schema,
                commonTableExpressions),
            Action = action,
            Next = RewriteUpsertSchema(upsert.Next, schema, commonTableExpressions),
        };
    }

    private static QueryStatement RewriteQuerySchema(
        QueryStatement query,
        string schema,
        HashSet<string> commonTableExpressions)
    {
        return query switch
        {
            SelectStatement select => select with
            {
                Projections = RewriteProjections(select.Projections, schema, commonTableExpressions)!,
                Source = RewriteSourceSchema(select.Source, schema, commonTableExpressions),
                Where = RewriteNullableExpression(select.Where, schema, commonTableExpressions),
                GroupBy = select.GroupBy.Select(expression =>
                    RewriteExpressionSchema(expression, schema, commonTableExpressions)).ToArray(),
                Having = RewriteNullableExpression(select.Having, schema, commonTableExpressions),
                NamedWindows = select.NamedWindows.Select(window => window with
                {
                    Specification = RewriteWindowSchema(
                        window.Specification,
                        schema,
                        commonTableExpressions)!,
                }).ToArray(),
                OrderBy = RewriteOrderBy(select.OrderBy, schema, commonTableExpressions),
                Limit = RewriteNullableExpression(select.Limit, schema, commonTableExpressions),
                Offset = RewriteNullableExpression(select.Offset, schema, commonTableExpressions),
            },
            ValuesClause values => values with
            {
                Rows = values.Rows.Select(row => row.Select(expression =>
                    RewriteExpressionSchema(expression, schema, commonTableExpressions)).ToArray()).ToArray(),
            },
            CompoundSelectStatement compound => compound with
            {
                Terms = compound.Terms.Select(term =>
                    RewriteQuerySchema(term, schema, commonTableExpressions)).ToArray(),
                OrderBy = RewriteOrderBy(compound.OrderBy, schema, commonTableExpressions),
                Limit = RewriteNullableExpression(compound.Limit, schema, commonTableExpressions),
                Offset = RewriteNullableExpression(compound.Offset, schema, commonTableExpressions),
            },
            WithSelectStatement with => RewriteWithSelectSchema(with, schema, commonTableExpressions),
            _ => throw new InvalidOperationException($"Cannot rewrite query {query.GetType().Name}."),
        };
    }

    private static WithSelectStatement RewriteWithSelectSchema(
        WithSelectStatement statement,
        string schema,
        HashSet<string> commonTableExpressions)
    {
        var names = new HashSet<string>(commonTableExpressions, StringComparer.OrdinalIgnoreCase);
        var rewritten = new List<CommonTableExpression>();
        foreach (var commonTableExpression in statement.CommonTableExpressions)
        {
            names.Add(commonTableExpression.Name);
            rewritten.Add(RewriteCommonTableExpressionSchema(commonTableExpression, schema, names));
        }

        return statement with
        {
            CommonTableExpressions = rewritten,
            Query = RewriteQuerySchema(statement.Query, schema, names),
        };
    }

    private static CommonTableExpression RewriteCommonTableExpressionSchema(
        CommonTableExpression commonTableExpression,
        string schema,
        HashSet<string> names)
    {
        return commonTableExpression.WritableBody is null
            ? commonTableExpression with
            {
                Query = RewriteQuerySchema(commonTableExpression.Query, schema, names),
            }
            : commonTableExpression with
            {
                WritableBody = RewriteStatementSchema(
                    commonTableExpression.WritableBody,
                    schema,
                    names),
            };
    }

    private static TableSource? RewriteSourceSchema(
        TableSource? source,
        string schema,
        HashSet<string> commonTableExpressions)
    {
        return source switch
        {
            null => null,
            NamedTableSource named => !named.IsSchemaQualified
                && commonTableExpressions.Contains(named.Name)
                ? named
                : named with { Name = RewriteSourceObjectName(named.Name, schema) },
            DerivedTableSource derived => derived with
            {
                Query = RewriteQuerySchema(derived.Query, schema, commonTableExpressions),
            },
            JoinTableSource join => join with
            {
                Left = RewriteSourceSchema(join.Left, schema, commonTableExpressions)!,
                Right = RewriteSourceSchema(join.Right, schema, commonTableExpressions)!,
                Condition = RewriteNullableExpression(join.Condition, schema, commonTableExpressions),
            },
            TableValuedFunctionSource function => function with
            {
                Arguments = [.. function.Arguments.Select(argument =>
                    RewriteExpressionSchema(argument, schema, commonTableExpressions))],
                Schema = function.Schema ?? schema,
            },
            _ => throw new InvalidOperationException($"Cannot rewrite source {source.GetType().Name}."),
        };
    }

    private static string RewriteSourceObjectName(string name, string schema)
    {
        var localName = RewritePersistentObjectName(name, schema);
        return schema.Equals("temp", StringComparison.OrdinalIgnoreCase)
            && IsTemporarySchemaTable(localName)
                ? "sqlite_schema"
                : localName;
    }

    private static IReadOnlyList<Projection>? RewriteProjections(
        IReadOnlyList<Projection>? projections,
        string schema,
        HashSet<string> commonTableExpressions)
        => projections?.Select(projection => projection with
        {
            Expression = RewriteExpressionSchema(projection.Expression, schema, commonTableExpressions),
        }).ToArray();

    private static IReadOnlyList<OrderByTerm> RewriteOrderBy(
        IReadOnlyList<OrderByTerm> orderBy,
        string schema,
        HashSet<string> commonTableExpressions)
        => orderBy.Select(term => term with
        {
            Expression = RewriteExpressionSchema(term.Expression, schema, commonTableExpressions),
        }).ToArray();

    private static Expression? RewriteNullableExpression(
        Expression? expression,
        string schema,
        HashSet<string> commonTableExpressions)
        => expression is null ? null : RewriteExpressionSchema(expression, schema, commonTableExpressions);

    private static Expression RewriteExpressionSchema(
        Expression expression,
        string schema,
        HashSet<string> commonTableExpressions)
    {
        return expression switch
        {
            ColumnExpression column when schema.Equals(PersistentTriggerColumnSchemaMarker, StringComparison.Ordinal)
                && column.Schema is not null
                => column with { Schema = null },
            ScalarSubqueryExpression scalarSubquery => scalarSubquery with
            {
                Query = RewriteQuerySchema(scalarSubquery.Query, schema, commonTableExpressions),
            },
            ExistsExpression exists => exists with
            {
                Query = RewriteQuerySchema(exists.Query, schema, commonTableExpressions),
            },
            InSubqueryExpression inSubquery => inSubquery with
            {
                Value = RewriteExpressionSchema(inSubquery.Value, schema, commonTableExpressions),
                Query = RewriteQuerySchema(inSubquery.Query, schema, commonTableExpressions),
            },
            FunctionExpression function => function with
            {
                Arguments = function.Arguments.Select(argument =>
                    RewriteExpressionSchema(argument, schema, commonTableExpressions)).ToArray(),
                Filter = RewriteNullableExpression(function.Filter, schema, commonTableExpressions),
                Window = RewriteWindowSchema(function.Window, schema, commonTableExpressions),
                AggregateOrderBy = RewriteOrderBy(
                    function.AggregateOrderBy ?? [],
                    schema,
                    commonTableExpressions),
                OrderedSetOrderBy = function.OrderedSetOrderBy is null
                    ? null
                    : function.OrderedSetOrderBy with
                    {
                        Expression = RewriteExpressionSchema(
                            function.OrderedSetOrderBy.Expression,
                            schema,
                            commonTableExpressions),
                    },
            },
            RowValueExpression rowValue => rowValue with
            {
                Values = rowValue.Values.Select(value =>
                    RewriteExpressionSchema(value, schema, commonTableExpressions)).ToArray(),
            },
            CollationExpression collation => collation with
            {
                Expression = RewriteExpressionSchema(collation.Expression, schema, commonTableExpressions),
            },
            CastExpression cast => cast with
            {
                Expression = RewriteExpressionSchema(cast.Expression, schema, commonTableExpressions),
            },
            CaseExpression @case => @case with
            {
                Operand = RewriteNullableExpression(@case.Operand, schema, commonTableExpressions),
                Clauses = @case.Clauses.Select(clause => clause with
                {
                    When = RewriteExpressionSchema(clause.When, schema, commonTableExpressions),
                    Then = RewriteExpressionSchema(clause.Then, schema, commonTableExpressions),
                }).ToArray(),
                Else = RewriteNullableExpression(@case.Else, schema, commonTableExpressions),
            },
            LikeExpression like => like with
            {
                Value = RewriteExpressionSchema(like.Value, schema, commonTableExpressions),
                Pattern = RewriteExpressionSchema(like.Pattern, schema, commonTableExpressions),
                Escape = RewriteNullableExpression(like.Escape, schema, commonTableExpressions),
            },
            GlobExpression glob => glob with
            {
                Value = RewriteExpressionSchema(glob.Value, schema, commonTableExpressions),
                Pattern = RewriteExpressionSchema(glob.Pattern, schema, commonTableExpressions),
            },
            InExpression @in => @in with
            {
                Value = RewriteExpressionSchema(@in.Value, schema, commonTableExpressions),
                Values = @in.Values.Select(value =>
                    RewriteExpressionSchema(value, schema, commonTableExpressions)).ToArray(),
            },
            BetweenExpression between => between with
            {
                Value = RewriteExpressionSchema(between.Value, schema, commonTableExpressions),
                Lower = RewriteExpressionSchema(between.Lower, schema, commonTableExpressions),
                Upper = RewriteExpressionSchema(between.Upper, schema, commonTableExpressions),
            },
            UnaryExpression unary => unary with
            {
                Operand = RewriteExpressionSchema(unary.Operand, schema, commonTableExpressions),
            },
            BinaryExpression binary => binary with
            {
                Left = RewriteExpressionSchema(binary.Left, schema, commonTableExpressions),
                Right = RewriteExpressionSchema(binary.Right, schema, commonTableExpressions),
            },
            _ => expression,
        };
    }

    private static WindowSpecification? RewriteWindowSchema(
        WindowSpecification? window,
        string schema,
        HashSet<string> commonTableExpressions)
    {
        if (window is null)
            return null;

        return window with
        {
            PartitionBy = window.PartitionBy.Select(expression =>
                RewriteExpressionSchema(expression, schema, commonTableExpressions)).ToArray(),
            OrderBy = RewriteOrderBy(window.OrderBy, schema, commonTableExpressions),
            Frame = window.Frame is null
                ? null
                : window.Frame with
                {
                    Start = window.Frame.Start with
                    {
                        Offset = RewriteNullableExpression(
                            window.Frame.Start.Offset,
                            schema,
                            commonTableExpressions),
                    },
                    End = window.Frame.End with
                    {
                        Offset = RewriteNullableExpression(
                            window.Frame.End.Offset,
                            schema,
                            commonTableExpressions),
                    },
                },
        };
    }

    private static string RewritePersistentObjectName(string name, string schema)
    {
        if (!ManagedSchemaName.TrySplit(name, out var objectSchema, out var localName))
            return name;
        if (!objectSchema.Equals(schema, StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException("A cross-database object escaped managed ATTACH routing.");

        return localName;
    }

    private RoutedStatement RouteSchema(string schema, string localName, Func<string, ParsedStatement> rewrite)
    {
        if (schema.Equals("temp", StringComparison.OrdinalIgnoreCase))
            return new RoutedStatement(_tempDatabase, rewrite(localName), IsAttached: false);
        if (schema.Equals("main", StringComparison.OrdinalIgnoreCase))
            return new RoutedStatement(_database, rewrite(localName), IsAttached: false);
        if (!_attachedDatabases.TryGetValue(schema, out var attachment))
            throw new EmbeddedSqlException($"no such database: {schema}");

        return new RoutedStatement(attachment.Database, rewrite(localName), IsAttached: true);
    }

    private EmbeddedDatabase ResolveBlobDatabase(string databaseName)
    {
        if (databaseName.Equals("temp", StringComparison.OrdinalIgnoreCase))
        {
            throw new EmbeddedSqlException(
                "Managed incremental blob I/O does not support the temporary database.");
        }
        if (databaseName.Equals("main", StringComparison.OrdinalIgnoreCase))
            return _database;
        if (_attachedDatabases.TryGetValue(databaseName, out var attachment))
            return attachment.Database;

        throw new EmbeddedSqlException($"no such database: {databaseName}");
    }

    private static bool ContainsSchemaQualification(ParsedStatement statement)
    {
        return statement switch
        {
            CreateTableStatement create => ManagedSchemaName.TrySplit(create.Name, out _, out _),
            DropTableStatement drop => ManagedSchemaName.TrySplit(drop.Name, out _, out _),
            CreateIndexStatement createIndex => ManagedSchemaName.TrySplit(createIndex.Name, out _, out _)
                || ManagedSchemaName.TrySplit(createIndex.TableName, out _, out _),
            DropIndexStatement dropIndex => ManagedSchemaName.TrySplit(dropIndex.Name, out _, out _),
            CreateViewStatement createView => ManagedSchemaName.TrySplit(createView.Name, out _, out _)
                || QueryContainsSchemaQualification(createView.Query),
            DropViewStatement dropView => ManagedSchemaName.TrySplit(dropView.Name, out _, out _),
            CreateTriggerStatement createTrigger => ManagedSchemaName.TrySplit(createTrigger.Name, out _, out _)
                || ManagedSchemaName.TrySplit(createTrigger.TableName, out _, out _)
                || ExpressionContainsSchemaQualification(createTrigger.When)
                || createTrigger.Body.Any(ContainsSchemaQualification),
            DropTriggerStatement dropTrigger => ManagedSchemaName.TrySplit(dropTrigger.Name, out _, out _),
            AlterTableAddColumnStatement addColumn => ManagedSchemaName.TrySplit(addColumn.TableName, out _, out _),
            AlterTableRenameStatement rename => ManagedSchemaName.TrySplit(rename.TableName, out _, out _),
            AlterTableRenameColumnStatement renameColumn => ManagedSchemaName.TrySplit(renameColumn.TableName, out _, out _),
            AlterTableAlterColumnStatement alterColumn => ManagedSchemaName.TrySplit(alterColumn.TableName, out _, out _),
            AlterTableDropColumnStatement dropColumn => ManagedSchemaName.TrySplit(dropColumn.TableName, out _, out _),
            ReindexStatement { Target: { } target } => ManagedSchemaName.TrySplit(target, out _, out _),
            OptimizeIndexStatement { IndexName: { } indexName } => ManagedSchemaName.TrySplit(indexName, out _, out _),
            InsertStatement insert => ManagedSchemaName.TrySplit(insert.TableName, out _, out _)
                || insert.Rows.SelectMany(row => row).Any(ExpressionContainsSchemaQualification)
                || (insert.Source is not null && QueryContainsSchemaQualification(insert.Source))
                || insert.Upsert?.Clauses().Any(upsert =>
                    upsert.Target.Any(target => ExpressionContainsSchemaQualification(target.Expression))
                    || ExpressionContainsSchemaQualification(upsert.TargetWhere)
                    || upsert.Action is DoUpdateUpsertAction update
                        && (update.Assignments.Any(assignment => ExpressionContainsSchemaQualification(assignment.Value))
                            || ExpressionContainsSchemaQualification(update.Where))) == true
                || (insert.Returning?.Any(projection => ExpressionContainsSchemaQualification(projection.Expression)) ?? false),
            UpdateStatement update => ManagedSchemaName.TrySplit(update.TableName, out _, out _)
                || update.Assignments.Any(assignment => ExpressionContainsSchemaQualification(assignment.Value))
                || SourceContainsSchemaQualification(update.From)
                || ExpressionContainsSchemaQualification(update.Where)
                || update.EffectiveOrderBy.Any(term => ExpressionContainsSchemaQualification(term.Expression))
                || ExpressionContainsSchemaQualification(update.Limit)
                || ExpressionContainsSchemaQualification(update.Offset)
                || (update.Returning?.Any(projection => ExpressionContainsSchemaQualification(projection.Expression)) ?? false),
            DeleteStatement delete => ManagedSchemaName.TrySplit(delete.TableName, out _, out _)
                || ExpressionContainsSchemaQualification(delete.Where)
                || delete.EffectiveOrderBy.Any(term => ExpressionContainsSchemaQualification(term.Expression))
                || ExpressionContainsSchemaQualification(delete.Limit)
                || ExpressionContainsSchemaQualification(delete.Offset)
                || (delete.Returning?.Any(projection => ExpressionContainsSchemaQualification(projection.Expression)) ?? false),
            WithDmlStatement with => with.CommonTableExpressions.Any(commonTableExpression =>
                    ManagedSchemaName.TrySplit(commonTableExpression.Name, out _, out _)
                    || ContainsSchemaQualification(commonTableExpression.Body))
                || ContainsSchemaQualification(with.Dml),
            QueryStatement query => QueryContainsSchemaQualification(query),
            ExplainStatement explain => ContainsSchemaQualification(explain.Inner),
            ExplainQueryPlanStatement explainQueryPlan => ContainsSchemaQualification(explainQueryPlan.Inner),
            _ => false,
        };
    }

    private static bool QueryContainsSchemaQualification(QueryStatement query)
    {
        return query switch
        {
            SelectStatement select => SourceContainsSchemaQualification(select.Source)
                || select.Projections.Any(projection => ExpressionContainsSchemaQualification(projection.Expression))
                || ExpressionContainsSchemaQualification(select.Where)
                || select.GroupBy.Any(ExpressionContainsSchemaQualification)
                || ExpressionContainsSchemaQualification(select.Having)
                || select.NamedWindows.Any(window => WindowContainsSchemaQualification(window.Specification))
                || select.OrderBy.Any(orderBy => ExpressionContainsSchemaQualification(orderBy.Expression))
                || ExpressionContainsSchemaQualification(select.Limit)
                || ExpressionContainsSchemaQualification(select.Offset),
            ValuesClause values => values.Rows.SelectMany(row => row).Any(ExpressionContainsSchemaQualification),
            CompoundSelectStatement compound => compound.Terms.Any(QueryContainsSchemaQualification)
                || compound.OrderBy.Any(orderBy => ExpressionContainsSchemaQualification(orderBy.Expression))
                || ExpressionContainsSchemaQualification(compound.Limit)
                || ExpressionContainsSchemaQualification(compound.Offset),
            WithSelectStatement with => with.CommonTableExpressions.Any(commonTableExpression =>
                    ContainsSchemaQualification(commonTableExpression.Body))
                || QueryContainsSchemaQualification(with.Query),
            _ => false,
        };
    }

    private static bool SourceContainsSchemaQualification(TableSource? source)
    {
        return source switch
        {
            null => false,
            NamedTableSource named => ManagedSchemaName.TrySplit(named.Name, out _, out _),
            DerivedTableSource derived => QueryContainsSchemaQualification(derived.Query),
            JoinTableSource join => SourceContainsSchemaQualification(join.Left)
                || SourceContainsSchemaQualification(join.Right)
                || ExpressionContainsSchemaQualification(join.Condition),
            TableValuedFunctionSource function => function.Schema is not null
                || function.Arguments.Any(ExpressionContainsSchemaQualification),
            _ => false,
        };
    }

    private static bool ExpressionContainsSchemaQualification(Expression? expression)
    {
        return expression switch
        {
            null => false,
            ScalarSubqueryExpression scalarSubquery => QueryContainsSchemaQualification(scalarSubquery.Query),
            ExistsExpression exists => QueryContainsSchemaQualification(exists.Query),
            InSubqueryExpression inSubquery => QueryContainsSchemaQualification(inSubquery.Query)
                || ExpressionContainsSchemaQualification(inSubquery.Value),
            FunctionExpression function => function.Arguments.Any(ExpressionContainsSchemaQualification)
                || ExpressionContainsSchemaQualification(function.Filter)
                || WindowContainsSchemaQualification(function.Window),
            RowValueExpression rowValue => rowValue.Values.Any(ExpressionContainsSchemaQualification),
            CollationExpression collation => ExpressionContainsSchemaQualification(collation.Expression),
            CastExpression cast => ExpressionContainsSchemaQualification(cast.Expression),
            CaseExpression @case => ExpressionContainsSchemaQualification(@case.Operand)
                || @case.Clauses.Any(clause => ExpressionContainsSchemaQualification(clause.When)
                    || ExpressionContainsSchemaQualification(clause.Then))
                || ExpressionContainsSchemaQualification(@case.Else),
            LikeExpression like => ExpressionContainsSchemaQualification(like.Value)
                || ExpressionContainsSchemaQualification(like.Pattern)
                || ExpressionContainsSchemaQualification(like.Escape),
            InExpression @in => ExpressionContainsSchemaQualification(@in.Value)
                || @in.Values.Any(ExpressionContainsSchemaQualification),
            BetweenExpression between => ExpressionContainsSchemaQualification(between.Value)
                || ExpressionContainsSchemaQualification(between.Lower)
                || ExpressionContainsSchemaQualification(between.Upper),
            UnaryExpression unary => ExpressionContainsSchemaQualification(unary.Operand),
            GlobExpression glob => ExpressionContainsSchemaQualification(glob.Value)
                || ExpressionContainsSchemaQualification(glob.Pattern),
            BinaryExpression binary => ExpressionContainsSchemaQualification(binary.Left)
                || ExpressionContainsSchemaQualification(binary.Right),
            _ => false,
        };
    }

    private static bool WindowContainsSchemaQualification(WindowSpecification? window)
    {
        if (window is null)
            return false;

        return window.PartitionBy.Any(ExpressionContainsSchemaQualification)
            || window.OrderBy.Any(orderBy => ExpressionContainsSchemaQualification(orderBy.Expression))
            || ExpressionContainsSchemaQualification(window.Frame?.Start.Offset)
            || ExpressionContainsSchemaQualification(window.Frame?.End.Offset);
    }

    private (string Path, bool ReadOnly) ResolveAttachmentPath(string requestedPath)
    {
        if (!requestedPath.StartsWith("file:", StringComparison.OrdinalIgnoreCase))
            return (requestedPath, false);

        var queryStart = requestedPath.IndexOf('?', StringComparison.Ordinal);
        var escapedPath = queryStart < 0 ? requestedPath[5..] : requestedPath[5..queryStart];
        string path;
        try
        {
            if (escapedPath.StartsWith("//", StringComparison.Ordinal)
                && Uri.TryCreate(requestedPath, UriKind.Absolute, out var absoluteUri)
                && absoluteUri.IsFile)
            {
                path = absoluteUri.LocalPath;
            }
            else
            {
                path = Uri.UnescapeDataString(escapedPath);
            }
        }
        catch (UriFormatException exception)
        {
            throw new EmbeddedSqlException($"Invalid managed ATTACH URI path '{requestedPath}'.", exception);
        }

        var mode = "rwc";
        var query = queryStart < 0 ? string.Empty : requestedPath[(queryStart + 1)..];
        foreach (var part in query.Split('&', StringSplitOptions.RemoveEmptyEntries))
        {
            var pieces = part.Split('=', 2);
            var name = Uri.UnescapeDataString(pieces[0]);
            // Turso OpenOptions::parse recognizes mode/modeof/cache/immutable/vfs/cipher/hexkey
            // and ignores unknown keys. Managed ATTACH applies mode; other known options are
            // accepted as no-ops so Turso-compatible URIs attach cleanly.
            if (name.Equals("mode", StringComparison.OrdinalIgnoreCase))
            {
                mode = pieces.Length == 2 ? Uri.UnescapeDataString(pieces[1]) : string.Empty;
                continue;
            }

            if (name.Equals("modeof", StringComparison.OrdinalIgnoreCase)
                || name.Equals("cache", StringComparison.OrdinalIgnoreCase)
                || name.Equals("immutable", StringComparison.OrdinalIgnoreCase)
                || name.Equals("vfs", StringComparison.OrdinalIgnoreCase)
                || name.Equals("cipher", StringComparison.OrdinalIgnoreCase)
                || name.Equals("hexkey", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            // Unknown options ignored (Turso `_ => {}`).
        }

        var readOnly = mode.Equals("ro", StringComparison.OrdinalIgnoreCase);
        var requireExisting = readOnly || mode.Equals("rw", StringComparison.OrdinalIgnoreCase);
        if (!readOnly
            && !mode.Equals("rw", StringComparison.OrdinalIgnoreCase)
            && !mode.Equals("rwc", StringComparison.OrdinalIgnoreCase))
        {
            throw new EmbeddedSqlException($"Managed ATTACH URI has unsupported access mode '{mode}'.");
        }
        if (requireExisting && (!_database.FileSystem.FileExists(path) || !_database.FileSystem.FileExists(path + "-wal")))
            throw new EmbeddedSqlException($"unable to open database file: {path}");

        return (path, readOnly);
    }

    private static string GetAttachmentPathIdentity(string path)
    {
        try
        {
            return Path.GetFullPath(path);
        }
        catch (Exception exception) when (exception is ArgumentException or NotSupportedException)
        {
            throw new EmbeddedSqlException($"Invalid managed ATTACH file path '{path}'.", exception);
        }
    }

    private StringComparer GetAttachmentPathComparer()
    {
        var fileSystem = AhtolaEncryptionFileSystem.Unwrap(_database.FileSystem);
        return fileSystem is PhysicalFileSystem
            ? EmbeddedDatabase.PhysicalPathComparer
            : StringComparer.Ordinal;
    }

    private void EnsureAutocommitAttachmentLifecycle()
    {
        if (_transactionDatabases is not null)
            throw new EmbeddedSqlException("Managed ATTACH and DETACH are not supported inside a transaction.");
    }

    private TransactionDatabaseState? GetTransactionState(EmbeddedDatabase database)
    {
        if (_transactionDatabases is null)
            return null;
        if (!_transactionDatabases.TryGetValue(database, out var state))
            throw new InvalidOperationException("The managed transaction does not own the routed database.");

        return state;
    }

    private bool StatementMayMutate(EmbeddedDatabase database, ParsedStatement statement)
    {
        var catalog = _transactionDatabases is not null
            && _transactionDatabases.TryGetValue(database, out var transactionState)
                ? transactionState.Catalog
                : database.LiveCatalog;
        return EmbeddedDatabase.MayMutate(statement, catalog.Views);
    }

    internal bool StatementMayMutate(ParsedStatement statement)
        => StatementMayMutate(_database, statement)
            || StatementMayMutate(_tempDatabase, statement);

    private void BeginTransaction(bool openedBySavepoint, TransactionMode mode)
    {
        // A peer connection may have enabled MVCC after this connection opened.
        // Every transaction mode must attach before deciding whether it needs an
        // MvStore reader or exclusive-writer registration.
        _database.EnsureMvccAttachedIfDurable();
        if (mode == TransactionMode.Concurrent)
        {
            if (!_database.IsMvccEnabled)
            {
                throw new EmbeddedSqlException(
                    "Concurrent transaction mode is only supported when MVCC is enabled");
            }

            _database.EnsureMvccLogVersion4(GetSynchronousMode(_database));
        }

        var databases = _attachedDatabases.Values
            .OrderBy(attachment => attachment.PathIdentity, StringComparer.OrdinalIgnoreCase)
            .Select(attachment => attachment.Database)
            .Prepend(_tempDatabase)
            .Prepend(_database)
            .ToArray();

        var concurrent = mode == TransactionMode.Concurrent;
        // CONCURRENT does not take the classic write reservation (Turso multi-writer).
        // IMMEDIATE/EXCLUSIVE still do — including when MVCC is enabled (exclusive MVCC tx).
        if (mode is TransactionMode.Immediate or TransactionMode.Exclusive)
            AcquireTransactionWriteReservations(databases, mode);

        var states = new Dictionary<EmbeddedDatabase, TransactionDatabaseState>();
        var mvccTxs = new Dictionary<EmbeddedDatabase, MvccTxId>();
        try
        {
            foreach (var database in databases)
            {
                if (mode == TransactionMode.Deferred || concurrent)
                    database.TransactionLock.ThrowIfReadBlocked(this, BusyTimeout);

                // Register the MVCC reader before cloning the catalog. This closes
                // the begin/schema-publish race: once the transaction is visible
                // to MvStore, DDL cannot publish a new generation underneath the
                // catalog snapshot being captured here.
                if (concurrent
                    && ReferenceEquals(database, _database)
                    && database.MvStore is not null)
                {
                    var concurrentSnapshot = database.BeginConcurrentTransactionSnapshot(
                        BusyTimeout,
                        AfterMvccBeginBeforeCatalogSnapshotForTesting);
                    mvccTxs.Add(database, concurrentSnapshot.TransactionId);
                    try
                    {
                        states.Add(database, new TransactionDatabaseState(
                            concurrentSnapshot.Snapshot.Catalog,
                            concurrentSnapshot.Snapshot.Version,
                            concurrentSnapshot.Snapshot.PragmaHeader)
                        {
                            // MVCC-eligible index joins/scans read through this pinned durable
                            // snapshot merged lazily with visible MvStore effects instead of
                            // materializing the base index; Overlay stays null for a concurrent
                            // transaction (that gate is exclusively for the classic path).
                            PinnedSnapshot = concurrentSnapshot.PinnedSnapshot,
                        });
                    }
                    catch (Exception primaryFailure)
                    {
                        mvccTxs.Remove(database);
                        // Both cleanup steps must be attempted even if the first throws: a
                        // failing MVCC rollback must never skip EndTransaction and leak this
                        // database's active-transaction count registration.
                        List<Exception>? cleanupFailures = null;
                        try
                        {
                            concurrentSnapshot.PinnedSnapshot?.Dispose();
                        }
                        catch (Exception exception)
                        {
                            (cleanupFailures ??= []).Add(exception);
                        }

                        try
                        {
                            database.MvStore?.Rollback(concurrentSnapshot.TransactionId);
                        }
                        catch (Exception exception)
                        {
                            (cleanupFailures ??= []).Add(exception);
                        }

                        try
                        {
                            database.EndTransaction();
                        }
                        catch (Exception exception)
                        {
                            (cleanupFailures ??= []).Add(exception);
                        }

                        if (cleanupFailures is null)
                            throw;

                        throw new AggregateException([primaryFailure, .. cleanupFailures]);
                    }
                    continue;
                }
                else if (!concurrent
                    && database.MvStore is { } exclusiveStore
                    && mode is TransactionMode.Immediate or TransactionMode.Exclusive)
                {
                    var tx = exclusiveStore.BeginExclusiveTransaction();
                    mvccTxs.Add(database, tx.Id);
                }

                var (snapshot, pinnedSnapshot) = database.CreateTransactionSnapshotWithPin(busyTimeout: BusyTimeout);
                try
                {
                    states.Add(database, new TransactionDatabaseState(
                        snapshot.Catalog,
                        snapshot.Version,
                        snapshot.PragmaHeader)
                    {
                        PinnedSnapshot = pinnedSnapshot,
                        Overlay = pinnedSnapshot is not null ? new TransactionMutationOverlay() : null,
                    });
                }
                catch (Exception primaryFailure)
                {
                    // CreateTransactionSnapshotWithPin already registered this database as an
                    // active transaction and cloned its catalog before returning; if adding the
                    // resulting state fails, this database is never recorded in states, so the
                    // outer catch below (which only walks states.Values/Keys) would otherwise
                    // never see it and would leak the pinned snapshot and the active-transaction
                    // count for it. Every cleanup step below must be attempted even if an earlier
                    // one throws — in particular EndTransaction must always run, so a failing
                    // virtual-table disconnect can never leak the active-transaction count this
                    // method already bumped — so failures are collected and combined with the
                    // original failure rather than one throw short-circuiting the rest.
                    List<Exception>? cleanupFailures = null;
                    try
                    {
                        pinnedSnapshot?.Dispose();
                    }
                    catch (Exception exception)
                    {
                        (cleanupFailures ??= []).Add(exception);
                    }

                    try
                    {
                        snapshot.Catalog.DisconnectOwnedVirtualTables();
                    }
                    catch (Exception exception)
                    {
                        (cleanupFailures ??= []).Add(exception);
                    }

                    try
                    {
                        database.EndTransaction();
                    }
                    catch (Exception exception)
                    {
                        (cleanupFailures ??= []).Add(exception);
                    }

                    if (cleanupFailures is null)
                        throw;

                    throw new AggregateException([primaryFailure, .. cleanupFailures]);
                }
            }
        }
        catch (Exception primaryFailure)
        {
            // Every step below must be attempted for every database/state even if an earlier
            // one throws: a failing disconnect/dispose for one database must never skip
            // EndTransaction (leaking its active-transaction count) or
            // ReleaseTransactionWriteReservations (leaking a write reservation) for the rest.
            List<Exception>? cleanupFailures = null;
            foreach (var (database, txId) in mvccTxs)
            {
                try
                {
                    database.MvStore?.Rollback(txId);
                }
                catch (Exception exception)
                {
                    (cleanupFailures ??= []).Add(exception);
                }
            }

            foreach (var state in states.Values)
            {
                try
                {
                    state.Catalog.DisconnectOwnedVirtualTables();
                }
                catch (Exception exception)
                {
                    (cleanupFailures ??= []).Add(exception);
                }

                try
                {
                    state.PinnedSnapshot?.Dispose();
                }
                catch (Exception exception)
                {
                    (cleanupFailures ??= []).Add(exception);
                }
            }

            foreach (var database in states.Keys)
            {
                try
                {
                    database.EndTransaction();
                }
                catch (Exception exception)
                {
                    (cleanupFailures ??= []).Add(exception);
                }
            }

            try
            {
                ReleaseTransactionWriteReservations();
            }
            catch (Exception exception)
            {
                (cleanupFailures ??= []).Add(exception);
            }

            if (cleanupFailures is null)
                throw;

            throw new AggregateException([primaryFailure, .. cleanupFailures]);
        }

        _transactionDatabases = states;
        _transactionWriteDatabase = null;
        _transactionMutationDatabase = null;
        _transactionOpenedBySavepoint = openedBySavepoint;
        _transactionIsConcurrent = concurrent;
        _mvccTransactions.Clear();
        foreach (var pair in mvccTxs)
            _mvccTransactions[pair.Key] = pair.Value;
        _savepoints.Clear();
        _changeDataCapture?.StartTransaction();
    }

    /// <summary>
    /// Takes the eager write reservation for an IMMEDIATE or EXCLUSIVE transaction
    /// on every database it covers, releasing everything already taken when one
    /// database is busy so a failed BEGIN leaves no lock behind.
    /// </summary>
    private void AcquireTransactionWriteReservations(
        IReadOnlyList<EmbeddedDatabase> databases,
        TransactionMode mode)
    {
        try
        {
            foreach (var database in databases)
            {
                if (database.IsReadOnly)
                    continue;

                var excludeReaders = mode == TransactionMode.Exclusive
                                     && database.ExclusiveTransactionsExcludeReaders;
                database.TransactionLock.Enter(this, excludeReaders, BusyTimeout);
                _writeReservations.Add(database);
            }
        }
        catch
        {
            ReleaseTransactionWriteReservations();
            throw;
        }
    }

    /// <summary>
    /// Takes the write reservation a DEFERRED transaction defers until its first
    /// write, which is where SQLite reports busy for that mode.
    /// </summary>
    private void AcquireDeferredWriteReservation(EmbeddedDatabase database)
    {
        if (database.TransactionLock.IsHeldBy(this))
            return;

        database.TransactionLock.Enter(this, excludeReaders: false, BusyTimeout);
        _writeReservations.Add(database);
    }

    private void ReleaseTransactionWriteReservations()
    {
        for (var index = _writeReservations.Count - 1; index >= 0; index--)
            _writeReservations[index].TransactionLock.Exit(this);
        _writeReservations.Clear();
        foreach (var admission in _classicMvccWriteAdmissions.Values)
            admission.Dispose();
        _classicMvccWriteAdmissions.Clear();
    }

    private void EnsureTransactionMayMutate(EmbeddedDatabase database, ParsedStatement statement)
    {
        if (!StatementMayMutate(database, statement))
            return;
        if (database.IsReadOnly)
            throw new EmbeddedSqlException("attempt to write a readonly database");
        if (_transactionMutationDatabase is not null)
        {
            throw new EmbeddedSqlException(
                "Managed connections do not support reentrant writes from SQL callbacks.");
        }

        // BEGIN CONCURRENT currently scopes multi-writer MVCC to main only; attached
        // and temp mutations would otherwise land as classic catalog edits without a
        // matching version-store tx (bounded Ahtola scope until attach+MVCC inherits).
        if (_transactionIsConcurrent && !ReferenceEquals(database, _database))
        {
            throw new EmbeddedSqlException(
                "Concurrent transaction mode only supports mutations on the main database");
        }

        if (ReferenceEquals(database, _tempDatabase))
            return;
        if (_transactionWriteDatabase is null
            || ReferenceEquals(_transactionWriteDatabase, database))
        {
            return;
        }

        throw new EmbeddedSqlException(
            "Managed ATTACH transactions cannot modify more than one database because independent WAL files cannot be committed atomically.");
    }

    private bool ReserveTransactionMutation(EmbeddedDatabase database, ParsedStatement statement)
    {
        EnsureTransactionMayMutate(database, statement);
        if (!StatementMayMutate(database, statement))
            return false;

        MvStore? classicStore = null;
        if (!ReferenceEquals(database, _tempDatabase)
            && !_mvccTransactions.ContainsKey(database))
        {
            database.EnsureMvccAttachedIfDurable();
            if (database.MvStore is { } store
                && (_transactionDatabases is null
                    || !_classicMvccWriteAdmissions.ContainsKey(database)))
            {
                classicStore = store;
            }
        }

        if (_transactionDatabases is null)
        {
            // An autocommit write takes the write reservation for the whole
            // statement, exactly like SQLite's implicit write transaction:
            // contenders then block through the current writer's statement
            // burst and evaluate against the committed state it leaves behind,
            // instead of slipping into the gap between a peer's commit and its
            // next autocommit statement (ENGINE #17 EF migrations-lock convoy).
            // The catalog was refreshed at statement entry, before this
            // reservation was taken, so re-sync it now that the lock is held:
            // the statement must decide against the committed state it
            // serializes with, the way native reads the btree under the write
            // lock.
            database.TransactionLock.EnterAutocommit(this, BusyTimeout);
            try
            {
                database.RefreshOwnedCatalogForStatementIfNeeded();
                _autocommitMvccWriteAdmission =
                    classicStore?.EnterClassicWrite(BusyTimeout);
            }
            catch
            {
                database.TransactionLock.Exit(this);
                throw;
            }

            _autocommitWriteReservation = database;
            _transactionMutationDatabase = database;
            return true;
        }

        var alreadyHeldWriteReservation = database.TransactionLock.IsHeldBy(this);
        ReserveWriteAccess(database);
        try
        {
            if (classicStore is not null)
            {
                var admission = classicStore.EnterClassicWrite(BusyTimeout);
                try
                {
                    _classicMvccWriteAdmissions.Add(database, admission);
                }
                catch
                {
                    admission.Dispose();
                    throw;
                }
            }
        }
        catch
        {
            if (!alreadyHeldWriteReservation
                && database.TransactionLock.IsHeldBy(this))
            {
                _writeReservations.Remove(database);
                database.TransactionLock.Exit(this);
            }
            throw;
        }

        _transactionMutationDatabase = database;
        return true;
    }

    /// <summary>
    /// Applies the transaction-mode locking rules to a write against
    /// <paramref name="database"/>, whether it runs inside a transaction or in
    /// autocommit.
    /// </summary>
    private void ReserveWriteAccess(EmbeddedDatabase database)
    {
        if (_transactionDatabases is not null)
        {
            // BEGIN CONCURRENT uses the MVCC store for multi-writer isolation and
            // must not take the classic single-writer reservation.
            if (_transactionIsConcurrent)
                return;

            // A DEFERRED transaction takes its write reservation here, at the first
            // write, exactly where SQLite escalates to RESERVED. IMMEDIATE and
            // EXCLUSIVE already hold it, so this is a no-op for them.
            AcquireDeferredWriteReservation(database);
        }
        else
        {
            // An autocommit write is serialized with other autocommit writes by the
            // owning database, so it takes no reservation of its own; it only has to
            // lose to a connection that is holding one across a transaction.
            database.TransactionLock.ThrowIfWriteBlocked(this, BusyTimeout);
        }
    }

    private ExecutionResult ExecuteWithMutationReservation(
        EmbeddedDatabase database,
        Func<ExecutionResult> operation)
    {
        if (_transactionMutationDatabase is not null)
        {
            throw new EmbeddedSqlException(
                "Managed connections do not support reentrant writes from SQL callbacks.");
        }

        _transactionMutationDatabase = database;
        try
        {
            return operation();
        }
        finally
        {
            ReleaseTransactionMutation(database);
        }
    }

    private void ReleaseTransactionMutation(EmbeddedDatabase database)
    {
        if (!ReferenceEquals(_transactionMutationDatabase, database))
            throw new InvalidOperationException("The managed transaction mutation reservation was lost.");

        _transactionMutationDatabase = null;
        if (ReferenceEquals(_autocommitWriteReservation, database))
        {
            _autocommitWriteReservation = null;
            try
            {
                database.TransactionLock.Exit(this);
            }
            finally
            {
                var admission = _autocommitMvccWriteAdmission;
                _autocommitMvccWriteAdmission = null;
                admission?.Dispose();
            }
        }
    }

    /// <summary>
    /// Historical hook retained for call-site compatibility. Concurrent INSERT/DELETE/UPDATE
    /// now mirror into the version store per-row via
    /// <see cref="EmbeddedDatabase.QueryContext.ReportRowChange"/> (covers multi-row and
    /// trigger-body inserts without double-recording).
    /// </summary>
    private void RecordConcurrentMvccMutation(
        EmbeddedDatabase database,
        ParsedStatement statement,
        EmbeddedDatabase.SchemaCatalog catalog,
        ExecutionResult result)
    {
        _ = database;
        _ = statement;
        _ = catalog;
        _ = result;
    }

    private bool TryGetConcurrentMvccScope(
        EmbeddedDatabase database,
        out MvStore? store,
        out MvccTxId? txId)
    {
        store = null;
        txId = null;
        if (!_transactionIsConcurrent
            || !_mvccTransactions.TryGetValue(database, out var id)
            || database.MvStore is not { } mvStore)
        {
            return false;
        }

        store = mvStore;
        txId = id;
        return true;
    }

    private void BeginConcurrentSchemaChange()
    {
        if (!_transactionIsConcurrent
            || !_mvccTransactions.TryGetValue(_database, out var txId)
            || _database.MvStore is not { } store)
        {
            throw new EmbeddedSqlException(
                "Concurrent schema changes require an active main-database MVCC transaction.");
        }

        if (store.HasSchemaChange(txId))
            return;

        store.BeginSchemaChange(txId, BusyTimeout);
        try
        {
            // The durable pager read snapshot pinned at BEGIN CONCURRENT (see
            // BeginConcurrentTransactionSnapshotLocked) holds an open pager read
            // transaction on this very connection. A schema-changing transaction's
            // frozen snapshot predates the schema generation it is about to publish,
            // so a page-native index join/scan has nothing useful left to read from
            // it anyway once DDL starts. Release it before the TRUNCATE checkpoint
            // below so this transaction's own reader can never be mistaken for a
            // foreign one blocking its own schema-change checkpoint — TRUNCATE
            // requires zero active pager readers, and before this snapshot existed
            // an MVCC transaction never held one, so this call always used to see
            // zero readers from itself. Falling back to the non-page-native merge
            // path for the remainder of this (already schema-changing) transaction
            // is the correct, conservative behavior here.
            if (_transactionDatabases is not null
                && _transactionDatabases.TryGetValue(_database, out var schemaOwnerState))
            {
                schemaOwnerState.PinnedSnapshot?.Dispose();
                schemaOwnerState.PinnedSnapshot = null;
            }

            // Retire every older logical frame before the private catalog can
            // diverge. The owner transaction is admitted only as a frozen
            // snapshot; its uncommitted versions are excluded from collection.
            var checkpoint = _database.RunMvccCheckpoint(
                "TRUNCATE",
                BusyTimeout,
                GetSynchronousMode(_database),
                permittedTransaction: txId);
            if (checkpoint.Busy)
                throw new EmbeddedBusyException();
        }
        catch
        {
            store.CancelSchemaChange(txId);
            throw;
        }
    }

    private string BeginConcurrentStatementSavepoint(MvStore store, MvccTxId txId)
    {
        var name = "\u0001ahtola-mvcc-statement-" + checked(++_nextMvccStatementSavepoint);
        store.BeginNamedSavepoint(txId, name);
        return name;
    }

    private static void ReleaseConcurrentStatementSavepoint(
        MvStore? store,
        MvccTxId? txId,
        string? name)
    {
        if (store is not null && txId is { } id && name is not null)
            store.ReleaseNamedSavepoint(id, name);
    }

    private static void RollbackConcurrentStatementSavepoint(
        MvStore? store,
        MvccTxId? txId,
        string? name)
    {
        if (store is not null && txId is { } id && name is not null)
            store.RollbackToNamedSavepoint(id, name);
    }

    private void CommitTransaction()
    {
        if (_transactionDatabases is null)
            throw new InvalidOperationException("No managed transaction is active.");

        ValidateDeferredForeignKeys();
        if (_changeDataCapture is { } changeDataCapture
            && _transactionDatabases.TryGetValue(_database, out var cdcState))
        {
            TryGetConcurrentMvccScope(_database, out var cdcStore, out var cdcTxId);
            if (changeDataCapture.CompleteExplicitTransaction(cdcState.Catalog.Tables, cdcStore, cdcTxId))
            {
                cdcState.HasChanges = true;
                // Appending a CDC record is never a targeted index rebuild: an earlier
                // REINDEX in this same transaction must not cause commit to skip
                // persisting it.
                cdcState.HasNonTargetedIndexRebuildChange = true;
                _transactionWriteDatabase = _database;
            }
        }
        var changed = _transactionDatabases
            .Where(pair => pair.Value.HasChanges)
            .ToArray();

        foreach (var state in _transactionDatabases.Values)
            state.VirtualTableTransaction.Sync(state.Catalog);

        // SQLite only consults the commit hook when the transaction actually has something to
        // commit, and a veto turns the commit into a rollback.
        if (changed.Length != 0 && _hooks.CommitHook is { } commitHook && !InvokeHook(commitHook))
        {
            ResetTransactionState();
            FireRollbackHook();
            throw new EmbeddedCommitVetoException();
        }

        // Ordinary MVCC commits publish the logical frame first. Schema-changing
        // transactions instead stop at Preparing: their complete private catalog
        // must land through the pager before the new generation becomes visible.
        var preparedSchemaCommits = new List<(EmbeddedDatabase Database, MvccTxId TxId)>();
        var mvccWriteWasPublished = false;
        try
        {
            foreach (var (database, txId) in _mvccTransactions.ToArray())
            {
                if (database.MvStore is { } store)
                {
                    if (store.HasSchemaChange(txId))
                    {
                        var publish = _transactionDatabases.TryGetValue(database, out var state)
                            && state.HasSchemaChanges;
                        if (publish)
                        {
                            store.PrepareSchemaCommit(txId);
                            preparedSchemaCommits.Add((database, txId));
                            continue;
                        }

                        store.CancelSchemaChange(txId);
                    }
                    var hasPendingWrites = store.HasPendingWrites(txId);
                    store.Commit(txId, GetSynchronousMode(database));
                    mvccWriteWasPublished |= hasPendingWrites;
                }
                _mvccTransactions.Remove(database);
            }
        }
        catch (MvccLogicalLogCommitIndeterminateException)
        {
            ResetTransactionState();
            throw;
        }

        var persistentChanges = changed
            .Where(pair => !ReferenceEquals(pair.Key, _tempDatabase))
            .ToArray();
        if (persistentChanges.Length > 1)
            throw new InvalidOperationException("A managed ATTACH transaction reached an unsafe multi-database write state.");

        var tempChange = changed
            .Where(pair => ReferenceEquals(pair.Key, _tempDatabase))
            .Select(pair => pair.Value)
            .SingleOrDefault();

        // Release every pinned snapshot before the durable WAL commit below: post-commit
        // checkpoint maintenance requires that this connection hold no outstanding pager reader
        // of its own, and by this point deferred FK validation and the commit hook have already
        // run any query that might have needed the transaction's own read-your-writes overlay.
        foreach (var pinnedState in _transactionDatabases.Values)
        {
            pinnedState.PinnedSnapshot?.Dispose();
            pinnedState.PinnedSnapshot = null;
        }

        ExceptionDispatchInfo? deferredMaintenanceFailure = null;
        var schemaCatalogWasPublished = false;
        try
        {
            if (persistentChanges.Length == 1)
            {
                var (database, state) = persistentChanges[0];
                try
                {
                    database.CommitTransaction(
                        state.Catalog,
                        state.Version,
                        database.IsFileBacked && !state.HasSnapshotPragmaHeader && !state.HasSchemaChanges
                            ? null
                            : state.PragmaHeader,
                        state.ForceFullCatalogRewrite,
                        busyTimeout: BusyTimeout,
                        concurrent: _transactionIsConcurrent,
                        containsSchemaChanges: state.HasSchemaChanges,
                        synchronousMode: GetSynchronousMode(database),
                        // A targeted, in-place index rebuild never rewrites table row storage, so
                        // it must never be attempted as the sole persistence path when anything
                        // else in this transaction also changed durable state -- see
                        // HasNonTargetedIndexRebuildChange. Passing null here (rather than an
                        // empty set) makes EmbeddedFileStore.PersistCore skip the targeted attempt
                        // entirely and fall through to the full-catalog rewrite that
                        // ForceFullCatalogRewrite already forces for any REINDEX, so every
                        // coexisting change is persisted atomically alongside the rebuilt index.
                        targetedIndexRebuildNames: state.HasNonTargetedIndexRebuildChange
                            ? null
                            : state.TargetedIndexRebuildNames);
                }
                catch (EmbeddedPostCommitMaintenanceException failure)
                {
                    // The pager commit is durable even though post-commit cleanup
                    // failed. Publish the in-memory schema generation before the
                    // maintenance error is surfaced.
                    deferredMaintenanceFailure = ExceptionDispatchInfo.Capture(failure);
                }
                schemaCatalogWasPublished = state.HasSchemaChanges;
            }

            foreach (var (database, txId) in preparedSchemaCommits)
            {
                database.MvStore?.CompleteSchemaCommit(txId);
                _mvccTransactions.Remove(database);
            }
        }
        catch (MvccLogicalLogCommitIndeterminateException)
        {
            ResetTransactionState();
            throw;
        }
        catch (Exception failure)
        {
            if (!mvccWriteWasPublished && !schemaCatalogWasPublished)
            {
                if (preparedSchemaCommits.Count != 0)
                    ResetTransactionState();
                throw;
            }
            ResetTransactionState();
            throw new EmbeddedPostCommitMaintenanceException(failure);
        }

        CommitTemporaryTransaction(tempChange);
        try
        {
            foreach (var state in _transactionDatabases.Values)
                state.VirtualTableTransaction.Commit(state.Catalog);
        }
        finally
        {
            ResetTransactionState(rollbackVirtualTables: false);
        }
        deferredMaintenanceFailure?.Throw();
    }

    private void CommitTemporaryTransaction(TransactionDatabaseState? tempChange)
    {
        if (tempChange is null)
            return;

        _tempDatabase.CommitTransaction(
            tempChange.Catalog,
            tempChange.Version,
            tempChange.PragmaHeader);
    }

    // Runs an eligible top-level VALUES statement through its prepared, cached lowering. The lowering is
    // owned and cached by the calling EmbeddedStatement; this method only re-checks connection liveness so
    // a disposed connection throws exactly as the general Execute path does. A VALUES row list references
    // no tables, so it is independent of the transaction catalog, query-only guard, and last-insert-rowid
    // bookkeeping the general path threads -- nothing here needs them.
    internal ExecutionResult ExecutePreparedValues(
        EmbeddedDatabase.PreparedValuesLowering lowering,
        SqlValue[] parameters)
    {
        ThrowIfDisposed();
        return EmbeddedDatabase.ExecutePreparedValues(lowering, parameters);
    }

    private ExecutionResult ExecutePragmaQueryOnly(PragmaQueryOnlyStatement statement)
    {
        ValidatePragmaSchema(statement.Schema);
        if (statement.Enabled is { } enabled)
        {
            _queryOnly = enabled;
            return ExecutionResult.Empty;
        }

        return new ExecutionResult(["query_only"], [[SqlValue.Integer(_queryOnly ? 1 : 0)]], 0);
    }

    private ExecutionResult ExecutePragmaForeignKeys(PragmaForeignKeysStatement statement)
    {
        ValidatePragmaSchema(statement.Schema);
        // SQLite leaves this connection setting unchanged while a transaction or savepoint
        // is active; it is neither transactional nor shared with sibling connections.
        if (statement.Enabled is { } enabled && _transactionDatabases is null)
            _foreignKeys = enabled;

        return statement.Enabled is null
            ? new ExecutionResult(["foreign_keys"], [[SqlValue.Integer(_foreignKeys ? 1 : 0)]], 0)
            : ExecutionResult.Empty;
    }

    private ExecutionResult ExecutePragmaDeferForeignKeys(PragmaDeferForeignKeysStatement statement)
    {
        ValidatePragmaSchema(statement.Schema);
        if (statement.Enabled is { } enabled)
        {
            _deferForeignKeys = enabled;
            if (!enabled && _transactionDatabases is not null)
            {
                foreach (var state in _transactionDatabases.Values)
                    state.PendingDeferredViolations.Clear();
            }
            return ExecutionResult.Empty;
        }

        return new ExecutionResult(
            ["defer_foreign_keys"],
            [[SqlValue.Integer(_deferForeignKeys ? 1 : 0)]],
            0);
    }

    private void ValidateDeferredForeignKeys()
    {
        if (!_foreignKeys || _transactionDatabases is null)
            return;

        foreach (var (database, state) in _transactionDatabases)
        {
            if (state.PendingDeferredViolations.Count == 0)
                continue;

            var current = database.CollectForeignKeyViolations(
                state.Catalog.Tables,
                includeImmediate: _deferForeignKeys);
            if (state.PendingDeferredViolations.Any(current.Contains))
                throw new EmbeddedSqlException("FOREIGN KEY constraint failed");
        }
    }

    private ExecutionResult ExecutePragmaRecursiveTriggers(PragmaRecursiveTriggersStatement statement)
    {
        ValidatePragmaSchema(statement.Schema);
        if (statement.Enabled is { } enabled)
        {
            _recursiveTriggers = enabled;
            return ExecutionResult.Empty;
        }

        return new ExecutionResult(
            ["recursive_triggers"],
            [[SqlValue.Integer(_recursiveTriggers ? 1 : 0)]],
