    }

    private ExecutionResult ExecutePragmaHeaderInteger(
        PragmaHeaderIntegerStatement statement,
        CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        var columnName = statement.Kind switch
        {
            PragmaHeaderIntegerKind.SchemaVersion => "schema_version",
            PragmaHeaderIntegerKind.UserVersion => "user_version",
            PragmaHeaderIntegerKind.ApplicationId => "application_id",
            _ => throw new InvalidOperationException($"Unknown PRAGMA header integer kind {statement.Kind}."),
        };

        var database = ResolvePragmaDatabase(statement.Schema);
        var transactionState = GetTransactionState(database);
        if (statement.Value is null)
        {
            var metadata = transactionState?.PragmaHeader ?? database.GetPragmaHeaderMetadata();
            var value = statement.Kind switch
            {
                PragmaHeaderIntegerKind.SchemaVersion => metadata.SchemaVersion,
                PragmaHeaderIntegerKind.UserVersion => metadata.UserVersion,
                PragmaHeaderIntegerKind.ApplicationId => metadata.ApplicationId,
                _ => throw new InvalidOperationException($"Unknown PRAGMA header integer kind {statement.Kind}."),
            };
            return new ExecutionResult([columnName], [[SqlValue.Integer(value)]], 0);
        }

        if (_queryOnly)
            throw new EmbeddedSqlException("attempt to write a readonly database");
        if (database.IsReadOnly)
            throw new EmbeddedSqlException("attempt to write a readonly database");

        if (_transactionDatabases is null)
        {
            database.SetPragmaHeaderInteger(
                statement.Kind,
                statement.Value.Value,
                busyTimeout: BusyTimeout,
                cancellationToken: cancellationToken,
                synchronousMode: GetSynchronousMode(database));
            if (ReferenceEquals(database, _tempDatabase))
                _tempInitialized = true;
            return ExecutionResult.Empty;
        }

        var current = transactionState?.PragmaHeader
            ?? throw new InvalidOperationException("The managed transaction lost its PRAGMA target state.");
        var updated = statement.Kind switch
        {
            PragmaHeaderIntegerKind.SchemaVersion => current with { SchemaVersion = statement.Value.Value },
            PragmaHeaderIntegerKind.UserVersion => current with { UserVersion = statement.Value.Value },
            PragmaHeaderIntegerKind.ApplicationId => current with { ApplicationId = statement.Value.Value },
            _ => throw new InvalidOperationException($"Unknown PRAGMA header integer kind {statement.Kind}."),
        };

        if (updated != current)
        {
            cancellationToken.ThrowIfCancellationRequested();
            EnsureTransactionMayMutate(database, statement);
            transactionState.PragmaHeader = updated;
            transactionState.HasChanges = true;
            // A pragma header write is never a targeted index rebuild: an earlier REINDEX in
            // this same transaction must not cause commit to skip persisting this header change.
            transactionState.HasNonTargetedIndexRebuildChange = true;
            transactionState.HasSnapshotPragmaHeader = true;
            if (!ReferenceEquals(database, _tempDatabase))
                _transactionWriteDatabase = database;
        }
        if (ReferenceEquals(database, _tempDatabase))
            _tempInitialized = true;

        return ExecutionResult.Empty;
    }

    private ExecutionResult ExecutePragmaJournalMode(PragmaJournalModeStatement statement)
    {
        var database = ResolvePragmaDatabase(statement.Schema);
        var isTempDatabase = ReferenceEquals(database, _tempDatabase);
        var current = DescribeJournalMode(database, isTempDatabase);
        if (statement.Mode is null)
            return new ExecutionResult(["journal_mode"], [[SqlValue.Text(current)]], 0);

        // Turso's JournalMode opcode keeps non-main databases in their existing mode.
        // The connection-local temp catalog has no managed pager, but SQL observes its
        // WAL-compatible mode rather than that implementation detail. temp.journal_mode=mvcc
        // is ignored (still reports wal) — see temp_tables_mvcc.sqltest.
        if (isTempDatabase)
            return new ExecutionResult(["journal_mode"], [[SqlValue.Text(current)]], 0);

        if (!TryParseJournalMode(statement.Mode, out var requested))
            return new ExecutionResult(["journal_mode"], [[SqlValue.Text(current)]], 0);
        if (requested == database.GetJournalMode()
            || (requested == SqliteJournalMode.Mvcc && database.IsMvccEnabled))
        {
            return new ExecutionResult(
                ["journal_mode"],
                [[SqlValue.Text(DescribeJournalMode(database, isTempDatabase: false))]],
                0);
        }

        if (_queryOnly || database.IsReadOnly)
            return new ExecutionResult(["journal_mode"], [[SqlValue.Text(current)]], 0);
        if (_transactionDatabases is not null)
            throw new EmbeddedSqlException("cannot change journal mode while a transaction is active");

        // In-memory main DBs only accept MVCC as a logical mode switch; other modes stay "memory".
        if (!database.IsFileBacked)
        {
            if (requested != SqliteJournalMode.Mvcc)
                return new ExecutionResult(["journal_mode"], [[SqlValue.Text(current)]], 0);
            var memoryResult = database
                .EnableMvccMode(GetSynchronousMode(database))
                .ToString()
                .ToLowerInvariant();
            return new ExecutionResult(["journal_mode"], [[SqlValue.Text(memoryResult)]], 0);
        }

        var result = database.SwitchJournalMode(
                requested,
                busyTimeout: BusyTimeout,
                synchronousMode: GetSynchronousMode(database))
            .ToString()
            .ToLowerInvariant();
        return new ExecutionResult(["journal_mode"], [[SqlValue.Text(result)]], 0);
    }

    private static string DescribeJournalMode(EmbeddedDatabase database, bool isTempDatabase)
    {
        if (isTempDatabase)
            return "wal";
        // Peer may have enabled MVCC after this connection opened.
        database.EnsureMvccAttachedIfDurable();
        if (database.IsMvccEnabled)
            return "mvcc";
        if (!database.IsFileBacked)
            return "memory";
        return database.GetJournalMode().ToString().ToLowerInvariant();
    }

    private static bool TryParseJournalMode(string mode, out SqliteJournalMode journalMode)
    {
        if (mode.Equals("experimental_mvcc", StringComparison.OrdinalIgnoreCase))
        {
            journalMode = SqliteJournalMode.Mvcc;
            return true;
        }

        return Enum.TryParse(mode, ignoreCase: true, out journalMode)
            && journalMode is SqliteJournalMode.Delete or SqliteJournalMode.Wal or SqliteJournalMode.Mvcc;
    }

    private ExecutionResult ExecutePragmaPageSize(PragmaPageSizeStatement statement)
    {
        var database = ResolvePragmaDatabase(statement.Schema);
        var current = database.GetPageSize();
        if (statement.Value is null)
            return new ExecutionResult(["page_size"], [[SqlValue.Integer(current)]], 0);

        if (_queryOnly || database.IsReadOnly)
            return ExecutionResult.Empty;

        var requested = statement.Value.Value;
        if (requested < SqlitePageSize.Minimum
            || requested > SqlitePageSize.Maximum
            || (requested & (requested - 1)) != 0)
        {
            return ExecutionResult.Empty;
        }

        if (database.IsFileBacked)
            _pendingPageSizes[database] = requested;
        else if (!database._inMemoryInitialized)
            database._inMemoryPageSize = requested;
        return ExecutionResult.Empty;
    }

    private ExecutionResult ExecutePragmaCacheSize(PragmaCacheSizeStatement statement)
    {
        var database = ResolvePragmaDatabase(statement.Schema);
        if (statement.Value is { } value)
        {
            // Connection-scoped hint; the managed pager does not evict on this bound yet,
            // but the stored value follows Turso's update_cache_size clamping so callers
            // can rely on SQLite's read-back contract.
            _cacheSizes[database] = NormalizeCacheSize(database, value);
            return ExecutionResult.Empty;
        }

        return new ExecutionResult(
            ["cache_size"],
            [[SqlValue.Integer(_cacheSizes.GetValueOrDefault(database, -2000))]],
            0);
    }

    private static long NormalizeCacheSize(EmbeddedDatabase database, long value)
    {
        // Mirrors turso-src/core/translate/pragma.rs update_cache_size: negative values are
        // KiB budgets converted to pages, > MAX_SAFE collapses to 0, and anything below the
        // minimum page-cache size clamps to MINIMUM_PAGE_CACHE_SIZE_IN_PAGES.
        const long maximumSafe = 2147450880;
        const long minimumPages = 200;

        var pages = value;
        if (value < 0)
        {
            var pageSize = database.GetPageSize();
            if (pageSize <= 0)
                pageSize = 4096;
            long absoluteKiB = value == long.MinValue ? long.MaxValue : -value;
            pages = (long)(((Int128)absoluteKiB * 1024) / pageSize);
        }

        if (pages > maximumSafe || pages < 0)
            return 0;
        if (pages < minimumPages)
            return minimumPages;
        return value;
    }

    private ExecutionResult ExecutePragmaCacheSpill(PragmaCacheSpillStatement statement)
    {
        var database = ResolvePragmaDatabase(statement.Schema);
        if (statement.Enabled is { } enabled)
        {
            _cacheSpills[database] = enabled;
            return ExecutionResult.Empty;
        }

        return new ExecutionResult(
            ["cache_spill"],
            [[SqlValue.Integer(_cacheSpills.GetValueOrDefault(database, true) ? 1 : 0)]],
            0);
    }

    private ExecutionResult ExecutePragmaMaxPageCount(PragmaMaxPageCountStatement statement)
    {
        var database = ResolvePragmaDatabase(statement.Schema);
        if (statement.Value is null)
            return new ExecutionResult(["max_page_count"], [[SqlValue.Integer(database.MaxPageCount)]], 0);

        // Turso treats 0 as a no-op query and clamps any other request to at
        // least the current database size (set_max_page_count).
        if (statement.Value.Value == 0)
            return new ExecutionResult(["max_page_count"], [[SqlValue.Integer(database.MaxPageCount)]], 0);

        var requested = statement.Value.Value < 0 ? 0 : (uint)statement.Value.Value;
        var newMax = Math.Max(requested, database.GetPageCount());
        database.MaxPageCount = newMax;
        return new ExecutionResult(["max_page_count"], [[SqlValue.Integer(newMax)]], 0);
    }

