    private ExecutionResult ExecutePragmaTempStore(PragmaTempStoreStatement statement)
    {
        ValidatePragmaSchema(statement.Schema);
        if (statement.Value is null)
            return new ExecutionResult(["temp_store"], [[SqlValue.Integer(_tempStore)]], 0);

        // Turso rejects the change only while a transaction is open AND a temp
        // database exists; otherwise the new setting simply tears down and
        // reinitializes temp storage.
        if (HasActiveTransaction && _tempInitialized)
            throw new EmbeddedSqlException("temporary storage cannot be changed from within a transaction");

        _tempStore = statement.Value.Value;
        // A transaction already owns the current temp database snapshot. When no temp object
        // exists there is nothing to reset, and preserving that instance keeps subsequent temp
        // DDL inside the same transaction ownership map.
        if (!HasActiveTransaction)
            ResetTemporaryDatabase();
        _tempInitialized = false;
        return ExecutionResult.Empty;
    }

    private ExecutionResult ExecutePragmaWalCheckpoint(PragmaWalCheckpointStatement statement)
    {
        if (statement.Mode is { } mode)
        {
            if (!mode.Equals("PASSIVE", StringComparison.OrdinalIgnoreCase)
                && !mode.Equals("FULL", StringComparison.OrdinalIgnoreCase)
                && !mode.Equals("RESTART", StringComparison.OrdinalIgnoreCase)
                && !mode.Equals("TRUNCATE", StringComparison.OrdinalIgnoreCase))
            {
                throw new EmbeddedSqlException($"Unknown Checkpoint Mode: {mode}");
            }
        }

        string[] columns = ["busy", "log", "checkpointed"];
        if (statement.Schema is not null && statement.Schema.Equals("temp", StringComparison.OrdinalIgnoreCase))
        {
            // The temp schema carries no WAL; Turso reports -1 for both counters.
            return new ExecutionResult(columns, [[SqlValue.Integer(0), SqlValue.Integer(-1), SqlValue.Integer(-1)]], 0);
        }

        ValidatePragmaSchema(statement.Schema);
        var database = ResolvePragmaDatabase(statement.Schema);
        if (database.IsMvccEnabled)
        {
            // Managed MVCC checkpoint: materialize WAL pages -> backfill/flush
            // main storage -> retire the logical log -> reset the WAL last.
            var result = database.RunMvccCheckpoint(
                statement.Mode,
                BusyTimeout,
                GetSynchronousMode(database));
            return new ExecutionResult(
                columns,
                [[
                    SqlValue.Integer(result.Busy ? 1 : 0),
                    SqlValue.Integer(result.LogFramesBefore),
                    SqlValue.Integer(result.CheckpointedFrames),
                ]],
                0);
        }

        // Classic path: managed engine commits inline and keeps no persistent WAL
        // frames, so every checkpoint completes trivially with nothing left in the log.
        return new ExecutionResult(columns, [[SqlValue.Integer(0), SqlValue.Integer(0), SqlValue.Integer(0)]], 0);
    }

    private ExecutionResult ExecutePragmaBusyTimeout(PragmaBusyTimeoutStatement statement)
    {
        ValidatePragmaSchema(statement.Schema);
        if (statement.Value is { } value)
        {
            // Turso clamps negative values to zero.
            BusyTimeout = TimeSpan.FromMilliseconds(Math.Max(0, value));
            return ExecutionResult.Empty;
        }

        return new ExecutionResult(["busy_timeout"], [[SqlValue.Integer((long)BusyTimeout.TotalMilliseconds)]], 0);
    }

    private ExecutionResult ExecutePragmaSynchronous(PragmaSynchronousStatement statement)
    {
        var database = ResolvePragmaDatabase(statement.Schema);
        if (statement.Value is null)
        {
            return new ExecutionResult(
                ["synchronous"],
                [[SqlValue.Integer((int)GetSynchronousMode(database))]],
                0);
        }

        if (HasActiveTransaction)
            throw new EmbeddedSqlException("Safety level may not be changed inside a transaction");

        var current = GetSynchronousMode(database);
        _synchronousModes[database] = statement.Value.ToUpperInvariant() switch
        {
            "OFF" or "0" => SqliteSynchronousMode.Off,
            "NORMAL" or "1" => SqliteSynchronousMode.Normal,
            "FULL" or "2" => SqliteSynchronousMode.Full,
            "EXTRA" or "3" => SqliteSynchronousMode.Extra,
            _ => current,
        };
        return ExecutionResult.Empty;
    }

    private SqliteSynchronousMode GetSynchronousMode(EmbeddedDatabase database)
        => _synchronousModes.GetValueOrDefault(database, SqliteSynchronousMode.Full);

    private ExecutionResult ExecutePragmaLockingMode(PragmaLockingModeStatement statement)
    {
        var database = ResolvePragmaDatabase(statement.Schema);
        var lockingMode = _lockingModes.GetValueOrDefault(database, "normal");
        if (statement.Value is not null && _transactionDatabases is not null)
            return new ExecutionResult(["locking_mode"], [[SqlValue.Text(lockingMode)]], 0);

        if (statement.Value is not null
            && statement.Value.Equals("normal", StringComparison.OrdinalIgnoreCase)
            && lockingMode == "exclusive")
        {
            _ = database.SetConnectionExclusiveLockingMode(exclusive: false, BusyTimeout);
            lockingMode = "normal";
        }
        else if (statement.Value is not null
            && statement.Value.Equals("exclusive", StringComparison.OrdinalIgnoreCase)
            && lockingMode == "normal")
        {
            lockingMode = database.SetConnectionExclusiveLockingMode(exclusive: true, BusyTimeout)
                ? "exclusive"
                : "normal";
        }

        _lockingModes[database] = lockingMode;
        return new ExecutionResult(["locking_mode"], [[SqlValue.Text(lockingMode)]], 0);
    }

    private void ReleaseExclusiveLockingMode(EmbeddedDatabase database)
    {
        if (!_lockingModes.Remove(database, out var lockingMode)
            || !lockingMode.Equals("exclusive", StringComparison.Ordinal))
        {
            return;
        }

        _ = database.SetConnectionExclusiveLockingMode(exclusive: false, BusyTimeout);
    }

    private void ReleaseExclusiveLockingModes()
    {
        foreach (var database in _lockingModes
                     .Where(pair => pair.Value.Equals("exclusive", StringComparison.Ordinal))
                     .Select(pair => pair.Key)
                     .ToArray())
        {
            _ = database.SetConnectionExclusiveLockingMode(exclusive: false, BusyTimeout);
        }

        _lockingModes.Clear();
    }

