    {
        ValidatePragmaSchema(statement.Schema);
        if (statement.Value is { } value)
        {
            if (value != -1 && value < 1)
                throw new EmbeddedSqlException("mvcc_gc_threshold must be -1 (disabled) or a positive integer");

            _mvccGcThreshold = value;
            return ExecutionResult.Empty;
        }

        return new ExecutionResult(
            ["mvcc_gc_threshold"],
            [[SqlValue.Integer(_mvccGcThreshold)]],
            0);
    }

    // PRAGMA list_types reuses the table_info result shape, reporting one row per built-in
    // storage type with the remaining columns left NULL (Turso translate/pragma.rs).
    private static readonly string[] ListTypeNames = ["INTEGER", "REAL", "TEXT", "BLOB", "ANY"];

    private ExecutionResult ExecutePragmaListTypes(PragmaListTypesStatement statement)
    {
        ValidatePragmaSchema(statement.Schema);
        var rows = ListTypeNames
            .Select(name => new[]
            {
                SqlValue.Text(name),
                SqlValue.Null,
                SqlValue.Null,
                SqlValue.Null,
                SqlValue.Null,
                SqlValue.Null,
            })
            .ToList();
        return new ExecutionResult(
            ["name", "type", "notnull", "dflt_value", "pk", "hidden"],
            rows,
            0);
    }

    private ExecutionResult ExecutePragmaFunctionList(PragmaFunctionListStatement statement)
    {
        ValidatePragmaSchema(statement.Schema);
        return new ExecutionResult(
            ["name", "builtin", "type", "enc", "narg", "flags"],
            EmbeddedDatabase.BuildPragmaFunctionListRows(_database),
            0);
    }

    private ExecutionResult ExecutePragmaModuleList(PragmaModuleListStatement statement)
    {
        ValidatePragmaSchema(statement.Schema);
        return new ExecutionResult(["name"], EmbeddedDatabase.BuildPragmaModuleListRows(), 0);
    }

    private ExecutionResult ExecuteVacuum(VacuumStatement statement, SqlValue[] parameters)
    {
        if (_queryOnly)
            throw new EmbeddedSqlException("attempt to write a readonly database");
        if (_transactionDatabases is not null)
            throw new EmbeddedSqlException("cannot VACUUM from within a transaction");

        var databaseName = statement.Schema ?? "main";
        var database = ResolveDatabase(databaseName);
        if (database.IsReadOnly)
            throw new EmbeddedSqlException("attempt to write a readonly database");
        if (!database.IsFileBacked && statement.Into is null)
            return ExecutionResult.Empty;

        // VACUUM rewrites the whole database, so it has to lose to a connection
        // holding a write transaction just like any other write.
        ReserveWriteAccess(database);

        int? pendingPageSize = _pendingPageSizes.TryGetValue(database, out var pendingPageSizeValue)
            ? pendingPageSizeValue
            : null;
        var currentPageSize = database.GetPageSize();
        var targetPageSize = statement.Into is not null
            ? pendingPageSize ?? currentPageSize
            : database.GetJournalMode() == SqliteJournalMode.Wal
                ? currentPageSize
                : pendingPageSize ?? currentPageSize;
        if (statement.Into is null)
        {
            database.MigratePageSize(
                targetPageSize,
                busyTimeout: BusyTimeout,
                synchronousMode: GetSynchronousMode(database));
        }
        else
        {
            var destinationValue = database.EvaluateConstant(
                statement.Into,
                parameters,
                _lastInsertRowId);
            if (destinationValue.Kind != SqlValueKind.Text)
                throw new EmbeddedSqlException("non-text filename");

            var destinationPath = destinationValue.AsText();
            if (string.IsNullOrWhiteSpace(destinationPath)
                || destinationPath.Equals(":memory:", StringComparison.OrdinalIgnoreCase)
                || destinationPath.StartsWith("file:", StringComparison.OrdinalIgnoreCase))
            {
                throw new EmbeddedSqlException(
                    "Managed VACUUM INTO supports only non-empty ordinary file paths.");
            }
            if (!database.IsFileBacked)
                throw new EmbeddedSqlException("Managed VACUUM INTO requires a file-backed source database.");

            var openDatabases = new[] { _database }
                .Concat(_attachedDatabases.Values.Select(attachment => attachment.Database));
            if (openDatabases.Any(openDatabase =>
                    openDatabase.ReferencesStoragePath(destinationPath, database.FileSystem)))
            {
                throw new EmbeddedSqlException("output file already exists");
            }

            database.VacuumInto(
                destinationPath,
                targetPageSize,
                busyTimeout: BusyTimeout,
                synchronousMode: GetSynchronousMode(database));
        }

        if (statement.Into is null)
            _pendingPageSizes.Remove(database);
        return ExecutionResult.Empty;
    }

    /// <summary>
    /// The rowid of the most recent successful INSERT on this connection, mirroring the
    /// value reported by <c>last_insert_rowid()</c>.
    /// </summary>
    public long LastInsertRowId => _lastInsertRowId;

    internal string[] DescribeColumns(ParsedStatement statement)
    {
        ThrowIfRecursiveTriggerCallbackReentry();
        if (statement is ExplainStatement)
            return EmbeddedDatabase.ExplainColumns();
        if (statement is ExplainQueryPlanStatement)
            return EmbeddedDatabase.ExplainQueryPlanColumns();
        if (statement is PragmaTableInfoStatement)
            return ["cid", "name", "type", "notnull", "dflt_value", "pk"];
        if (statement is PragmaTableXInfoStatement)
            return ["cid", "name", "type", "notnull", "dflt_value", "pk", "hidden"];
        if (statement is PragmaIndexListStatement)
            return ["seq", "name", "unique", "origin", "partial"];
        if (statement is PragmaIndexInfoStatement)
            return ["seqno", "cid", "name"];
        if (statement is PragmaIndexXInfoStatement)
            return ["seqno", "cid", "name", "desc", "coll", "key"];
        if (statement is PragmaForeignKeyListStatement)
            return ["id", "seq", "table", "from", "to", "on_update", "on_delete", "match"];
        if (statement is PragmaForeignKeyCheckStatement)
            return ["table", "rowid", "parent", "fkid"];
        if (statement is PragmaIntegrityCheckStatement integrityCheck)
            return integrityCheck.Quick ? ["quick_check"] : ["integrity_check"];
        if (statement is PragmaTableListStatement)
            return ["schema", "name", "type", "ncol", "wr", "strict"];
        if (statement is PragmaDatabaseListStatement)
            return ["seq", "name", "file"];
        if (statement is PragmaEncodingStatement)
            return ["encoding"];
        if (statement is PragmaPageCountStatement)
            return ["page_count"];
        if (statement is PragmaFreelistCountStatement)
            return ["freelist_count"];
        if (statement is PragmaQueryOnlyStatement { Enabled: null })
            return ["query_only"];
        if (statement is PragmaForeignKeysStatement { Enabled: null })
            return ["foreign_keys"];
        if (statement is PragmaDeferForeignKeysStatement { Enabled: null })
            return ["defer_foreign_keys"];
        if (statement is PragmaRecursiveTriggersStatement { Enabled: null })
            return ["recursive_triggers"];
        if (statement is PragmaCaptureDataChangesConnectionStatement { Value: null })
            return ["capture_data_changes_conn", "table_name", "version"];
        if (statement is PragmaHeaderIntegerStatement { Value: null } headerInteger)
        {
            return headerInteger.Kind switch
            {
                PragmaHeaderIntegerKind.SchemaVersion => ["schema_version"],
                PragmaHeaderIntegerKind.UserVersion => ["user_version"],
                PragmaHeaderIntegerKind.ApplicationId => ["application_id"],
                _ => throw new InvalidOperationException(
                    $"Unknown PRAGMA header integer kind {headerInteger.Kind}."),
            };
        }
        if (statement is PragmaJournalModeStatement)
            return ["journal_mode"];
        if (statement is PragmaPageSizeStatement { Value: null })
            return ["page_size"];
        if (statement is PragmaMaxPageCountStatement)
            return ["max_page_count"];
        if (statement is PragmaIgnoreCheckConstraintsStatement { Enabled: null })
            return ["ignore_check_constraints"];
        if (statement is PragmaRequireWhereStatement { Enabled: null })
            return ["require_where"];
        if (statement is PragmaTempStoreStatement { Value: null })
            return ["temp_store"];
        if (statement is PragmaWalCheckpointStatement)
            return ["busy", "log", "checkpointed"];
        if (statement is PragmaBusyTimeoutStatement { Value: null })
            return ["busy_timeout"];
        if (statement is PragmaSynchronousStatement { Value: null })
            return ["synchronous"];
        if (statement is PragmaLockingModeStatement)
            return ["locking_mode"];
        if (statement is PragmaAutoVacuumStatement { Value: null })
            return ["auto_vacuum"];
        if (statement is PragmaDataSyncRetryStatement { Enabled: null })
            return ["data_sync_retry"];
        if (statement is PragmaFullColumnNamesStatement { Enabled: null })
            return ["full_column_names"];
        if (statement is PragmaShortColumnNamesStatement { Enabled: null })
            return ["short_column_names"];
        if (statement is PragmaMvccCheckpointThresholdStatement { Value: null })
            return ["mvcc_checkpoint_threshold"];
        if (statement is PragmaMvccGcThresholdStatement { Value: null })
            return ["mvcc_gc_threshold"];
        if (statement is PragmaListTypesStatement)
            return ["name", "type", "notnull", "dflt_value", "pk", "hidden"];
        if (statement is PragmaFunctionListStatement)
            return ["name", "builtin", "type", "enc", "narg", "flags"];
        if (statement is PragmaModuleListStatement)
            return ["name"];

        var routed = RouteStatement(statement);
        var transactionState = GetTransactionState(routed.Database);
        if (EmbeddedDatabase.TryGetReturning(routed.Statement, out var returningTable, out var returning))
        {
            return transactionState is null
                ? routed.Database.DescribeReturning(returningTable, returning)
                : routed.Database.DescribeReturning(returningTable, returning, transactionState.Catalog);
        }

        if (routed.Statement is not QueryStatement query)
            return [];

        return transactionState is null
            ? routed.Database.DescribeColumns(query)
            : routed.Database.DescribeColumns(query, transactionState.Catalog);
    }

    private void CreateSavepoint(string name)
    {
        // A SAVEPOINT issued outside an explicit BEGIN...COMMIT opens a transaction
        // that stays active until its outermost savepoint is released or rolled back.
        if (_transactionDatabases is null)
            BeginTransaction(openedBySavepoint: true, TransactionMode.Deferred);

        foreach (var (database, txId) in _mvccTransactions)
            database.MvStore?.BeginNamedSavepoint(txId, name);

        var snapshots = new Dictionary<EmbeddedDatabase, SavepointDatabaseState>();
        try
        {
            foreach (var pair in _transactionDatabases!)
            {
                snapshots.Add(
                    pair.Key,
                    new SavepointDatabaseState(
                        pair.Value.Catalog.Clone(),
                        pair.Value.HasChanges,
                        pair.Value.PragmaHeader,
                        pair.Value.HasSnapshotPragmaHeader,
                        pair.Value.HasSchemaChanges,
                        pair.Value.ForceFullCatalogRewrite,
                        pair.Value.VirtualTableTransaction.CreateCheckpoint(),
                        new HashSet<EmbeddedDatabase.ForeignKeyViolation>(
                            pair.Value.PendingDeferredViolations),
                        pair.Value.Overlay?.CreateCheckpoint(),
                        new HashSet<string>(
                            pair.Value.TargetedIndexRebuildNames,
                            StringComparer.OrdinalIgnoreCase),
                        pair.Value.HasNonTargetedIndexRebuildChange));
            }

            _savepoints.Add(new SavepointEntry(
                name,
                snapshots,
                _transactionWriteDatabase,
                _changeDataCapture?.Snapshot()));
        }
        catch
        {
            foreach (var state in snapshots.Values)
                state.Catalog.DisconnectOwnedVirtualTables();
            throw;
        }
    }

    private void ReleaseSavepoint(string name)
    {
        var index = FindSavepointIndex(name);

        // Releasing the outermost savepoint of a savepoint-opened transaction commits it.
        if (index == 0 && _transactionOpenedBySavepoint)
        {
            CommitTransaction();
            return;
        }

        foreach (var (database, txId) in _mvccTransactions)
            database.MvStore?.ReleaseNamedSavepoint(txId, name);

        // RELEASE removes the named savepoint and every savepoint created after it,
        // keeping their changes in the enclosing scope.
        for (var removed = index; removed < _savepoints.Count; removed++)
        {
            foreach (var state in _savepoints[removed].Databases.Values)
                state.Catalog.DisconnectOwnedVirtualTables();
        }
        _savepoints.RemoveRange(index, _savepoints.Count - index);
    }

    private void RollbackToSavepoint(string name)
    {
        var index = FindSavepointIndex(name);
        var savepoint = _savepoints[index];

        // Restore the state captured when the savepoint was created. Clone so the
        // stored snapshot stays pristine for a later ROLLBACK TO the same savepoint.
        if (_transactionDatabases is null)
            throw new InvalidOperationException("The managed savepoint lost its transaction state.");
        foreach (var (database, savedState) in savepoint.Databases)
        {
            var state = _transactionDatabases[database];
            var replacedCatalog = state.Catalog;
            state.VirtualTableTransaction.RollbackTo(savedState.VirtualTableTransactionCheckpoint);
            state.Catalog = savedState.Catalog.Clone();
            replacedCatalog.DisconnectOwnedVirtualTables(state.VirtualTableTransaction);
            state.HasChanges = savedState.HasChanges;
            state.PragmaHeader = savedState.PragmaHeader;
            state.HasSnapshotPragmaHeader = savedState.HasSnapshotPragmaHeader;
            state.HasSchemaChanges = savedState.HasSchemaChanges;
            state.ForceFullCatalogRewrite = savedState.ForceFullCatalogRewrite;
            state.PendingDeferredViolations.Clear();
            state.PendingDeferredViolations.UnionWith(savedState.PendingDeferredViolations);
            state.TargetedIndexRebuildNames.Clear();
            state.TargetedIndexRebuildNames.UnionWith(savedState.TargetedIndexRebuildNames);
            state.HasNonTargetedIndexRebuildChange = savedState.HasNonTargetedIndexRebuildChange;
            if (state.Overlay is not null && savedState.OverlayCheckpoint is not null)
            {
                state.Overlay.RestoreCheckpoint(
                    savedState.OverlayCheckpoint,
                    tableName => database.CreatePrimaryKeyRecordComparer(
                        state.Catalog.Tables.TryGetValue(tableName, out var restoredTable)
                            ? restoredTable.PrimaryKeySchema
                                ?? throw new InvalidOperationException(
                                    $"WITHOUT ROWID table '{tableName}' is missing its primary-key metadata.")
                            : throw new InvalidOperationException(
                                $"Restoring the mutation overlay for table '{tableName}' requires it to exist in the restored catalog.")));
            }
        }
        _transactionWriteDatabase = savepoint.WriteDatabase;
        if (_changeDataCapture is { } changeDataCapture
            && savepoint.ChangeDataCapture is { } changeDataCaptureSnapshot)
        {
            changeDataCapture.Restore(changeDataCaptureSnapshot);
        }

        // Undo concurrent version-store ops after the named mark (Turso MVCC savepoints).
        foreach (var (database, txId) in _mvccTransactions)
            database.MvStore?.RollbackToNamedSavepoint(txId, name);
        ReleaseConcurrentSchemaGateIfUnused();

        // ROLLBACK TO keeps the named savepoint but cancels any created after it.
        if (index + 1 < _savepoints.Count)
        {
            for (var removed = index + 1; removed < _savepoints.Count; removed++)
            {
                foreach (var state in _savepoints[removed].Databases.Values)
                    state.Catalog.DisconnectOwnedVirtualTables();
            }
            _savepoints.RemoveRange(index + 1, _savepoints.Count - index - 1);
        }
    }

    private int FindSavepointIndex(string name)
    {
        for (var index = _savepoints.Count - 1; index >= 0; index--)
        {
            if (string.Equals(_savepoints[index].Name, name, StringComparison.OrdinalIgnoreCase))
                return index;
        }

        throw new EmbeddedSqlException($"no such savepoint: {name}");
    }

    private void ReleaseConcurrentSchemaGateIfUnused()
    {
        if (!_transactionIsConcurrent
            || _transactionDatabases is null
            || _transactionDatabases.Values.Any(state => state.HasSchemaChanges))
        {
            return;
        }

        foreach (var (database, txId) in _mvccTransactions)
            database.MvStore?.CancelSchemaChange(txId);
    }

    private void ResetTransactionState(bool rollbackVirtualTables = true)
    {
        var transactionDatabases = _transactionDatabases;
        _transactionDatabases = null;
        _transactionWriteDatabase = null;
        _transactionMutationDatabase = null;
        _transactionOpenedBySavepoint = false;
        _transactionIsConcurrent = false;
        if (_mvccTransactions.Count != 0)
        {
            foreach (var (database, txId) in _mvccTransactions)
                database.MvStore?.Rollback(txId);
            _mvccTransactions.Clear();
        }

        // Every step below must run even if an earlier one throws — most notably a
        // virtual-table module's own Rollback callback, which is arbitrary user/extension code.
        // Losing the rest of this cleanup to one throwing callback would leak pinned snapshots
        // (an open pager read mark) and write reservations, and would skip EndTransaction,
        // leaking the active-transaction count forever. Only the first exception is preserved
        // (matching the ManagedVirtualTableTransaction.Complete idiom used elsewhere in this
        // file) and rethrown only after every deterministic cleanup step below has run.
        ExceptionDispatchInfo? failure = null;

        if (transactionDatabases is not null)
        {
            if (rollbackVirtualTables)
            {
                foreach (var state in transactionDatabases.Values)
                {
                    try
                    {
                        state.VirtualTableTransaction.Rollback(state.Catalog);
                    }
                    catch (Exception exception)
                    {
                        failure ??= ExceptionDispatchInfo.Capture(exception);
                    }
                }
            }

            foreach (var state in transactionDatabases.Values)
            {
                try
                {
                    state.Catalog.DisconnectOwnedVirtualTables();
                }
                catch (Exception exception)
                {
                    failure ??= ExceptionDispatchInfo.Capture(exception);
                }

                try
                {
                    state.PinnedSnapshot?.Dispose();
                }
                catch (Exception exception)
                {
                    failure ??= ExceptionDispatchInfo.Capture(exception);
                }
            }
        }

        foreach (var savepoint in _savepoints)
        {
            foreach (var state in savepoint.Databases.Values)
            {
                try
                {
                    state.Catalog.DisconnectOwnedVirtualTables();
                }
                catch (Exception exception)
                {
                    failure ??= ExceptionDispatchInfo.Capture(exception);
                }
            }
        }

        _savepoints.Clear();
        _changeDataCapture?.ResetTransaction();
        _deferForeignKeys = false;
        ReleaseTransactionWriteReservations();
        if (transactionDatabases is not null)
        {
            foreach (var database in transactionDatabases.Keys)
            {
                try
                {
                    database.EndTransaction();
                }
                catch (Exception exception)
                {
                    failure ??= ExceptionDispatchInfo.Capture(exception);
                }
            }
        }

        failure?.Throw();
    }

    private sealed record SavepointEntry(
        string Name,
        IReadOnlyDictionary<EmbeddedDatabase, SavepointDatabaseState> Databases,
        EmbeddedDatabase? WriteDatabase,
        ChangeDataCaptureTransactionSnapshot? ChangeDataCapture);

    private sealed record SavepointDatabaseState(
        EmbeddedDatabase.SchemaCatalog Catalog,
        bool HasChanges,
        PragmaHeaderMetadata PragmaHeader,
        bool HasSnapshotPragmaHeader,
        bool HasSchemaChanges,
        bool ForceFullCatalogRewrite,
        int VirtualTableTransactionCheckpoint,
        IReadOnlySet<EmbeddedDatabase.ForeignKeyViolation> PendingDeferredViolations,
        TransactionMutationOverlayCheckpoint? OverlayCheckpoint,
        IReadOnlySet<string> TargetedIndexRebuildNames,
        bool HasNonTargetedIndexRebuildChange);

    private void ThrowIfRecursiveTriggerCallbackReentry()
    {
        if (EmbeddedDatabase.IsRecursiveTriggerCallbackDatabase(_database)
            || EmbeddedDatabase.IsRecursiveTriggerCallbackDatabase(_tempDatabase)
            || _attachedDatabases.Values.Any(attachment =>
                EmbeddedDatabase.IsRecursiveTriggerCallbackDatabase(attachment.Database)))
        {
            EmbeddedDatabase.ThrowRecursiveTriggerCallbackReentry();
        }
    }

    /// <summary>
    /// PRAGMA require_where / i_am_a_dummy forbids UPDATE and DELETE statements
    /// with no WHERE clause. Turso checks this at translate time, before table
    /// resolution, so the guard fires even for nonexistent tables and through
    /// WITH-DML wrappers.
    /// </summary>
    private void ThrowIfRequireWhereViolated(ParsedStatement statement)
    {
        if (!_requireWhere)
            return;

        if (statement is WithDmlStatement withDml)
            statement = withDml.Dml;

        if (statement is UpdateStatement { Where: null })
        {
            throw new EmbeddedSqlException(
                "UPDATE without a WHERE clause is not allowed when require_where (or i_am_a_dummy) is enabled");
        }

        if (statement is DeleteStatement { Where: null })
        {
            throw new EmbeddedSqlException(
                "DELETE without a WHERE clause is not allowed when require_where (or i_am_a_dummy) is enabled");
        }
    }

    private void ThrowIfDisposed()
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
    }
}

public sealed class EmbeddedStatement : IDisposable
{
    private readonly EmbeddedConnection _connection;
    private readonly ParsedStatement _statement;
    private readonly SqlParameterMap _parameters;
    private readonly string _sql;
    private readonly SqlValue[] _boundValues;
    private string[]? _columnNames;
    private ExecutionResult? _result;
    private SqlValue[]? _currentRow;
    private IDisposable? _readerLease;
    private int _rowIndex = -1;
    private bool _disposed;

    // Per-prepared-statement cache for an eligible top-level VALUES lowering. The immutable program and
    // slot map are compiled at most once (on the first execution that resolves the shape) and reused across
    // every Reset/rebind, so a routed VALUES stops recompiling per Execute. Reset never clears this; only
    // Dispose releases it. The state is a tri-state so a fallback shape (a computed cell) is resolved once
    // to Ineligible and then always routed to the evaluator, and an eligible shape stays Cached.
    private EmbeddedDatabase.PreparedValuesLowering? _valuesLowering;
    private ValuesLoweringState _valuesLoweringState = ValuesLoweringState.Unresolved;
    private int _valuesLoweringCompilationCount;

    private enum ValuesLoweringState
    {
        Unresolved,
        Cached,
        Ineligible,
    }

    internal EmbeddedStatement(
        EmbeddedConnection connection,
        ParsedStatement statement,
        SqlParameterMap parameters,
        string sql = "")
    {
        _connection = connection;
        _statement = statement;
        _parameters = parameters;
        _sql = sql;
        _boundValues = new SqlValue[parameters.Count + 1];
    }

    public int ParameterCount => _parameters.Count;

    public int ColumnCount => _result?.Columns.Length ?? _columnNames?.Length ?? 0;

    public int RowsAffected => _result?.RowsAffected ?? 0;

    public int GetColumnCount()
    {
        ThrowIfDisposed();
        return GetColumnNames().Length;
    }

    public bool HasRows()
    {
        ThrowIfDisposed();
        if (_statement is (QueryStatement or PragmaTableInfoStatement or PragmaTableXInfoStatement
            or PragmaIndexListStatement or PragmaIndexInfoStatement or PragmaIndexXInfoStatement
            or PragmaForeignKeyListStatement
            or PragmaForeignKeyCheckStatement or PragmaTableListStatement
            or PragmaIntegrityCheckStatement
            or PragmaDatabaseListStatement or PragmaEncodingStatement
            or PragmaPageCountStatement or PragmaFreelistCountStatement
            or ExplainStatement)
            || _statement is ExplainQueryPlanStatement
            || _statement is PragmaQueryOnlyStatement { Enabled: null }
            || _statement is PragmaForeignKeysStatement { Enabled: null }
            || _statement is PragmaDeferForeignKeysStatement { Enabled: null }
            || _statement is PragmaRecursiveTriggersStatement { Enabled: null }
            || _statement is PragmaHeaderIntegerStatement { Value: null }
            || _statement is PragmaJournalModeStatement
            || _statement is PragmaPageSizeStatement { Value: null }
            || _statement is PragmaMaxPageCountStatement
            || _statement is PragmaIgnoreCheckConstraintsStatement { Enabled: null }
            || _statement is PragmaRequireWhereStatement { Enabled: null }
            || _statement is PragmaTempStoreStatement { Value: null }
            || _statement is PragmaWalCheckpointStatement
            || _statement is PragmaBusyTimeoutStatement { Value: null }
            || EmbeddedDatabase.TryGetReturning(_statement, out _, out _))
        {
            ExecuteIfNeeded();
            return _result!.Rows switch
            {
                StreamingProjectionRows streamingRows => streamingRows.HasAny(),
                StreamingVdbeRows vdbeRows => vdbeRows.HasAny(),
                _ => _result.Rows.Count > 0,
            };
        }

        return false;
    }

    public int GetParameterIndex(string name)
    {
        ThrowIfDisposed();
        return _parameters.TryGetIndex(name, out var index) ? index : 0;
    }

    public string? GetParameterName(int index)
    {
        ThrowIfDisposed();
        if (index < 1 || index > ParameterCount)
            throw new ArgumentOutOfRangeException(nameof(index));

        return _parameters.GetName(index);
    }

    public void Bind(int index, SqlValue value)
    {
        ThrowIfDisposed();
        if (index < 1 || index > ParameterCount)
            throw new ArgumentOutOfRangeException(nameof(index));

        _boundValues[index] = value.WithoutJsonSubtype();
    }

    public bool Bind(string name, SqlValue value)
    {
        ThrowIfDisposed();
        return _parameters.TryGetIndex(name, out var index) && BindResolved(index, value);
    }

    public StatementStepResult Step(CancellationToken cancellationToken = default)
    {
        ThrowIfDisposed();
        if (cancellationToken.IsCancellationRequested)
        {
            DisposeStreamingRows();
            ReleaseReaderLease();
            cancellationToken.ThrowIfCancellationRequested();
        }
        ExecuteIfNeeded(cancellationToken);

        var nextRowIndex = _rowIndex + 1;
        if (_result!.Rows is StreamingVdbeRows vdbeRows)
        {
            try
            {
                _currentRow = null;
                if (vdbeRows.TryGetRow(nextRowIndex, cancellationToken, out var row))
                {
                    _currentRow = row;
                    _rowIndex = nextRowIndex;
                    return StatementStepResult.Row;
                }
            }
            catch
            {
                ReleaseReaderLease();
                throw;
            }
        }
        else if (_result.Rows is StreamingProjectionRows streamingRows)
        {
            while (nextRowIndex < streamingRows.SourceCount && !streamingRows.IsComplete)
            {
                _currentRow = null;
                if (streamingRows.TryGetRow(nextRowIndex, cancellationToken, out var row))
                {
                    _currentRow = row;
                    _rowIndex = nextRowIndex;
                    return StatementStepResult.Row;
                }

                _rowIndex = nextRowIndex;
                nextRowIndex++;
            }
        }
        else if (nextRowIndex < _result.Rows.Count)
        {
            _currentRow = _result.Rows[nextRowIndex];
            _rowIndex = nextRowIndex;
            return StatementStepResult.Row;
        }

        _currentRow = null;
        ReleaseReaderLease();
        return StatementStepResult.Done;
    }

    /// <summary>
    /// Advances the statement without ever blocking the calling thread on lock
    /// contention, honoring <paramref name="cancellationToken"/> exactly.
    /// </summary>
    /// <remarks>
    /// The engine's execution pipeline is synchronous, and its lock waits park a
    /// thread in <see cref="Monitor.Wait(object)"/> or <see cref="Thread.Sleep(int)"/>
    /// for the whole busy timeout — fatal on a browser's single thread and
    /// unresponsive to cancellation. This drains the contention first: an autocommit
    /// mutation takes its write reservation through the transaction lock's
    /// asynchronous barging acquisition, so the synchronous attempt finds it
    /// re-entrant, and the attempt itself runs with this connection's budget zeroed
    /// so no remaining wait can block. Anything still reported busy suspends on the
    /// same lock's asynchronous signal and retries, bounded by the connection's
    /// <c>busy_timeout</c>, and surfaces the original busy failure when the budget
    /// runs out. The statement is only advanced by a successful attempt, because
    /// execution publishes its result as a single assignment.
    /// </remarks>
    public async ValueTask<StatementStepResult> StepAsync(CancellationToken cancellationToken = default)
    {
        ThrowIfDisposed();
        cancellationToken.ThrowIfCancellationRequested();
        var busyTimeout = _connection.BusyTimeout;

        // A zero budget already fails fast, and a busy_timeout PRAGMA owns the very
        // knob the fail-fast scope displaces, so both run the statement directly.
        if (busyTimeout == TimeSpan.Zero || _statement is PragmaBusyTimeoutStatement)
            return Step(cancellationToken);

        var deadline = EmbeddedDatabase.CreateBusyDeadline(busyTimeout);
        while (true)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var reservation = await _connection
                .AcquireAutocommitWriteReservationAsync(
                    _statement,
                    EmbeddedDatabase.RemainingBusyBudget(deadline),
                    cancellationToken)
                .ConfigureAwait(false);
            try
            {
                using (_connection.EnterFailFastBusyScope())
                    return Step(cancellationToken);
            }
            catch (EmbeddedBusyException)
            {
                if (!await _connection
                        .WaitForBusyRetryAsync(deadline, cancellationToken)
                        .ConfigureAwait(false))
                {
                    throw;
                }
            }
            finally
            {
                reservation?.Dispose();
            }
        }
    }

    public SqlValue GetValue(int ordinal)
    {
        ThrowIfDisposed();
        if (_result is null || _currentRow is null)
            throw new InvalidOperationException("Statement is not positioned on a row.");
        if (ordinal < 0 || ordinal >= _result.Columns.Length)
            throw new ArgumentOutOfRangeException(nameof(ordinal));

        return _currentRow[ordinal];
    }

    public string GetColumnName(int ordinal)
    {
        ThrowIfDisposed();
        var columnNames = GetColumnNames();
        if (ordinal < 0 || ordinal >= columnNames.Length)
            throw new ArgumentOutOfRangeException(nameof(ordinal));

        return columnNames[ordinal];
    }

    public void Reset()
    {
        ThrowIfDisposed();
        ReleaseReaderLease();
        DisposeStreamingRows();
        _result = null;
        _currentRow = null;
        _rowIndex = -1;
    }

    /// <summary>
    /// Diagnostic/test seam: the immutable VDBE program cached for this statement's eligible top-level
    /// <c>VALUES</c> lowering, or <c>null</c> when the statement is not an eligible <c>VALUES</c>, has not
    /// been executed yet, or fell back to the evaluator. The reference is stable across <see cref="Reset"/>
    /// and rebinds, so observing the same instance across executions proves the program is reused rather
    /// than recompiled per execution.
    /// </summary>
    public VdbeProgram? CompiledValuesProgram => _valuesLowering?.Program;

    /// <summary>
    /// Diagnostic/test seam: the number of times an eligible top-level <c>VALUES</c> lowering has been
    /// compiled for this statement. It reaches one on the first execution that resolves the lowering and
    /// never increases again, so repeated <see cref="Reset"/>/rebind cycles reuse the cached program.
    /// </summary>
    public int ValuesProgramCompilationCount => _valuesLoweringCompilationCount;

    public void Dispose()
    {
        ReleaseReaderLease();
        DisposeStreamingRows();
        _disposed = true;
        _result = null;
        _currentRow = null;

        // Release the cached lowering so its VdbeProgram is collectable; a disposed statement rejects
        // any further use, so no re-resolution can occur after this point.
        _valuesLowering = null;
    }

    private bool BindResolved(int index, SqlValue value)
    {
        Bind(index, value);
        return true;
    }

    private void ExecuteIfNeeded(CancellationToken cancellationToken = default)
    {
        if (_result is not null)
            return;

        cancellationToken.ThrowIfCancellationRequested();

        // Translate-time validation must run before execution, including for statements whose
        // parameters remain NULL because they were never bound.
        EmbeddedTable.ValidateGeneratedColumnExpressions(_statement);

        if (_sql.Length != 0)
            _connection.FireTraceHook(_sql);

        // An eligible top-level VALUES reuses its cached lowering (compiled once for this statement) instead
        // of recompiling on every execution; every other statement -- and any fallback VALUES shape -- keeps
        // the general execution path unchanged.
        if (_statement is ValuesClause values
            && TryExecuteCachedValuesLowering(values, out var valuesResult))
        {
            _result = valuesResult;
            cancellationToken.ThrowIfCancellationRequested();
            OpenReaderLeaseIfNeeded();
            return;
        }

        var mayMutate = _connection.StatementMayMutate(_statement);
        IDisposable? executionLease = _statement is
            VacuumStatement or PragmaJournalModeStatement or PragmaPageSizeStatement
            ? null
            : _connection.OpenStatementReaderLease();
        try
        {
            try
            {
                _result = _connection.Execute(_statement, _boundValues, cancellationToken);
                if (!mayMutate)
                    cancellationToken.ThrowIfCancellationRequested();
                if (HasPotentialRows(_result.Rows))
                {
                    _readerLease = executionLease
                        ?? _connection.OpenStatementReaderLease();
                    executionLease = null;
                }
            }
            catch
            {
                DisposeStreamingRows();
                _result = null;
                throw;
            }
        }
        finally
        {
            executionLease?.Dispose();
        }
    }

    private void OpenReaderLeaseIfNeeded()
    {
        if (HasPotentialRows(_result!.Rows) && _readerLease is null)
            _readerLease = _connection.OpenStatementReaderLease();
    }

    private static bool HasPotentialRows(IReadOnlyList<SqlValue[]> rows)
        => rows switch
        {
            StreamingProjectionRows streamingRows => streamingRows.SourceCount != 0,
            StreamingVdbeRows => true,
            _ => rows.Count != 0,
        };

    private void DisposeStreamingRows()
    {
        if (_result?.Rows is IDisposable disposable)
            disposable.Dispose();
    }

    private void ReleaseReaderLease()
    {
        var lease = Interlocked.Exchange(ref _readerLease, null);
        lease?.Dispose();
    }

    // Routes an eligible top-level VALUES through its per-statement cached lowering. The lowering is
    // resolved lazily on the first execution: an eligible shape compiles its immutable program and slot map
    // once (bumping the compilation count) and is reused thereafter, while a fallback shape (a computed
    // cell) is resolved once to Ineligible and always defers to the evaluator. Resolution can throw the
    // unequal-width diagnostic; because the state is only advanced on a clean resolution, that error keeps
    // recurring on each execution exactly as the evaluator raises it, and each successful run builds a fresh
    // parameter binding from the current bound values, so no mutable binding is shared across executions.
    private bool TryExecuteCachedValuesLowering(ValuesClause values, out ExecutionResult result)
    {
        result = null!;
        if (_valuesLoweringState == ValuesLoweringState.Ineligible)
            return false;

        if (_valuesLoweringState == ValuesLoweringState.Unresolved)
        {
            if (EmbeddedDatabase.TryPrepareValuesLowering(values, out var lowering))
            {
                _valuesLowering = lowering;
                _valuesLoweringState = ValuesLoweringState.Cached;
                _valuesLoweringCompilationCount++;
            }
            else
            {
                _valuesLoweringState = ValuesLoweringState.Ineligible;
                return false;
            }
        }

        result = _connection.ExecutePreparedValues(_valuesLowering!, _boundValues);
        return true;
    }

    private string[] GetColumnNames()
    {
        if (_result is not null)
            return _result.Columns;

        return _columnNames ??= _connection.DescribeColumns(_statement);
    }

    private void ThrowIfDisposed()
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
    }
}

// Row storage that funnels every mutation through a revision counter, so
// statement-level caches (transient equality lookups) can detect staleness
// without hunting down each individual mutation site.
internal sealed class RowStore : IList<SqlValue[]>, IReadOnlyList<SqlValue[]>
{
    private static long _lineageSequence;

    private readonly List<SqlValue[]> _rows = [];

    public long Revision { get; private set; }

    /// <summary>
    /// Identifies this specific RowStore instance's physical storage lineage, distinct from
    /// <see cref="Revision"/>. Assigned fresh, process-uniquely, whenever a RowStore is
    /// constructed, and copied forward only by <see cref="ReplaceContentsPreservingRevision"/> —
    /// i.e. only <see cref="EmbeddedTable.Clone"/>'s same-statement working copy carries the
    /// same LineageId as its source; every other path that builds a replacement
    /// <see cref="EmbeddedTable"/> (ALTER COLUMN, ADD/DROP COLUMN, or any other full rebuild that
    /// re-adds every row into a brand-new RowStore) gets a distinct one.
    /// </summary>
    /// <remarks>
    /// Revision alone cannot distinguish "the same physical row store, unchanged since the
    /// previous commit" from "a brand-new row store that coincidentally replayed the same number
    /// of mutations." For example, <c>EmbeddedTable.CreateWithAlteredColumn</c> rebuilds every row
    /// via <see cref="Add"/> into a fresh RowStore: a table with N rows and no prior
    /// updates/deletes has Revision == N both before and after an ALTER COLUMN, even though every
    /// row's bytes may have changed under the new column's affinity/type — and the table's
    /// <c>Indexes</c> list is carried forward by reference, so an index-reference check alone
    /// would not catch it either. Comparing LineageId closes that gap: it can only ever match
    /// when the very same in-memory RowStore was carried forward, never across a rebuild that
    /// constructs a new one — see
    /// <see cref="EmbeddedFileStore.IsTableRowStorageUnchangedFromPrevious"/>.
    /// </remarks>
    public long LineageId { get; private set; } = Interlocked.Increment(ref _lineageSequence);

    public int Count => _rows.Count;

    public bool IsReadOnly => false;

    public SqlValue[] this[int index]
    {
        get => _rows[index];
        set
        {
            _rows[index] = value;
            Revision++;
        }
    }

    public void Add(SqlValue[] item)
    {
        _rows.Add(item);
        Revision++;
    }

    public void AddRange(IEnumerable<SqlValue[]> items)
    {
        _rows.AddRange(items);
        Revision++;
    }

    public void Clear()
    {
        _rows.Clear();
        Revision++;
    }

    public bool Contains(SqlValue[] item) => _rows.Contains(item);

    public void CopyTo(SqlValue[][] array, int arrayIndex) => _rows.CopyTo(array, arrayIndex);

    public int FindIndex(Predicate<SqlValue[]> match) => _rows.FindIndex(match);

    public IEnumerator<SqlValue[]> GetEnumerator() => _rows.GetEnumerator();

    public int IndexOf(SqlValue[] item) => _rows.IndexOf(item);

    public void Insert(int index, SqlValue[] item)
    {
        _rows.Insert(index, item);
        Revision++;
    }

    public bool Remove(SqlValue[] item)
    {
        var removed = _rows.Remove(item);
        if (removed)
            Revision++;
        return removed;
    }

    public void RemoveAt(int index)
    {
        _rows.RemoveAt(index);
        Revision++;
    }

    // EmbeddedTable.Clone() deep-copies every table in the working catalog on every
    // statement (so a rolled-back statement never mutates the live, published catalog),
    // even tables the statement never touches. Populating the clone through the ordinary
    // Add() path would bump Revision once per copied row, making a fully-untouched clone's
    // Revision diverge from its source (row count vs. the source's full mutation history)
    // and defeating any same-instance staleness check built on it. Copying the rows
    // directly and assigning Revision verbatim instead means an untouched clone keeps
    // exactly its source's Revision, so a later mutation (via the ordinary Add/Insert/
    // Remove/indexer members, all of which still bump Revision as usual) is the only thing
    // that can make it diverge again. LineageId is carried forward the same way, so a
    // same-statement clone also keeps proving "this is still the very same physical row
    // store" even when Revision alone would be ambiguous (see LineageId's doc comment).
    internal void ReplaceContentsPreservingRevision(RowStore source)
    {
        _rows.Clear();
        foreach (var row in source._rows)
            _rows.Add(row.ToArray());
        Revision = source.Revision;
        LineageId = source.LineageId;
    }

    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();
}

internal sealed class EmbeddedTable
{
    private readonly Dictionary<string, int> _columnIndices;
    private bool _hasEffectivePrimaryKeyConflictAlgorithm;
    private InsertConflictAlgorithm? _effectivePrimaryKeyConflictAlgorithm;
    private int[]? _cachedRowidScanOrder;
    private long _cachedRowidScanOrderRevision = -1;
    private Dictionary<long, int>? _cachedRowIdPositions;
    private long _cachedRowIdPositionsRevision = -1;
    private int _cachedRowIdPositionsCount = -1;
    private readonly Dictionary<string, (long Revision, int[] Order)> _cachedIndexScanOrders =
        new(StringComparer.OrdinalIgnoreCase);

    public EmbeddedTable(
        string name,
        IReadOnlyList<EmbeddedColumn> columns,
        bool withoutRowid = false,
        IReadOnlyList<TablePrimaryKeyColumn>? tablePrimaryKey = null,
        IReadOnlyList<TableUniqueConstraint>? uniqueConstraints = null,
        IReadOnlyList<CheckConstraint>? checkConstraints = null,
        InsertConflictAlgorithm? primaryKeyConflictAlgorithm = null,
        string? primaryKeyConstraintName = null,
        int? primaryKeyDeclarationOrder = null,
        IReadOnlyList<ForeignKeyDefinition>? tableForeignKeys = null,
        bool strict = false)
    {
        Name = name;
        ColumnDefinitions = columns
            .Select(column => strict
                    && string.Equals(
                        column.DeclaredType?.Trim(),
                        "ANY",
                        StringComparison.OrdinalIgnoreCase)
                ? column with { StrictAny = true }
                : column)
            .ToArray();
        Columns = ColumnDefinitions.Select(column => column.Name).ToArray();
        _columnIndices = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        for (var index = 0; index < Columns.Length; index++)
        {
            if (!_columnIndices.TryAdd(Columns[index], index))
                throw new EmbeddedSqlException($"duplicate column name: {Columns[index]}");
        }

        WithoutRowid = withoutRowid;
        Strict = strict;
        if (Strict)
            ValidateStrictColumnTypes();
        TableLevelPrimaryKey = tablePrimaryKey is null
            ? null
            : Array.AsReadOnly(tablePrimaryKey.ToArray());
        TableUniqueConstraints = Array.AsReadOnly((uniqueConstraints ?? []).ToArray());
        CheckConstraints = Array.AsReadOnly((checkConstraints ?? []).ToArray());
        TableForeignKeys = Array.AsReadOnly((tableForeignKeys ?? []).ToArray());
        TablePrimaryKeyConflictAlgorithm = primaryKeyConflictAlgorithm;
        TablePrimaryKeyConstraintName = primaryKeyConstraintName;
        TablePrimaryKeyDeclarationOrder = primaryKeyDeclarationOrder;
        PrimaryKeyColumns = Array.AsReadOnly(
            ResolvePrimaryKeyColumns(ColumnDefinitions, TableLevelPrimaryKey, _columnIndices).ToArray());
        PrimaryKeySchema = CreatePrimaryKeySchema(ColumnDefinitions, TableLevelPrimaryKey, PrimaryKeyColumns);

        // A WITHOUT ROWID table has no rowid, so no column can alias one; a rowid table
        // keeps SQLite's single-column INTEGER PRIMARY KEY alias rule.
        RowidAliasColumnIndex = withoutRowid
            ? -1
            : ComputeRowidAliasColumnIndex(
                ColumnDefinitions,
                TableLevelPrimaryKey,
                PrimaryKeyColumns);
        var columnAutoIncrement = ColumnDefinitions
            .Select((column, index) => (column, index))
            .Where(entry => entry.column.AutoIncrement)
            .Select(entry => entry.index)
            .ToArray();
        var tableAutoIncrement = TableLevelPrimaryKey?
            .Where(column => column.AutoIncrement)
            .Select(column => _columnIndices[column.Name])
            .ToArray() ?? [];
        var autoIncrementColumns = columnAutoIncrement.Concat(tableAutoIncrement).ToArray();
        if (autoIncrementColumns.Length > 0)
        {
            if (withoutRowid)
                throw new EmbeddedSqlException("AUTOINCREMENT not allowed on WITHOUT ROWID tables");
            if (autoIncrementColumns.Length != 1
                || RowidAliasColumnIndex < 0
                || autoIncrementColumns[0] != RowidAliasColumnIndex)
            {
                throw new EmbeddedSqlException("AUTOINCREMENT is only allowed on an INTEGER PRIMARY KEY");
            }

            IsAutoIncrement = true;
        }

        GeneratedColumnOrder = ValidateAndOrderGeneratedColumns(ColumnDefinitions, PrimaryKeyColumns, _columnIndices);
        RefreshForeignKeys();
        ValidateForeignKeyChildColumns();

        CreateConstraintIndexes();
        ValidateSchemaExpressions();
    }

    private void CreateConstraintIndexes()
    {
        if (WithoutRowid)
        {
            CreateWithoutRowidConstraintIndexes();
            return;
        }

        var autoIndex = 0;
        for (var columnIndex = 0; columnIndex < ColumnDefinitions.Length; columnIndex++)
        {
            var column = ColumnDefinitions[columnIndex];
            var constraints = new List<(
                int DeclarationOrder,
                int FallbackOrder,
                EmbeddedIndexOrigin Origin,
                InsertConflictAlgorithm? ConflictAlgorithm,
                bool Descending)>();
            if (column.PrimaryKey && !HasRowidAlias)
            {
                constraints.Add((
                    column.PrimaryKeyDeclarationOrder ?? 0,
                    0,
                    EmbeddedIndexOrigin.PrimaryKey,
                    column.PrimaryKeyConflictAlgorithm,
                    column.PrimaryKeyDescending));
            }
            if (column.Unique)
            {
                constraints.Add((
                    column.UniqueDeclarationOrder ?? 1,
                    1,
                    EmbeddedIndexOrigin.UniqueConstraint,
                    column.UniqueConflictAlgorithm,
                    Descending: false));
            }

            foreach (var constraint in constraints
                         .OrderBy(constraint => constraint.DeclarationOrder)
                         .ThenBy(constraint => constraint.FallbackOrder))
            {
                AddConstraint(
                    [new EmbeddedIndexColumn(
                        column.Name,
                        columnIndex,
                        column.Collation,
                        constraint.Descending)],
                    constraint.Origin,
                    constraint.ConflictAlgorithm);
            }
        }

        foreach (var constraint in GetTableKeyConstraintsInDeclarationOrder())
        {
            if (constraint.IsPrimaryKey && HasRowidAlias)
                continue;

            AddConstraint(
                constraint.Columns,
                constraint.IsPrimaryKey
                    ? EmbeddedIndexOrigin.PrimaryKey
                    : EmbeddedIndexOrigin.UniqueConstraint,
                constraint.ConflictAlgorithm);
        }

        void AddConstraint(
            EmbeddedIndexColumn[] columns,
            EmbeddedIndexOrigin origin,
            InsertConflictAlgorithm? conflictAlgorithm)
        {
            var existingPosition = Indexes.FindIndex(index =>
                index.Origin != EmbeddedIndexOrigin.Explicit
                && SameConstraintKey(index.Columns, columns));
            if (existingPosition >= 0)
            {
                var existing = Indexes[existingPosition];
                if (existing.ConflictAlgorithm is { } existingAlgorithm
                    && conflictAlgorithm is { } newAlgorithm
                    && existingAlgorithm != newAlgorithm)
                {
                    throw new EmbeddedSqlException("conflicting ON CONFLICT clauses specified");
                }

                var mergedOrigin = existing.Origin == EmbeddedIndexOrigin.PrimaryKey
                    || origin == EmbeddedIndexOrigin.PrimaryKey
                        ? EmbeddedIndexOrigin.PrimaryKey
                        : EmbeddedIndexOrigin.UniqueConstraint;
                var mergedConflictAlgorithm = existing.ConflictAlgorithm ?? conflictAlgorithm;
                Indexes[existingPosition] = existing with
                {
                    Origin = mergedOrigin,
                    ConflictAlgorithm = mergedConflictAlgorithm,
                };
                if (mergedOrigin == EmbeddedIndexOrigin.PrimaryKey)
                    SetEffectivePrimaryKeyConflictAlgorithm(mergedConflictAlgorithm);
                return;
            }

            autoIndex++;
            if (origin == EmbeddedIndexOrigin.PrimaryKey)
                SetEffectivePrimaryKeyConflictAlgorithm(conflictAlgorithm);
            Indexes.Add(new EmbeddedIndex(
                $"sqlite_autoindex_{Name}_{autoIndex}",
                Unique: true,
                columns,
                origin,
                conflictAlgorithm,
                ConstraintOrdinal: autoIndex));
        }

        bool SameConstraintKey(
            IReadOnlyList<EmbeddedIndexColumn> left,
            IReadOnlyList<EmbeddedIndexColumn> right)
        {
            if (left.Count != right.Count)
                return false;

            for (var position = 0; position < left.Count; position++)
            {
                if (left[position].ColumnIndex != right[position].ColumnIndex)
                    return false;
                var leftCollation = left[position].Collation
                    ?? ColumnDefinitions[left[position].ColumnIndex].Collation
                    ?? "BINARY";
                var rightCollation = right[position].Collation
                    ?? ColumnDefinitions[right[position].ColumnIndex].Collation
                    ?? "BINARY";
                if (!string.Equals(leftCollation, rightCollation, StringComparison.OrdinalIgnoreCase))
                    return false;
            }

            return true;
        }
    }

    private void RefreshForeignKeys()
    {
        ForeignKeys = Array.AsReadOnly(
            ColumnDefinitions
                .SelectMany(column => column.ForeignKeyConstraints)
                .Concat(TableForeignKeys)
                .ToArray());
    }

    private void CreateWithoutRowidConstraintIndexes()
    {
        var autoIndex = 0;
        var groups = new List<(
            EmbeddedIndexColumn[] Columns,
            bool IsPrimaryKey,
            EmbeddedIndex? Index,
            int ConstraintOrdinal,
            InsertConflictAlgorithm? ConflictAlgorithm)>();

        for (var columnIndex = 0; columnIndex < ColumnDefinitions.Length; columnIndex++)
        {
            var column = ColumnDefinitions[columnIndex];
            var constraints = new List<(
                int DeclarationOrder,
                int FallbackOrder,
                bool IsPrimaryKey,
                InsertConflictAlgorithm? ConflictAlgorithm,
                bool Descending)>();
            if (column.PrimaryKey)
            {
                constraints.Add((
                    column.PrimaryKeyDeclarationOrder ?? 0,
                    0,
                    IsPrimaryKey: true,
                    column.PrimaryKeyConflictAlgorithm,
                    column.PrimaryKeyDescending));
            }
            if (column.Unique)
            {
                constraints.Add((
                    column.UniqueDeclarationOrder ?? 1,
                    1,
                    IsPrimaryKey: false,
                    column.UniqueConflictAlgorithm,
                    Descending: false));
            }

            foreach (var constraint in constraints
                         .OrderBy(constraint => constraint.DeclarationOrder)
                         .ThenBy(constraint => constraint.FallbackOrder))
            {
                AddConstraint(
                    [new EmbeddedIndexColumn(
                        column.Name,
                        columnIndex,
                        column.Collation,
                        constraint.Descending)],
                    constraint.IsPrimaryKey,
                    constraint.ConflictAlgorithm);
            }
        }

        foreach (var constraint in GetTableKeyConstraintsInDeclarationOrder())
        {
            AddConstraint(
                constraint.Columns,
                constraint.IsPrimaryKey,
                constraint.ConflictAlgorithm);
        }
        void AddConstraint(
            EmbeddedIndexColumn[] columns,
            bool isPrimaryKey,
            InsertConflictAlgorithm? conflictAlgorithm)
        {
            var existingPosition = groups.FindIndex(group => SameConstraintKey(group.Columns, columns));
            if (existingPosition >= 0)
            {
                var existing = groups[existingPosition];
                if (existing.ConflictAlgorithm is { } existingAlgorithm
                    && conflictAlgorithm is { } newAlgorithm
                    && existingAlgorithm != newAlgorithm)
                {
                    throw new EmbeddedSqlException("conflicting ON CONFLICT clauses specified");
                }

                var mergedConflictAlgorithm = existing.ConflictAlgorithm ?? conflictAlgorithm;
                var mergedIsPrimaryKey = existing.IsPrimaryKey || isPrimaryKey;
                var mergedIndex = existing.Index;
                if (mergedIsPrimaryKey)
                {
                    if (mergedIndex is not null)
                    {
                        WithoutRowidPrimaryKeyIndexName = mergedIndex.Name;
                        Indexes.Remove(mergedIndex);
                    }
                    mergedIndex = null;
                    PrimaryKeyConstraintOrdinal = existing.ConstraintOrdinal;
                    SetEffectivePrimaryKeyConflictAlgorithm(mergedConflictAlgorithm);
                    PrimaryKeyColumns = Array.AsReadOnly(existing.Columns
                        .Select(column => (column.ColumnIndex, column.Descending))
                        .ToArray());
                    PrimaryKeySchema = CreatePrimaryKeySchema(ColumnDefinitions, existing.Columns);
                }
                else if (mergedIndex is not null
                    && mergedIndex.ConflictAlgorithm != mergedConflictAlgorithm)
                {
                    var indexPosition = Indexes.IndexOf(mergedIndex);
                    mergedIndex = mergedIndex with
                    {
                        ConflictAlgorithm = mergedConflictAlgorithm,
                    };
                    Indexes[indexPosition] = mergedIndex;
                }

                groups[existingPosition] = (
                    existing.Columns,
                    mergedIsPrimaryKey,
                    mergedIndex,
                    existing.ConstraintOrdinal,
                    mergedConflictAlgorithm);
                return;
            }

            autoIndex++;
            if (isPrimaryKey)
            {
                PrimaryKeyConstraintOrdinal = autoIndex;
                SetEffectivePrimaryKeyConflictAlgorithm(conflictAlgorithm);
                PrimaryKeySchema = CreatePrimaryKeySchema(ColumnDefinitions, columns);
            }
            EmbeddedIndex? index = null;
            if (isPrimaryKey)
            {
                WithoutRowidPrimaryKeyIndexName = $"sqlite_autoindex_{Name}_{autoIndex}";
            }
            else
            {
                index = new EmbeddedIndex(
                    $"sqlite_autoindex_{Name}_{autoIndex}",
                    Unique: true,
                    columns,
                    EmbeddedIndexOrigin.UniqueConstraint,
                    conflictAlgorithm,
                    ConstraintOrdinal: autoIndex);
                Indexes.Add(index);
            }

            groups.Add((columns, isPrimaryKey, index, autoIndex, conflictAlgorithm));
        }

        bool SameConstraintKey(
            IReadOnlyList<EmbeddedIndexColumn> left,
            IReadOnlyList<EmbeddedIndexColumn> right)
        {
            if (left.Count != right.Count)
                return false;

            for (var index = 0; index < left.Count; index++)
            {
                if (left[index].ColumnIndex != right[index].ColumnIndex)
                    return false;
                var leftCollation = left[index].Collation
                    ?? ColumnDefinitions[left[index].ColumnIndex].Collation
                    ?? "BINARY";
                var rightCollation = right[index].Collation
                    ?? ColumnDefinitions[right[index].ColumnIndex].Collation
                    ?? "BINARY";
                if (!string.Equals(leftCollation, rightCollation, StringComparison.OrdinalIgnoreCase))
                    return false;
            }

            return true;
        }
    }

    private void SetEffectivePrimaryKeyConflictAlgorithm(InsertConflictAlgorithm? conflictAlgorithm)
    {
        _hasEffectivePrimaryKeyConflictAlgorithm = true;
        _effectivePrimaryKeyConflictAlgorithm = conflictAlgorithm;
    }

    internal bool TryGetLegacyImplicitIndex(string indexName, out EmbeddedIndex? index)
    {
        index = null;
        if (WithoutRowid)
            return false;

        var autoIndex = 0;
        for (var columnIndex = 0; columnIndex < ColumnDefinitions.Length; columnIndex++)
        {
            var column = ColumnDefinitions[columnIndex];
            if (!column.Unique)
                continue;

            autoIndex++;
            var candidate = new EmbeddedIndex(
                $"sqlite_autoindex_{Name}_{autoIndex}",
                Unique: true,
                [new EmbeddedIndexColumn(column.Name, columnIndex, column.Collation, Descending: false)],
                EmbeddedIndexOrigin.UniqueConstraint,
                column.UniqueConflictAlgorithm,
                ConstraintOrdinal: autoIndex);
            if (string.Equals(candidate.Name, indexName, StringComparison.OrdinalIgnoreCase))
            {
                index = candidate;
                return true;
            }
        }

        foreach (var constraint in GetTableKeyConstraintsInDeclarationOrder())
        {
            if (constraint.IsPrimaryKey && HasRowidAlias)
                continue;

            autoIndex++;
            var candidate = new EmbeddedIndex(
                $"sqlite_autoindex_{Name}_{autoIndex}",
                Unique: true,
                constraint.Columns,
                constraint.IsPrimaryKey
                    ? EmbeddedIndexOrigin.PrimaryKey
                    : EmbeddedIndexOrigin.UniqueConstraint,
                constraint.ConflictAlgorithm,
                ConstraintOrdinal: autoIndex);
            if (string.Equals(candidate.Name, indexName, StringComparison.OrdinalIgnoreCase))
            {
                index = candidate;
                return true;
            }
        }

        return false;
    }

    private IReadOnlyList<(
        EmbeddedIndexColumn[] Columns,
        bool IsPrimaryKey,
        InsertConflictAlgorithm? ConflictAlgorithm)> GetTableKeyConstraintsInDeclarationOrder()
    {
        var constraints = new List<(
            int DeclarationOrder,
            int FallbackOrder,
            EmbeddedIndexColumn[] Columns,
            bool IsPrimaryKey,
            InsertConflictAlgorithm? ConflictAlgorithm)>();
        if (TableLevelPrimaryKey is not null)
        {
            constraints.Add((
                TablePrimaryKeyDeclarationOrder ?? -1,
                0,
                ResolveConstraintIndexColumns(TableLevelPrimaryKey, "PRIMARY KEY"),
                IsPrimaryKey: true,
                TablePrimaryKeyConflictAlgorithm));
        }

        for (var index = 0; index < TableUniqueConstraints.Count; index++)
        {
            var constraint = TableUniqueConstraints[index];
            constraints.Add((
                constraint.DeclarationOrder,
                index + 1,
                ResolveConstraintIndexColumns(constraint.Columns, "UNIQUE"),
                IsPrimaryKey: false,
                constraint.ConflictAlgorithm));
        }

        return constraints
            .OrderBy(constraint => constraint.DeclarationOrder)
            .ThenBy(constraint => constraint.FallbackOrder)
            .Select(constraint => (
                constraint.Columns,
                constraint.IsPrimaryKey,
                constraint.ConflictAlgorithm))
            .ToArray();
    }

    private void ValidateForeignKeyChildColumns()
    {
        foreach (var foreignKey in ForeignKeys)
        {
            if (foreignKey.ChildColumns.Count == 0)
                throw new EmbeddedSqlException("foreign key constraint must contain at least one child column");

            foreach (var childColumn in foreignKey.ChildColumns)
            {
                if (!_columnIndices.ContainsKey(childColumn))
                {
                    throw new EmbeddedSqlException(
                        $"unknown column \"{childColumn}\" in foreign key definition");
                }
            }
        }
    }

    private EmbeddedIndexColumn[] ResolveConstraintIndexColumns(
        IReadOnlyList<TablePrimaryKeyColumn> terms,
        string constraint)
    {
        if (terms.Count == 0)
            throw new EmbeddedSqlException($"{constraint} constraint must contain at least one column");

        var columns = new EmbeddedIndexColumn[terms.Count];
        var seen = new HashSet<int>();
        for (var position = 0; position < terms.Count; position++)
        {
            var term = terms[position];
            if (!_columnIndices.TryGetValue(term.Name, out var columnIndex))
                throw new EmbeddedSqlException($"no such column: {term.Name}");
            if (!seen.Add(columnIndex))
                throw new EmbeddedSqlException($"duplicate column name: {term.Name}");

            columns[position] = new EmbeddedIndexColumn(
                ColumnDefinitions[columnIndex].Name,
                columnIndex,
                term.Collation ?? ColumnDefinitions[columnIndex].Collation,
                term.Descending);
        }

        return columns;
    }

    private void ValidateSchemaExpressions()
    {
        foreach (var column in ColumnDefinitions)
        {
            if (column.DefaultExpression is not null)
                ValidateConstraintExpression(column.DefaultExpression, allowColumns: false, "default value", definingColumn: column.Name);
            foreach (var check in column.CheckConstraints)
                ValidateConstraintExpression(check.Expression, allowColumns: true, "CHECK constraint");
        }

        foreach (var check in CheckConstraints)
            ValidateConstraintExpression(check.Expression, allowColumns: true, "CHECK constraint");
    }

    private void ValidateConstraintExpression(Expression expression, bool allowColumns, string context, string? definingColumn = null)
    {
        switch (expression)
        {
            case LiteralExpression:
            case CurrentTimeExpression:
                return;
            case ColumnExpression column:
                // A bare TRUE/FALSE keyword is the integer literal 1/0 unless a column of that
                // name is in scope. DEFAULT expressions resolve with no columns in scope at all,
                // so there the keyword is always the literal.
                if (column.BooleanKeyword is not null && (!allowColumns || !IsConstraintColumn(column)))
                    return;
                if (!allowColumns)
                    throw new EmbeddedSqlException($"default value of column [{definingColumn}] is not constant");
                if (!IsConstraintColumn(column))
                    throw new EmbeddedSqlException($"no such column: {column.Name}");
                return;
            case ParameterExpression:
                throw new EmbeddedSqlException($"parameters are prohibited in {context}s");
            case RowValueExpression rowValue:
                foreach (var value in rowValue.Values)
                    ValidateConstraintExpression(value, allowColumns, context, definingColumn);
                return;
            case ScalarSubqueryExpression or ExistsExpression or InSubqueryExpression:
                throw new EmbeddedSqlException($"subqueries are prohibited in {context}s");
            case StarExpression or QualifiedStarExpression:
                throw new EmbeddedSqlException($"cannot use '*' in a {context}");
            case FunctionExpression function:
                // SQLite resolves functions in CHECK constraints at CREATE time: unknown names
                // and aggregates fail immediately. DEFAULT expressions defer all function
                // resolution to insert time, so any scalar name - even unknown, non-deterministic,
                // or aggregate - is accepted at CREATE and errors only when the default value is
                // materialized for a row.
                if (allowColumns)
                {
                    // SQLite names the offending call in its CHECK diagnostic: window calls are a
                    // window misuse, aggregate calls an aggregate misuse.
                    if (function.Window is not null || SqliteBuiltinFunctions.IsWindowOnly(function.Name))
                        throw new EmbeddedSqlException($"misuse of window function {function.Name}()");
                    if ((function.CountStar
                            && string.Equals(function.Name, "COUNT", StringComparison.OrdinalIgnoreCase))
                        || function.Distinct || function.Filter is not null
                        || EmbeddedDatabase.IsBuiltInAggregate(function)
                        || EmbeddedDatabase.IsManagedPercentileAggregate(function.Name))
                    {
                        throw new EmbeddedSqlException($"misuse of aggregate function {function.Name}()");
                    }

                    // fts_score() reads the covering index's corpus statistics, so its value for one
                    // row depends on every other row and on which indexes exist. A CHECK constraint
                    // evaluated during the very statement that is mutating that corpus has no
                    // well-defined answer, so it is rejected at CREATE time the way a generated
                    // column is.
                    if (IsCorpusDependentMethodFunction(function.Name))
                    {
                        throw new EmbeddedSqlException(
                            $"non-deterministic functions are prohibited in {context}s");
                    }
                }

                foreach (var argument in function.Arguments)
                    ValidateConstraintExpression(argument, allowColumns, context, definingColumn);
                return;
            case CollationExpression collation:
                ValidateConstraintExpression(collation.Expression, allowColumns, context, definingColumn);
                return;
            case CastExpression cast:
                ValidateConstraintExpression(cast.Expression, allowColumns, context, definingColumn);
                return;
            case CaseExpression @case:
                if (@case.Operand is not null)
                    ValidateConstraintExpression(@case.Operand, allowColumns, context, definingColumn);
                foreach (var clause in @case.Clauses)
                {
                    ValidateConstraintExpression(clause.When, allowColumns, context, definingColumn);
                    ValidateConstraintExpression(clause.Then, allowColumns, context, definingColumn);
                }
                if (@case.Else is not null)
                    ValidateConstraintExpression(@case.Else, allowColumns, context, definingColumn);
                return;
            case LikeExpression like:
                ValidateConstraintExpression(like.Value, allowColumns, context, definingColumn);
                ValidateConstraintExpression(like.Pattern, allowColumns, context, definingColumn);
                if (like.Escape is not null)
                    ValidateConstraintExpression(like.Escape, allowColumns, context, definingColumn);
                return;
            case GlobExpression glob:
                ValidateConstraintExpression(glob.Value, allowColumns, context, definingColumn);
                ValidateConstraintExpression(glob.Pattern, allowColumns, context, definingColumn);
                return;
            case InExpression @in:
                ValidateConstraintExpression(@in.Value, allowColumns, context, definingColumn);
                foreach (var value in @in.Values)
                    ValidateConstraintExpression(value, allowColumns, context, definingColumn);
                return;
            case BetweenExpression between:
                ValidateConstraintExpression(between.Value, allowColumns, context, definingColumn);
                ValidateConstraintExpression(between.Lower, allowColumns, context, definingColumn);
                ValidateConstraintExpression(between.Upper, allowColumns, context, definingColumn);
                return;
            case UnaryExpression unary:
                ValidateConstraintExpression(unary.Operand, allowColumns, context, definingColumn);
                return;
            case BinaryExpression binary:
                ValidateConstraintExpression(binary.Left, allowColumns, context, definingColumn);
                ValidateConstraintExpression(binary.Right, allowColumns, context, definingColumn);
                return;
            default:
                throw new EmbeddedSqlException($"expression is not allowed in a {context}");
        }
    }

    private bool IsConstraintColumn(ColumnExpression column)
    {
        if (column.Qualifier is not null
            && !string.Equals(column.Qualifier, Name, StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var bare = column.UnqualifiedName ?? column.Name;
        return _columnIndices.ContainsKey(bare)
            || (HasRowid && IsRowidAliasName(bare));
    }

    public bool HasQualifiedCheckReferences()
    {
        foreach (var check in ColumnDefinitions.SelectMany(column => column.CheckConstraints).Concat(CheckConstraints))
        {
            var references = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (CollectColumnReferences(check.Expression, references))
                return true;
        }

        return false;
    }

    public string Name { get; private set; }

    public string[] Columns { get; private set; }

    public EmbeddedColumn[] ColumnDefinitions { get; private set; }

    public RowStore Rows { get; } = new();

    // Parallel to <see cref="Rows"/> (index-aligned): the SQLite rowid backing each row.
    // Every row-mutating site keeps this list the same length and order as Rows.
    public List<long> RowIds { get; } = [];

    // Index of the INTEGER PRIMARY KEY column that aliases the rowid, or -1 when the
    // table has a hidden rowid. A single column-level INTEGER PRIMARY KEY (declared type
    // exactly "INTEGER", ascending) is the alias, matching SQLite.
    public int RowidAliasColumnIndex { get; private set; }

    public bool HasRowidAlias => RowidAliasColumnIndex >= 0;

    public bool IsAutoIncrement { get; }

    public string? WithoutRowidPrimaryKeyIndexName { get; private set; }

    public InsertConflictAlgorithm? RowidAliasConflictAlgorithm
        => !HasRowidAlias
            ? null
            : TableLevelPrimaryKey is not null
                ? TablePrimaryKeyConflictAlgorithm
                : ColumnDefinitions[RowidAliasColumnIndex].PrimaryKeyConflictAlgorithm;

    // True for an ordinary rowid table; false for a WITHOUT ROWID table, which has no
    // hidden rowid and therefore rejects rowid/_rowid_/oid references.
    public bool HasRowid => !WithoutRowid;

    public bool WithoutRowid { get; }

    internal IEnumerable<int> GetScanOrderIndices()
    {
        if (!HasRowid)
        {
            for (var index = 0; index < Rows.Count; index++)
                yield return index;
            yield break;
        }

        if (_cachedRowidScanOrder is null
            || _cachedRowidScanOrderRevision != Rows.Revision
            || _cachedRowidScanOrder.Length != Rows.Count)
        {
            if (RowIds.Count != Rows.Count)
                throw new InvalidOperationException($"Table '{Name}' has inconsistent row identity metadata.");

            _cachedRowidScanOrder = Enumerable.Range(0, Rows.Count).ToArray();
            Array.Sort(
                _cachedRowidScanOrder,
                (left, right) => RowIds[left].CompareTo(RowIds[right]));
            _cachedRowidScanOrderRevision = Rows.Revision;
        }

        foreach (var index in _cachedRowidScanOrder)
            yield return index;
    }

    // STAT4 validates a small sample set repeatedly while planning. Cache the rowid map by
    // RowStore revision, but verify the live slot so same-count rowid replacements fail closed.
    internal int TryGetRowIdPosition(long rowId, out bool cacheRebuilt)
    {
        cacheRebuilt = false;
        if (!HasRowid || RowIds.Count != Rows.Count)
        {
            InvalidateCache();
            return -1;
        }

        var builtThisCall = false;
        if (_cachedRowIdPositions is null
            || _cachedRowIdPositionsRevision != Rows.Revision
            || _cachedRowIdPositionsCount != RowIds.Count)
        {
            RebuildCache();
            cacheRebuilt = true;
            builtThisCall = true;
        }

        if (TryReadLivePosition(rowId, out var position))
            return position;
        if (builtThisCall)
            return -1;

        // A same-count rowid replacement can bypass RowStore.Revision. Rebuild once on a stale
        // hit or miss, then let the caller's live index-key validation decide whether to trust it.
        RebuildCache();
        cacheRebuilt = true;
        return TryReadLivePosition(rowId, out position) ? position : -1;

        bool TryReadLivePosition(long id, out int found)
        {
            if (_cachedRowIdPositions!.TryGetValue(id, out found)
                && found >= 0
                && found < RowIds.Count
                && RowIds[found] == id)
            {
                return true;
            }

            found = -1;
            return false;
        }

        void RebuildCache()
        {
            var positions = new Dictionary<long, int>(RowIds.Count);
            for (var index = 0; index < RowIds.Count; index++)
                positions.TryAdd(RowIds[index], index);
            _cachedRowIdPositions = positions;
            _cachedRowIdPositionsRevision = Rows.Revision;
            _cachedRowIdPositionsCount = RowIds.Count;
        }

        void InvalidateCache()
        {
            _cachedRowIdPositions = null;
            _cachedRowIdPositionsRevision = -1;
            _cachedRowIdPositionsCount = -1;
        }
    }

    internal IReadOnlyList<int> GetOrCreateIndexScanOrder(
        string indexName,
        Func<int[]> build)
    {
        ArgumentException.ThrowIfNullOrEmpty(indexName);
        ArgumentNullException.ThrowIfNull(build);
        if (_cachedIndexScanOrders.TryGetValue(indexName, out var cached)
            && cached.Revision == Rows.Revision)
        {
            return cached.Order;
        }

        var order = build();
        _cachedIndexScanOrders[indexName] = (Rows.Revision, order);
        return order;
    }

    public bool Strict { get; }

    // SQLite stores the schema SQL of a CREATE TABLE AS SELECT result in compact form
    // ("CREATE TABLE t(a,b)" — no space before '(' and none after ','). The flag only
    // affects catalog-regenerated schema text; ALTER TABLE rebuilds preserve it because
    // SQLite splices added columns into the original statement text.
    public bool SchemaSqlCompact { get; internal set; }

    // The original CREATE TABLE statement text, stored verbatim (minus the trailing ';')
    // the way SQLite keeps it in sqlite_schema. Catalog dumps and persistence prefer this
    // over regenerating from the model, so quote style, keyword case, and internal spacing
    // round-trip. Null only for tables whose schema was generated internally (CTAS before
    // regeneration, ALTER rebuilds), in which case the caller regenerates.
    public string? Sql { get; internal set; }

    // The table-level PRIMARY KEY(...) clause as declared, retained so the schema can be
    // regenerated verbatim; null when the primary key (if any) is column-level.
    public IReadOnlyList<TablePrimaryKeyColumn>? TableLevelPrimaryKey { get; }

    public IReadOnlyList<TableUniqueConstraint> TableUniqueConstraints { get; }

    public IReadOnlyList<CheckConstraint> CheckConstraints { get; }

    public IReadOnlyList<ForeignKeyDefinition> TableForeignKeys { get; }

    public InsertConflictAlgorithm? TablePrimaryKeyConflictAlgorithm { get; }

    public InsertConflictAlgorithm? PrimaryKeyConflictAlgorithm
        => _hasEffectivePrimaryKeyConflictAlgorithm
            ? _effectivePrimaryKeyConflictAlgorithm
            : TableLevelPrimaryKey is not null
                ? TablePrimaryKeyConflictAlgorithm
                : PrimaryKeyColumns.Count == 1
                    ? ColumnDefinitions[PrimaryKeyColumns[0].Index].PrimaryKeyConflictAlgorithm
                    : null;

    public string? TablePrimaryKeyConstraintName { get; }

    public int? TablePrimaryKeyDeclarationOrder { get; }

    public int? PrimaryKeyConstraintOrdinal { get; private set; }

    // The resolved primary-key columns (index + direction) in key order. Empty when the
    // table has no primary key. Used for WITHOUT ROWID ordering/uniqueness and table_info.
    public IReadOnlyList<(int Index, bool Descending)> PrimaryKeyColumns { get; private set; }

    // The immutable physical-key descriptor in declaration order. A table-level COLLATE
    // overrides the declared column collation; absent declarations use SQLite's BINARY
    // default. File-backed index-table support must consume this instead of reconstructing
    // key metadata from lossy column flags.
    public SqlitePrimaryKeySchema? PrimaryKeySchema { get; private set; }

    // Column indices of generated columns in dependency (topological) order, so evaluating
    // them in sequence always sees the values a later generated column depends on. Mutable so
    // ALTER TABLE ADD COLUMN can append the newly added generated column (its dependencies are
    // all pre-existing columns, so appending preserves the topological order).
    public IReadOnlyList<int> GeneratedColumnOrder { get; private set; }

    public bool HasGeneratedColumns => GeneratedColumnOrder.Count > 0;

    public bool HasVirtualGeneratedColumns => ColumnDefinitions.Any(
        column => column.IsGenerated && !column.GeneratedStored);

    // Generated columns are recomputed whenever any of their (transitive) dependencies is
    // assigned, so such an UPDATE also affects foreign keys that reference those generated
    // columns even when the generated column itself is not assigned (SQLite's
    // columns_affected_by_update semantics). GeneratedColumnOrder is topological, so a single
    // pass propagates transitive dependents.
    internal void ExpandAssignedColumnsThroughGeneratedColumns(HashSet<int> assignedColumns)
    {
        if (!HasGeneratedColumns)
            return;

        foreach (var columnIndex in GeneratedColumnOrder)
        {
            var referencedNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            CollectColumnReferences(ColumnDefinitions[columnIndex].GenerationExpression!, referencedNames);
            foreach (var name in referencedNames)
            {
                if (_columnIndices.TryGetValue(name, out var dependencyIndex)
                    && assignedColumns.Contains(dependencyIndex))
                {
                    assignedColumns.Add(columnIndex);
                    break;
                }
            }
        }
    }

    public bool HasCheckConstraints => CheckConstraints.Count > 0
        || ColumnDefinitions.Any(column => column.CheckConstraints.Count > 0);

    public bool HasNonDefaultConflictAlgorithms => TablePrimaryKeyConflictAlgorithm is not null
        || TableUniqueConstraints.Any(constraint => constraint.ConflictAlgorithm is not null)
        || ColumnDefinitions.Any(column =>
            column.PrimaryKeyConflictAlgorithm is not null
            || column.NotNullConflictAlgorithm is not null
            || column.UniqueConflictAlgorithm is not null);

    public IReadOnlyList<ForeignKeyDefinition> ForeignKeys { get; private set; } = [];

    // The 1-based position of a column within the primary key, or 0 when it is not part of
    // the primary key. Mirrors the value SQLite reports in PRAGMA table_info.pk.
    public int PrimaryKeyPosition(int columnIndex)
    {
        for (var position = 0; position < PrimaryKeyColumns.Count; position++)
        {
            if (PrimaryKeyColumns[position].Index == columnIndex)
                return position + 1;
        }

        return 0;
    }

    public bool IsPrimaryKeyColumn(int columnIndex) => PrimaryKeyPosition(columnIndex) > 0;

    // Applies the column's declared-type affinity to a value, used to coerce a computed
    // generated-column result the same way an inserted value is coerced.
    public SqlValue ApplyColumnAffinity(EmbeddedColumn column, SqlValue value)
    {
        var result = CoerceColumnAffinity(column, value);
        ValidateStrictValue(column, result);
        return result;
    }

    public SqlValue CoerceColumnAffinity(EmbeddedColumn column, SqlValue value)
        => ApplyAffinity(column, value, Strict);

    // True when the column's declared-type affinity is numeric (INTEGER/REAL/NUMERIC): the
    // subset where a stored INTEGER/REAL/NULL value feeds arithmetic unchanged, so a compiled
    // Arithmetic opcode over the column matches the tree-walking evaluator byte-for-byte. TEXT
    // and BLOB affinity columns decline (fall back to the evaluator), which applies the numeric
    // affinity the Arithmetic opcode deliberately does not.
    public bool ColumnHasNumericAffinity(int columnIndex)
    {
        var affinity = GetColumnAffinity(ColumnDefinitions[columnIndex]);
        return affinity is ColumnAffinity.Integer or ColumnAffinity.Real or ColumnAffinity.Numeric;
    }

    public ColumnAffinity GetColumnAffinity(EmbeddedColumn column)
        => Strict
            && string.Equals(column.DeclaredType?.Trim(), "ANY", StringComparison.OrdinalIgnoreCase)
                ? ColumnAffinity.Blob
                : GetAffinity(column.DeclaredType);

    public List<EmbeddedIndex> Indexes { get; } = [];

    /// <summary>
    /// Live attachments for this table's method indexes, keyed by index name. The cache is part of
    /// the catalog snapshot, so a transaction, savepoint or DDL rollback discards method state along
    /// with the rows it was derived from.
    /// </summary>
    /// <remarks>
    /// Each entry also remembers the <see cref="EmbeddedIndex"/> instance it was built for. An index
    /// dropped and recreated under the same name produces a new definition object, so a stale
    /// attachment carrying the old <c>WITH</c> options can never be handed out for the new one.
    /// </remarks>
    private readonly Dictionary<string, MethodAttachmentEntry> _methodAttachments =
        new(StringComparer.OrdinalIgnoreCase);

    private Indexing.ManagedIndexMethodJournal? _methodIndexJournal;

    /// <summary>True when at least one method attachment is currently published.</summary>
    public bool HasPublishedMethodAttachments => _methodAttachments.Count > 0;

    /// <summary>Returns the published attachment for an index definition, if it matches.</summary>
    public bool TryGetMethodAttachment(
        EmbeddedIndex index,
        out Indexing.ManagedIndexMethodAttachment attachment)
    {
        if (_methodAttachments.TryGetValue(index.Name, out var entry) && ReferenceEquals(entry.Index, index))
        {
            attachment = entry.Attachment;
            return true;
        }

        attachment = null!;
        return false;
    }

    /// <summary>Returns the published attachment for an index name regardless of definition identity.</summary>
    public bool TryGetMethodAttachmentByName(
        string indexName,
        out Indexing.ManagedIndexMethodAttachment attachment)
    {
        if (_methodAttachments.TryGetValue(indexName, out var entry))
        {
            attachment = entry.Attachment;
            return true;
        }

        attachment = null!;
        return false;
    }

    /// <summary>Publishes a fully constructed attachment and starts journaling mutations for it.</summary>
    public void PublishMethodAttachment(EmbeddedIndex index, Indexing.ManagedIndexMethodAttachment attachment)
    {
        _methodAttachments[index.Name] = new MethodAttachmentEntry(index, attachment);
        _methodIndexJournal ??= new Indexing.ManagedIndexMethodJournal(Rows.Revision);
    }

    /// <summary>Forgets one attachment; the next use re-derives it from the base rows.</summary>
    public void ForgetMethodAttachment(string indexName)
    {
        _methodAttachments.Remove(indexName);
        if (_methodAttachments.Count == 0)
            _methodIndexJournal = null;
    }

    /// <summary>
    /// Records one reported row mutation for incremental method maintenance. No-op until a method
    /// attachment is published, because nothing derives from the rows before then.
    /// </summary>
    public void RecordMethodIndexMutation(long rowId)
        => _methodIndexJournal?.Record(rowId, Rows.Revision);

    /// <summary>The rowids touched since a revision, or null when the range cannot be proven complete.</summary>
    public Indexing.ManagedIndexSourceDelta? TryGetMethodIndexDelta(long sinceRevision)
        => _methodIndexJournal?.TryGetDelta(sinceRevision, Rows.Revision);

    /// <summary>Re-establishes the journal baseline after a method rebuilt from the base rows.</summary>
    public void ResetMethodIndexJournalBaseline(long revision)
        => _methodIndexJournal?.ResetBaseline(revision);

    private readonly record struct MethodAttachmentEntry(
        EmbeddedIndex Index,
        Indexing.ManagedIndexMethodAttachment Attachment);

    /// <summary>True when any index on this table is served by a managed index method.</summary>
    public bool HasMethodIndexes
    {
        get
        {
            foreach (var index in Indexes)
            {
                if (index.IsMethodIndex)
                    return true;
            }

            return false;
        }
    }

    /// <summary>
    /// Adopts <paramref name="source"/>'s rows, explicit indexes and method attachments into this freshly
    /// parsed definition. <c>ParseSchema</c> uses it when a rewritten <c>CREATE TABLE</c> replaces a table
    /// that already holds data: the column shape comes from the new SQL, the content comes from the table
    /// being replaced. It performs the same transfer <see cref="Clone"/> does, in the opposite direction.
    /// </summary>
    internal void AdoptContentFrom(EmbeddedTable source)
    {
        ArgumentNullException.ThrowIfNull(source);
        Rows.ReplaceContentsPreservingRevision(source.Rows);
        RowIds.Clear();
        RowIds.AddRange(source.RowIds);
        Indexes.RemoveAll(index => index.Origin == EmbeddedIndexOrigin.Explicit);
        Indexes.AddRange(source.Indexes.Where(index => index.Origin == EmbeddedIndexOrigin.Explicit));
        source.CopyMethodAttachmentsTo(this);
    }

    private void CopyMethodAttachmentsTo(EmbeddedTable clone)
    {
        // Forked attachments carry no derived state and no journal: a snapshot that is later
        // restored must rebuild from the rows it restored, never replay a delta recorded against
        // rows that no longer exist.
        foreach (var (name, entry) in _methodAttachments)
        {
            var forkedIndex = clone.Indexes.FirstOrDefault(
                candidate => string.Equals(candidate.Name, name, StringComparison.OrdinalIgnoreCase));
            if (forkedIndex is null)
                continue;

            clone._methodAttachments[name] = new MethodAttachmentEntry(forkedIndex, entry.Attachment.Fork());
        }

        if (clone._methodAttachments.Count > 0)
            clone._methodIndexJournal = new Indexing.ManagedIndexMethodJournal(clone.Rows.Revision);
    }

    public int GetColumnIndex(string name)
    {
        if (!_columnIndices.TryGetValue(name, out var index))
            throw new EmbeddedSqlException($"table has no column named {name}");

        return index;
    }

    public bool TryGetColumnIndex(string name, out int index) => _columnIndices.TryGetValue(name, out index);

    // rowid/_rowid_/oid are interchangeable spellings of the rowid pseudo-column in SQLite.
    public static bool IsRowidAliasName(string name)
        => string.Equals(name, "rowid", StringComparison.OrdinalIgnoreCase)
            || string.Equals(name, "_rowid_", StringComparison.OrdinalIgnoreCase)
            || string.Equals(name, "oid", StringComparison.OrdinalIgnoreCase);

    // A rowid alias requires the declared type to be exactly "INTEGER" (case-insensitive,
    // trimmed). Broader integer affinities like "BIGINT" or "INT" are NOT rowid aliases.
    public static bool IsIntegerDeclaredType(string? declaredType)
        => declaredType is not null
            && string.Equals(declaredType.Trim(), "INTEGER", StringComparison.OrdinalIgnoreCase);

    private static int ComputeRowidAliasColumnIndex(
        IReadOnlyList<EmbeddedColumn> columns,
        IReadOnlyList<TablePrimaryKeyColumn>? tablePrimaryKey,
        IReadOnlyList<(int Index, bool Descending)> primaryKeyColumns)
    {
        if (tablePrimaryKey is not null)
        {
            if (primaryKeyColumns.Count != 1)
                return -1;

            var tableCandidate = primaryKeyColumns[0].Index;
            return IsIntegerDeclaredType(columns[tableCandidate].DeclaredType)
                ? tableCandidate
                : -1;
        }

        var primaryKeyCount = 0;
        var candidate = -1;
        for (var index = 0; index < columns.Count; index++)
        {
            if (!columns[index].PrimaryKey)
                continue;

            primaryKeyCount++;
            candidate = index;
        }

        // Only a single-column INTEGER PRIMARY KEY declared ascending aliases the rowid.
        if (primaryKeyCount != 1
            || !IsIntegerDeclaredType(columns[candidate].DeclaredType)
            || columns[candidate].PrimaryKeyDescending)
        {
            return -1;
        }

        return candidate;
    }

    // Resolves the effective primary-key columns. A table-level PRIMARY KEY(...) takes the
    // declared column order; otherwise column-level PRIMARY KEY markers are used. Declaring
    // more than one primary key is rejected, matching SQLite/Turso: multiple column-level
    // markers, or a table-level key alongside any column-level marker (a second table-level
    // key is rejected earlier in the parser).
    private static IReadOnlyList<(int Index, bool Descending)> ResolvePrimaryKeyColumns(
        IReadOnlyList<EmbeddedColumn> columns,
        IReadOnlyList<TablePrimaryKeyColumn>? tablePrimaryKey,
        IReadOnlyDictionary<string, int> indices)
    {
        var columnLevel = new List<(int Index, bool Descending)>();
        for (var index = 0; index < columns.Count; index++)
        {
            if (columns[index].PrimaryKey)
                columnLevel.Add((index, columns[index].PrimaryKeyDescending));
        }

        if (columnLevel.Count > 1)
            throw new EmbeddedSqlException("table has more than one primary key");

        if (tablePrimaryKey is null)
            return columnLevel;

        if (columnLevel.Count > 0)
            throw new EmbeddedSqlException("table has more than one primary key");

        var resolved = new List<(int Index, bool Descending)>(tablePrimaryKey.Count);
        foreach (var keyColumn in tablePrimaryKey)
        {
            if (!indices.TryGetValue(keyColumn.Name, out var index))
                throw new EmbeddedSqlException($"no such column: {keyColumn.Name}");

            resolved.Add((index, keyColumn.Descending));
        }

        return resolved;
    }

    private static SqlitePrimaryKeySchema? CreatePrimaryKeySchema(
        IReadOnlyList<EmbeddedColumn> columns,
        IReadOnlyList<TablePrimaryKeyColumn>? tablePrimaryKey,
        IReadOnlyList<(int Index, bool Descending)> primaryKeyColumns)
    {
        if (primaryKeyColumns.Count == 0)
            return null;

        if (tablePrimaryKey is not null && tablePrimaryKey.Count != primaryKeyColumns.Count)
            throw new EmbeddedSqlException("primary-key metadata is inconsistent");

        var terms = new SqlitePrimaryKeyTerm[primaryKeyColumns.Count];
        for (var position = 0; position < primaryKeyColumns.Count; position++)
        {
            var (columnIndex, descending) = primaryKeyColumns[position];
            var collation = tablePrimaryKey?[position].Collation ?? columns[columnIndex].Collation;
            terms[position] = new SqlitePrimaryKeyTerm(
                columnIndex,
                columns[columnIndex].Name,
                descending ? SqliteKeySortOrder.Descending : SqliteKeySortOrder.Ascending,
                collation is null ? SqliteKeyCollation.Binary : SqliteKeyCollation.FromName(collation));
        }

        return new SqlitePrimaryKeySchema(terms);
    }

    private static SqlitePrimaryKeySchema CreatePrimaryKeySchema(
        IReadOnlyList<EmbeddedColumn> columns,
        IReadOnlyList<EmbeddedIndexColumn> primaryKeyColumns)
    {
        var terms = primaryKeyColumns.Select(column =>
        {
            var collation = column.Collation ?? columns[column.ColumnIndex].Collation;
            return new SqlitePrimaryKeyTerm(
                column.ColumnIndex,
                columns[column.ColumnIndex].Name,
                column.Descending ? SqliteKeySortOrder.Descending : SqliteKeySortOrder.Ascending,
                collation is null ? SqliteKeyCollation.Binary : SqliteKeyCollation.FromName(collation));
        });
        return new SqlitePrimaryKeySchema(terms);
    }

    // Validates the generated columns and returns their evaluation order. The precedence of
    // checks matches SQLite: DEFAULT-on-generated, generated-in-PRIMARY-KEY, at-least-one
    // non-generated column, then per-expression validation and loop detection.
    private static IReadOnlyList<int> ValidateAndOrderGeneratedColumns(
        IReadOnlyList<EmbeddedColumn> columns,
        IReadOnlyList<(int Index, bool Descending)> primaryKeyColumns,
        IReadOnlyDictionary<string, int> indices)
    {
        var generated = new List<int>();
        for (var index = 0; index < columns.Count; index++)
        {
            if (columns[index].IsGenerated)
                generated.Add(index);
        }

        if (generated.Count == 0)
            return [];

        foreach (var index in generated)
        {
            if (columns[index].HasDefault)
                throw new EmbeddedSqlException("cannot use DEFAULT on a generated column");
        }

        foreach (var (index, _) in primaryKeyColumns)
        {
            if (columns[index].IsGenerated)
                throw new EmbeddedSqlException("generated columns cannot be part of the PRIMARY KEY");
        }

        if (generated.Count == columns.Count)
            throw new EmbeddedSqlException("must have at least one non-generated column");

        var dependencies = new Dictionary<int, List<int>>();
        foreach (var index in generated)
        {
            var expression = columns[index].GenerationExpression!;
            ValidateGenerationExpressionAllowed(expression);

            var referencedNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            CollectColumnReferences(expression, referencedNames);

            var generatedDependencies = new List<int>();
            foreach (var name in referencedNames)
            {
                if (!indices.TryGetValue(name, out var referencedIndex))
                    throw new EmbeddedSqlException($"no such column: {name}");

                if (columns[referencedIndex].IsGenerated)
                    generatedDependencies.Add(referencedIndex);
            }

            dependencies[index] = generatedDependencies;
        }

        var order = new List<int>(generated.Count);
        var state = new Dictionary<int, int>();
        foreach (var index in generated)
        {
            if (state.GetValueOrDefault(index) != 2)
                VisitGeneratedColumn(index, columns, dependencies, state, order);
        }

        return order;
    }

    private static void VisitGeneratedColumn(
        int node,
        IReadOnlyList<EmbeddedColumn> columns,
        Dictionary<int, List<int>> dependencies,
        Dictionary<int, int> state,
        List<int> order)
    {
        state[node] = 1;
        foreach (var dependency in dependencies[node])
        {
            var dependencyState = state.GetValueOrDefault(dependency);
            if (dependencyState == 1)
                throw new EmbeddedSqlException($"generated column loop on \"{columns[node].Name}\"");
            if (dependencyState != 2)
                VisitGeneratedColumn(dependency, columns, dependencies, state, order);
        }

        state[node] = 2;
        order.Add(node);
    }

    // Mirrors Turso's ordering: generated-column expressions are validated at CREATE/ALTER
    // translate time, before execution, so their prohibition diagnostics preempt the
    // execution-time unbound-parameter error (gencol_error_bind_parameter).
    internal static void ValidateGeneratedColumnExpressions(ParsedStatement statement)
    {
        switch (statement)
        {
            case CreateTableStatement create:
                foreach (var column in create.Columns)
                {
                    if (column.GenerationExpression is { } expression)
                        ValidateGenerationExpressionAllowed(expression);
                }
                return;
            case AlterTableAddColumnStatement { Column.GenerationExpression: { } expression }:
                ValidateGenerationExpressionAllowed(expression);
                return;
        }
    }

    // Rejects constructs that cannot be evaluated deterministically inside a generated
    // column: bound parameters, subqueries, qualified column references, aggregate/window
    // functions, and any function that is not deterministic. Mirrors Turso's
    // validate_generated_expr (schema.rs).
    private static void ValidateGenerationExpressionAllowed(Expression expression)
    {
        switch (expression)
        {
            case LiteralExpression:
                return;
            case ColumnExpression column:
                if (column.Qualifier is not null)
                    throw new EmbeddedSqlException("the \".\" operator prohibited in generated columns");
                return;
            case CurrentTimeExpression:
                // CURRENT_DATE/TIME/TIMESTAMP re-evaluate on every read, so SQLite rejects
                // them like any other non-deterministic function.
                throw new EmbeddedSqlException("non-deterministic functions prohibited in generated columns");
            case ParameterExpression:
                throw new EmbeddedSqlException("bind parameters prohibited in generated columns");
            case RowValueExpression rowValue:
                foreach (var value in rowValue.Values)
                    ValidateGenerationExpressionAllowed(value);
                return;
            case ScalarSubqueryExpression or ExistsExpression or InSubqueryExpression:
                throw new EmbeddedSqlException("subqueries prohibited in generated columns");
            case StarExpression or QualifiedStarExpression:
                throw new EmbeddedSqlException("cannot use '*' in a generated column");
            case FunctionExpression function:
                // SQLite's generated-column validation reports window and aggregate calls with
                // its prohibition diagnostics before it ever reaches the determinism allow-list.
                if (function.Window is not null)
                    throw new EmbeddedSqlException("window functions prohibited in generated columns");
                if ((function.CountStar
                        && string.Equals(function.Name, "COUNT", StringComparison.OrdinalIgnoreCase))
                    || function.Distinct || function.Filter is not null
                    || EmbeddedDatabase.IsBuiltInAggregate(function)
                    || EmbeddedDatabase.IsManagedPercentileAggregate(function.Name))
                {
                    throw new EmbeddedSqlException("aggregate functions prohibited in generated columns");
                }
                if (SqliteBuiltinFunctions.IsWindowOnly(function.Name))
                    throw new EmbeddedSqlException($"misuse of window function {function.Name}()");
                if (!IsDeterministicGenerationFunction(function))
                    throw new EmbeddedSqlException("non-deterministic functions prohibited in generated columns");
                foreach (var argument in function.Arguments)
                    ValidateGenerationExpressionAllowed(argument);
                return;
            case CollationExpression collation:
                ValidateGenerationExpressionAllowed(collation.Expression);
                return;
            case CastExpression cast:
                ValidateGenerationExpressionAllowed(cast.Expression);
                return;
            case CaseExpression @case:
                if (@case.Operand is not null)
                    ValidateGenerationExpressionAllowed(@case.Operand);
                foreach (var clause in @case.Clauses)
                {
                    ValidateGenerationExpressionAllowed(clause.When);
                    ValidateGenerationExpressionAllowed(clause.Then);
                }
                if (@case.Else is not null)
                    ValidateGenerationExpressionAllowed(@case.Else);
                return;
            case LikeExpression like:
                ValidateGenerationExpressionAllowed(like.Value);
                ValidateGenerationExpressionAllowed(like.Pattern);
                if (like.Escape is not null)
                    ValidateGenerationExpressionAllowed(like.Escape);
                return;
            case GlobExpression glob:
                ValidateGenerationExpressionAllowed(glob.Value);
                ValidateGenerationExpressionAllowed(glob.Pattern);
                return;
            case InExpression @in:
                ValidateGenerationExpressionAllowed(@in.Value);
                foreach (var value in @in.Values)
                    ValidateGenerationExpressionAllowed(value);
                return;
            case BetweenExpression between:
                ValidateGenerationExpressionAllowed(between.Value);
                ValidateGenerationExpressionAllowed(between.Lower);
                ValidateGenerationExpressionAllowed(between.Upper);
                return;
            case UnaryExpression unary:
                ValidateGenerationExpressionAllowed(unary.Operand);
                return;
            case BinaryExpression binary:
                ValidateGenerationExpressionAllowed(binary.Left);
                ValidateGenerationExpressionAllowed(binary.Right);
                return;
            default:
                throw new EmbeddedSqlException("expression is not allowed in a generated column");
        }
    }

    // Mirrors Turso's is_deterministic_schema_function_call (schema.rs): a generated-column
    // call is allowed when it resolves to a deterministic built-in scalar. The date/time
    // family is deterministic only when it cannot read the wall clock or the local timezone.
    // Shared by generated-column validation (schema.rs) and index-expression
    // validation: date/time functions are deterministic only when they cannot
    // read the wall clock or the local timezone.
    internal static bool IsDeterministicSchemaFunction(FunctionExpression function)
    {
        var upperName = function.Name.ToUpperInvariant();
        if (!SqliteBuiltinFunctions.AcceptsCall(
                upperName,
                function.Arguments.Count,
                function.CountStar))
        {
            return false;
        }
        if (upperName is "DATE" or "TIME" or "DATETIME" or "UNIXEPOCH" or "JULIANDAY"
            or "STRFTIME" or "TIMEDIFF")
        {
            return IsDeterministicDateTimeCall(upperName, function.Arguments);
        }

        return SqliteBuiltinFunctions.IsDeterministic(function.Name);
    }

    /// <summary>
    /// True for a method-index SQL function whose result depends on the indexed corpus and on the
    /// covering index's configuration rather than only on its arguments.
    /// </summary>
    internal static bool IsCorpusDependentMethodFunction(string name)
        => string.Equals(name, "fts_score", StringComparison.OrdinalIgnoreCase);

    private static bool IsDeterministicGenerationFunction(FunctionExpression function)
        => IsDeterministicSchemaFunction(function);

    private static bool IsDeterministicDateTimeCall(string upperName, IReadOnlyList<Expression> arguments)
    {
        if (upperName == "TIMEDIFF")
        {
            foreach (var argument in arguments)
            {
                if (IsCurrentTimeLiteral(argument))
                    return false;
            }

            return true;
        }

        // strftime(format, value, modifier, ...): the time value is the second argument;
        // strftime('%s') defaults to 'now' and is therefore non-deterministic.
        if (upperName == "STRFTIME")
        {
            if (arguments.Count < 2 || IsCurrentTimeLiteral(arguments[1]))
                return false;
            for (var i = 2; i < arguments.Count; i++)
            {
                if (IsUnsafeDateTimeModifier(arguments[i]))
                    return false;
            }

            return true;
        }

        // date/time/datetime/unixepoch/julianday(value, modifier, ...): require an explicit
        // time value that is not the current clock, and no localtime/utc modifiers.
        if (arguments.Count == 0 || IsCurrentTimeLiteral(arguments[0]))
            return false;
        for (var i = 1; i < arguments.Count; i++)
        {
            if (IsUnsafeDateTimeModifier(arguments[i]))
                return false;
        }

        return true;
    }

    private static bool IsCurrentTimeLiteral(Expression expression)
    {
        if (expression is CurrentTimeExpression)
            return true;
        return expression is LiteralExpression literal
            && literal.Value.Kind == SqlValueKind.Text
            && string.Equals(literal.Value.AsText(), "now", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsUnsafeDateTimeModifier(Expression expression)
    {
        if (IsCurrentTimeLiteral(expression))
            return true;
        return expression is LiteralExpression literal
            && literal.Value.Kind == SqlValueKind.Text
            && (string.Equals(literal.Value.AsText(), "localtime", StringComparison.OrdinalIgnoreCase)
                || string.Equals(literal.Value.AsText(), "utc", StringComparison.OrdinalIgnoreCase));
    }

    internal static bool CollectColumnReferences(Expression expression, HashSet<string> names)
    {
        switch (expression)
        {
            case ColumnExpression column:
                names.Add(column.Name);
                if (column.UnqualifiedName is not null)
                    names.Add(column.UnqualifiedName);
                return column.Qualifier is not null;
            case FunctionExpression function:
                var functionQualified = false;
                foreach (var argument in function.Arguments)
                    functionQualified |= CollectColumnReferences(argument, names);
                if (function.Filter is not null)
                    functionQualified |= CollectColumnReferences(function.Filter, names);
                return functionQualified;
            case RowValueExpression rowValue:
                var rowQualified = false;
                foreach (var value in rowValue.Values)
                    rowQualified |= CollectColumnReferences(value, names);
                return rowQualified;
            case CollationExpression collation:
                return CollectColumnReferences(collation.Expression, names);
            case CastExpression cast:
                return CollectColumnReferences(cast.Expression, names);
            case CaseExpression @case:
                var caseQualified = false;
                if (@case.Operand is not null)
                    caseQualified |= CollectColumnReferences(@case.Operand, names);
                foreach (var clause in @case.Clauses)
                {
                    caseQualified |= CollectColumnReferences(clause.When, names);
                    caseQualified |= CollectColumnReferences(clause.Then, names);
                }
                if (@case.Else is not null)
                    caseQualified |= CollectColumnReferences(@case.Else, names);
                return caseQualified;
            case LikeExpression like:
                var likeQualified = CollectColumnReferences(like.Value, names)
                    | CollectColumnReferences(like.Pattern, names);
                if (like.Escape is not null)
                    likeQualified |= CollectColumnReferences(like.Escape, names);
                return likeQualified;
            case GlobExpression glob:
                return CollectColumnReferences(glob.Value, names)
                    | CollectColumnReferences(glob.Pattern, names);
            case InExpression @in:
                var inQualified = CollectColumnReferences(@in.Value, names);
                foreach (var value in @in.Values)
                    inQualified |= CollectColumnReferences(value, names);
                return inQualified;
            case BetweenExpression between:
                return CollectColumnReferences(between.Value, names)
                    | CollectColumnReferences(between.Lower, names)
                    | CollectColumnReferences(between.Upper, names);
            case UnaryExpression unary:
                return CollectColumnReferences(unary.Operand, names);
            case BinaryExpression binary:
                return CollectColumnReferences(binary.Left, names)
                    | CollectColumnReferences(binary.Right, names);
            default:
                return false;
        }
    }


    public static bool TryCoerceRowid(SqlValue value, out long rowid)
    {
        switch (value.Kind)
        {
            case SqlValueKind.Integer:
                rowid = value.AsInteger();
                return true;
            case SqlValueKind.Real:
                {
                    var real = value.AsReal();
                    if (real == Math.Truncate(real)
                        && real > long.MinValue
                        && real < -(double)long.MinValue)
                    {
                        rowid = (long)real;
                        return true;
                    }

                    break;
                }
            case SqlValueKind.Text:
                {
                    var text = TrimAsciiWhitespace(value.AsText());
                    if (long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out rowid))
                        return true;
                    if (double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var real)
                        && double.IsFinite(real)
                        && real == Math.Truncate(real)
                        && real > long.MinValue
                        && real < -(double)long.MinValue)
                    {
                        rowid = (long)real;
                        return true;
                    }

                    break;
                }
        }

        rowid = 0;
        return false;
    }

    /// <summary>
    /// SQLite skips only ASCII whitespace (space, tab, line feed, vertical tab, form feed,
    /// carriage return) when parsing numbers out of text. .NET's <see cref="string.Trim()"/>
    /// also strips Unicode whitespace such as U+00A0 (non-breaking space), which would wrongly
    /// let text padded with U+00A0 convert to a number.
    /// </summary>
    internal static string TrimAsciiWhitespace(string text)
    {
        var start = 0;
        var end = text.Length;
        while (start < end && IsAsciiWhitespace(text[start]))
            start++;
        while (end > start && IsAsciiWhitespace(text[end - 1]))
            end--;
        return start == 0 && end == text.Length ? text : text[start..end];
    }

    private static bool IsAsciiWhitespace(char character)
        => character is ' ' or '\t' or '\n' or '\v' or '\f' or '\r';

    public void AddColumn(EmbeddedColumn column)
    {
        if (_columnIndices.ContainsKey(column.Name))
            throw new EmbeddedSqlException($"duplicate column name: {column.Name}");
        // Mirrors SQLite/Turso: the generated-column PRIMARY-KEY prohibition is diagnosed before
        // the generic ALTER restriction, with its own message.
        if (column.IsGenerated && column.PrimaryKey)
            throw new EmbeddedSqlException("generated columns cannot be part of the PRIMARY KEY");
        if (column.PrimaryKey || column.Unique)
            throw new EmbeddedSqlException("Cannot add a PRIMARY KEY or UNIQUE column.");

        _ = new EmbeddedTable(
            Name,
            [.. ColumnDefinitions, column],
            WithoutRowid,
            TableLevelPrimaryKey,
            TableUniqueConstraints,
            CheckConstraints,
            TablePrimaryKeyConflictAlgorithm,
            TablePrimaryKeyConstraintName,
            TablePrimaryKeyDeclarationOrder,
            TableForeignKeys,
            Strict);

        if (column.DefaultExpression is not null && Rows.Count > 0)
            throw new EmbeddedSqlException("Cannot add a column with non-constant default.");

        // Turso (translate/alter.rs strict_default_type_mismatch): the added column's constant
        // DEFAULT gets PLAIN affinity conversion without a strict storage-class throw. A STRICT
        // table then reports "type mismatch on DEFAULT" — but only when the table already has
        // rows, because upstream emits the validation as a table scan; an empty table defers the
        // failure to the first INSERT that stores the default (which hits the normal strict
        // storage-class check).
        var defaultValue = CoerceColumnAffinity(column, column.DefaultValue ?? SqlValue.Null);
        if (Strict
            && Rows.Count > 0
            && defaultValue.Kind != SqlValueKind.Null
            && !StrictValueMatchesDeclaredType(column, defaultValue))
        {
            throw new EmbeddedSqlException("type mismatch on DEFAULT");
        }
        // A generated column always produces a value, so SQLite permits NOT NULL on it and
        // instead validates the computed value against every pre-existing row (raising
        // "NOT NULL constraint failed" on the first violation) — the NOT-NULL-needs-default
        // rejection only applies to ordinary columns.
        if (column.NotNull && !column.IsGenerated && Rows.Count > 0 && defaultValue.Kind == SqlValueKind.Null)
            throw new EmbeddedSqlException("Cannot add a NOT NULL column without a default value.");

        var index = Columns.Length;
        Columns = [.. Columns, column.Name];
        ColumnDefinitions = [.. ColumnDefinitions, column];
        _columnIndices.Add(column.Name, index);
        RefreshForeignKeys();
        if (column.IsGenerated)
            GeneratedColumnOrder = [.. GeneratedColumnOrder, index];
        for (var rowIndex = 0; rowIndex < Rows.Count; rowIndex++)
        {
            var row = Rows[rowIndex];
            Array.Resize(ref row, index + 1);
            row[index] = defaultValue;
            Rows[rowIndex] = row;
            // SQLite evaluates the generation expression against pre-existing rows when a
            // generated column is added; Ahtola materializes generated values, so the backfill
            // computes and stores the value (and enforces NOT NULL) row by row.
            if (column.IsGenerated)
                EmbeddedDatabase.ComputeGeneratedColumnsAfterAddColumn(this, Name, row);
        }
    }

    /// <summary>
    /// Rebuilds a table for Turso's <c>ALTER COLUMN</c> extension. The replacement owns its
    /// complete column definition, while table-level constraints and explicit indexes survive.
    /// A rename first uses the established token-aware rewrite path so dependent expressions,
    /// self references, and explicit-index text continue to resolve against the replacement name.
    /// </summary>
    public EmbeddedTable CreateWithAlteredColumn(
        string name,
        EmbeddedColumn replacementColumn,
        CancellationToken cancellationToken)
    {
        var alteredColumnIndex = GetColumnIndex(name);
        var oldName = Columns[alteredColumnIndex];
        if (!string.Equals(oldName, replacementColumn.Name, StringComparison.OrdinalIgnoreCase)
            && _columnIndices.ContainsKey(replacementColumn.Name))
        {
            throw new EmbeddedSqlException($"duplicate column name: {replacementColumn.Name}");
        }
        if (replacementColumn.PrimaryKey)
            throw new EmbeddedSqlException("PRIMARY KEY constraint cannot be altered");
        if (replacementColumn.Unique)
            throw new EmbeddedSqlException("UNIQUE constraint cannot be altered");
        if (replacementColumn.IsGenerated)
            throw new EmbeddedSqlException("ALTER COLUMN to a generated column is not supported");
        if (replacementColumn.ForeignKeyConstraints.Count > 0)
            throw new EmbeddedSqlException("ALTER COLUMN with REFERENCES is not supported");

        var renamed = string.Equals(oldName, replacementColumn.Name, StringComparison.Ordinal)
            ? Clone()
            : CreateWithRenamedColumn(name, replacementColumn.Name, quoteNewName: false, cancellationToken);
        var columns = renamed.ColumnDefinitions.ToArray();
        columns[alteredColumnIndex] = replacementColumn;

        EmbeddedTable altered;
        try
        {
            altered = new EmbeddedTable(
                Name,
                columns,
                WithoutRowid,
                renamed.TableLevelPrimaryKey,
                renamed.TableUniqueConstraints,
                renamed.CheckConstraints,
                renamed.TablePrimaryKeyConflictAlgorithm,
                renamed.TablePrimaryKeyConstraintName,
                renamed.TablePrimaryKeyDeclarationOrder,
                renamed.TableForeignKeys,
                Strict);
        }
        catch (EmbeddedSqlException exception)
        {
            throw new EmbeddedSqlException(
                $"error in table {Name} after alter column: {exception.Message}",
                exception);
        }

        altered.SchemaSqlCompact = SchemaSqlCompact;
        altered.Sql = EmbeddedDatabase.BuildCreateTableSql(Name, altered);
        foreach (var index in renamed.Indexes.Where(index => index.Origin == EmbeddedIndexOrigin.Explicit))
            altered.Indexes.Add(index);

        if (RowIds.Count != Rows.Count)
            throw new InvalidOperationException($"Table '{Name}' has inconsistent row identity metadata.");
        for (var rowIndex = 0; rowIndex < renamed.Rows.Count; rowIndex++)
        {
            if ((rowIndex & 0xff) == 0)
                cancellationToken.ThrowIfCancellationRequested();

            var row = renamed.Rows[rowIndex].ToArray();
            row[alteredColumnIndex] = ApplyColumnAffinity(replacementColumn, row[alteredColumnIndex]);
            altered.Rows.Add(row);
            EmbeddedDatabase.ComputeGeneratedColumnsAfterAddColumn(altered, Name, row);
        }
        altered.RowIds.AddRange(renamed.RowIds);
        return altered;
    }

    public EmbeddedTable CreateWithoutColumn(string name, CancellationToken cancellationToken)
    {
        if (!_columnIndices.TryGetValue(name, out var droppedColumnIndex))
            throw new EmbeddedSqlException($"no such column: \"{name}\"");

        var droppedColumn = ColumnDefinitions[droppedColumnIndex];
        if (droppedColumn.PrimaryKey || IsPrimaryKeyColumn(droppedColumnIndex))
            throw new EmbeddedSqlException($"cannot drop PRIMARY KEY column: \"{name}\"");
        if (droppedColumn.Unique
            || TableUniqueConstraints.Any(constraint =>
                constraint.Columns.Any(column =>
                    string.Equals(column.Name, name, StringComparison.OrdinalIgnoreCase))))
        {
            throw new EmbeddedSqlException($"cannot drop UNIQUE column: \"{name}\"");
        }
        if (ColumnDefinitions.Length == 1)
            throw new EmbeddedSqlException($"cannot drop column \"{name}\": no other columns exist");

        var dependentIndex = Indexes.FirstOrDefault(index =>
            index.Origin == EmbeddedIndexOrigin.Explicit
            && (index.Columns.Any(column =>
                    column.ColumnIndex == droppedColumnIndex
                    || column.Expression is not null && ReferencesColumn(column.Expression, name))
                || ReferencesColumn(index.Where, name)));
        if (dependentIndex is not null)
        {
            throw new EmbeddedSqlException(
                $"error in index {dependentIndex.Name} after drop column: no such column: {name}");
        }

        EmbeddedTable replacement;
        try
        {
            replacement = new EmbeddedTable(
                Name,
                ColumnDefinitions.Where((_, index) => index != droppedColumnIndex).ToArray(),
                WithoutRowid,
                TableLevelPrimaryKey,
                TableUniqueConstraints,
                CheckConstraints,
                TablePrimaryKeyConflictAlgorithm,
                TablePrimaryKeyConstraintName,
                TablePrimaryKeyDeclarationOrder,
                TableForeignKeys,
                Strict);
            replacement.SchemaSqlCompact = SchemaSqlCompact;
            replacement.Sql = Sql is not null ? AlterTableSqlRewriter.RemoveColumn(Sql, name) : null;
        }
        catch (EmbeddedSqlException exception)
        {
            throw new EmbeddedSqlException(
                $"error in table {Name} after drop column: {exception.Message}",
                exception);
        }

        foreach (var index in Indexes.Where(index => index.Origin == EmbeddedIndexOrigin.Explicit))
        {
            cancellationToken.ThrowIfCancellationRequested();
            var rewritten = index with
            {
                Columns = index.Columns
                    .Select(column => column.IsExpression
                        ? column
                        : column with { ColumnIndex = replacement.GetColumnIndex(column.Name) })
                    .ToArray(),
            };
            IndexExpressionSemantics.ValidateDefinition(Name, replacement, rewritten);
            IndexExpressionSemantics.ValidateRoundTrip(Name, replacement, rewritten);
            replacement.Indexes.Add(rewritten);
        }

        if (RowIds.Count != Rows.Count)
            throw new InvalidOperationException($"Table '{Name}' has inconsistent row identity metadata.");
        for (var rowIndex = 0; rowIndex < Rows.Count; rowIndex++)
        {
            if ((rowIndex & 0xff) == 0)
                cancellationToken.ThrowIfCancellationRequested();

            var row = Rows[rowIndex];
            if (row.Length != ColumnDefinitions.Length)
                throw new InvalidOperationException($"Table '{Name}' has an inconsistent row width.");
            var rewritten = new SqlValue[row.Length - 1];
            Array.Copy(row, 0, rewritten, 0, droppedColumnIndex);
            Array.Copy(
                row,
                droppedColumnIndex + 1,
                rewritten,
                droppedColumnIndex,
                row.Length - droppedColumnIndex - 1);
            replacement.Rows.Add(rewritten);
        }

        replacement.RowIds.AddRange(RowIds);
        return replacement;

        static bool ReferencesColumn(Expression? expression, string columnName)
        {
            if (expression is null)
                return false;

            var references = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            CollectColumnReferences(expression, references);
            return references.Contains(columnName);
        }
    }

    public void Rename(string newName)
    {
        var autoIndexPrefix = $"sqlite_autoindex_{Name}_";
        string? renamedWithoutRowidPrimaryKeyIndex = null;
        if (WithoutRowidPrimaryKeyIndexName is { } primaryKeyIndexName)
        {
            if (!primaryKeyIndexName.StartsWith(autoIndexPrefix, StringComparison.OrdinalIgnoreCase)
                || !int.TryParse(
                    primaryKeyIndexName.AsSpan(autoIndexPrefix.Length),
                    System.Globalization.NumberStyles.None,
                    System.Globalization.CultureInfo.InvariantCulture,
                    out var primaryKeyOrdinal)
                || primaryKeyOrdinal <= 0)
            {
                throw new InvalidOperationException(
                    $"Constraint index '{primaryKeyIndexName}' does not match table '{Name}'.");
            }

            renamedWithoutRowidPrimaryKeyIndex =
                $"sqlite_autoindex_{newName}_{primaryKeyOrdinal}";
        }
        var renamedIndexes = new List<(int Position, string Name)>();
        for (var index = 0; index < Indexes.Count; index++)
        {
            if (Indexes[index].Origin is not (
                EmbeddedIndexOrigin.UniqueConstraint or EmbeddedIndexOrigin.PrimaryKey))
            {
                continue;
            }

            var indexName = Indexes[index].Name;
            if (!indexName.StartsWith(autoIndexPrefix, StringComparison.OrdinalIgnoreCase)
                || !int.TryParse(
                    indexName.AsSpan(autoIndexPrefix.Length),
                    System.Globalization.NumberStyles.None,
                    System.Globalization.CultureInfo.InvariantCulture,
                    out var ordinal)
                || ordinal <= 0)
            {
                throw new InvalidOperationException(
                    $"Constraint index '{indexName}' does not match table '{Name}'.");
            }

            renamedIndexes.Add((index, $"sqlite_autoindex_{newName}_{ordinal}"));
        }

        Name = newName;
        WithoutRowidPrimaryKeyIndexName = renamedWithoutRowidPrimaryKeyIndex;
        foreach (var (position, name) in renamedIndexes)
            Indexes[position] = Indexes[position] with { Name = name };
    }

    // Columns the statement assigns are skipped: SQLite evaluates a DEFAULT expression only
    // when the column is omitted, so an unknown or non-deterministic function in one must not
    // fail (or run for) inserts that supply the value explicitly.
    public SqlValue[] CreateRowWithDefaults(
        Func<Expression, SqlValue> evaluate,
        IReadOnlySet<int>? assignedColumns = null)
    {
        var row = new SqlValue[ColumnDefinitions.Length];
        for (var index = 0; index < ColumnDefinitions.Length; index++)
        {
            var column = ColumnDefinitions[index];
            var value = assignedColumns is not null && assignedColumns.Contains(index)
                ? SqlValue.Null
                : column.DefaultExpression is { } expression
                    ? evaluate(expression)
                    : column.DefaultValue ?? SqlValue.Null;
            row[index] = CoerceColumnAffinity(column, value);
        }

        return row;
    }

    /// <summary>
    /// Builds a replacement table with <paramref name="name"/> renamed to
    /// <paramref name="newName"/>. Every stored expression the table owns — CHECK bodies,
    /// generated-column expressions, table-level key column lists, foreign-key column lists,
    /// index keys, and partial-index predicates — is reparsed and rewritten so no reference to
    /// the old spelling survives and no unrelated text is disturbed.
    /// </summary>
    public EmbeddedTable CreateWithRenamedColumn(
        string name,
        string newName,
        bool quoteNewName,
        CancellationToken cancellationToken)
    {
        var renamedIndex = GetColumnIndex(name);
        var oldName = Columns[renamedIndex];
        if (!string.Equals(oldName, newName, StringComparison.OrdinalIgnoreCase)
            && _columnIndices.ContainsKey(newName))
        {
            throw new EmbeddedSqlException($"duplicate column name: {newName}");
        }

        var previousColumns = Columns.ToArray();
        var rewrittenColumns = new EmbeddedColumn[ColumnDefinitions.Length];
        for (var position = 0; position < ColumnDefinitions.Length; position++)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var column = ColumnDefinitions[position];
            if (column.GenerationExpression is not null)
            {
                if (column.GenerationSql is null)
                {
                    throw new InvalidOperationException(
                        $"Generated column '{column.Name}' of table '{Name}' has no stored expression text.");
                }

                if (RewriteFragment(column.GenerationSql) is { } generationSql)
                {
                    column = column with
                    {
                        GenerationSql = generationSql,
                        GenerationExpression = SqlParser.ParseExpressionWithSpans(generationSql, out _),
                    };
                }
            }

            if (column.CheckConstraints.Count > 0
                || column.ForeignKey is not null
                || column.AdditionalForeignKeys is { Count: > 0 })
            {
                column = column.WithConstraints(
                    column.CheckConstraints.Count > 0 ? RewriteChecks(column.CheckConstraints) : column.Checks,
                    column.ForeignKey is null ? null : RewriteForeignKey(column.ForeignKey),
                    column.AdditionalForeignKeys?.Select(RewriteForeignKey).ToArray());
            }

            if (position == renamedIndex)
                column = column with { Name = newName };

            rewrittenColumns[position] = column;
        }

        EmbeddedTable replacement;
        try
        {
            replacement = new EmbeddedTable(
                Name,
                rewrittenColumns,
                WithoutRowid,
                TableLevelPrimaryKey?.Select(RewriteKeyColumn).ToArray(),
                TableUniqueConstraints
                    .Select(constraint => constraint with
                    {
                        Columns = constraint.Columns.Select(RewriteKeyColumn).ToArray(),
                    })
                    .ToArray(),
                RewriteChecks(CheckConstraints),
                TablePrimaryKeyConflictAlgorithm,
                TablePrimaryKeyConstraintName,
                TablePrimaryKeyDeclarationOrder,
                TableForeignKeys.Select(RewriteForeignKey).ToArray(),
                Strict);
            replacement.SchemaSqlCompact = SchemaSqlCompact;
            if (Sql is not null)
                replacement.Sql = RenameColumnRewriter.RewriteCreateTable(Sql, Name, previousColumns, oldName, newName, quoteNewName);
        }
        catch (EmbeddedSqlException exception)
        {
            throw new EmbeddedSqlException(
                $"error in table {Name} after rename column: {exception.Message}",
                exception);
        }

        foreach (var index in Indexes.Where(index => index.Origin == EmbeddedIndexOrigin.Explicit))
        {
            cancellationToken.ThrowIfCancellationRequested();
            var rewritten = index with
            {
                Columns = index.Columns.Select(RewriteIndexColumn).ToArray(),
            };
            if (index.WhereSql is { } whereSql && RewriteFragment(whereSql) is { } rewrittenWhere)
            {
                rewritten = rewritten with
                {
                    WhereSql = rewrittenWhere,
                    Where = SqlParser.ParseExpressionWithSpans(rewrittenWhere, out _),
                };
            }

            if (index.Sql is not null)
            {
                rewritten = rewritten with
                {
                    Sql = RenameColumnRewriter.RewriteCreateIndex(index.Sql, Name, previousColumns, oldName, newName, quoteNewName),
                };
            }

            try
            {
                IndexExpressionSemantics.ValidateDefinition(Name, replacement, rewritten);
                IndexExpressionSemantics.ValidateRoundTrip(Name, replacement, rewritten);
            }
            catch (EmbeddedSqlException exception)
            {
                throw new EmbeddedSqlException(
                    $"error in index {index.Name} after rename column: {exception.Message}",
                    exception);
            }

            replacement.Indexes.Add(rewritten);
        }

        if (RowIds.Count != Rows.Count)
            throw new InvalidOperationException($"Table '{Name}' has inconsistent row identity metadata.");
        foreach (var row in Rows)
            replacement.Rows.Add(row.ToArray());

        replacement.RowIds.AddRange(RowIds);
        return replacement;

        string? RewriteFragment(string sql)
            => RenameColumnRewriter.RewriteTableExpression(
                sql,
                Name,
                previousColumns,
                oldName,
                newName,
                quoteNewName);

        IReadOnlyList<CheckConstraint> RewriteChecks(IReadOnlyList<CheckConstraint> checks)
            => checks
                .Select(check => RewriteFragment(check.Sql) is { } sql
                    ? check with { Sql = sql, Expression = SqlParser.ParseExpressionWithSpans(sql, out _) }
                    : check)
                .ToArray();

        TablePrimaryKeyColumn RewriteKeyColumn(TablePrimaryKeyColumn column)
            => string.Equals(column.Name, oldName, StringComparison.OrdinalIgnoreCase)
                ? column with { Name = newName }
                : column;

        EmbeddedIndexColumn RewriteIndexColumn(EmbeddedIndexColumn column)
        {
            if (column.ExpressionSql is { } expressionSql)
            {
                return RewriteFragment(expressionSql) is { } rewritten
                    ? column with
                    {
                        ExpressionSql = rewritten,
                        Expression = SqlParser.ParseExpressionWithSpans(rewritten, out _),
                    }
                    : column;
            }

            return string.Equals(column.Name, oldName, StringComparison.OrdinalIgnoreCase)
                ? column with { Name = newName }
                : column;
        }

        // A self-referencing foreign key names this table's columns on both sides of the
        // REFERENCES clause, so both lists follow the rename.
        ForeignKeyDefinition RewriteForeignKey(ForeignKeyDefinition foreignKey)
        {
            var rewritten = foreignKey with { ChildColumns = RenameAll(foreignKey.ChildColumns) };
            if (string.Equals(foreignKey.ParentTable, Name, StringComparison.OrdinalIgnoreCase))
                rewritten = rewritten with { ParentColumns = RenameAll(foreignKey.ParentColumns) };

            return rewritten;
        }

        string[] RenameAll(IReadOnlyList<string> columns)
            => columns
                .Select(column => string.Equals(column, oldName, StringComparison.OrdinalIgnoreCase)
                    ? newName
                    : column)
                .ToArray();
    }

    public EmbeddedTable Clone()
    {
        var clone = new EmbeddedTable(
            Name,
            ColumnDefinitions,
            WithoutRowid,
            TableLevelPrimaryKey,
            TableUniqueConstraints,
            CheckConstraints,
            TablePrimaryKeyConflictAlgorithm,
            TablePrimaryKeyConstraintName,
            TablePrimaryKeyDeclarationOrder,
            TableForeignKeys,
            Strict);
        clone.SchemaSqlCompact = SchemaSqlCompact;
        clone.Sql = Sql;
        clone.Rows.ReplaceContentsPreservingRevision(Rows);

        clone.RowIds.AddRange(RowIds);
        clone.Indexes.RemoveAll(index => index.Origin == EmbeddedIndexOrigin.Explicit);
        clone.Indexes.AddRange(Indexes.Where(index => index.Origin == EmbeddedIndexOrigin.Explicit));
        CopyMethodAttachmentsTo(clone);
        return clone;
    }

    internal EmbeddedTable CloneSchemaOnly()
    {
        var clone = new EmbeddedTable(
            Name,
            ColumnDefinitions,
            WithoutRowid,
            TableLevelPrimaryKey,
            TableUniqueConstraints,
            CheckConstraints,
            TablePrimaryKeyConflictAlgorithm,
            TablePrimaryKeyConstraintName,
            TablePrimaryKeyDeclarationOrder,
            TableForeignKeys,
            Strict);
        clone.SchemaSqlCompact = SchemaSqlCompact;
        clone.Sql = Sql;
        clone.Indexes.RemoveAll(index => index.Origin == EmbeddedIndexOrigin.Explicit);
        clone.Indexes.AddRange(Indexes.Where(index => index.Origin == EmbeddedIndexOrigin.Explicit));
        return clone;
    }

    /// <summary>
    /// Clones this table with every self-qualified CHECK expression rebound to a renamed table.
    /// The matching stored CREATE TABLE token rewrite happens separately in
    /// <see cref="AlterTableSqlRewriter.RenameTable"/>.
    /// </summary>
    public EmbeddedTable CloneWithRenamedCheckTableReferences(string oldName, string newName)
    {
        var columns = ColumnDefinitions
            .Select(column => column.CheckConstraints.Count == 0
                ? column
                : column.WithConstraints(
                    RewriteChecks(column.CheckConstraints),
                    column.ForeignKey,
                    column.AdditionalForeignKeys))
            .ToArray();
        var clone = new EmbeddedTable(
            newName,
            columns,
            WithoutRowid,
            TableLevelPrimaryKey,
            TableUniqueConstraints,
            RewriteChecks(CheckConstraints),
            TablePrimaryKeyConflictAlgorithm,
            TablePrimaryKeyConstraintName,
            TablePrimaryKeyDeclarationOrder,
            TableForeignKeys,
            Strict);
        clone.SchemaSqlCompact = SchemaSqlCompact;
        clone.Sql = Sql;
        foreach (var row in Rows)
            clone.Rows.Add(row.ToArray());

        clone.RowIds.AddRange(RowIds);
        clone.Indexes.RemoveAll(index => index.Origin == EmbeddedIndexOrigin.Explicit);
        clone.Indexes.AddRange(Indexes.Where(index => index.Origin == EmbeddedIndexOrigin.Explicit));
        CopyMethodAttachmentsTo(clone);
        return clone;

        IReadOnlyList<CheckConstraint> RewriteChecks(IReadOnlyList<CheckConstraint> checks)
            => checks
                .Select(check =>
                {
                    var sql = AlterTableSqlRewriter.RenameTableExpressionReferences(
                        check.Sql,
                        oldName,
                        newName);
                    if (sql is null)
                    {
                        throw new EmbeddedSqlException(
                            "ALTER TABLE RENAME cannot rewrite table-qualified CHECK expressions.");
                    }

                    return string.Equals(sql, check.Sql, StringComparison.Ordinal)
                        ? check
                        : check with
                        {
                            Sql = sql,
                            Expression = SqlParser.ParseExpressionWithSpans(sql, out _),
                        };
                })
                .ToArray();
    }

    // Shallow snapshot for DML statement rollback: a fresh table shell with a fresh
    // RowStore/RowIds list, but sharing the per-row SqlValue[] references with the live
    // table. DML never mutates a row array in place (it rebuilds the row list via
    // Clear/AddRange/Add/RemoveAt/whole-slot replacement), so the shared arrays keep
    // their pre-statement values. RestoreTables deep-clones this snapshot on the rare
    // throw path, so the common no-throw path avoids the O(rows) per-row allocation
    // that turned N-row bulk inserts into O(N^2) minute-long hangs.
    public EmbeddedTable CloneShallow()
    {
        var clone = new EmbeddedTable(
            Name,
            ColumnDefinitions,
            WithoutRowid,
            TableLevelPrimaryKey,
            TableUniqueConstraints,
            CheckConstraints,
            TablePrimaryKeyConflictAlgorithm,
            TablePrimaryKeyConstraintName,
            TablePrimaryKeyDeclarationOrder,
            TableForeignKeys,
            Strict);
        clone.SchemaSqlCompact = SchemaSqlCompact;
        clone.Sql = Sql;
        foreach (var row in Rows)
            clone.Rows.Add(row);

        clone.RowIds.AddRange(RowIds);
        clone.Indexes.RemoveAll(index => index.Origin == EmbeddedIndexOrigin.Explicit);
        clone.Indexes.AddRange(Indexes.Where(index => index.Origin == EmbeddedIndexOrigin.Explicit));
        CopyMethodAttachmentsTo(clone);
        return clone;
    }

    public void ApplyAffinities(SqlValue[] row)
    {
        for (var columnIndex = 0; columnIndex < ColumnDefinitions.Length; columnIndex++)
            row[columnIndex] = ApplyColumnAffinity(ColumnDefinitions[columnIndex], row[columnIndex]);
    }

    public void ValidateRows(string tableName, IReadOnlyList<SqlValue[]> rows)
    {
        for (var columnIndex = 0; columnIndex < ColumnDefinitions.Length; columnIndex++)
        {
            // A WITHOUT ROWID primary key (and any table-level PRIMARY KEY) is validated
            // separately with table-qualified messages, so skip those columns here to avoid
            // an unqualified duplicate check.
            if ((WithoutRowid || TableLevelPrimaryKey is not null) && IsPrimaryKeyColumn(columnIndex))
                continue;

            var column = ColumnDefinitions[columnIndex];
            if ((column.NotNull || (Strict && IsPrimaryKeyColumn(columnIndex)))
                && rows.Any(row => row[columnIndex].Kind == SqlValueKind.Null))
            {
                throw new EmbeddedSqlException(
                    $"NOT NULL constraint failed: {tableName}.{column.Name}",
                    column.NotNullConflictAlgorithm);
            }

            if (!column.PrimaryKey)
                continue;
            if (Indexes.Any(index =>
                    index.Origin == EmbeddedIndexOrigin.PrimaryKey
                    && index.Columns.Count == 1
                    && index.Columns[0].ColumnIndex == columnIndex))
            {
                continue;
            }

            var values = new HashSet<SqlValue>();
            foreach (var row in rows)
            {
                var value = row[columnIndex];
                if (value.Kind == SqlValueKind.Null)
                    continue;
                if (!values.Add(value))
                {
                    throw new EmbeddedSqlException(
                        $"UNIQUE constraint failed: {tableName}.{column.Name}",
                        column.PrimaryKeyConflictAlgorithm);
                }
            }
        }
    }

    private static SqlValue ApplyAffinity(EmbeddedColumn column, SqlValue value, bool strict)
    {
        if (strict
            && string.Equals(column.DeclaredType?.Trim(), "ANY", StringComparison.OrdinalIgnoreCase))
        {
            return value.WithoutJsonSubtype();
        }

        return ApplyAffinity(GetAffinity(column.DeclaredType), value);
    }

    internal static ColumnAffinity GetDeclaredColumnAffinity(EmbeddedColumn column)
        => GetAffinity(column.DeclaredType);

    internal static SqlValue ApplyColumnAffinity(ColumnAffinity affinity, SqlValue value)
        => ApplyAffinity(affinity, value);

    private static SqlValue ApplyAffinity(ColumnAffinity affinity, SqlValue value)
    {
        value = value.WithoutJsonSubtype();
        if (value.Kind is SqlValueKind.Null or SqlValueKind.Blob)
            return value;

        if (affinity == ColumnAffinity.Blob)
            return value;
        if (affinity == ColumnAffinity.Text)
            return value.Kind == SqlValueKind.Text
                ? value
                : SqlValue.Text(ToText(value));

        if (!TryGetNumeric(value, out var numeric))
            return value;
        if (affinity == ColumnAffinity.Real)
            return numeric.Kind == SqlValueKind.Integer
                ? SqlValue.Real(numeric.AsInteger())
                : numeric;

        return ConvertToIntegerWhenExact(numeric);
    }

    private void ValidateStrictColumnTypes()
    {
        foreach (var column in ColumnDefinitions)
        {
            if (string.IsNullOrWhiteSpace(column.DeclaredType))
                throw new EmbeddedSqlException($"missing datatype for {Name}.{column.Name}");

            var declaredType = column.DeclaredType.Trim();
            if (declaredType.Equals("INT", StringComparison.OrdinalIgnoreCase)
                || declaredType.Equals("INTEGER", StringComparison.OrdinalIgnoreCase)
                || declaredType.Equals("REAL", StringComparison.OrdinalIgnoreCase)
                || declaredType.Equals("TEXT", StringComparison.OrdinalIgnoreCase)
                || declaredType.Equals("BLOB", StringComparison.OrdinalIgnoreCase)
                || declaredType.Equals("ANY", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            throw new EmbeddedSqlException(
                $"unknown datatype for {Name}.{column.Name}: \"{declaredType}\"");
        }
    }

    private void ValidateStrictValue(EmbeddedColumn column, SqlValue value)
    {
        if (!Strict || value.Kind == SqlValueKind.Null)
            return;

        var declaredType = column.DeclaredType!.Trim().ToUpperInvariant();
        var valid = declaredType switch
        {
            "INT" or "INTEGER" => value.Kind == SqlValueKind.Integer,
            "REAL" => value.Kind == SqlValueKind.Real,
            "TEXT" => value.Kind == SqlValueKind.Text,
            "BLOB" => value.Kind == SqlValueKind.Blob,
            "ANY" => true,
            _ => throw new InvalidOperationException("A STRICT table contains an invalid declared type."),
        };
        if (valid)
            return;

        var storageClass = value.Kind switch
        {
            SqlValueKind.Integer => "INTEGER",
            SqlValueKind.Real => "REAL",
            SqlValueKind.Text => "TEXT",
            SqlValueKind.Blob => "BLOB",
            _ => throw new InvalidOperationException("NULL STRICT values are handled before storage-class validation."),
        };
        throw new EmbeddedSqlException(
            $"cannot store {storageClass} value in {declaredType} column {Name}.{column.Name}");
    }

    // The storage-class predicate behind ValidateStrictValue, exposed for the ALTER TABLE ADD
    // COLUMN DEFAULT validation on STRICT tables (Turso translate/alter.rs
    // strict_default_type_mismatch), which reports "type mismatch on DEFAULT" instead. NULL is
    // exempt and must be handled by the caller.
    private static bool StrictValueMatchesDeclaredType(EmbeddedColumn column, SqlValue value)
    {
        var declaredType = column.DeclaredType!.Trim().ToUpperInvariant();
        return declaredType switch
        {
            "INT" or "INTEGER" => value.Kind == SqlValueKind.Integer,
            "REAL" => value.Kind == SqlValueKind.Real,
            "TEXT" => value.Kind == SqlValueKind.Text,
            "BLOB" => value.Kind == SqlValueKind.Blob,
            "ANY" => true,
            _ => throw new InvalidOperationException("A STRICT table contains an invalid declared type."),
        };
    }

    internal static ColumnAffinity GetAffinity(string? declaredType)
    {
        if (string.IsNullOrEmpty(declaredType)
            || declaredType.Contains("BLOB", StringComparison.OrdinalIgnoreCase))
        {
            return ColumnAffinity.Blob;
        }
        if (declaredType.Contains("INT", StringComparison.OrdinalIgnoreCase))
            return ColumnAffinity.Integer;
        if (declaredType.Contains("CHAR", StringComparison.OrdinalIgnoreCase)
            || declaredType.Contains("CLOB", StringComparison.OrdinalIgnoreCase)
            || declaredType.Contains("TEXT", StringComparison.OrdinalIgnoreCase))
        {
            return ColumnAffinity.Text;
        }
        if (declaredType.Contains("REAL", StringComparison.OrdinalIgnoreCase)
            || declaredType.Contains("FLOA", StringComparison.OrdinalIgnoreCase)
            || declaredType.Contains("DOUB", StringComparison.OrdinalIgnoreCase))
        {
            return ColumnAffinity.Real;
        }

        return ColumnAffinity.Numeric;
    }

    private static bool TryGetNumeric(SqlValue value, out SqlValue numeric)
    {
        switch (value.Kind)
        {
            case SqlValueKind.Integer:
            case SqlValueKind.Real:
                numeric = value;
                return true;
            case SqlValueKind.Text:
                {
                    var text = TrimAsciiWhitespace(value.AsText());
                    if (long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var integer))
                    {
                        numeric = SqlValue.Integer(integer);
                        return true;
                    }
                    if (double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var real)
                        && double.IsFinite(real))
                    {
                        numeric = SqlValue.Real(real);
                        return true;
                    }

                    break;
                }
        }

        numeric = default;
        return false;
    }

    private static SqlValue ConvertToIntegerWhenExact(SqlValue numeric)
    {
        if (numeric.Kind == SqlValueKind.Integer)
            return numeric;

        var real = numeric.AsReal();
        // SQLite requires the real to be STRICTLY between i64::MIN and i64::MAX
        // (Turso cast_real_to_integer rejects the endpoints themselves), so a real that
        // is exactly -9223372036854775808.0 stays REAL instead of converting to i64::MIN.
        return real == Math.Truncate(real)
            && real > long.MinValue
            && real < -(double)long.MinValue
            ? SqlValue.Integer((long)real)
            : numeric;
    }

    private static string ToText(SqlValue value)
    {
        return value.Kind switch
        {
            SqlValueKind.Integer => value.AsInteger().ToString(CultureInfo.InvariantCulture),
            SqlValueKind.Real => EmbeddedDatabase.FormatPrintfTextReal(value.AsReal()),
            SqlValueKind.Text => value.AsText(),
            _ => throw new InvalidOperationException($"Cannot convert {value.Kind} to text."),
        };
    }

}

internal enum ColumnAffinity
{
    Blob,
    Text,
    Numeric,
    Integer,
    Real,
}

// The set of storage classes an expression can produce, mirroring Turso's
// StorageClassMask (core/translate/expr/affinity.rs). Used to compute the combined
// affinity of a compound SELECT column: a column survives with its arm's affinity only
// if no other arm can produce a storage class that would force it to BLOB.
[Flags]
internal enum StorageClassMask : byte
{
    None = 0,
    Numeric = 1,
    Text = 2,
    Blob = 4,
    All = Numeric | Text | Blob,
}

internal sealed record ExecutionResult(
    string[] Columns,
    IReadOnlyList<SqlValue[]> Rows,
    int RowsAffected,
    bool Changed = false,
    bool ForceFullCatalogRewrite = false,
    IReadOnlyList<(string TableName, EmbeddedTable Table, EmbeddedIndex Index)>? TargetedIndexRebuild = null)
{
    public static ExecutionResult Empty { get; } = new([], [], 0);

    // The rowid assigned by the most recent INSERT this statement performed, surfaced so
    // the owning connection can answer last_insert_rowid(). Null for statements that did
    // not insert a row.
    public long? LastInsertRowId { get; init; }
}

internal sealed class StreamingProjectionRows(
    IReadOnlyList<SourceRow> sourceRows,
    long offset,
    long? limit,
    Func<SourceRow, CancellationToken, bool>? include,
    Func<SourceRow, CancellationToken, SqlValue[]> project) : IReadOnlyList<SqlValue[]>
{
    // Step drives this list by source position so WHERE predicates can defer their
    // callbacks until the matching source row is reached.
    private readonly bool?[] _included = new bool?[sourceRows.Count];
    private readonly SqlValue[]?[] _projected = new SqlValue[]?[sourceRows.Count];
    private readonly long _offset = offset;
    private readonly long? _limit = limit is >= 0 ? limit : null;
    private long _skipped;
    private long _returned;
    private SqlValue[][]? _materialized;

    // The IReadOnlyList surface has dense result indexes, while Step uses source
    // indexes to preserve deferred WHERE and projection evaluation.
    public int Count => Materialize().Count;

    public int SourceCount => sourceRows.Count;

    public bool IsComplete { get; private set; }

    public SqlValue[] this[int index] => Materialize()[index];

    public SqlValue[] GetRow(int index, CancellationToken cancellationToken)
    {
        if (!TryGetRow(index, cancellationToken, out var row))
            throw new ArgumentOutOfRangeException(nameof(index), "The source row does not satisfy the streaming predicate.");

        return row;
    }

    public bool TryGetRow(int index, CancellationToken cancellationToken, out SqlValue[] row)
    {
        cancellationToken.ThrowIfCancellationRequested();
        if ((uint)index >= (uint)SourceCount
            || IsComplete
            || !Includes(index, cancellationToken))
        {
            row = [];
            return false;
        }

        if (_skipped < _offset)
        {
            _skipped++;
            row = [];
            return false;
        }

        row = Project(index, cancellationToken);
        _returned++;
        if (_limit is { } limit && _returned >= limit)
            IsComplete = true;
        return true;
    }

    public bool HasAny()
    {
        if (_limit == 0)
            return false;

        var skipped = 0L;
        for (var index = 0; index < SourceCount; index++)
        {
            if (!Includes(index, CancellationToken.None))
                continue;
            if (skipped < _offset)
            {
                skipped++;
                continue;
            }

            return true;
        }

        return false;
    }

    public IEnumerator<SqlValue[]> GetEnumerator()
    {
        return ((IEnumerable<SqlValue[]>)Materialize()).GetEnumerator();
    }

    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();

    public IReadOnlyList<SqlValue[]> Materialize()
    {
        if (_materialized is not null)
            return _materialized;

        var rows = new List<SqlValue[]>();
        var skipped = 0L;
        for (var index = 0; index < SourceCount; index++)
        {
            if (!Includes(index, CancellationToken.None))
                continue;
            if (skipped < _offset)
            {
                skipped++;
                continue;
            }

            rows.Add(Project(index, CancellationToken.None));
            if (_limit is { } limit && rows.Count >= limit)
                break;
        }

        _materialized = rows.ToArray();
        return _materialized;
    }

    private bool Includes(int index, CancellationToken cancellationToken)
    {
        var included = _included[index];
        if (included is not null)
            return included.Value;

        cancellationToken.ThrowIfCancellationRequested();
        included = include?.Invoke(sourceRows[index], cancellationToken) ?? true;
        _included[index] = included;
        return included.Value;
    }

    private SqlValue[] Project(int index, CancellationToken cancellationToken)
    {
        var projected = _projected[index];
        if (projected is not null)
            return projected;

        cancellationToken.ThrowIfCancellationRequested();
        projected = project(sourceRows[index], cancellationToken);
        _projected[index] = projected;
        return projected;
    }
}

internal sealed record CreateTableMaterialization(
    IReadOnlyList<EmbeddedColumn> Columns,
    IReadOnlyList<SqlValue[]> Rows);

internal readonly record struct BlobMutationIdentity
{
    public BlobMutationIdentity(string tableName, long rowId)
    {
        TableName = tableName.ToUpperInvariant();
        RowId = rowId;
    }

    public string TableName { get; }

    public long RowId { get; }
}

internal sealed class BlobMutationLease(EmbeddedDatabase database, BlobMutationIdentity identity) : IDisposable
{
    private EmbeddedDatabase? _database = database;

    public void Dispose()
    {
        var database = System.Threading.Interlocked.Exchange(ref _database, null);
        database?.ReleaseBlobMutationLease(identity);
    }
}

internal sealed class StatementReaderLease(EmbeddedDatabase database) : IDisposable
{
    private EmbeddedDatabase? _database = database;

    public void Dispose()
    {
        var owner = Interlocked.Exchange(ref _database, null);
        owner?.ReleaseStatementReaderLease();
    }
}

internal sealed record OutputColumn(
    string? Qualifier,
    string Name,
    int Index,
    int? CoalesceIndex = null,
    IReadOnlyList<int>? AdditionalCoalesceIndices = null,
    // Identity of the leaf table source that produced this column. Used only by the
    // star-expansion ambiguity check to tell "one source with duplicate names" (legal)
    // apart from "the same name contributed by two distinct FROM sources" (ambiguous).
    object? Origin = null);

/// <summary>
/// The base table one scanned source came from, carried on the rows it produced so a scalar method
/// function can bind to the source's identity rather than to its name.
/// </summary>
internal readonly record struct MethodIndexSourceBinding(string TableName, EmbeddedTable Table);

internal sealed record SourceRow(
    string[] Columns,
    SqlValue[] Values,
    IReadOnlyDictionary<string, int>? QualifiedColumns = null,
    SourceRow? Parent = null,
    IReadOnlyList<OutputColumn>? OutputColumns = null,
    long? RowId = null,
    string? RowIdQualifier = null,
    IReadOnlyDictionary<string, long?>? QualifiedRowIds = null,
    IReadOnlyList<EmbeddedColumn?>? ColumnDefinitions = null,
    IReadOnlyDictionary<string, EmbeddedColumn>? QualifiedColumnDefinitions = null,
    IReadOnlySet<string>? AmbiguousQualifiedColumns = null,
    MethodIndexSourceBinding? MethodIndexSource = null,
    IReadOnlyDictionary<string, MethodIndexSourceBinding>? QualifiedMethodIndexSources = null,
    ManagedFts5SourceBinding? Fts5Source = null,
    IReadOnlyDictionary<string, ManagedFts5SourceBinding>? QualifiedFts5Sources = null)
{
    public SqlValue GetValue(string name)
        => GetValue(name, allowQualifiedLookup: true);

    /// <summary>
    /// The base table the source identified by <paramref name="qualifier"/> was scanned from, or
    /// null when this row carries no such source.
    /// </summary>
    /// <remarks>
    /// This is what a scalar method function binds to. Resolving the alias through a
    /// statement-wide registry instead meant that a nested subquery reusing an outer alias for a
    /// different table silently rebound the outer call: the inner scan registered its own table
    /// under the same name, and every later evaluation of the outer projection scored against it.
    /// The row itself is the only thing that always knows which source produced it, so the binding
    /// travels with the row — through joins, through the outer-row chain, and past any number of
    /// nested queries that happen to reuse the name.
    /// </remarks>
    public MethodIndexSourceBinding? GetMethodIndexSourceForQualifier(string qualifier)
    {
        if (QualifiedMethodIndexSources is { } qualified && qualified.TryGetValue(qualifier, out var bound))
            return bound;

        return MethodIndexSource is { } own
            && RowIdQualifier is { } owner
            && string.Equals(owner, qualifier, StringComparison.OrdinalIgnoreCase)
                ? own
                : Parent?.GetMethodIndexSourceForQualifier(qualifier);
    }

    public ManagedFts5SourceBinding? GetFts5SourceForQualifier(string qualifier)
    {
        if (QualifiedFts5Sources is { } qualified && qualified.TryGetValue(qualifier, out var bound))
            return bound;

        return Fts5Source is { } own
            && RowIdQualifier is { } owner
            && string.Equals(owner, qualifier, StringComparison.OrdinalIgnoreCase)
                ? own
                : Parent?.GetFts5SourceForQualifier(qualifier);
    }

    public ManagedFts5SourceBinding? GetFts5SourceForTable(string tableName)
    {
        var resolved = GetLocalFts5SourceForTable(tableName);
        return resolved ?? Parent?.GetFts5SourceForTable(tableName);
    }

    public bool TryResolveFts5Source(
        ColumnExpression column,
        out ManagedFts5SourceBinding? binding)
    {
        if (column.Qualifier is { } qualifier)
        {
            if (AmbiguousQualifiedColumns?.Contains(column.Name) == true)
                ThrowAmbiguousColumn(column.Name);
            if (QualifiedColumns?.ContainsKey(column.Name) == true)
            {
                binding = GetLocalFts5SourceForQualifier(qualifier);
                return true;
            }
        }
        else if (FindUnqualifiedColumnIndex(column.Name) is not null)
        {
            binding = GetLocalFts5SourceForTable(column.Name);
            return true;
        }

        if (Parent is not null)
            return Parent.TryResolveFts5Source(column, out binding);

        binding = null;
        return false;
    }

    private ManagedFts5SourceBinding? GetLocalFts5SourceForQualifier(string qualifier)
    {
        if (QualifiedFts5Sources is { } qualified && qualified.TryGetValue(qualifier, out var bound))
            return bound;

        return Fts5Source is { } own
            && RowIdQualifier is { } owner
            && string.Equals(owner, qualifier, StringComparison.OrdinalIgnoreCase)
                ? own
                : null;
    }

    private ManagedFts5SourceBinding? GetLocalFts5SourceForTable(string tableName)
    {
        ManagedFts5SourceBinding? resolved = null;
        if (QualifiedFts5Sources is not null)
        {
            foreach (var binding in QualifiedFts5Sources.Values)
            {
                if (!string.Equals(binding.Table.TableName, tableName, StringComparison.OrdinalIgnoreCase))
                    continue;
                if (resolved is not null
                    && (!ReferenceEquals(resolved.Table, binding.Table) || resolved.RowId != binding.RowId))
                {
                    return null;
                }

                resolved = binding;
            }
        }

        if (resolved is null
            && Fts5Source is { } own
            && string.Equals(own.Table.TableName, tableName, StringComparison.OrdinalIgnoreCase))
        {
            resolved = own;
        }

        return resolved;
    }

    /// <summary>
    /// The rowid of the source identified by <paramref name="qualifier"/>, or null when this row
    /// carries no rowid for it. Joined rows keep one entry per source, so a scalar function bound to
    /// one source never reads another source's rowid.
    /// </summary>
    public long? GetRowIdForQualifier(string qualifier)
    {
        if (QualifiedRowIds is { } qualified && qualified.TryGetValue(qualifier, out var rowId))
            return rowId;

        return RowIdQualifier is { } owner && string.Equals(owner, qualifier, StringComparison.OrdinalIgnoreCase)
            ? RowId
            : Parent?.GetRowIdForQualifier(qualifier);
    }

    public SqlValue GetValue(ColumnExpression column)
    {
        if (TryGetValue(column, out var value))
            return value;

        throw CreateUnresolvedColumnException(column);
    }

    /// <summary>
    /// Builds the diagnostic SQLite/Turso emits when a column reference cannot be
    /// resolved. A reference qualified by an unknown database (<c>unknown.t.c</c>)
    /// reports <c>no such database: unknown</c>; a missing column in a known schema
    /// (<c>main.t.nope</c>) reports <c>no such column: main.t.nope</c>, preserving
    /// the schema qualifier the way SQLite does.
    /// </summary>
    internal static Exception CreateUnresolvedColumnException(ColumnExpression column)
    {
        if (column.Schema is { } schema
            && !schema.Equals("main", StringComparison.OrdinalIgnoreCase)
            && !schema.Equals("temp", StringComparison.OrdinalIgnoreCase))
        {
            return new EmbeddedSqlException($"no such database: {schema}");
        }

        return new EmbeddedSqlException($"no such column: {FormatColumnReference(column)}");
    }

    /// <summary>
    /// Formats a column reference for a "no such column" diagnostic, preserving
    /// a schema qualifier (<c>main.t.b</c>) the same way SQLite does. <see cref="ColumnExpression.Name"/>
    /// already carries the table qualifier for one- or two-part references, so the
    /// schema is only prepended when present.
    /// </summary>
    internal static string FormatColumnReference(ColumnExpression column)
        => column.Schema is { } schema ? schema + "." + column.Name : column.Name;

    public bool TryGetValue(ColumnExpression column, out SqlValue value)
    {
        // Attached-database execution is not available yet. Until a source row carries its
        // database identity, only the schemas this row can represent may resolve here.
        if (column.Schema is { } schema
            && !schema.Equals("main", StringComparison.OrdinalIgnoreCase)
            && !schema.Equals("temp", StringComparison.OrdinalIgnoreCase))
        {
            value = default;
            return false;
        }

        if (column.Qualifier is null)
            return TryGetValue(column.Name, allowQualifiedLookup: false, out value);

        if (AmbiguousQualifiedColumns?.Contains(column.Name) == true)
            ThrowAmbiguousColumn(column.Name);

        if (QualifiedColumns is not null
            && QualifiedColumns.TryGetValue(column.Name, out var qualifiedIndex))
        {
            value = Values[qualifiedIndex];
            return true;
        }

        if (QualifiedRowIds is not null
            && column.Qualifier is not null
            && column.UnqualifiedName is { } rowIdName
            && EmbeddedTable.IsRowidAliasName(rowIdName)
            && QualifiedRowIds.TryGetValue(column.Qualifier, out var qualifiedRowId))
        {
            value = qualifiedRowId is { } rowId ? SqlValue.Integer(rowId) : SqlValue.Null;
            return true;
        }

        for (var index = 0; index < Columns.Length; index++)
        {
            if (string.Equals(Columns[index], column.Name, StringComparison.OrdinalIgnoreCase))
            {
                value = Values[index];
                return true;
            }
        }

        if (RowId is { } rowid
            && RowIdQualifier is not null
            && string.Equals(column.Qualifier, RowIdQualifier, StringComparison.OrdinalIgnoreCase)
            && column.UnqualifiedName is { } bareName
            && EmbeddedTable.IsRowidAliasName(bareName))
        {
            value = SqlValue.Integer(rowid);
            return true;
        }

        if (Parent is not null)
            return Parent.TryGetValue(column, out value);

        value = default;
        return false;
    }

    public bool TryGetQualifiedValue(ColumnExpression column, out SqlValue value)
    {
        if (column.Qualifier is null)
        {
            value = default;
            return false;
        }
        if (AmbiguousQualifiedColumns?.Contains(column.Name) == true)
            ThrowAmbiguousColumn(column.Name);
        if (QualifiedColumns is not null
            && QualifiedColumns.TryGetValue(column.Name, out var qualifiedIndex))
        {
            value = Values[qualifiedIndex];
            return true;
        }
        if (QualifiedRowIds is not null
            && column.UnqualifiedName is { } rowIdName
            && EmbeddedTable.IsRowidAliasName(rowIdName)
            && QualifiedRowIds.TryGetValue(column.Qualifier, out var qualifiedRowId))
        {
            value = qualifiedRowId is { } rowId ? SqlValue.Integer(rowId) : SqlValue.Null;
            return true;
        }
        if (RowId is { } rowid
            && RowIdQualifier is not null
            && string.Equals(column.Qualifier, RowIdQualifier, StringComparison.OrdinalIgnoreCase)
            && column.UnqualifiedName is { } bareName
            && EmbeddedTable.IsRowidAliasName(bareName))
        {
            value = SqlValue.Integer(rowid);
            return true;
        }
        if (Parent is not null)
            return Parent.TryGetQualifiedValue(column, out value);

        value = default;
        return false;
    }

    public EmbeddedColumn? GetColumnDefinition(Expression expression)
    {
        while (expression is CollationExpression collation)
            expression = collation.Expression;
        if (expression is not ColumnExpression column)
            return null;

        if (QualifiedColumnDefinitions is not null
            && QualifiedColumnDefinitions.TryGetValue(column.Name, out var qualified))
        {
            return qualified;
        }

        if (column.Qualifier is not null
            && QualifiedColumns is not null
            && QualifiedColumns.TryGetValue(column.Name, out var qualifiedIndex)
            && ColumnDefinitions is not null
            && qualifiedIndex < ColumnDefinitions.Count)
        {
            return ColumnDefinitions[qualifiedIndex];
        }

        if (column.Qualifier is null && ColumnDefinitions is not null)
        {
            for (var index = 0; index < Columns.Length && index < ColumnDefinitions.Count; index++)
            {
                if (string.Equals(Columns[index], column.Name, StringComparison.OrdinalIgnoreCase))
                    return ColumnDefinitions[index];
            }
        }

        return Parent?.GetColumnDefinition(expression);
    }

    // Whether a column expression resolves to a rowid value (hidden rowid or rowid alias)
    // without a backing column definition, mirroring the shadowing order of TryGetValue.
    // Comparison affinity treats such references as INTEGER, like a real INTEGER column.
    public bool IsRowidReference(ColumnExpression column)
    {
        if (GetColumnDefinition(column) is not null)
            return false;

        if (column.Qualifier is null)
        {
            for (var index = 0; index < Columns.Length; index++)
            {
                if (string.Equals(Columns[index], column.Name, StringComparison.OrdinalIgnoreCase))
                    return false;
            }

            if (RowId is not null && EmbeddedTable.IsRowidAliasName(column.Name))
                return true;

            return Parent?.IsRowidReference(column) ?? false;
        }

        if (AmbiguousQualifiedColumns?.Contains(column.Name) == true)
            return false;
        if (QualifiedColumns?.ContainsKey(column.Name) == true)
            return false;
        if (QualifiedRowIds is not null
            && column.UnqualifiedName is { } qualifiedName
            && EmbeddedTable.IsRowidAliasName(qualifiedName)
            && QualifiedRowIds.ContainsKey(column.Qualifier))
        {
            return true;
        }
        if (RowId is not null
            && RowIdQualifier is not null
            && string.Equals(column.Qualifier, RowIdQualifier, StringComparison.OrdinalIgnoreCase)
            && column.UnqualifiedName is { } unqualifiedName
            && EmbeddedTable.IsRowidAliasName(unqualifiedName))
        {
            return true;
        }
        return Parent?.IsRowidReference(column) ?? false;
    }

    private SqlValue GetValue(string name, bool allowQualifiedLookup)
    {
        if (TryGetValue(name, allowQualifiedLookup, out var value))
            return value;

        throw new EmbeddedSqlException($"no such column: {name}");
    }

    private bool TryGetValue(string name, bool allowQualifiedLookup, out SqlValue value)
    {
        if (allowQualifiedLookup
            && QualifiedColumns is not null
            && QualifiedColumns.TryGetValue(name, out var qualifiedIndex))
        {
            value = Values[qualifiedIndex];
            return true;
        }

        // Columns joined with USING/NATURAL are coalesced: an unqualified reference to
        // such a column must resolve to COALESCE(left, right) so RIGHT/FULL joins report
        // the surviving side rather than the NULL-padded one.
        var coalesced = OutputColumns?
            .Where(output => string.Equals(output.Name, name, StringComparison.OrdinalIgnoreCase)
                && (output.CoalesceIndex is not null
                    || output.AdditionalCoalesceIndices is { Count: > 0 }))
            .ToArray();
        if (coalesced is { Length: > 1 })
            ThrowAmbiguousColumn(name);
        if (coalesced is { Length: 1 })
        {
            var output = coalesced[0];
            value = Values[output.Index];
            if (value.Kind != SqlValueKind.Null)
                return true;
            if (output.CoalesceIndex is { } coalesceIndex)
            {
                value = Values[coalesceIndex];
                if (value.Kind != SqlValueKind.Null)
                    return true;
            }
            if (output.AdditionalCoalesceIndices is not null)
            {
                foreach (var additionalIndex in output.AdditionalCoalesceIndices)
                {
                    value = Values[additionalIndex];
                    if (value.Kind != SqlValueKind.Null)
                        return true;
                }
            }

            value = SqlValue.Null;
            return true;
        }

        if (FindUnqualifiedColumnIndex(name) is { } index)
        {
            value = Values[index];
            return true;
        }

        // rowid/_rowid_/oid resolve to the hidden rowid only after real columns are
        // consulted, so a user column that happens to be named "oid" shadows the alias,
        // exactly as SQLite does.
        if (RowId is { } rowid && EmbeddedTable.IsRowidAliasName(name))
        {
            value = SqlValue.Integer(rowid);
            return true;
        }

        if (Parent is not null)
            return Parent.TryGetValue(name, allowQualifiedLookup, out value);

        value = default;
        return false;
    }

    private int? FindUnqualifiedColumnIndex(string name)
    {
        int? resolved = null;
        for (var index = 0; index < Columns.Length; index++)
        {
            if (!string.Equals(Columns[index], name, StringComparison.OrdinalIgnoreCase))
                continue;

            if (resolved is not null)
                ThrowAmbiguousColumn(name);

            resolved = index;
        }

        return resolved;
    }

    private static void ThrowAmbiguousColumn(string name)
        => throw new EmbeddedSqlException($"ambiguous column name: {name}");

}

internal sealed record SourceData(
    string[] Columns,
    IReadOnlyList<SourceRow> Rows,
    IReadOnlyList<string?>? Collations = null,
    IReadOnlyList<EmbeddedColumn?>? ColumnDefinitions = null,
    IReadOnlyList<Expression>? OmittedVirtualTablePredicates = null,
    bool OrderByConsumed = false);

internal sealed class LazyReadOnlyList<T>(IEnumerable<T> source) : IReadOnlyList<T>, IDisposable
{
    private readonly object _gate = new();
    private readonly List<T> _cache = [];
    private IEnumerator<T>? _source = (source ?? throw new ArgumentNullException(nameof(source))).GetEnumerator();

    public int Count
    {
        get
        {
            lock (_gate)
            {
                while (MoveNextLocked())
                {
                }
                return _cache.Count;
            }
        }
    }

    public T this[int index]
    {
        get
        {
            if (index < 0)
                throw new ArgumentOutOfRangeException(nameof(index));
            lock (_gate)
            {
                while (_cache.Count <= index && MoveNextLocked())
                {
                }
                return index < _cache.Count
                    ? _cache[index]
                    : throw new ArgumentOutOfRangeException(nameof(index));
            }
        }
    }

    public IEnumerator<T> GetEnumerator()
    {
        for (var index = 0; TryGet(index, out var item); index++)
            yield return item!;
    }

    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();

    private bool TryGet(int index, out T? item)
    {
        lock (_gate)
        {
            while (_cache.Count <= index && MoveNextLocked())
            {
            }
            if (index < _cache.Count)
            {
                item = _cache[index];
                return true;
            }
        }

        item = default;
        return false;
    }

    private bool MoveNextLocked()
    {
        if (_source is null)
            return false;
        try
        {
            if (_source.MoveNext())
            {
                _cache.Add(_source.Current);
                return true;
            }
        }
        catch
        {
            DisposeSourceLocked();
            throw;
        }

        DisposeSourceLocked();
        return false;
    }

    public void Dispose()
    {
        lock (_gate)
            DisposeSourceLocked();
    }

    private void DisposeSourceLocked()
    {
        var source = _source;
        _source = null;
        source?.Dispose();
    }
}
